/*
 * The jump to a post. A link to the newest post ends in "#" and its number, and
 * the browser jumps there while the page is still coming in. Whatever the modules
 * change afterwards moves the post away from where the jump left it: the mobile
 * layout most of all, which makes the page narrower and taller in one go and so
 * leaves the reader somewhere in the middle of the thread.
 *
 * So the jump is made again once the modules are through, and once more when the
 * page has finished loading. Only where the page still stood where the browser
 * had put it, and only until the player moves it himself. Going back or reloading
 * puts the page where it was before, and that is left alone.
 */
var MM_SPRUNG_NACH_LADEN_MS = 200;
var mmSprungSelbst = false;

//The element the address points at: by its id, or the old way by its name, as the
//forum marks its posts.
function mmSprungZiel() {
	var marke = String(window.location.hash || '').replace(/^#/, '');
	if (!marke)
		return null;
	try {
		marke = decodeURIComponent(marke);
	} catch (e) {
		//a broken address is taken as it stands
	}
	var ziel = document.getElementById(marke);
	if (!ziel && document.getElementsByName)
		ziel = document.getElementsByName(marke)[0] || null;
	return ziel;
}

function mmSprungZurueck() {
	try {
		var leistung = window.performance;
		var eintrag = (leistung && leistung.getEntriesByType)
			? leistung.getEntriesByType('navigation')[0] : null;
		if (eintrag && eintrag.type)
			return eintrag.type === 'back_forward' || eintrag.type === 'reload';
		var alt = (leistung && leistung.navigation) ? leistung.navigation.type : 0;
		return alt === 1 || alt === 2;
	} catch (e) {
		return false;
	}
}

//Is the page still where the jump put it? The target at the top, or the page as
//far down as it goes, when the post is too close to the end to get there. A page
//still at its very top has not been jumped yet.
function mmSprungSteht(ziel) {
	var oben = ziel.getBoundingClientRect().top;
	var wurzel = document.documentElement;
	var y = window.pageYOffset || 0;
	return y === 0 || Math.abs(oben) <= 2
		|| y + window.innerHeight >= wurzel.scrollHeight - 2;
}

function mmSprung() {
	if (mmSprungSelbst)
		return false;
	var ziel = mmSprungZiel();
	if (!ziel || !ziel.scrollIntoView)
		return false;
	ziel.scrollIntoView({ block: 'start', inline: 'nearest' });
	return true;
}

//Before the modules: is there a jump to keep? Afterwards: keep it.
function mmSprungVorher() {
	try {
		var ziel = mmSprungZiel();
		return !!ziel && !mmSprungZurueck() && mmSprungSteht(ziel);
	} catch (e) {
		return false;
	}
}

function mmSprungHalten() {
	var selbst = function () { mmSprungSelbst = true; };
	['wheel', 'touchstart', 'keydown', 'mousedown'].forEach(function (art) {
		window.addEventListener(art, selbst, { capture: true, passive: true });
	});

	mmSprung();
	if (document.readyState !== 'complete')
		window.addEventListener('load', function () {
			window.setTimeout(function () {
				try {
					mmSprung();
				} catch (e) {
					mmReportError('Sprung zum Beitrag', e);
				}
			}, MM_SPRUNG_NACH_LADEN_MS);
		}, false);
}

function modulesRun() {
	//A redirect page is a hallway, not a room: it is gone again in a moment and
	//carries nothing worth hooking into.
	if (isRedirectPage)
		return;

	altdatenAufraeumen();

	//The login page is no game page: no hero stands there, no world in the form and
	//no button bar. What has no business there stays off, and what belongs only there
	//runs nowhere else.
	var anmeldung = loginIsLoginPage();
	var sprung = mmSprungVorher();

	for (var i = 0; i < MODULES.length; i++) {
		var module = MODULES[i];
		try {
			if (anmeldung !== (module.login === true))
				continue;
			if (module.pages && module.pages.indexOf(page) < 0)
				continue;
			if (module.toggle && settingsRead(module.toggle) !== true)
				continue;
			module.init();
		} catch (e) {
			mmReportError(module.name, e);
		}
	}

	//All buttons are in place now, so the game's icon row can be measured for real.
	//Two of the modules put something there, and each one only knew about its own.
	try {
		settingsFitGadgetBar();
	} catch (e) {
		//a row that stays narrow is a blemish, not a failure
	}

	if (sprung) {
		try {
			mmSprungHalten();
		} catch (e) {
			mmReportError('Sprung zum Beitrag', e);
		}
	}
}

