/*
 * The bar. Its own switch, and one per button.
 *
 * Twenty buttons are twenty buttons whether one uses two of them or all of them,
 * and which two those are differs from player to player: one writes tables, the
 * next only ever links an item. So every button can be sent away.
 */
var BBCODE_CFG = bbcodeDefaults();

//Which buttons the bar starts with. Read off the table above rather than typed out
//a second time, so a new button is there without a second edit.
function bbcodeDefaults() {
	//Buttons the player writes himself: a name for the button and the code it puts
	//into the field. Empty on delivery - what belongs in here nobody but the player
	//knows.
	var out = { enabled: false, eigene: [] };

	for (var i = 0; i < BBCODE_PARTS.length; i++)
		out[BBCODE_PARTS[i].marke] = BBCODE_PARTS[i].vorgabe !== false;
	return out;
}

/*
 * Where the marked text goes in a code the player wrote. Everything in front of
 * the marker is put before the selection, everything behind it after - so
 * "[spoiler]%s[/spoiler]" wraps, and "[hr]" simply drops in.
 */
var BBCODE_MARK = '%s';

//The buttons from the settings, turned into entries of the same shape as the ones
//in the table above. An entry without a name or without a code is half typed and
//is left out rather than put on the bar as a riddle.
function bbcodeCustomParts() {
	var liste = BBCODE_CFG.eigene || [];
	var out = [];

	for (var i = 0; i < liste.length; i++) {
		var eintrag = liste[i] || { };
		var name = String(eintrag.name == null ? '' : eintrag.name).trim();
		var code = String(eintrag.code == null ? '' : eintrag.code);
		if (!name || !code.trim())
			continue;

		var stelle = code.indexOf(BBCODE_MARK);
		out.push({
			marke: 'eigen' + i,
			label: name,
			titel: 'Eigener Knopf: ' + code,
			auf: stelle < 0 ? code : code.slice(0, stelle),
			zu: stelle < 0 ? '' : code.slice(stelle + BBCODE_MARK.length),
			//What a player wrote himself is his business on every one of the three
			//pages; only the game's own codes know where they do nothing.
			ausrufer: true
		});
	}
	return out;
}

//One tick per button for the options window, in the order of the bar. The word on
//the tick is the one the button explains itself with; the button itself carries
//only a letter or two.
function bbcodeFields() {
	var out = [];

	for (var i = 0; i < BBCODE_PARTS.length; i++)
		out.push({
			path: 'BBCODE_CFG.' + BBCODE_PARTS[i].marke, type: 'bool',
			label: BBCODE_PARTS[i].titel, reihe: 'bbcode',
			needs: 'BBCODE_CFG.enabled'
		});
	return out;
}

//How long after loading posts that arrive late are still watched for.
var TAKTIK_WATCH_MS = 10000;

/*
 * The defence columns of the overview, in this order. They are combat kinds, and
 * the short forms are the ones the game itself uses in a report.
 *
 * This stands here and not down in the module block because the options window is
 * built from SETTINGS_TABS further below, and the tab offers one tick per column.
 */
var TAKTIK_PARRY = ['NK', 'FK', 'Magie', 'Sozial', 'HiHa', 'NG'];

var TAKTIK_CFG = taktikDefaults();

function taktikDefaults() {
	var out = {
		//The whole module. Off means the report stays as the game delivers it.
		enabled: false,

		//Take the debuffs out of the rolls instead of using the bare number. Off on
		//delivery: the note in the options window says why - in a long fight the
		//assumption behind it stops holding.
		debuffs: false,

		//Open the forum's spoiler boxes without being asked. A module of its own and
		//therefore off on delivery, like every other one: whoever installs the script
		//decides what may run.
		spoiler: false,

		/*
		 * How the enemies are put together.
		 *
		 * 'art' is one row per kind and position: twelve goblins standing in front
		 * are one row with a twelve in it, and the rolls in that row are the highest
		 * any of the twelve managed. That is the short answer to "what can this
		 * dungeon do to me".
		 *
		 * 'einzeln' gives every single being its own row. Longer, and the only way
		 * to see that of twelve goblins eleven are harmless and the twelfth is not.
		 */
		gruppieren: 'art',

		/*
		 * Which of the rolls behind a row ends up in it.
		 *
		 * 'hoechster' is the worst case: what the strongest of twelve goblins got
		 * through on his best throw, and therefore what the group has to survive.
		 *
		 * 'median' is the middle one of all rolls in that discipline. A single
		 * lucky throw no longer speaks for the whole row, which says more about
		 * what a dungeon does on an ordinary day - and less about what it can do
		 * on a bad one.
		 *
		 * 'beide' writes the highest and the middle one behind it in brackets.
		 */
		wert: 'hoechster',

		//Which columns the overview carries. The name of the enemy always comes
		//along - without it a row says nothing at all.
		zeigeAnzahl: true,
		zeigePosition: true,
		zeigeInitiative: true,
		zeigeAngriff: true,
		zeigeAbwehr: true,

		//Put the table into a spoiler box. In the forum that is what keeps a long
		//overview from burying the post it belongs to; pasted anywhere else the box
		//is only two lines of code around a table.
		spoilerTag: true,

		//Round the rolls up to ten. The overview is meant to name a threshold - "this
		//one gets to about fifty" - and a threshold that reads 47 pretends to a
		//precision a handful of rolls cannot carry. Off, the numbers stand as they
		//were read.
		runden: true
	};

	//One tick per defence column. A group that never meets a spell has no use for
	//an empty "Magie PW" in every report it ever writes.
	for (var i = 0; i < TAKTIK_PARRY.length; i++)
		out['pw' + TAKTIK_PARRY[i]] = true;
	return out;
}

//The defence columns as ticks for the options window, in the order of the table.
function taktikFields() {
	var out = [];

	for (var i = 0; i < TAKTIK_PARRY.length; i++)
		out.push({
			path: 'TAKTIK_CFG.pw' + TAKTIK_PARRY[i], type: 'bool',
			label: TAKTIK_PARRY[i], reihe: 'taktikpw',
			needs: ['TAKTIK_CFG.enabled', 'TAKTIK_CFG.zeigeAbwehr']
		});
	return out;
}

