/*
 * The tabs above, gathered into groups. With twenty of them in one row nobody
 * finds anything any more, so the row at the top names the group and the list
 * beside the page names what is in it.
 *
 * "data" is the window's own page and "legend" the calculator - neither is a
 * module, and both are named here like everything else so that the order is read
 * from one place.
 *
 * A group holding a single page shows no list: there would be nothing to choose.
 */
var SETTINGS_GROUPS = [
	{ id: 'core', label: 'Einstellungen', tabs: ['data', 'login'] },
	{ id: 'iface', label: 'Interface',
		tabs: ['mobil', 'pin', 'konfig', 'bbcode', 'compare', 'iface'] },
	{ id: 'held', label: 'Fertigkeitenseite', tabs: ['skills', 'rank', 'skillsrest'] },
	{ id: 'bericht', label: 'Kampfberichte',
		tabs: ['funde', 'kstat', 'taktik', 'hell'] },
	{ id: 'markt', label: 'Marktplatz', tabs: ['markt', 'preis'] },
	{ id: 'trigger', label: 'Trigger Items', tabs: ['trigger'] },
	{ id: 'rest', label: 'Sonstiges', tabs: ['legend', 'planner', 'exam'] }
];

//Which group a page belongs to, or the first one where it belongs to none.
function settingsGroupOf(tabId) {
	for (var i = 0; i < SETTINGS_GROUPS.length; i++)
		if (SETTINGS_GROUPS[i].tabs.indexOf(tabId) > -1)
			return SETTINGS_GROUPS[i];
	return SETTINGS_GROUPS[0];
}

//Read one value out of its block. 'ITEM_CFG.faerben' -> ITEM_CFG.faerben
function settingsRead(path) {
	var parts = String(path).split('.');
	var block = SETTINGS_BLOCKS[parts[0]];
	return block ? block[parts[1]] : undefined;
}

function settingsWrite(path, value) {
	var parts = String(path).split('.');
	var block = SETTINGS_BLOCKS[parts[0]];
	if (block)
		block[parts[1]] = value;
}

//Every adjustable field, flat, in the order the dialog shows them.
function settingsAllFields() {
	var out = [];
	for (var i = 0; i < SETTINGS_TABS.length; i++)
		for (var j = 0; j < SETTINGS_TABS[i].fields.length; j++)
			out.push(SETTINGS_TABS[i].fields[j]);
	return out;
}

function settingsSnapshot() {
	var out = { };
	var fields = settingsAllFields();
	for (var i = 0; i < fields.length; i++) {
		var value = settingsRead(fields[i].path);
		//A list is copied, not handed over. The dialog edits its snapshot freely and
		//"Abbrechen" has to leave the block above untouched - which it would not if
		//both sides pointed at the same array. A list of pairs needs each pair
		//copied too, or editing a number would reach straight through.
		out[fields[i].path] = settingsIsList(value) ? settingsCopyList(value) : value;
	}
	return out;
}

//Lists are the only values in the settings that are not a single number, word or
//tick, and two of them have to be compared and copied differently everywhere.
function settingsIsList(value) {
	return Object.prototype.toString.call(value) == '[object Array]';
}

function settingsCopyList(value) {
	var out = [];
	for (var i = 0; i < value.length; i++) {
		var entry = value[i];
		if (entry && typeof entry == 'object') {
			var copy = { };
			for (var key in entry)
				copy[key] = entry[key];
			out.push(copy);
		} else {
			out.push(entry);
		}
	}
	return out;
}

function settingsSameValue(a, b) {
	//Written out rather than joined: a list can hold words as well as pairs of
	//numbers, and joining ['ab','c'] and ['a','bc'] would call them the same while
	//a pair would come out as "[object Object]" either way.
	if (settingsIsList(a) || settingsIsList(b))
		return settingsIsList(a) && settingsIsList(b)
			&& JSON.stringify(a) === JSON.stringify(b);
	return a === b;
}

//A list of steps as it is worth keeping: both numbers whole, a step that rounds to
//nothing thrown out, and the whole thing from the largest threshold down - that is
//the order it is read in, so it is also the order it is shown in.
function settingsStepsClean(value) {
	var out = [];
	if (!settingsIsList(value))
		return out;

	for (var i = 0; i < value.length; i++) {
		var step = value[i] || { };
		var from = parseInt(step.ab, 10);
		var to = parseInt(step.auf, 10);
		if (isNaN(from) || isNaN(to) || from < 0 || to < 1)
			continue;
		out.push({ ab: from, auf: to });
	}

	out.sort(function (a, b) { return b.ab - a.ab; });
	return out;
}

/*
 * A list of pairs - a name and what belongs to it. A row missing either half is
 * half typed and is thrown away rather than kept as a puzzle; the name is trimmed,
 * the code is not, because a space at the end of a piece of BBCode can be exactly
 * what somebody wanted there.
 */
function settingsPairsClean(value) {
	var out = [];
	if (!settingsIsList(value))
		return out;

	for (var i = 0; i < value.length; i++) {
		var paar = value[i] || { };
		var name = String(paar.name == null ? '' : paar.name).trim();
		var code = String(paar.code == null ? '' : paar.code);
		if (!name || !code.trim())
			continue;
		out.push({ name: name, code: code });
	}
	return out;
}

//A list of words as it is worth keeping: everything blank thrown out and the rest
//trimmed, so a row the reader started and abandoned does not come back tomorrow.
function settingsListClean(value) {
	var out = [];
	if (!settingsIsList(value))
		return out;

	for (var i = 0; i < value.length; i++) {
		var text = String(value[i] == null ? '' : value[i]).trim();
		if (text)
			out.push(text);
	}
	return out;
}

//The values from the blocks above, before anything stored is laid over them.
var SETTINGS_DEFAULTS = settingsSnapshot();

function settingsLoadStored() {
	try {
		var raw = GM_getValue(SETTINGS_KEY, false);
		if (!raw)
			return { };
		var parsed = JSON.parse(raw);
		return (parsed && typeof parsed == 'object') ? parsed : { };
	} catch (e) {
		//Unreadable settings are no reason to keep the script from starting.
		return { };
	}
}

/*
 * Settings saved by an older version keep the switches for hiding buttons in the
 * icon row among those of the mobile mode. Hiding buttons is a module of its own,
 * and whoever had it set should not have to set it again: the stored values are
 * carried over once and the entries under the mobile mode dropped.
 *
 * Carried over only where the stored mobile mode is on: with it off, those entries
 * stand for nothing hidden, and someone who never used it should not suddenly
 * find the manual gone.
 */
var SETTINGS_HIDE_MOVED = ['ohneAnleitung', 'ohneQuests', 'ohneDuelle', 'ohneTitel'];

function settingsMoveHideFields(stored) {
	var alt = [], i, name;

	for (i = 0; i < SETTINGS_HIDE_MOVED.length; i++)
		if (('MOBIL_CFG.' + SETTINGS_HIDE_MOVED[i]) in stored)
			alt.push(SETTINGS_HIDE_MOVED[i]);
	if (!alt.length)
		return false;

	if (stored['MOBIL_CFG.enabled'] === true) {
		var irgendwas = false;
		for (i = 0; i < SETTINGS_HIDE_MOVED.length; i++) {
			name = SETTINGS_HIDE_MOVED[i];
			var wert = (('MOBIL_CFG.' + name) in stored)
				? stored['MOBIL_CFG.' + name] === true
				: SETTINGS_DEFAULTS['HIDE_CFG.' + name] === true;
			stored['HIDE_CFG.' + name] = wert;
			if (wert)
				irgendwas = true;
		}
		stored['HIDE_CFG.enabled'] = irgendwas;
	}

	for (i = 0; i < alt.length; i++)
		delete stored['MOBIL_CFG.' + alt[i]];

	try {
		GM_setValue(SETTINGS_KEY, JSON.stringify(stored));
	} catch (e) {
		//The values are in place for this page either way; the next save writes them.
	}
	return true;
}

/*
 * One value, brought into the shape its field needs.
 *
 * undefined comes back where the value does not fit that field at all any more: a
 * colour that is no colour, a word the choice no longer offers, a number that is
 * no number. What to do with that is the caller's business - settingsApply leaves
 * the default standing, the import says so out loud and falls back to the default
 * as well. Both go through this one gate, so neither can be stricter than the
 * other by accident.
 */
function settingsFieldValue(field, value) {
	if (field.type == 'bool')
		return value === true || value === 'true';
	if (field.type == 'colour')
		//Not a number - parseInt would make NaN of it and the stored colour would
		//silently never arrive.
		return settingsColourValue(value) || undefined;
	if (field.type == 'text')
		return String(value == null ? '' : value);
	if (field.type == 'choice')
		return settingsChoiceKnows(field, value) ? value : undefined;
	if (field.type == 'order')
		return settingsOrderClean(field, value);
	if (field.type == 'list')
		return settingsListClean(value);
	if (field.type == 'pairs' || field.type == 'farbpaare')
		return settingsPairsClean(value);
	if (field.type == 'steps')
		return settingsStepsClean(value);

	var num = parseInt(value, 10);
	if (isNaN(num))
		return undefined;
	if (field.min != null) num = Math.max(field.min, num);
	if (field.max != null) num = Math.min(field.max, num);
	return num;
}

//Lay the stored values over the defaults. Only known fields, and only in the type
//the default has - a stray entry from an older version cannot break anything.
function settingsApply() {
	var stored = settingsLoadStored();
	settingsMoveHideFields(stored);
	var fields = settingsAllFields();

	for (var i = 0; i < fields.length; i++) {
		if (!(fields[i].path in stored))
			continue;

		var wert = settingsFieldValue(fields[i], stored[fields[i].path]);
		if (wert !== undefined)
			settingsWrite(fields[i].path, wert);
	}
}

function settingsChoiceKnows(field, value) {
	var options = field.options || [];
	for (var i = 0; i < options.length; i++)
		if (options[i].value === value)
			return true;
	return false;
}

//A stored order is only a wish: entries the field does not offer are dropped, and
//entries it offers but the wish never named are appended. So an order saved by an
//older version keeps working when a table is added or taken away.
function settingsOrderClean(field, value) {
	var options = field.options || [];
	var out = [];

	if (settingsIsList(value))
		for (var i = 0; i < value.length; i++)
			if (settingsChoiceKnows(field, value[i]) && out.indexOf(value[i]) < 0)
				out.push(value[i]);

	for (var j = 0; j < options.length; j++)
		if (out.indexOf(options[j].value) < 0)
			out.push(options[j].value);

	return out;
}

//Store only what actually differs from the default. That keeps the entry small and
//lets a changed default reach anyone who never touched that field.
function settingsSave(values) {
	var out = { };

	//First what a tab keeps itself - the auto login its credentials, for instance.
	for (var k = 0; k < SETTINGS_EXTRA_SAVE.length; k++)
		SETTINGS_EXTRA_SAVE[k]();

	var fields = settingsAllFields();
	for (var i = 0; i < fields.length; i++) {
		var path = fields[i].path;
		if (!(path in values))
			continue;
		if (fields[i].type == 'list')
			values[path] = settingsListClean(values[path]);
		if (fields[i].type == 'pairs' || fields[i].type == 'farbpaare')
			values[path] = settingsPairsClean(values[path]);
		if (fields[i].type == 'steps')
			values[path] = settingsStepsClean(values[path]);
		if (!settingsSameValue(values[path], SETTINGS_DEFAULTS[path]))
			out[path] = values[path];
	}
	GM_setValue(SETTINGS_KEY, JSON.stringify(out));
	for (var j = 0; j < fields.length; j++)
		if (fields[j].path in values)
			settingsWrite(fields[j].path, values[fields[j].path]);
}

function settingsReset() {
	GM_deleteValue(SETTINGS_KEY);
	var fields = settingsAllFields();
	for (var i = 0; i < fields.length; i++) {
		//A list goes back as a copy: handing over the original would make the block
		//and the table of defaults one and the same, and the next change would take
		//the default with it.
		var value = SETTINGS_DEFAULTS[fields[i].path];
		settingsWrite(fields[i].path, settingsIsList(value) ? settingsCopyList(value) : value);
	}
}

/* --- Carrying the settings out of the browser and back in ------------------ *
 * The settings live in the browser's own store, which belongs to one browser on
 * one machine. A new computer, a second browser, a Tampermonkey that was cleared
 * out - every one of those starts from nothing, and setting a hundred ticks again
 * is not something anybody should be asked to do twice.
 *
 * So they go out as one file, with the version of the script that wrote them
 * stamped on it, and come back the same way. What no longer exists is named and
 * skipped; what exists but no longer fits falls back to its default and is named
 * too. A silent import that quietly left half the settings on old values would be
 * worse than none.
 *
 * On request the stored data travels along: the item compare, the skills read
 * in, the battle statistics and the rest. Whoever moves to a new browser keeps
 * everything the script has learnt.
 *
 * Never in the file: the auto login's user name and password. Those are kept apart
 * from the settings on purpose, and a file that travels between machines is the
 * last place they belong.
 * ------------------------------------------------------------------------- */

var SETTINGS_EXPORT_NAME = 'WoD Enhancer';
var SETTINGS_EXPORT_FILE = 'wod-enhancer-einstellungen.json';
var SETTINGS_EXPORT_FILE_DATA = 'wod-enhancer-einstellungen-und-daten.json';

//Which stored keys go into a file with data, and come back out of one: all but
//the settings themselves, which travel as "werte", and all but what the storage
//list marks as staying put - the settings and the auto login.
function settingsDataKeyTravels(key) {
	if (typeof key != 'string' || !key)
		return false;
	var art = storageKindOf(key);
	return !(art && art.bleibt);
}

function settingsExportData() {
	var daten = { };
	var keys;

	try {
		keys = GM_listValues();
	} catch (e) {
		return daten;
	}

	for (var i = 0; i < keys.length; i++) {
		var key = String(keys[i]);
		if (!settingsDataKeyTravels(key))
			continue;
		var wert = GM_getValue(key, null);
		if (wert !== null && wert !== undefined)
			daten[key] = wert;
	}
	return daten;
}

//The version out of the script header. Tampermonkey hands it over unasked; where
//it is missing, an export carries none and an import says nothing about it.
function mmScriptVersion() {
	try {
		if (typeof GM_info != 'undefined' && GM_info && GM_info.script)
			return String(GM_info.script.version || '');
	} catch (e) {
		//Then it stays empty.
	}
	return '';
}

//Everything, not only what differs from the default: a file that names every
//setting can be read by a human and says what it will do before it is imported.
function settingsExportText(mitDaten) {
	var werte = { };
	var fields = settingsAllFields();

	for (var i = 0; i < fields.length; i++)
		werte[fields[i].path] = settingsRead(fields[i].path);

	var inhalt = {
		skript: SETTINGS_EXPORT_NAME,
		version: mmScriptVersion(),
		erstellt: new Date().toISOString(),
		werte: werte
	};
	if (mitDaten)
		inhalt.daten = settingsExportData();

	return JSON.stringify(inhalt, null, '\t');
}

/*
 * Out of the browser and onto the disk. The file is built in the page itself and
 * handed to the browser's own download - nothing goes to any server, and the
 * address it is handed over under is thrown away again right after.
 */
function settingsExportDownload(melden, mitDaten) {
	var url = null;
	var name = mitDaten ? SETTINGS_EXPORT_FILE_DATA : SETTINGS_EXPORT_FILE;

	try {
		url = window.URL.createObjectURL(
			new window.Blob([settingsExportText(mitDaten)], { type: 'application/json' }));

		var link = document.createElement('a');
		link.href = url;
		link.download = name;
		link.style.display = 'none';
		document.body.appendChild(link);
		link.click();
		document.body.removeChild(link);
	} catch (e) {
		melden(['Die Datei liess sich nicht anlegen.'], true);
		return false;
	}

	window.setTimeout(function () {
		try {
			window.URL.revokeObjectURL(url);
		} catch (e) {
			//Then the browser lets go of it by itself when the page goes.
		}
	}, 2000);

	melden(['Gespeichert als "' + name + '".'], false);
	return true;
}

/*
 * A file, read and checked, but nothing written yet. What comes back is the whole
 * story: which values would be set, which the file named and this version does not
 * know, and which it named with a value that no longer fits.
 *
 * Every setting starts at its default and is only then laid over with what the
 * file says. So an import really is what the file holds, and not a mixture of the
 * file and whatever happened to stand here before.
 */
function settingsImportRead(text) {
	var daten;

	try {
		daten = JSON.parse(String(text));
	} catch (e) {
		return { fehler: 'Das ist keine Einstellungsdatei: sie liess sich nicht lesen.' };
	}

	if (!daten || typeof daten != 'object' || !daten.werte
			|| typeof daten.werte != 'object')
		return { fehler: 'In dieser Datei stehen keine Einstellungen.' };

	var bericht = { fehler: null, version: String(daten.version || ''), werte: { },
		gesetzt: 0, unbekannt: [], zurueck: [], fehlen: [],
		daten: settingsImportDataOf(daten.daten), datenGesetzt: 0 };
	var fields = settingsAllFields();
	var kennt = { };
	var i;

	for (i = 0; i < fields.length; i++) {
		kennt[fields[i].path] = fields[i];
		bericht.werte[fields[i].path] = SETTINGS_DEFAULTS[fields[i].path];
		if (!(fields[i].path in daten.werte))
			bericht.fehlen.push(fields[i].path);
	}

	for (var pfad in daten.werte) {
		if (!Object.prototype.hasOwnProperty.call(daten.werte, pfad))
			continue;

		//Naming what fell away is the whole service: the reader knows what he once
		//set and can go looking for where it went.
		if (!kennt[pfad]) {
			bericht.unbekannt.push(pfad);
			continue;
		}

		var wert = settingsFieldValue(kennt[pfad], daten.werte[pfad]);
		if (wert === undefined) {
			bericht.zurueck.push(kennt[pfad].label || pfad);
			continue;
		}

		bericht.werte[pfad] = wert;
		bericht.gesetzt++;
	}
	return bericht;
}

//The stored data a file carries, as far as it may come back in: keys that travel,
//and values that are plain text, numbers or yes and no.
function settingsImportDataOf(daten) {
	var out = { };
	if (!daten || typeof daten != 'object')
		return out;

	for (var key in daten) {
		if (!Object.prototype.hasOwnProperty.call(daten, key) || !settingsDataKeyTravels(key))
			continue;
		var wert = daten[key];
		if (typeof wert == 'string' || typeof wert == 'number' || typeof wert == 'boolean')
			out[key] = wert;
	}
	return out;
}

//The data into the store, beside what is there. An entry of the same name is
//replaced; everything else stays.
function settingsImportDataApply(bericht) {
	var zahl = 0;
	for (var key in bericht.daten) {
		GM_setValue(key, bericht.daten[key]);
		zahl++;
	}
	bericht.datenGesetzt = zahl;
	return zahl;
}

/*
 * And now for real. The same road the "Speichern" of the window takes, so an
 * import can do nothing a hand on the ticks could not have done. The draft of an
 * open window is brought along, or a "Speichern" afterwards would write the old
 * values back over the new ones.
 */
function settingsImportApply(bericht) {
	var werte = { };

	for (var pfad in bericht.werte) {
		//A list goes in as a copy. Handing over the one out of the table of defaults
		//would make the block and that table the same thing, and the next change
		//would take the default with it.
		werte[pfad] = settingsIsList(bericht.werte[pfad])
			? settingsCopyList(bericht.werte[pfad]) : bericht.werte[pfad];
		if (settingsDraft)
			settingsDraft[pfad] = settingsIsList(werte[pfad])
				? settingsCopyList(werte[pfad]) : werte[pfad];
	}

	settingsSave(werte);
	return werte;
}

//What an import has to tell, line by line. German, because it is read by whoever
//pressed the button and not by whoever wrote the script.
function settingsImportReport(bericht) {
	if (bericht.fehler)
		return [bericht.fehler];

	var eigen = mmScriptVersion();
	var out = [];

	if (bericht.version && eigen && bericht.version !== eigen)
		out.push('Achtung: die Datei stammt aus Version ' + bericht.version
			+ ', hier läuft Version ' + eigen + '. Das kann gutgehen, muss es aber '
			+ 'nicht. Was nicht mehr passt, steht darunter.');

	out.push(bericht.gesetzt + ' Einstellungen übernommen.');

	if (bericht.datenGesetzt)
		out.push(bericht.datenGesetzt + ' gespeicherte Einträge übernommen.');
	else if (Object.keys(bericht.daten || { }).length)
		out.push('Die gespeicherten Daten aus der Datei wurden nicht übernommen.');

	if (bericht.zurueck.length)
		out.push(bericht.zurueck.length + ' Einträge hatten einen Wert, den es so '
			+ 'nicht mehr gibt, sie stehen jetzt auf der Vorgabe: '
			+ bericht.zurueck.join(', ') + '.');

	if (bericht.unbekannt.length)
		out.push(bericht.unbekannt.length + ' Einträge aus der Datei kennt diese '
			+ 'Version nicht mehr, sie wurden übergangen: '
			+ bericht.unbekannt.join(', ') + '.');

	if (bericht.fehlen.length)
		out.push(bericht.fehlen.length + ' Einstellungen dieser Version standen nicht '
			+ 'in der Datei, sie stehen jetzt auf der Vorgabe.');

	out.push('Fenster einmal schliessen und wieder öffnen, damit die Reiter die '
		+ 'neuen Werte zeigen.');
	return out;
}

function settingsImportFile(datei, melden) {
	var leser;

	try {
		leser = new window.FileReader();
	} catch (e) {
		melden(['Dieser Browser kann die Datei nicht selbst lesen.'], true);
		return false;
	}

	leser.onload = function () {
		var bericht = settingsImportRead(leser.result);
		if (bericht.fehler) {
			melden([bericht.fehler], true);
			return;
		}
		settingsImportApply(bericht);

		//The data only with a yes: it replaces entries of the same name, and a
		//file from someone else may hold a great deal.
		var zahl = Object.keys(bericht.daten).length;
		if (zahl && window.confirm('Die Datei enthält auch ' + zahl + ' gespeicherte '
				+ 'Einträge, zum Beispiel den Gegenstandsvergleich. Sollen die '
				+ 'übernommen werden? Einträge mit gleichem Namen werden dabei ersetzt.'))
			settingsImportDataApply(bericht);

		melden(settingsImportReport(bericht), false);
	};
	leser.onerror = function () {
		melden(['Die Datei liess sich nicht lesen.'], true);
	};

	leser.readAsText(datei);
	return true;
}

//Has to run here: below the blocks it reads from, above the page dispatcher that
//already acts on the values.
settingsApply();


/////////////////////////////////////////////////////////////////////////////
////////////// Groundwork: which page, which hero, which world //////////////
/////////////////////////////////////////////////////////////////////////////

var isRedirectPage, pageSection, page, id, world, world_written;
getEssentialData();

function getEssentialData() {
	try {
		//Check if it is a redirect page
		var pageHeadline = document.querySelector('table.content_table h1');
		if (pageHeadline && pageHeadline.innerHTML.trim() == "Leite weiter") {
			isRedirectPage = true;
		} else {

			var pathname = window.location.pathname.split("/");
			pageSection = pathname[pathname.length-2];
			page = pathname[pathname.length-1];

			//Each field on its own, so that a missing one cannot take the other two
			//with it: the world would stay undefined, every storage key would then
			//begin with "undefined", and nothing would say so out loud. The hidden
			//fields also do not have to be direct children of a form: that they are
			//is a detail of the desktop layout, not something the game promises.
			//The hidden field is the authority - but it is not on every page under
			///wod/spiel/. The forum, for instance, carries neither it nor the other
			//two, and the item compare runs there all the same. So both fall back to
			//the address bar: the world stands in the host name, the hero number in
			//the query string.
			id = essentialField('session_hero_id') || urlParameter('session_hero_id');
			world = essentialField('wod_post_world') || worldFromHostname();

			//The host name is the more reliable source: it also holds for a world whose
			//code the table above does not know.
			world_written = worldSubdomain() || WORLD_NAMES[world] || '';


			//Without the world every stored key would be wrong. Worth saying out loud -
			//but only on a page the script actually works on. Everywhere else it is
			//merely a passer-by and has no business complaining.
			if (world == null && WORLD_PAGES.indexOf(page) > -1)
				mmReportError('getEssentialData',
					'Die Welt lässt sich auf dieser Seite nicht bestimmen. '
					+ 'Adresse: ' + window.location.href);
		}
	} catch (e) {
		mmReportError('getEssentialData', e);
	}
}

//The hidden fields the game carries along on most pages. Direct child of a form
//first, because that is where they sit in the layout the script was written for;
//anywhere on the page afterwards.
function essentialField(name) {
	var el = document.querySelector('form > input[name="' + name + '"]')
		|| document.querySelector('input[name="' + name + '"]');
	return el && el.value ? el.value : null;
}

//Every world has its own host name - cartegon.world-of-dungeons.de and so on. That
//makes the address a second, always available source for the world code.
function worldFromHostname() {
	var subdomain = worldSubdomain();
	for (var code in WORLD_NAMES)
		if (WORLD_NAMES[code] == subdomain)
			return code;
	return null;
}

//"darakesh.world-of-dungeons.de" -> "darakesh".
function worldSubdomain() {
	var host = String(window.location.hostname || '').toLowerCase();
	var first = host.split('.')[0];
	return first && first != 'www' && host.indexOf('world-of-dungeons') > -1 ? first : '';
}

//What the world is CALLED, for the reader: "Darakesh", not "WD".
function worldName() {
	return worldNameOf(world, world_written);
}

//A world as a player calls it. The two-letter code is what the storage keys are
//built from and has no business in anything anybody reads: "WC" names no world.
function worldNameOf(code, geschrieben) {
	var name = geschrieben || WORLD_NAMES[code] || '';
	if (!name)
		return code || '?';
	return name.charAt(0).toUpperCase() + name.slice(1);
}

function urlParameter(name) {
	var hit = String(window.location.search || '')
		.match(new RegExp('[?&]' + name + '=([^&#]*)'));
	if (!hit)
		return null;
	try {
		return decodeURIComponent(hit[1].replace(/\+/g, ' ')) || null;
	} catch (e) {
		return hit[1] || null;
	}
}

/////////////////////////////////////////////////////////////////////////////
/////////////////////////// Module: rank colours ////////////////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * It works on the game's own table alone, and also with the details switched off:
 * that table already carries the trained rank, the effective rank and the bonus
 * tooltips, which is everything the colouring needs, cross-check included.
 *
 * Where the skills page is rebuilt on the same visit, the colouring waits for its
 * data: then class, race, monument and the sets the hero wears are known by name.
 */

function rankColoursInit() {
	if (page == 'clan.php') {
		rankColoursReadMonument();
		return;
	}
	if (rankColoursClassOverview())
		return;
	//A page shown in parts has an incomplete table - nothing may be calculated from
	//it, and a colour is a calculation.
	if (rankColoursDetailsOn() && rankColoursPageSplit())
		return;
	if (!rankColoursDetailsOn() && !CAP_CFG.RUN_WITHOUT_DETAILS)
		return;

	//After a new build of the skills page with other data, the colours are reckoned
	//again from scratch.
	skillsWhenReady(function () {
		skillCapClear();
		skillCapRun();
	});
}

//The rank colours taken off the page again: colour, badge, tooltip and legend,
//each back to what it was before.
function skillCapClear() {
	var alt = document.querySelectorAll('[data-wodcap="1"]');
	for (var i = 0; i < alt.length; i++) {
		var el = alt[i];
		skillCapPutBack(el, 'style', 'data-wodcap-stil');
		skillCapPutBack(el, 'title', 'data-wodcap-titel');
		var host = el.closest('td') || el.parentElement;
		if (host) {
			skillCapPutBack(host, 'onmouseover', 'data-wodcap-tip');
			skillCapPutBack(host, 'style', 'data-wodcap-hstil');
		}
		var badge = el.parentNode ? el.parentNode.querySelector('span.wodcap-badge') : null;
		if (badge)
			badge.parentNode.removeChild(badge);
		el.removeAttribute('data-wodcap');
	}
	var legende = document.getElementById('wodcap-legend');
	if (legende && legende.parentNode)
		legende.parentNode.removeChild(legende);
}

//One attribute noted before the rank colours changed it, and put back. Empty means
//it was not there.
function skillCapNote(el, name, merker) {
	if (!el.hasAttribute(merker))
		el.setAttribute(merker, el.getAttribute(name) || '');
}

function skillCapPutBack(el, name, merker) {
	if (!el.hasAttribute(merker))
		return;
	var wert = el.getAttribute(merker);
	if (wert)
		el.setAttribute(name, wert);
	else
		el.removeAttribute(name);
	el.removeAttribute(merker);
}

//skills.php with ?class= or ?subclass= lists the skills of a class, not the
//hero's own: the same file, but nothing to colour.
function rankColoursClassOverview() {
	return /[?&](sub)?class=/.test(String(window.location.search || ''));
}

//Is the game showing the detailed table? Two switches on the page would mean
//something unexpected, so that counts as "no" as well.
function rankColoursDetailsOn() {
	var form = document.forms['the_form'];
	if (form) {
		var showDetails = form.elements && form.elements.namedItem('show_details');
		return !showDetails;
	}
	return document.querySelectorAll("table input.button[value*='Details aus']").length == 1;
}

//The game can be set to show the skills a page at a time. Then the table on screen
//is only part of the truth and nothing may be calculated from it.
function rankColoursPageSplit() {
	return !!document.querySelector('form[name*="the_form"] > input.paginator');
}

/*
 * The monument of the hero's own clan, one of the sources whose bonuses are not
 * capped. Its name stands on the clan page, in the link right below the form; the
 * own clan is the one whose page carries the hints box. No monument: 'none'.
 */
function rankColoursReadMonument() {
	if (!document.querySelector('div.hints, span.hints'))
		return;
	var link = document.querySelector('form[name*="the_form"] > a');
	var name = link ? itemNamePlain(link.textContent) : '';
	GM_setValue(world + '_monument_' + id, name || 'none');
}

/////////////////////////////////////////////////////////////////////////////
////////////// Groundwork: messages, clipboard, small helpers ///////////////
/////////////////////////////////////////////////////////////////////////////


//Despite its name it sends nothing anywhere. The error goes to the console, into
//the message list of the options window and - so it does not pass unnoticed -
//into a thin bar at the top of the page. A dialog would be too intrusive, complete
//silence too little: then it would look as if the script were simply doing nothing.
/*
 * Where an error goes: the console, the message list of the options window, and
 * the bar at the top of the page. Called from the nets at the entry points - the
 * module table, the listeners, the timers, the async reader - and from nowhere
 * inside them: a function that fails in the middle of a module takes that module
 * down, and the net around it says so.
 */
function mmReportError(wo, errorMessage) {
	try {
		console.error('[WoD Enhancer] Fehler in ' + wo + ':', errorMessage);
		mmNote('Fehler in ' + wo + ': ' + errorMessage);
		mmShowErrorBar(wo, errorMessage);
	} catch (e) {
		//nothing else to do
	}
}

/* --- The clipboard -------------------------------------------------------- *
 * Writing to the clipboard needs a click behind it: a browser allows it as the
 * answer to something the player did and at no other moment. Two ways there - the
 * modern one, and, where a browser or a page refuses it, a field that holds the
 * text and the selection for the length of one command.
 *
 * "sagen" gets the news and decides where it goes; every caller has its own place
 * for it. Without one the copy simply happens quietly.
 * ------------------------------------------------------------------------- */

/*
 * How a button of this page looks. Copied and not invented: the skin the player
 * wears decides it, and a button of ours is meant to look like one of the game's.
 *
 * But only like a button that carries WORDS. The game also has little picture
 * buttons - "button_image_info" is the info icon beside every equipment slot - and
 * those are drawn as a fixed-size image with a background picture on them. A word
 * written on one of those is squeezed into twenty pixels and unreadable. So the
 * plain "button" is looked for, the class the game's own "Änderungen durchführen"
 * wears, and a picture button is only taken when there is nothing else at all.
 */
function mmButtonClass(wurzel) {
	var knoepfe = (wurzel || document).getElementsByTagName('input');
	var ersatz = '';

	for (var i = 0; i < knoepfe.length; i++) {
		if (knoepfe[i].type !== 'button' && knoepfe[i].type !== 'submit')
			continue;

		var klasse = String(knoepfe[i].className || '');
		if (/(^|\s)button(\s|$)/.test(klasse))
			return klasse;
		if (!ersatz)
			ersatz = klasse;
	}
	return ersatz || 'button clickable';
}

/*
 * A small text link the way the game writes its own: "Einblenden", "Ausblenden",
 * the words that stand beside a heading. Not a button - the game draws those as
 * raised boxes and keeps them for what submits a form. A word beside a headline is
 * a link there, and wearing the game's own class it takes the right colour in
 * whichever skin the player has on.
 */
function mmMinorLink(text, titel) {
	var link = document.createElement('a');

	link.href = '#';
	link.className = mmMinorClass();
	if (titel)
		link.title = titel;
	link.appendChild(document.createTextNode(text));
	return link;
}

function mmMinorClass() {
	var links = document.getElementsByTagName('a');

	for (var i = 0; i < links.length; i++)
		if (/(^|\s)button_minor(\s|$)/.test(String(links[i].className)))
			return links[i].className;
	return 'button_minor';
}

function mmCopy(text, sagen, gutText) {
	var gut = gutText || 'In die Zwischenablage kopiert.';

	function melden(gelungen) {
		if (sagen)
			sagen(gelungen ? gut : 'Die Zwischenablage liess sich nicht beschreiben.',
				!gelungen);
	}

	try {
		if (window.navigator && window.navigator.clipboard
				&& window.navigator.clipboard.writeText) {
			window.navigator.clipboard.writeText(text).then(function () {
				melden(true);
			}, function () {
				melden(mmCopyByField(text));
			});
			return;
		}
	} catch (e) {
		//Then by hand instead.
	}
	melden(mmCopyByField(text));
}

function mmCopyByField(text) {
	var feld = document.createElement('textarea');

	feld.value = text;
	feld.style.cssText = 'position:fixed;top:-1000px;left:-1000px;';
	document.body.appendChild(feld);
	feld.select();

	var gut = false;
	try {
		gut = document.execCommand('copy');
	} catch (e) {
		gut = false;
	}
	document.body.removeChild(feld);
	return gut;
}

/*
 * A short word beside a button: it stands for a moment and takes itself away
 * again. A message that has to be clicked away for something that went right is
 * one click too many; one that never goes is a stain on the page.
 */
function mmFlash(wo, text, schlimm, dauer) {
	mmEmpty(wo);

	var zeile = document.createElement('span');
	zeile.className = schlimm ? 'message_error' : '';
	zeile.appendChild(document.createTextNode(text));
	wo.appendChild(zeile);

	//A failure stays: whoever has to try again should still be able to read why.
	if (schlimm)
		return zeile;

	window.setTimeout(function () {
		if (zeile.parentNode === wo)
			wo.removeChild(zeile);
	}, dauer || 2500);
	return zeile;
}

function mmShowErrorBar(functionName, errorMessage) {
	try {
		if (mmErrorBarSeen[functionName])
			return;
		mmErrorBarSeen[functionName] = true;

		var form = document.querySelector('form[name*="the_form"]');

		var bar = document.querySelector('#mm_error_bar');
		if (!bar) {
			bar = document.createElement('div');
			bar.id = 'mm_error_bar';
			bar.style.cssText = 'margin:4px 0;padding:4px 6px;font-size:12px;color:#e0a030;'
				+ 'border:1px solid #e0a030;background:rgba(0,0,0,.45)';
			bar.appendChild(document.createTextNode(
				'Das Skript ist auf einen Fehler gestossen. Einzelheiten:'));
			if (form) {
				form.insertBefore(bar, form.firstChild);
			} else if (document.body) {
				//No main form - a layout the script does not know, or a page that
				//broke off early. Without this branch the message would be swallowed,
				//and on a telephone there is no console to fall back on.
				bar.style.cssText += ';position:fixed;left:0;right:0;top:0;z-index:2147483647;'
					+ 'background:#3a2a00;margin:0';
				document.body.appendChild(bar);
			} else {
				return;
			}
		}

		var line = document.createElement('div');
		line.textContent = functionName + ': ' + errorMessage;
		bar.appendChild(line);
	} catch (e) {
		//nothing else to do
	}
}

/////////////////////////////////////////////////////////////////////////////
//////////////// Groundwork: reading and writing stored data ////////////////
/////////////////////////////////////////////////////////////////////////////

//A stored value as an object, or the fallback when it cannot be read. A damaged
//entry then counts as never stored, and the next reading writes it anew.
function mmParseStored(raw, ersatz) {
	try {
		return JSON.parse(raw);
	} catch (e) {
		return ersatz;
	}
}


//Slot -> worn items, plus the labels this page gives the slots.
function saveEquipmentSlotsIntoStorage(slots, labels, fits, names) {
	//What is WORN is replaced - that is the current state. What a place is CALLED
	//is collected. A row only exists on the equipment page while something sits in
	//it, so "Beide Hände" is only ever seen while a two-hander is worn, and
	//"Waffenhand" only while one is not. Replacing would make the dictionary
	//forget one of them every time the hero swaps weapons, and a hovered piece
	//would then find no place to compare against.
	var bisher = mmParseStored(GM_getValue(world + '_equipSlots_' + id, ''), null);
	var known = (bisher && bisher.labels && typeof bisher.labels == 'object') ? bisher.labels : { };
	for (var label in labels)
		known[label] = labels[label];

	//What a place is called is the same for every hero of the world, and a fresh
	//hero with three pieces on shows three rows. So the names are also kept for the
	//world, and every hero reads the names all of them have seen.
	var welt = loadWorldSlotLabelsLearned();
	for (var name in labels)
		welt[name] = labels[name];
	GM_setValue(world + '_equipLabels', JSON.stringify(welt));

	GM_setValue(world + '_equipSlots_' + id,
		JSON.stringify({ slots: slots, labels: known, fits: fits || { }, names: names || { } }));
}

function loadEquipmentSlotsFromStorage() {
	var labels = loadWorldSlotLabels();
	try {
		var raw = GM_getValue(world + '_equipSlots_' + id, false);
		if (!raw)
			return { slots: { }, labels: labels, fits: { }, names: { } };
		var parsed = JSON.parse(raw);
		for (var name in parsed.labels || { })
			labels[name] = parsed.labels[name];
		return {
			slots: parsed.slots || { },
			labels: labels,
			fits: parsed.fits || { },
			names: parsed.names || { }
		};
	} catch (e) {
		return { slots: { }, labels: labels, fits: { }, names: { } };
	}
}

/*
 * The wearing places as the item page names them under "Wo getragen?", each with
 * the slot of the equipment page it belongs to. This is the game's own list of
 * wearing places (trage_typ in its data interface): tr_kopf sits in go_kopf, and
 * so on. "Einhändig" and "Nicht tragbar" name no place of their own.
 */
var ITEM_SLOT_NAMES = {
	'Kopf': 'go_kopf', 'Ohren': 'go_ohren', 'Brille': 'go_brille', 'Halskette': 'go_hals',
	'Torso': 'go_torso', 'Gürtel': 'go_schaerpe', 'Umhang': 'go_umhang',
	'Schultern': 'go_rucksack', 'Arme': 'go_arme', 'Handschuhe': 'go_hand',
	'Beide Hände': 'go_beide_haende', 'Waffenhand': 'go_waffen_hand',
	'Schildhand': 'go_schild_hand', 'Beine': 'go_beine', 'Füße': 'go_fuss',
	'Orden': 'go_orden', 'Tasche': 'go_tasche', 'Ring': 'go_ring'
};

//Where a piece can be worn, by the name the item page prints under "Wo getragen?":
//the game's list above, and on top of it what the equipment page has taught.
function loadWorldSlotLabels() {
	var labels = { };
	for (var name in ITEM_SLOT_NAMES)
		labels[name] = ITEM_SLOT_NAMES[name];

	var liste = loadWorldSlotLabelsLearned();
	for (var gelernt in liste)
		labels[gelernt] = liste[gelernt];
	return labels;
}

//Only what the equipment pages of this world have taught.
function loadWorldSlotLabelsLearned() {
	var liste = mmParseStored(GM_getValue(world + '_equipLabels', ''), null);
	return (liste && typeof liste == 'object') ? liste : { };
}


/*
 * Stored data no module reads: skills, items, sets, class and race and the hero's
 * attributes under a world prefix, and the name lists of the game's data
 * interface. It is removed once, on the first run. What the modules keep under a
 * world prefix stays: the equipment and the monument, the messages, the group, the
 * battle statistics, the legend plans and the answers the skills page keeps.
 * Settings, Auto Login and everything outside a world are not touched.
 */
var ALTDATEN_BEHALTEN = /^W[A-Z]_(equipSlots_|equipLabels$|monument_|messages$|gruppe_|kstat_|legendPlan_|peek|skills_)/;
var ALTDATEN_KEY = 'mm_aufgeraeumt_19';

function altdatenAufraeumen() {
	try {
		if (GM_getValue(ALTDATEN_KEY, false))
			return 0;
		var weg = 0;
		var alle = GM_listValues();
		for (var i = 0; i < alle.length; i++) {
			var key = String(alle[i]);
			if ((/^W[A-Z]_/.test(key) && !ALTDATEN_BEHALTEN.test(key)) || /^mm_api/.test(key)) {
				GM_deleteValue(key);
				weg++;
			}
		}
		GM_setValue(ALTDATEN_KEY, true);
		return weg;
	} catch (e) {
		mmReportError('Alte Daten aufräumen', e);
		return 0;
	}
}

/*
 * Both delete buttons run through here. They differ in one thing only: whether the
 * data of the other worlds goes along. What lies across all worlds - the planner's
 * dungeon list, the configuration helpers, the collapsed sections of the battle
 * statistics - is cleared either way, because a module's leftovers are as stale as
 * a world's after a reset. The settings and the Auto Login credentials stay.
 */
function deleteStoredData(alleWelten, frage) {
	if (!window.confirm(frage))
		return false;

	var keys = storageKeysToClear(alleWelten);
	for (var i = 0; i < keys.length; i++)
		GM_deleteValue(keys[i]);

	alert(keys.length + ' Einträge wurden gelöscht. Einstellungen und Auto Login '
		+ 'sind geblieben.');
	return true;
}

function deleteAllDataForWorld() {
	return deleteStoredData(false,
		'Wirklich alle Daten der Welt ' + worldName() + ' löschen, samt dem, was die '
		+ 'übrigen Module weltübergreifend gespeichert haben? Einstellungen und Auto '
		+ 'Login bleiben stehen.');
}

/*
 * What lies in the script's storage, and what it belongs to. Read top down, first
 * match wins, so the general world entry has to stand behind the special ones.
 *
 * "bleibt" marks the two things no delete button touches: the settings, which are
 * not read-in data at all, and the Auto Login credentials, which nobody expects to
 * lose by clearing a world. The Auto Login tab has its own button for those.
 *
 * Anything that finds no entry here lands under "Sonstiges" and is deleted with
 * the rest - a module that stores something new is then listed, not overlooked.
 */
var STORAGE_KINDS = [
	{ probe: /^W[A-Z]_peek/,        name: 'Gegenstandsvergleich', welt: true },
	{ probe: /^mm_peek_/,           name: 'Gegenstandsvergleich' },
	{ probe: /^W[A-Z]_equip/,       name: 'Ausrüstung', welt: true },
	{ probe: /^W[A-Z]_monument_/,   name: 'Monument', welt: true },
	{ probe: /^W[A-Z]_skills_/,     name: 'Fertigkeitenseite', welt: true },
	{ probe: /^W[A-Z]_gruppe_/,     name: 'Gruppe', welt: true },
	{ probe: /^W[A-Z]_kstat_/,      name: 'Kampfstatistik', welt: true },
	{ probe: /^W[A-Z]_legendPlan_/, name: 'Legendenrechner: Stärken und Schwächen', welt: true },
	{ probe: /^W[A-Z]_messages$/,   name: 'Meldungen des Skripts', welt: true },
	{ probe: /^W[A-Z]_/,            name: 'Sonstiges dieser Welt', welt: true },
	{ probe: /^mm_settings$/,       name: 'Einstellungen', bleibt: true },
	{ probe: /^mm_aufgeraeumt_/,    name: 'Einstellungen', bleibt: true },
	{ probe: /^mm_login/,           name: 'Auto Login', bleibt: true },
	{ probe: /^wod_dp_v3_/,         name: 'Dungeonplaner' },
	{ probe: /^mm_konfig_/,         name: 'Kampfkonfigurationen' },
	{ probe: /^mm_kstat/,           name: 'Kampfstatistik' },
	{ probe: /^mm_vg_/,             name: 'Verbrauchsgüter-Preise' },
	{ probe: /^mm_bbcode/,          name: 'BBCode-Leiste' },
	{ probe: /./,                   name: 'Sonstiges' }
];

function storageKindOf(key) {
	for (var i = 0; i < STORAGE_KINDS.length; i++)
		if (STORAGE_KINDS[i].probe.test(key))
			return STORAGE_KINDS[i];
	return STORAGE_KINDS[STORAGE_KINDS.length - 1];
}

//Everything in storage, counted and measured, grouped the way the window shows it:
//this world by kind, every other world as one line, and what lies across all worlds
//by module.
function storageInventory() {
	var welt = { }, andere = { }, ueber = { }, keys;

	try {
		keys = GM_listValues();
	} catch (e) {
		return null;
	}

	function zaehle(topf, name, key, bleibt) {
		var zeile = topf[name] || (topf[name] = { name: name, zahl: 0, zeichen: 0,
			bleibt: bleibt === true });
		zeile.zahl++;
		zeile.zeichen += String(key).length + String(GM_getValue(key, '')).length;
	}

	for (var i = 0; i < keys.length; i++) {
		var key = String(keys[i]);
		var art = storageKindOf(key);

		if (art.welt)
			zaehle(key.substring(0, 2) === world ? welt : andere,
				key.substring(0, 2) === world
					? art.name : 'Welt ' + worldNameOf(key.substring(0, 2)), key);
		else
			zaehle(ueber, art.name, key, art.bleibt);
	}
	return { welt: storageRows(welt, 'welt'), andere: storageRows(andere, 'andere'),
		ueber: storageRows(ueber, 'ueber') };
}

/*
 * The keys behind one line of that list. The line says which block it stands in
 * and what it is called, and that is enough to find them again: a kind of this
 * world, a whole other world, or a kind that lies across all of them.
 *
 * What is protected stays protected here as well.
 */
function storageKeysOfRow(block, name) {
	var out = [], keys;

	try {
		keys = GM_listValues();
	} catch (e) {
		return out;
	}

	for (var i = 0; i < keys.length; i++) {
		var key = String(keys[i]);
		var art = storageKindOf(key);
		if (art.bleibt === true)
			continue;

		var eigene = key.substring(0, 2) === world;

		if (block === 'welt' && art.welt && eigene && art.name === name)
			out.push(key);
		else if (block === 'andere' && art.welt && !eigene
				&& 'Welt ' + worldNameOf(key.substring(0, 2)) === name)
			out.push(key);
		else if (block === 'ueber' && !art.welt && art.name === name)
			out.push(key);
	}
	return out;
}

//One line of the list, and nothing else. Whoever wants to start one module over
//should not have to throw away everything the others have collected.
function deleteStorageRow(block, name) {
	try {
		var keys = storageKeysOfRow(block, name);
		if (!keys.length)
			return false;

		if (!window.confirm('Wirklich "' + name + '" löschen? '
				+ keys.length + (keys.length === 1 ? ' Eintrag' : ' Einträge') + '.'))
			return false;

		for (var i = 0; i < keys.length; i++)
			GM_deleteValue(keys[i]);
		return true;
	} catch (e) {
		mmReportError('deleteStorageRow', e);
		return false;
	}
}

function storageRows(topf, block) {
	var out = [];

	for (var name in topf)
		out.push(topf[name]);
	out.sort(function (a, b) { return b.zeichen - a.zeichen; });

	for (var i = 0; i < out.length; i++) {
		out[i].kb = Math.round(out[i].zeichen / 1024);
		out[i].block = block;
	}
	return out;
}

//Which keys a delete takes. The two protected kinds are never in it.
function storageKeysToClear(alleWelten) {
	var out = [], keys;

	try {
		keys = GM_listValues();
	} catch (e) {
		return out;
	}

	for (var i = 0; i < keys.length; i++) {
		var key = String(keys[i]);
		var art = storageKindOf(key);

		if (art.bleibt === true)
			continue;
		if (art.welt && !alleWelten && key.substring(0, 2) !== world)
			continue;
		out.push(key);
	}
	return out;
}

function deleteAllDataEverywhere() {
	return deleteStoredData(true,
		'Wirklich die gespeicherten Daten ALLER Welten und aller Module löschen? '
		+ 'Einstellungen und Auto Login bleiben stehen.');
}

/////////////////////////////////////////////////////////////////////////////
///////////////////////// Groundwork: bonus values //////////////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * One bonus, as numbers. A bonus in this game has up to four parts, and they are
 * kept apart until the throw that uses them is known, because two of them depend
 * on it:
 *
 *   f    a fixed number                            +2
 *   hs   a share of the hero level, in percent     +20% der Heldenstufe
 *   fr   a share of the skill rank, in percent     +50% des Fertigkeitenrangs
 *   p    a factor on the throw, 1 is none          -10%  ->  0.9
 *
 * A part that is not there is left out, so {} is no bonus at all. Two bonuses on
 * the same thing add up part by part, except the factors: those multiply, because
 * ten percent and ten percent make twenty-one.
 *
 * Damage, armour and weakness speak of three success levels at once, a hit, a
 * good hit and a critical one. They are a list of three such values. wertLeer,
 * wertPlus, wertMitRang and wertKurz take either shape; wertFest takes a single
 * value.
 */

var WERT_TEILE = ['f', 'hs', 'fr'];

//The three success levels, in the order the game prints them. A damage bonus says
//something for each of them.
var DAMAGE_LEVELS = ['erfolg', 'gut', 'kritisch'];

//Six places are more than any bonus in the game has, and they keep sums such as
//0.1 + 0.2 from turning up with a tail of digits.
function wertRund(zahl) {
	return Math.round(zahl * 1000000) / 1000000;
}


function wertFaktor(wert) {
	return (wert && typeof wert.p == 'number') ? wert.p : 1;
}

function wertLeer(wert) {
	if (Array.isArray(wert)) {
		for (var i = 0; i < wert.length; i++)
			if (!wertLeer(wert[i]))
				return false;
		return true;
	}
	return !wert || (!wert.f && !wert.hs && !wert.fr && wertFaktor(wert) === 1);
}

//Two bonuses on the same thing, as one.
function wertPlus(a, b) {
	if (Array.isArray(a) || Array.isArray(b)) {
		var liste = [];
		for (var k = 0; k < DAMAGE_LEVELS.length; k++)
			liste.push(wertPlus(a ? a[k] : null, b ? b[k] : null));
		return liste;
	}

	var out = { };
	for (var i = 0; i < WERT_TEILE.length; i++) {
		var summe = wertRund(((a && a[WERT_TEILE[i]]) || 0) + ((b && b[WERT_TEILE[i]]) || 0));
		if (summe)
			out[WERT_TEILE[i]] = summe;
	}
	var faktor = wertRund(wertFaktor(a) * wertFaktor(b));
	if (faktor !== 1)
		out.p = faktor;
	return out;
}


/*
 * A bonus that arrives as a bare number with its kind beside it, the way the data
 * interface sends typed values:
 *
 *   bo_wert           a fixed number                          3  ->  f 3
 *   bo_prozent        percent, absolute: 110 is +10%        110  ->  p 1.1
 *   bo_stufen_faktor  a share of the hero level              20  ->  hs 20
 *   bo_wirk_faktor    a share of the skill rank              50  ->  fr 50
 *
 * A percentage of nought counts as "not set". Kinds not listed count for nothing.
 */
var WERT_ARTEN = {
	bo_wert: 'f',
	bo_prozent: 'p',
	bo_stufen_faktor: 'hs',
	bo_wirk_faktor: 'fr'
};

function wertAusTyp(typ, zahl) {
	if (!Object.prototype.hasOwnProperty.call(WERT_ARTEN, typ))
		return { };

	var wert = parseFloat(zahl);
	if (isNaN(wert) || wert === 0)
		return { };
	wert = Math.round(wert * 100) / 100;

	var out = { };
	if (WERT_ARTEN[typ] === 'p') {
		if (wert !== 100)
			out.p = wertRund(wert / 100);
		return out;
	}
	out[WERT_ARTEN[typ]] = wert;
	return out;
}

//A bare number, as opposed to printed text.
function wertIstZahl(wert) {
	if (typeof wert === 'number')
		return true;
	return typeof wert === 'string' && /^\s*[+-]?\d+(\.\d+)?\s*$/.test(wert);
}

/*
 * A bonus as the game prints it, one piece or several in a row:
 *
 *   +3                           f +3
 *   -10%                         p 0.9
 *   +10% der Heldenstufe         hs +10
 *   +2 x Heldenstufe             hs +200
 *   +Heldenstufe                 hs +100
 *   +50% des Fertigkeitenrangs   fr +50
 *   -3 x Fertigkeitenrang        fr -300
 *   +Fertigkeitenrang            fr +100
 *
 * A piece begins at its sign, so "+2 +Fertigkeitenrang" is two of them. A nought
 * is no bonus.
 */
function wertAusText(text) {
	var stuecke = String(text == null ? '' : text).match(/[+-]?[^+-]+/g) || [];
	var out = { };

	for (var i = 0; i < stuecke.length; i++)
		out = wertPlus(out, wertStueck(stuecke[i]));
	return out;
}

function wertStueck(text) {
	var teile = String(text).trim().match(/^([+-]?)\s*(\d+(?:[.,]\d+)?)?\s*(%)?\s*(x\s)?\s*(.*)$/i);
	var out = { };
	if (!teile)
		return out;

	var zeichen = (teile[1] === '-') ? -1 : 1;
	var zahl = teile[2] ? parseFloat(teile[2].replace(',', '.')) : null;
	var worauf = /Heldenstufe/i.test(teile[5]) ? 'hs'
		: (/Fertigkeit/i.test(teile[5]) ? 'fr' : '');

	if (worauf) {
		var anteil = (zahl === null) ? 100 : (teile[4] ? zahl * 100 : zahl);
		if (anteil)
			out[worauf] = zeichen * anteil;
	} else if (zahl) {
		if (teile[3])
			out.p = wertRund(1 + zeichen * zahl / 100);
		else
			out.f = zeichen * zahl;
	}
	return out;
}

//Three values from one printed row, "+1 / 0 / +2", or null where the row does not
//hold three.
function wertDreiAusText(text) {
	var teile = String(text == null ? '' : text).split('/');
	if (teile.length !== DAMAGE_LEVELS.length)
		return null;

	var out = [];
	for (var k = 0; k < teile.length; k++)
		out.push(wertAusText(teile[k]));
	return out;
}

/*
 * A value written short, for a tooltip or a comparison: "+1 +20%HS", "+50%FR",
 * "-10%", three of them as "+1/+1/0". HS stands for the hero level, FR for the
 * skill rank. No bonus at all is a nought.
 */
function wertKurz(wert) {
	if (Array.isArray(wert)) {
		var drei = [];
		for (var k = 0; k < wert.length; k++)
			drei.push(wertKurz(wert[k]));
		return drei.join('/');
	}

	var mitZeichen = function (zahl) {
		zahl = Math.round(zahl * 100) / 100;
		return (zahl > 0 ? '+' : '') + zahl;
	};

	var out = [];
	if (wert && wert.f)
		out.push(mitZeichen(wert.f));
	if (wert && wert.hs)
		out.push(mitZeichen(wert.hs) + '%HS');
	if (wert && wert.fr)
		out.push(mitZeichen(wert.fr) + '%FR');
	if (wertFaktor(wert) !== 1)
		out.push(mitZeichen((wertFaktor(wert) - 1) * 100) + '%');
	return out.length ? out.join(' ') : '0';
}

/////////////////////////////////////////////////////////////////////////////
//////////////////// Groundwork: the male form of a name ////////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * Class and race carry the hero's gender in their name, and half the game does
 * not: class.php?name=Dieb gives the class, class.php?name=Diebin gives "Fehler",
 * and the forum's [class:...] tag behaves the same way. Whoever looks such a name
 * up needs the male form.
 *
 * Only the names that really differ stand here. Anything not in the list is the
 * same in both, and is handed back as it came.
 */
var HERO_MALE_FORMS = {
	'Grenzländerin': 'Grenzländer',
	'Kerasa': 'Kerasi',
	'Mag-Mor-Elfe': 'Mag-Mor-Elf',
	'Nebelwichtin': 'Nebelwicht',
	'Rashana': 'Rashani',
	'Tirem-Ag-Elfe': 'Tirem-Ag-Elf',
	'Gnerka': 'Gnerk',
	'Barbarin': 'Barbar',
	'Bardin': 'Barde',
	'Diebin': 'Dieb',
	'Gauklerin': 'Gaukler',
	'Gelehrte': 'Gelehrter',
	'Gestaltwandlerin': 'Gestaltwandler',
	'Gladiatorin': 'Gladiator',
	'Hasardeurin': 'Hasardeur',
	'Jägerin': 'Jäger',
	'Magierin': 'Magier',
	'Priesterin': 'Priester',
	'Prophetin': 'Prophet',
	'Quacksalberin': 'Quacksalber',
	'Ritterin': 'Ritter',
	'Schamanin': 'Schamane',
	'Schützin': 'Schütze'
};

function heroMaleForm(name) {
	var clean = String(name == null ? '' : name).trim();
	return HERO_MALE_FORMS[clean] || clean;
}

/////////////////////////////////////////////////////////////////////////////
/////////////////////// Reader: item names and slots ////////////////////////
/////////////////////////////////////////////////////////////////////////////

//The item's name, taken from the link's own address. That is the spelling the game
//uses, and the one place no other script can have decorated: the visible text may
//carry markup that a second script wrapped around it.
function itemNameFromLink(anchor) {
	if (!anchor)
		return '';

	var where = (anchor.getAttribute('href') || '') + ' ' + (anchor.getAttribute('onclick') || '');
	//No quote characters in this pattern on purpose: the name is followed by & in
	//both spellings, and a regex carrying ' and " trips up simple source scanners.
	var match = where.match(/[?&]name=([^&\s]*)/);
	if (match) {
		try {
			var raw = match[1].replace(/['"].*$/, '');
			var name = decodeURIComponent(raw.replace(/\+/g, ' ')).trim();
			if (name)
				return name;
		} catch (e) {
			//broken encoding - then the text after all
		}
	}

	//Fallback: the visible text, without markup and without a trailing use count.
	return String(anchor.textContent || '').replace(/\s*\(\d+\s*\/\s*\d+\)\s*$/, '').trim();
}

//Anything that ever reached storage as a name goes through here on the way back
//out, so an entry poisoned by another script heals itself on the next round.
function itemNamePlain(text) {
	return String(text == null ? '' : text)
		.replace(/<[^>]*>/g, '')
		.replace(/\s+/g, ' ')
		.trim();
}

/////////////////////////////////////////////////////////////////////////////
//////////////////////// Reader: the equipment page /////////////////////////
/////////////////////////////////////////////////////////////////////////////

/* --- Which piece may go where --------------------------------------------
 * The equipment page carries, for every place, a select listing the items that
 * may be put there - and the game fills those lists itself. That is the whole
 * classification we need: a piece offered for both hands is one-handed, a piece
 * offered for the weapon hand only can never go into the shield hand.
 *
 * Only the pieces actually WORN are recorded, and only which places accept them.
 * That is a handful of entries, and it is exactly what the comparison needs to
 * work out what a find would displace.
 * ------------------------------------------------------------------------- */
function gearReadSlotFits(doc, slots) {
	var fits = { };
	try {
		//Which instance ids does each place accept?
		var accepts = { };
		var selects = doc.querySelectorAll('select[name*="LocationEquip["]');
		for (var i = 0; i < selects.length; i++) {
			var key = (selects[i].getAttribute('name') || '').match(/LocationEquip\[(go_[a-z_]+)\]/);
			if (!key)
				continue;
			key = key[1];
			if (!accepts[key])
				accepts[key] = { };

			var options = selects[i].querySelectorAll('option');
			for (var j = 0; j < options.length; j++) {
				//"0" is whatever is worn there right now, a negative value is the
				//game's own placeholder for taking the piece off.
				var value = (options[j].getAttribute('value') || '').trim();
				if (/^\d+$/.test(value) && value != '0')
					accepts[key][value] = true;
			}
			//The piece worn in this place obviously fits it.
			var here = slots[key] || [];
			for (var k = 0; k < here.length; k++)
				accepts[key][here[k]] = true;
		}

		//Turn it round: for every worn piece, the places that accept it.
		for (var slot in slots)
			for (var m = 0; m < slots[slot].length; m++) {
				var instance = slots[slot][m];
				if (fits[instance])
					continue;
				var where = [];
				for (var candidate in accepts)
					if (accepts[candidate][instance])
						where.push(candidate);
				if (where.length)
					fits[instance] = where;
			}
	} catch (e) {
		//Without this the comparison falls back to the place a piece sits in.
	}
	return fits;
}


/*
 * The places on the equipment page: which piece sits where, what it is called,
 * what the places are called, and which hands a piece in the hands accepts. The
 * item compare works from it.
 */
function gearIsEquipmentPage() {
	var view = document.querySelector('form[name="the_form"] > input[name="view"]');
	return page == 'items.php' && !!view && view.value == 'gear';
}

function gearReadSlots() {
	var equipped = document.querySelectorAll('form > table td.middle > input[name*="LocationDefault"]');

	//Which slot carries which item, and what the slots are called on this page. The
	//item compare needs both to put a find next to the right worn piece. The labels
	//are learned rather than written into the script - "Gürtel" is go_schaerpe
	//internally, and pairs like that are better not invented.
	var slots = { };
	var slotLabels = { };
	var names = { };

	for (var i = 0; i < equipped.length; i++) {
		var temp = equipped[i].value.trim();
		var name = '';

		var slotKey = (equipped[i].getAttribute('name') || '').match(/LocationDefault\[(go_[a-z_]+)\]/);
		slotKey = slotKey ? slotKey[1] : '';
		if (slotKey) {
			var row = equipped[i].closest ? equipped[i].closest('tr') : null;
			var labelCell = row ? row.querySelector('td.texttoken') : null;
			if (labelCell) {
				//"Orden #3" and "Orden #4" are the same slot.
				var label = labelCell.textContent.replace(/\s*#\d+\s*$/, '').trim();
				if (label)
					slotLabels[label] = slotKey;
			}
		}

		//Check if it is an item with maximum uses.
		var checkedOption = equipped[i].parentNode.querySelector('option:checked');
		if (checkedOption) {
			name = checkedOption.textContent;
			var temp2 = checkedOption.innerHTML;
			var temp3 = temp2.split('(');
			if (temp3.length > 1) {
				temp2 = temp3[temp3.length-1].split(')')[0];
				temp2 = temp2.split('/');

				//Look if both parts of the (.../...) part of the item are numbers
				if (temp2[0].search(/\D/) < 0 && temp2[1].search(/\D/) < 0) {

					//Rebuild the item name
					for (var j = 1; j < temp3.length-1; j++)
						temp3[0] += '(' + temp3[j];

					//It is a verbrauchsgut
					temp = temp3[0].trim();
					name = temp;
				}
			}
		}

		if (temp != '' && slotKey) {
			if (!slots[slotKey])
				slots[slotKey] = [];
			slots[slotKey].push(temp);
			//The name of the piece, the way the item compare keeps what it has read.
			if (itemNamePlain(name))
				names[temp] = itemNamePlain(name);
		}
	}

	saveEquipmentSlotsIntoStorage(slots, slotLabels, gearReadSlotFits(document, slots), names);
}

/* --- The equipment as BBCode -------------------------------------------- *
 * What the hero is wearing, and above all which gems sit in which piece, stands
 * on the equipment page and nowhere else, so it is written out there.
 *
 * The shape of the table follows Fabian Dellwing's equipment exporter, down to the gem
 * codes, so that it looks in the forum the way readers there expect.
 * ----------------------------------------------------------------------- */

//Which group a slot belongs to, and in which order the groups are written. The
//slot key names the kind of place; the number in the second bracket -
//go_ring[3] - is only its position and is not part of the key.
//
//"spoiler" names a block that can be folded away behind a heading. The medals are
//the one block nobody reads: a long list that says what the hero has been awarded
//and nothing about how he fights. Folded, it is there for whoever wants it and out
//of the way for everybody else - and whoever wants it open says so with a tick.
var GEAR_EXPORT_GROUPS = [
	{ key: '',          title: 'Ausrüstung' },
	{ key: 'go_tasche', title: 'Tasche' },
	{ key: 'go_ring',   title: 'Ringe' },
	{ key: 'go_orden',  title: 'Orden', spoiler: 'Orden' }
];

//alt text of the gem image -> the forum's code for it.
var GEAR_GEM_CODES = {
	'leer': ':g0:',
	'weiß': ':gx:', 'weiß/gold': ':gk:', 'weiß/weiß': ':gX:', 'weiß/schwarz': ':gw:',
	'gelb': ':g1:', 'gelb/gold': ':g5:', 'gelb/weiß': ':gB:',
	'orange': ':ga:', 'orange/gold': ':gi:', 'orange/weiß': ':gA:',
	'türkis': ':g3:', 'türkis/gold': ':g8:', 'türkis/weiß': ':gG:',
	'blau': ':g4:', 'blau/gold': ':gb:', 'blau/weiß': ':gH:',
	'violett': ':g6:', 'violett/gold': ':gf:', 'violett/weiß': ':gI:',
	'rot': ':gc:', 'rot/gold': ':gj:', 'rot/weiß': ':gC:',
	'rubinrot': ':g9:', 'rubinrot/gold': ':gh:', 'rubinrot/weiß': ':gJ:',
	'hellgrün': ':gl:', 'hellgrün/gold': ':gp:', 'hellgrün/weiß': ':gL:',
	'grün': ':gn:', 'grün/gold': ':gr:', 'grün/weiß': ':gN:',
	'dunkelgrün': ':gm:', 'dunkelgrün/gold': ':gq:', 'dunkelgrün/weiß': ':gM:',
	'beige': ':g2:', 'beige/gold': ':g7:', 'beige/weiß': ':gF:',
	'braun': ':gd:', 'braun/gold': ':gK:', 'braun/weiß': ':gD:',
	'rosa': ':ge:', 'rosa/gold': ':go:', 'rosa/weiß': ':gE:',
	'silber': ':gy:', 'silber/gold': ':gt:', 'silber/weiß': ':gY:',
	'schwarz': ':gz:', 'schwarz/gold': ':gu:', 'schwarz/weiß': ':gZ:'
};

//The game decorates the name in the dropdown: "(3/5)" for a piece with a limited
//number of uses, a trailing "!" for a group item, and "!! " in front of one that
//needs a reset point before it can be taken off. None of that belongs in a build.
function gearExportCleanName(name) {
	var text = String(name || '').trim();
	if (text.indexOf('!! ') > -1)
		text = text.split('!! ')[1];
	if (/\(\d+\/\d+\)$/.test(text))
		text = text.split(' (')[0];
	return text.replace(/!+$/, '').trim();
}

function gearBuildExport(document) {
	var rows = document.querySelectorAll('form > table td.middle > input[name*="LocationDefault"]');
	var groups = { };

	for (var i = 0; i < rows.length; i++) {
		var row = rows[i].closest ? rows[i].closest('tr') : null;
		if (!row)
			continue;

		var option = rows[i].parentNode.querySelector('option:checked');
		var name = gearExportCleanName(option ? option.textContent : '');
		if (!name)
			continue;

		var labelCell = row.querySelector('td.texttoken');
		var label = labelCell ? labelCell.textContent.split(' #')[0].trim() : '';

		var keyMatch = (rows[i].getAttribute('name') || '').match(/LocationDefault\[(go_[a-z_]+)\]/);
		var key = keyMatch ? keyMatch[1] : '';

		//The first image in the row is the condition icon, everything after it is a
		//gem. An empty socket has its own picture and its own code.
		var pictures = row.getElementsByTagName('img');
		var gems = '';
		for (var g = 1; g < pictures.length; g++)
			gems += GEAR_GEM_CODES[pictures[g].getAttribute('alt')] || '';

		var group = groups[key] || (groups[key] = []);
		group.push('[tr][td]' + label + '[/td][td][item:' + name + '] ' + gems + '[/td][/tr]');
	}

	var out = [];
	for (var b = 0; b < GEAR_EXPORT_GROUPS.length; b++) {
		var block = GEAR_EXPORT_GROUPS[b];
		var lines = block.key ? groups[block.key] : gearExportRest(groups);
		if (!lines || !lines.length)
			continue;
		var tabelle = '[table border=1]' + lines.join('') + '[/table]';
		out.push((block.spoiler && FEATURES.gearOrdenSpoiler === true)
			? '[spoiler title="' + block.spoiler + '"]' + tabelle + '[/spoiler]'
			: tabelle);
	}
	return out.join('[br]');
}

//Everything that is not a bag, a ring or a medal: head to toe, in the order the
//page lists it.
function gearExportRest(groups) {
	var named = { };
	for (var i = 1; i < GEAR_EXPORT_GROUPS.length; i++)
		named[GEAR_EXPORT_GROUPS[i].key] = true;

	var out = [];
	for (var key in groups)
		if (!named[key])
			out = out.concat(groups[key]);
	return out;
}

/*
 * The equipment as BBCode, from a button on the equipment page, for whoever wants
 * to show what his hero is wearing.
 *
 * Nothing is fetched for it: the list is read off the page the button sits on, and
 * that page is already open.
 */
function gearExportButtonInit() {
	var form = document.querySelector('form[name="the_form"]');
	var view = document.querySelector('form[name="the_form"] > input[name="view"]');

	if (!form || !view || view.value != 'gear'
			|| document.getElementById('mm_gear_export'))
		return;

	//A small link, like the "Einblenden" and "Ausblenden" the game writes beside its
	//own headings. Beside a headline that is what the eye expects, and it is the
	//game's own class, so every skin paints it right.
	var knopf = mmMinorLink('Ausrüstung kopieren',
		'Legt die angelegte Ausrüstung als BBCode in die Zwischenablage');
	knopf.id = 'mm_gear_export';
	knopf.style.cssText = 'margin-left:10px;vertical-align:middle;'
		+ 'font-size:12px;font-weight:normal;';

	var note = document.createElement('span');
	note.id = 'mm_gear_export_note';
	note.style.cssText = 'margin-left:6px;vertical-align:middle;'
		+ 'font-size:11px;font-weight:normal;';

	knopf.addEventListener('click', function (event) {
		if (event && event.preventDefault)
			event.preventDefault();

		var text = gearBuildExport(document);
		if (!text) {
			mmFlash(note, 'Hier steht keine angelegte Ausrüstung.', true);
			return;
		}

		mmCopy(text, function (wort, schlimm) {
			mmFlash(note, wort, schlimm);
		}, 'Ausrüstung liegt in der Zwischenablage.');
	}, false);

	//Behind the page's own headline, on its line. A box of its own above the form
	//would push the whole page down by a line for the sake of one button.
	var titel = form.getElementsByTagName('h1')[0];
	if (titel) {
		titel.appendChild(knopf);
		titel.appendChild(note);
		return titel;
	}

	//No headline - a layout the script does not know. Then it goes where there is
	//certainly room.
	var kasten = document.createElement('p');
	kasten.appendChild(knopf);
	kasten.appendChild(note);
	form.insertBefore(kasten, form.firstChild);
	return kasten;
}


/////////////////////////////////////////////////////////////////////////////
/////////////////////////// Reader: the item page ///////////////////////////
/////////////////////////////////////////////////////////////////////////////


/*
 * The bonuses an item page prints for the owner, in one fixed shape:
 * { Besitzer: { Eigenschaften: { Hitpoints: value } } }. The item compare keeps
 * every page it reads in that shape, finds and worn pieces alike, so the two
 * sides always line up.
 *
 * What the owner gets while wearing the piece goes under Besitzer. A row marked
 * (a) counts only while the piece is used; those go apart, under Anwendung, where
 * the compare can show them on request. The other marks of a row, (z) for a bonus
 * that only adds to damage of a kind already being done and (r) for one that
 * needs a particular use, stay with the row: it is kept under its name with the
 * mark behind it, so it is only ever set against a bonus of the same kind. What
 * the piece does to the one it is used on is not the owner's at all.
 */
var ITEM_PAGE_SECTIONS = {
	'Boni auf Eigenschaften': 'Eigenschaften',
	'Boni auf Paraden': 'Paraden',
	'Boni auf Angriffe': 'Angriffe',
	'Boni auf Schaden': 'Schaden',
	'Boni auf Rüstung': 'Rüstung',
	'Boni auf den Rang von Fertigkeiten': 'Fertigkeitsrang',
	'Boni auf die Wirkung von Fertigkeiten': 'Wirkung'
};

//The sections whose rows carry three values and the kind of attack beside them.
var ITEM_PAGE_TRIPLES = ['Schaden', 'Rüstung', 'Anfälligkeit'];

/*
 * A gem changes one single piece. The item page says so itself, by the colour of a
 * value: one class for a bonus the piece has only through a gem, another for one
 * the gem has made higher or lower. ohneVeredelung leaves the first kind out, so
 * that what is read is what every piece of that name grants. For the second kind
 * the page shows only the changed value; what it was before is not on it.
 */
var ITEM_GEM_ONLY = '[class*="_only_by_gem"]';
var ITEM_GEM_ALSO = '[class*="_also_by_gem"]';

//What the gems of the piece on this page have done to its bonuses: nothing
//('keine'), only added some ('nur'), or changed one that was there ('auch').
function itemPageGemMarks(doc) {
	var tabellen = 'form div#link > table.content_table ';
	if (doc.querySelector(tabellen + ITEM_GEM_ALSO))
		return 'auch';
	return doc.querySelector(tabellen + ITEM_GEM_ONLY) ? 'nur' : 'keine';
}

function itemPageReadBonuses(doc, ohneVeredelung) {
	var besitzer = { };
	var anwendung = { };
	var marken = { };
	var fussnoten = { };
	var teile = doc.querySelectorAll('form div#link > h2, form div#link > h3, '
		+ 'form div#link > table.content_table, form div#link > font');
	var fuerBesitzer = false;
	var abschnitt = '';

	for (var i = 0; i < teile.length; i++) {
		var knoten = teile[i];
		var text = knoten.textContent.replace(/\s+/g, ' ').trim();

		if (knoten.tagName === 'H2') {
			fuerBesitzer = /Besitzer/.test(text);
			abschnitt = '';
		} else if (knoten.tagName === 'H3') {
			var link = knoten.querySelector('a');
			abschnitt = ITEM_PAGE_SECTIONS[text]
				|| ((link && link.textContent.trim() == 'Anfälligkeit') ? 'Anfälligkeit' : '');
		} else if (knoten.tagName === 'FONT') {
			itemPageReadFootnote(knoten, fussnoten);
		} else if (fuerBesitzer && abschnitt && !knoten.querySelector('tfoot')) {
			itemPageReadTable(knoten, abschnitt, besitzer, anwendung, ohneVeredelung);
			var kopf = itemPageMarkLetters(itemPageMarks(knoten.querySelector('tr.header') || knoten))
				.filter(function (b) { return b !== 'a'; });
			if (kopf.length)
				marken[abschnitt] = kopf;
		}
	}

	return { Besitzer: besitzer, Anwendung: anwendung, Marken: marken, Fussnoten: fussnoten };
}

/*
 * A mark in the head of a table stands for every row in it: "Schadensbonus (r)"
 * says it of every damage bonus the piece has. Those are kept per part, under
 * Marken, and shown beside the rows, but they are not made part of a row's name -
 * every piece's damage table carries the same one, and the pieces known from the
 * skills page's data would then never meet the ones read here.
 *
 * What a mark means the page says itself, underneath, in small print: "(r) wird
 * bei normalen / guten / kritischen Treffern zur Wirkung der benutzten Waffe
 * addiert". That text is kept as it is and shown with the mark.
 */
function itemPageReadFootnote(knoten, fussnoten) {
	var marke = knoten.querySelector('sup');
	var buchstabe = marke ? itemPageMarkLetters(marke.textContent)[0] : null;
	if (!buchstabe)
		return false;
	var kopie = knoten.cloneNode(true);
	var sups = kopie.querySelectorAll('sup');
	for (var i = 0; i < sups.length; i++)
		sups[i].parentNode.removeChild(sups[i]);
	var text = kopie.textContent.replace(/\s+/g, ' ').trim();
	if (text && !fussnoten[buchstabe])
		fussnoten[buchstabe] = text;
	return !!text;
}

function itemPageReadTable(tabelle, abschnitt, besitzer, anwendung, ohneVeredelung) {
	var zeilen = tabelle.querySelectorAll('tr.row0, tr.row1');
	var dreifach = ITEM_PAGE_TRIPLES.indexOf(abschnitt) > -1;

	for (var j = 0; j < zeilen.length; j++) {
		var marken = itemPageMarkLetters(itemPageMarks(zeilen[j]));
		var ziel = marken.indexOf('a') > -1 ? anwendung : besitzer;

		var zellen = zeilen[j].querySelectorAll('td');
		var wertZelle = null;
		for (var z = 0; z < zellen.length && !wertZelle; z++)
			if (zellen[z].querySelector('span'))
				wertZelle = zellen[z];
		if (!zellen.length || !wertZelle)
			continue;

		var worauf = itemPageBonusOn(zellen[0], abschnitt);
		if (dreifach && zellen[1] && zellen[1] !== wertZelle) {
			var angriff = zellen[1].innerHTML.split('<')[0].trim();
			if (angriff)
				worauf = worauf + ' (' + angriff + ')';
		}
		if (!worauf)
			continue;
		worauf += itemPageMarkLabel(marken);

		var roh = wertZelle.cloneNode(true);
		var marken = roh.querySelectorAll('sup');
		for (var m = 0; m < marken.length; m++)
			marken[m].parentNode.removeChild(marken[m]);
		//A nought in its place, so that a row of three keeps its three.
		var veredelt = ohneVeredelung ? roh.querySelectorAll(ITEM_GEM_ONLY) : [];
		for (var v = 0; v < veredelt.length; v++)
			veredelt[v].textContent = '0';
		var zahl = roh.textContent.replace(/\s+/g, ' ').trim();

		var wert = dreifach ? wertDreiAusText(zahl) : wertAusText(zahl);
		if (!wert) {
			var einer = wertAusText(zahl);
			wert = [einer, einer, einer];
		}
		if (wertLeer(wert))
			continue;

		if (!ziel[abschnitt])
			ziel[abschnitt] = { };
		ziel[abschnitt][worauf] = ziel[abschnitt][worauf]
			? wertPlus(ziel[abschnitt][worauf], wert) : wert;
	}
}

//The little marks behind a row, "(a)" and "(z)", all of them as one text.
function itemPageMarks(zeile) {
	var marken = zeile.querySelectorAll('sup');
	var text = '';
	for (var i = 0; i < marken.length; i++)
		text += marken[i].textContent;
	return text;
}

//"(a)(z)" -> ['a', 'z'].
function itemPageMarkLetters(text) {
	var out = [], treffer;
	var re = /\(([a-z])\)/g;
	while ((treffer = re.exec(String(text || ''))) !== null)
		if (out.indexOf(treffer[1]) < 0)
			out.push(treffer[1]);
	return out;
}

//What goes behind the name of a row: every mark but (a), which has a part of its
//own. "Feuerschaden (Nahkampf) (z)".
function itemPageMarkLabel(buchstaben) {
	var out = '';
	for (var i = 0; i < buchstaben.length; i++)
		if (buchstaben[i] !== 'a')
			out += ' (' + buchstaben[i] + ')';
	return out;
}

//What a row works on: the name the page gives it, a whole class of skills by the
//class name alone.
function itemPageBonusOn(zelle, abschnitt) {
	var link = zelle.querySelector('a');
	return itemPageClassName((link || zelle).innerHTML.trim(), abschnitt);
}

//The page writes a whole class of skills as "alle Fertigkeiten der Klasse
//<i>Bildung</i>". It is kept as "Bildung", and in the effect table as
//"<i>Bildung</i>".
function itemPageClassName(name, abschnitt) {
	var klasse = String(name).match(/^alle Fertigkeiten der Klasse\s*<i>([\s\S]*)<\/i>$/);
	if (!klasse)
		return name;
	return (abschnitt == 'Wirkung') ? '<i>' + klasse[1].trim() + '</i>' : klasse[1].trim();
}

/////////////////////////////////////////////////////////////////////////////
/////////////////////// Groundwork: the message list ////////////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * Whatever the script has to report without interrupting anyone: an error in a
 * module, a page that was not what it expected. The list lives at the bottom of
 * the options window rather than on the game page, and it is stored, so it
 * survives a reload of the page.
 */

function mmMessagesKey() {
	return world + '_messages';
}

function mmMessagesLoad() {
	try {
		var raw = GM_getValue(mmMessagesKey(), false);
		if (!raw)
			return [];
		var list = JSON.parse(raw);
		return (list && list.length) ? list : [];
	} catch (e) {
		return [];
	}
}

function mmMessagesSave(list) {
	try {
		GM_setValue(mmMessagesKey(), JSON.stringify(list.slice(-MESSAGES_MAX)));
	} catch (e) {
		//a message about a message helps nobody
	}
}

function mmMessagesClear() {
	try {
		GM_deleteValue(mmMessagesKey());
	} catch (e) {
		//nothing else to do
	}
}

//text is shown as it is; link, where there is one, makes it clickable.
function mmMessageAdd(text, link) {
	try {
		var message = String(text == null ? '' : text).trim();
		if (!message)
			return;
		var list = mmMessagesLoad();
		var last = list[list.length - 1];
		//The same line twice in a row says nothing twice.
		if (last && last.m === message && last.l === (link || ''))
			return;
		list.push({ t: new Date().getTime(), m: message, l: link || '' });
		mmMessagesSave(list);
	} catch (e) {
		//see above
	}
}

//A note for the list, where one is worth keeping. Before the settings have been
//read there is no list yet, and the note is dropped.
function mmNote(message) {
	try {
		mmMessageAdd(message);
	} catch (e) {
		//no message list yet
	}
}

/////////////////////////////////////////////////////////////////////////////
/////////////////// Module: rank colours, the calculation ///////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * This is how the game works out an effective rank (found by rebuilding it and
 * checked against 126 rows from three heroes - all 126 come out exactly):
 *
 *   1. Put every bonus into one of two buckets:
 *        - source appears in the skills list -> SKILL BONUS (unlimited)
 *        - source is called "Gabe: ..."      -> SKILL BONUS (unlimited)
 *        - everything else                   -> ITEM BONUS  (capped)
 *      Exception: a bare percentage such as "(+20%)" is always an item bonus,
 *      no matter what name stands in front of it.
 *      A Gabe is a skill that does not stand in the list of the page, so the
 *      list cannot say so; its name does.
 *   2. Round each bucket SEPARATELY. Adding first gives wrong values - the two
 *      fractional parts never help each other out.
 *   3. Cap the item bucket at the trained rank.
 *   4. Effective rank = trained rank + capped items + skills
 *   5. A trained rank of 0 gives an effective rank of 0; nothing applies.
 *
 * The bucket follows the SOURCE, not the reference quantity: a skill granting
 * "+50% der Heldenstufe" stays an unlimited skill bonus.
 *
 * A share of a rank, "(+25% des Fertigkeitenrangs)", is a share of the source's
 * effective rank. Where the source is the skill itself, that rank is the one
 * being worked out, and the share comes last: everything else is reckoned first,
 * the items capped as always, and the share is taken once from that sum and
 * rounded down. Waffenmeister with its own "+1" and "+25%" comes to
 * (rank + items + 1) * 1.25, rounded down. The share is a skill bonus; it uses up
 * none of the room for items. Checked against 18 rows of one hero, ranks 17 to 19
 * with 0 to 5 from items. In none of them did the items reach the cap, and no
 * other source stood beside them; the comparison with the rank the page shows
 * tells when such a row disagrees.
 */

//Strings the game itself writes into its tooltips. This is a data format, not
//display text - do not translate.
var SKILLCAP_WIRE = {
	ofHeroLevel: 'der Heldenstufe',
	ofSkillRank: 'des Fertigkeitenrangs',
	skillRank:   'Fertigkeitenrang',
	gift:        /^Gabe:/,
	footnote:    /Boni durch Gegenst|maximal so hoch/i,
	heroLevel:   /^\s*St\.\s*(\d+)/
};

//What the calculation says about a line it cannot reckon.
var SKILLCAP_NOTE = {
	missingSource: function (raw) { return 'Quelle nicht auf der Seite: "' + raw + '"'; },
	missingLevel:  function (raw) { return 'Heldenstufe unbekannt: "' + raw + '" ignoriert'; }
};

/* --- Sources that are not items ------------------------------------- *
 * The rule "appears in the skills list = skill, otherwise item" is right almost
 * always. Three sources slip through it: the clan monument, and the hero's class
 * and race. They turn up in the tooltip under their own name just like an item,
 * but they are not subject to the item bonus ceiling - so they must neither use
 * up the room nor be wasted against it. Class and race stand in hidden fields on
 * the page itself, in both forms of the name; the monument was read on the clan
 * page. A set is no item either: what it grants is not capped at the trained
 * rank. Its name, and those of class, race and monument once more, come from the
 * data of the skills page when that was rebuilt on this visit; otherwise the
 * plain rule decides for the sets.
 * ------------------------------------------------------------------- */
function skillCapOriginSources() {
	var out = Object.create(null);
	var namen = [essentialField('klasse_name'), essentialField('rasse_name')].concat(skillsOriginNames());

	try {
		//'none' means "the clan has no monument". That is not the name of a source.
		var monument = GM_getValue(world + '_monument_' + id, false);
		if (monument && monument != 'none' && monument != 'unknown')
			namen.push(monument);
	} catch (e) {
		//Without storage the monument stays unknown, and the plain rule decides.
	}

	for (var i = 0; i < namen.length; i++) {
		var name = String(namen[i] == null ? '' : namen[i]).trim();
		if (!name)
			continue;
		out[name] = true;
		out[heroMaleForm(name)] = true;
	}
	return out;
}

//Greedy on the name, so that names with brackets of their own - say
//"Tätowierung (Torso) (+2)" - bind to the LAST bracket group.
var SKILLCAP_BONUS_RE =
	/^(.*)\s*\(([+-])(\d+)?\s*(%)?\s*(?:x\s*)?(der Heldenstufe|des Fertigkeitenrangs|Fertigkeitenrang)?\)$/;

//The bonus lines of a rank tooltip, or of current_bonusse in the data interface,
//as sources with their values.
function skillCapParse(lines) {
	var list = [];

	for (var i = 0; i < lines.length; i++) {
		var line = lines[i];
		if (SKILLCAP_WIRE.footnote.test(line))
			continue;

		var m = line.match(SKILLCAP_BONUS_RE);
		//Without a number and without a reference quantity this is not a bonus line
		//but merely a name that happens to end in a bracket.
		if (!m || (m[3] === undefined && !m[5]))
			continue;

		var sign = m[2] === '-' ? -1 : 1;
		list.push({
			source: m[1].trim(),
			//"(+Fertigkeitenrang)" carries no digit and means once.
			value: sign * (m[3] !== undefined ? parseInt(m[3], 10) : 1),
			isPercent: m[4] === '%',
			basis: m[5] || null,
			raw: line
		});
	}
	return list;
}

/*
 * The model (derivation at the head of this section): the bonuses of one skill at
 * a trained rank, sorted into the item and the skill bucket. skillIndex knows every
 * skill by name with its rank and effective rank; originSources the sources that are
 * neither item nor skill; self the name of the skill these bonuses belong to, where
 * the caller knows it.
 */
function skillCapBuckets(bonuses, rank, skillIndex, heroLevel, originSources, self) {
	var itemFlat = 0, itemPct = 0, skillFlat = 0, skillPct = 0;
	//The shares the skill takes of its own rank, added up. They come last.
	var ownShare = 0;
	//How much of the item sum grows along with our own rank. Needed further down to
	//project the ceiling into the future.
	var itemRankCoeff = 0;
	var itemParts = [], skillParts = [], originParts = [], notes = [];

	for (var i = 0; i < bonuses.length; i++) {
		var b = bonuses[i];
		var src = skillIndex[b.source];
		//Clan monument, class and race do not appear in the skills list, but are no
		//more items for that. The script knows their names from storage.
		var fromOrigin = !src && !!originSources[b.source];
		//A Gabe is a skill by its name, in the list or not.
		var isSkill = !!src || SKILLCAP_WIRE.gift.test(b.source);
		var amount;
		//A bare percentage is otherwise always an item bonus and therefore always
		//capped, no matter what name stands in front of it. With a source known by
		//name as an origin, however, it is certain that it is not an item.
		var toItem = fromOrigin ? false : (!isSkill || (b.isPercent && !b.basis));

		if (b.basis === SKILLCAP_WIRE.skillRank) {
			//"(+Fertigkeitenrang)" or "(+N x Fertigkeitenrang)"
			if (!src) { notes.push(SKILLCAP_NOTE.missingSource(b.raw)); continue; }
			amount = b.value * src.eff;
		} else if (!b.isPercent) {
			amount = b.value;
		} else if (b.basis === SKILLCAP_WIRE.ofHeroLevel) {
			if (heroLevel == null) { notes.push(SKILLCAP_NOTE.missingLevel(b.raw)); continue; }
			amount = (b.value / 100) * heroLevel;
		} else if (b.basis === SKILLCAP_WIRE.ofSkillRank) {
			if (!src) { notes.push(SKILLCAP_NOTE.missingSource(b.raw)); continue; }
			if (self != null && b.source === self) {
				//The skill's own rank: taken at the end, from all the rest.
				ownShare += b.value / 100;
				skillParts.push(b.raw);
				continue;
			}
			//Share of the source's EFFECTIVE rank, not of its base rank.
			amount = (b.value / 100) * src.eff;
		} else {
			//Bare percentage: a share of our own trained rank.
			amount = (b.value / 100) * rank;
			//The coefficient describes how the item ceiling grows along. What does not
			//fall into the item bucket at all must not shift it either.
			if (toItem)
				itemRankCoeff += b.value / 100;
		}

		var scaled = b.isPercent || b.basis === SKILLCAP_WIRE.skillRank;
		if (toItem) {
			if (scaled) itemPct += amount; else itemFlat += amount;
			itemParts.push(b.raw);
		} else {
			if (scaled) skillPct += amount; else skillFlat += amount;
			//For the arithmetic the two are the same - shown separately in the tooltip.
			(fromOrigin ? originParts : skillParts).push(b.raw);
		}
	}

	var itemRaw     = itemFlat + itemPct;
	var itemBase    = itemRaw - itemRankCoeff * rank; // the part that does not scale with the rank
	var itemFloored = Math.floor(itemRaw);                // the game rounds down
	var itemApplied = Math.min(itemFloored, rank);    // ... and caps at the rank
	var skillTotal  = Math.floor(skillFlat + skillPct);   // rounded down on its own
	if (ownShare)
		skillTotal += Math.floor(ownShare * (rank + itemApplied + skillTotal));

	//While the cap binds, every further rank lifts the ceiling by one as well and is
	//therefore worth +2 effective rank instead of +1. That number is NOT the same as
	//the wasted remainder: bare percentages grow with the rank, so the ceiling can
	//keep running ahead. That is why it is projected forward step by step.
	var itemAt = function (r) { return itemBase + itemRankCoeff * r; };
	var doubleRanks = 0;
	if (Math.floor(itemAt(rank)) >= rank) {
		for (var r = rank + 1; r <= rank + 500; r++) {
			if (Math.floor(itemAt(r)) < r)
				break;
			doubleRanks++;
		}
	}

	return {
		bonuses: bonuses, notes: notes, itemParts: itemParts, skillParts: skillParts,
		originParts: originParts,
		itemRaw: itemRaw, itemFloored: itemFloored, itemApplied: itemApplied,
		skillTotal: skillTotal, doubleRanks: doubleRanks,
		//Caught at 0 from below. A large malus - say "Domänenwanderer (-25)" on a skill
		//at rank 1 - would otherwise come out as -22 while the page shows 0. Upwards it
		//is already bounded by itemApplied.
		predictedEff: Math.max(0, rank + itemApplied + skillTotal),
		wastedItem:   Math.max(0, itemFloored - rank),
		freeItemRoom: Math.max(0, rank - itemFloored)
	};
}

function skillCapRun() {
	'use strict';

	if (!FEATURES.rankColours)
		return;

	/* --- Wording on the screen ---------------------------------------- */
	var TEXT = {
		rank:        'Gesteigerter Rang',
		itemBonus:   'Itemboni',
		wasted:      'davon ungenutzt',
		room:        'Platz für Itemboni',
		doubleRanks: 'Ränge mit doppeltem Ertrag',
		effective:   'Effektivrang',

		//German counts "1 Rang" but "2 Ränge", and the verb follows suit. One helper
		//for both places rather than the same ternary twice.
		rangWord:     function (n) { return n === 1 ? 'Rang' : 'Ränge'; },
		verdictOver:  function (n) {
			return n + ' ' + TEXT.rangWord(n) + ' an Item-Boni '
				+ (n === 1 ? 'verpufft' : 'verpuffen') + ' am Cap.';
		},
		verdictExact: function ()  { return 'Item-Boni exakt ausgereizt.'; },
		verdictUnder: function (n) {
			return 'Noch Platz für ' + n + ' ' + TEXT.rangWord(n)
				+ ' an Item-Boni aus der Ausrüstung.';
		},
		doubleHint:   function (n) {
			return (n === 1 ? 'Der nächste ' : 'Die nächsten ') + n + ' ' + TEXT.rangWord(n)
				+ (n === 1 ? ' bringt' : ' bringen') + ' je +2 Effektivrang, danach nur noch +1.';
		},
		verifyFail:   function (n) { return 'Berechnung weicht ab, die Seite sagt ' + n + '. Farbe unzuverlässig.'; },

		headItems:  'Gegenstände',
		headSkills: 'Fertigkeiten',
		headOrigin: 'Herkunft und Monument',

		legendOver:  'Item-Boni verpuffen',
		legendExact: 'exakt ausgereizt',
		legendUnder: 'Luft für Item-Boni'
	};

	var WIRE = SKILLCAP_WIRE;

	/* --- Odds and ends -------------------------------------------------- */

	//First whole number in a string, ignoring the spaces WoD uses as thousands
	//separators. Without a number it returns null.
	function intOf(txt) {
		if (txt == null)
			return null;
		var m = String(txt).replace(/[\s ]/g, '').match(/-?\d+/);
		return m ? parseInt(m[0], 10) : null;
	}

	function esc(value) {
		return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
	}

	//Resolve entities and strip tags without executing anything.
	var scratch = document.createElement('div');
	function htmlToLines(html) {
		scratch.innerHTML = String(html).replace(/<br\s*\/?>/gi, '\n');
		return (scratch.textContent || '')
			.split('\n')
			.map(function (line) { return line.trim(); })
			.filter(Boolean);
	}

	/* --- Heldenstufe --------------------------------------------------- */
	function readHeroLevel() {
		//The hidden field the game carries on most pages.
		var feld = intOf(essentialField('stufe'));
		if (feld != null)
			return feld;
		//Otherwise the hero box: the level is an image, only the alt text is readable.
		var el = document.querySelector('.heroLevel img, img.font_Hero_Level');
		var lvl = el ? intOf(el.getAttribute('alt')) : null;
		if (lvl != null)
			return lvl;

		var all = document.querySelectorAll('img[alt]');
		for (var i = 0; i < all.length; i++) {
			var m = all[i].getAttribute('alt').match(WIRE.heroLevel);
			if (m)
				return parseInt(m[1], 10);
		}
		return null;
	}

	/* --- Reading the table ---------------------------------------------- */
	function collectRows() {
		var out = [];
		var rankElements = document.querySelectorAll('[id^="skill_rang_"]');

		for (var i = 0; i < rankElements.length; i++) {
			var rankEl = rankElements[i];
			var id = rankEl.id.slice('skill_rang_'.length);
			if (!/^\d+$/.test(id))
				continue;

			var row = rankEl.closest('tr');
			if (!row)
				continue;

			//The rank sits in a table inside the row, so the link to the skill can be one
			//or more tr levels further out.
			var anchor = null;
			var scope = row;
			while (scope && !anchor) {
				anchor = scope.querySelector('a[href*="skill.php"]');
				scope = scope.parentElement ? scope.parentElement.closest('tr') : null;
			}
			if (!anchor)
				continue;

			var name = (anchor.textContent || '').trim();
			if (!name)
				continue;

			var effEl = document.getElementById('skill_eff_rang_' + id);

			out.push({
				id: id,
				name: name,
				rankEl: rankEl,
				effEl: effEl,
				rank: intOf(rankEl.textContent),
				eff: effEl ? intOf(effEl.textContent) : null,
				tooltipRaw: anchor.getAttribute('onmouseover') || ''
			});
		}
		return out;
	}

	/* --- Tooltip holding a list of bonuses ------------------------------ */
	function extractTooltipHtml(onmouseover) {
		if (!onmouseover)
			return '';
		var m = onmouseover.match(/wodToolTip\s*\(\s*this\s*,\s*'([\s\S]*)'\s*\)/);
		if (!m)
			return '';
		//Everything behind <hr /> is the game's own footnote, not a bonus.
		return m[1].replace(/\\'/g, "'").split(/<hr\s*\/?>/i)[0];
	}

	function parseBonuses(tooltipHtml) {
		return skillCapParse(htmlToLines(tooltipHtml));
	}

	function computeSkill(row, skillIndex, heroLevel, originSources) {
		return skillCapBuckets(parseBonuses(extractTooltipHtml(row.tooltipRaw)), row.rank,
			skillIndex, heroLevel, originSources, row.name);
	}

	/* --- Presentation --------------------------------------------------- */

	//Darker than the rank colours: the tooltip has a light parchment ground on which
	//the light variants would not be legible.
	var TIP = { OVER: '#a11', EXACT: '#1a6b1a', UNDER: '#14508f', BORDER: '#a89464' };

	//Rebuilds the same layout the game's own data tooltips use.
	function buildTooltip(row, res, verdict, verifyFailed) {
		var cell = 'border:1px solid ' + TIP.BORDER + ';padding:1px 6px';
		var rows = [];
		var line = function (label, value, accent) {
			rows.push('<tr><td style="' + cell + '">' + label + ':</td>'
				+ '<td align="right" style="' + cell
				+ (accent ? ';color:' + accent + ';font-weight:bold' : '')
				+ '">' + value + '</td></tr>');
		};

		line(TEXT.rank, row.rank);
		line(TEXT.itemBonus, res.itemFloored);
		if (res.wastedItem > 0)   line(TEXT.wasted, res.wastedItem, TIP.OVER);
		if (res.freeItemRoom > 0) line(TEXT.room, res.freeItemRoom, TIP.UNDER);
		if (res.doubleRanks > 0)  line(TEXT.doubleRanks, res.doubleRanks, TIP.EXACT);
		if (CAP_CFG.TOOLTIP_SHOW_EFFECTIVE) line(TEXT.effective, res.predictedEff);

		var html = '<p><strong>' + esc(row.name) + '</strong>'
			+ '<table style="border-collapse:collapse;margin-top:3px">'
			+ rows.join('') + '</table>';

		var foot = [];
		if (verifyFailed)
			foot.push('<strong>' + TEXT.verifyFail(row.eff) + '</strong>');
		foot.push(verdict);
		if (res.doubleRanks > 0)
			foot.push(TEXT.doubleHint(res.doubleRanks));
		for (var i = 0; i < res.notes.length; i++)
			foot.push(esc(res.notes[i]));

		if (CAP_CFG.TOOLTIP_LIST_SOURCES) {
			if (res.itemParts.length)
				foot.push('<strong>' + TEXT.headItems + ':</strong><br />'
					+ res.itemParts.map(esc).join('<br />'));
			if (res.skillParts.length)
				foot.push('<strong>' + TEXT.headSkills + ':</strong><br />'
					+ res.skillParts.map(esc).join('<br />'));
			if (res.originParts.length)
				foot.push('<strong>' + TEXT.headOrigin + ':</strong><br />'
					+ res.originParts.map(esc).join('<br />'));
		}

		html += '<hr /><span class="tooltip_footenote_font">' + foot.join('<br />') + '</span></p>';
		return html;
	}

	//Only needed if the game's tooltip is not reachable.
	function tooltipToText(html) {
		scratch.innerHTML = html
			.replace(/<\/tr>/gi, '\n')
			.replace(/<\/td><td[^>]*>/gi, ' ')
			.replace(/<br\s*\/?>/gi, '\n')
			.replace(/<hr\s*\/?>/gi, '\n');
		return (scratch.textContent || '').replace(/\n{3,}/g, '\n\n').trim();
	}

	//wodToolTip stamps an id of its own onto the host element and hangs its state on
	//it. Not a single element of the page carries both an id of its own and a
	//wodToolTip call - hang one on an element that already has an id, say
	//#skill_rang_1271, and the tooltip appears only sporadically. So put it on the
	//surrounding cell, which has no id, and exactly the way the game does it: as an
	//attribute with "return". The cell is also a far larger target than the
	//two-digit number.
	function attachTooltip(rankEl, html, gameHasTooltips) {
		var host = rankEl.closest('td') || rankEl.parentElement;
		if (!host || !gameHasTooltips) {
			skillCapNote(rankEl, 'title', 'data-wodcap-titel');
			rankEl.title = tooltipToText(html); //Last resort: a plain title.
			return;
		}
		if (host.id)
			return; //A cell with an id belongs to someone else; left alone.
		skillCapNote(host, 'onmouseover', 'data-wodcap-tip');
		skillCapNote(host, 'style', 'data-wodcap-hstil');
		var payload = html.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
		host.setAttribute('onmouseover', "return wodToolTip(this,'" + payload + "');");
		host.style.cursor = 'help';
	}

	function paint(el, color) {
		skillCapNote(el, 'style', 'data-wodcap-stil');
		//!important, because the skin colours these cells itself.
		el.style.setProperty('color', color, 'important');
		if (CAP_CFG.BOLD)
			el.style.setProperty('font-weight', 'bold', 'important');
		if (CAP_CFG.TEXT_SHADOW)
			el.style.setProperty('text-shadow', '0 0 2px rgba(0,0,0,.9)', 'important');
	}

	function addBadge(el, text, color) {
		if (el.parentNode.querySelector('span.wodcap-badge'))
			return;
		var span = document.createElement('span');
		span.className = 'wodcap-badge';
		span.textContent = ' (' + text + ')';
		span.style.setProperty('color', color, 'important');
		span.style.setProperty('font-size', '0.85em', 'important');
		span.style.setProperty('font-weight', 'normal', 'important');
		el.parentNode.insertBefore(span, el.nextSibling);
	}

	function addLegend(anchorTable) {
		if (document.getElementById('wodcap-legend'))
			return;
		var box = document.createElement('div');
		box.id = 'wodcap-legend';
		box.style.cssText = 'margin:4px 0;font-size:12px;line-height:1.5;text-shadow:0 0 2px rgba(0,0,0,.9)';
		var item = function (c, t) {
			return '<span style="color:' + c + ';font-weight:bold">&#9632;</span> ' + t;
		};
		box.innerHTML = [
			item(CAP_CFG.COLOR_OVER,  TEXT.legendOver),
			item(CAP_CFG.COLOR_EXACT, TEXT.legendExact),
			item(CAP_CFG.COLOR_UNDER, TEXT.legendUnder)
		].join(' &nbsp; ');
		anchorTable.parentNode.insertBefore(box, anchorTable);
	}

	/* --- The run -------------------------------------------------------- */
	try {

	//The game's table, not one of those the skills page puts above it.
	var table = document.querySelector('table.content_table:not([id^="mm_skills_"])');
	if (!table)
		return;

	var rows = collectRows();
	if (!rows.length)
		return;

	var heroLevel = readHeroLevel();

	//Whether the game's tooltip function is present is read off the markup and not
	//off window - inside Tampermonkey's sandbox, window is not the page.
	var gameHasTooltips = !!document.querySelector('[onmouseover*="wodToolTip"]');

	//Name index - this is what decides skill against item.
	var skillIndex = Object.create(null);
	for (var i = 0; i < rows.length; i++) {
		if (rows[i].rank == null)
			continue;
		skillIndex[rows[i].name] = {
			rank: rows[i].rank,
			eff: rows[i].eff != null ? rows[i].eff : rows[i].rank
		};
	}

	var originSources = skillCapOriginSources();

	for (var j = 0; j < rows.length; j++) {
		var row = rows[j];
		if (row.rank == null)
			continue;
		if (CAP_CFG.SKIP_RANK_ZERO && row.rank === 0)
			continue;
		//On a tab switch the same cells are reused.
		if (row.rankEl.getAttribute('data-wodcap') === '1')
			continue;

		var res = computeSkill(row, skillIndex, heroLevel, originSources);

		var hasItemBonus = res.itemParts.length > 0;
		if (!hasItemBonus && !CAP_CFG.COLOR_ROWS_WITHOUT_ITEM_BONUS)
			continue;

		//Cross-check against the effective rank the page prints itself.
		var verifyFailed = false;
		if (CAP_CFG.VERIFY && row.eff != null && res.predictedEff !== row.eff)
			verifyFailed = true;

		var color, verdict;
		if (res.itemFloored > row.rank) {
			color = CAP_CFG.COLOR_OVER;
			verdict = TEXT.verdictOver(res.wastedItem);
		} else if (res.itemFloored === row.rank) {
			color = CAP_CFG.COLOR_EXACT;
			verdict = TEXT.verdictExact();
		} else {
			color = CAP_CFG.COLOR_UNDER;
			verdict = TEXT.verdictUnder(res.freeItemRoom);
		}
		if (verifyFailed)
			color = CAP_CFG.COLOR_ERROR;

		paint(row.rankEl, color);
		if (CAP_CFG.TOOLTIP)
			attachTooltip(row.rankEl, buildTooltip(row, res, verdict, verifyFailed), gameHasTooltips);

		if (CAP_CFG.SHOW_ITEM_BONUS && hasItemBonus)
			addBadge(row.rankEl, String(res.itemFloored), color);

		row.rankEl.setAttribute('data-wodcap', '1');
	}

	if (CAP_CFG.SHOW_LEGEND)
		addLegend(document.getElementById('mm_skills_tabs') || table);

	} catch (e) {
		mmReportError('skillCapRun', e);
	}
}

/////////////////////////////////////////////////////////////////////////////
////////////////////// Module: the skills page, start ///////////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * Rebuilds the skills page: tabs by kind of skill, and for every skill its class,
 * the item it is used with, its throws with the Rechenweg in the tooltip, its
 * attack type, mana cost, item class and number of targets. Above the table stand
 * the hero's general values and attributes, and on request the bonus overviews.
 * The export tab puts the whole build into the clipboard as BBCode.
 *
 * Everything is reckoned from the game's data interface (data.php): nine answers,
 * asked for all at once on every visit of the page, the same nine the Skills
 * Optimizer asks for. The page is rebuilt from the game's details view ("Details
 * ein"); without it, and on the skill lists of a class, nothing is fetched.
 *
 * The answers of the last visit are kept per hero, packed small. On the next visit
 * the page is built from them at once, while the nine requests are under way. Where
 * the fresh answers say the same, nothing more happens; where they say something
 * new, the page is built again from them, on the same tab. See "Keeping the
 * answers".
 *
 * The bonus bookkeeping is Darkflint's WoD Skills Optimizer. The throws follow the
 * rules measured on the engine's rolls, see skillsRoll.
 *
 * The blocks below: this one starts the module and fetches the data, then come the
 * data model (SkillsData and the powerup classes), the layout above the table
 * (SkillsLayout), the table itself (SkillsTable), the throws and their Rechenweg,
 * and the export.
 */

//The two worlds the Skills Optimizer leaves alone.
var SKILLS_WORLDS_WITHOUT = ['barkladesh', 'xerasia'];

//What is fetched on every visit, all at once.
var SKILLS_KINDS = ['sets', 'all_skills', 'items', 'attributes', 'monument', 'class_plain',
	'types', 'item_classes', 'skill_classes'];

//Give up on a single request after this long.
var SKILLS_TIMEOUT_MS = 25000;

//The key under which a damage bonus remembers its damage type.
var SKILLS_DAMAGE_TYPE_KEY = 'wod_S0_damage_key';

//The four parts of one visit: who the hero is, what the data interface says about
//him, the tables above the skills and the skills table itself.
var skillsHero = null;
var skillsData = null;
var skillsLayout = null;
var skillsTable = null;

//What uses the data of this visit: the rank colours. It runs once the page is
//built, or once it is clear that it will not be, and again after every new build.
var skillsFolgen = [];
var skillsDone = false;

//Will the page be rebuilt on this visit? Asked by the modules that use its data.
function skillsWillRun() {
	if (!FEATURES.skillsPage || page != 'skills.php')
		return false;
	if (SKILLS_WORLDS_WITHOUT.indexOf(worldSubdomain()) > -1 || rankColoursClassOverview())
		return false;
	return !!skillsGameTable() && rankColoursDetailsOn() && !document.getElementById('mm_skills_tabs');
}

//The game's skills table: the first content table of the form.
function skillsGameTable() {
	var form = document.querySelector('form[name="the_form"]');
	return form ? form.querySelector('table.content_table') : null;
}

//The names of class, race, monument and the sets the hero wears, as the data of
//this visit has them. None where the page was not rebuilt.
function skillsOriginNames() {
	if (!skillsData)
		return [];
	var herkunft = skillsData.oClass || { };
	var monument = skillsData.oMonument && skillsData.oMonument.monument;
	var namen = [herkunft['class'] && herkunft['class'].label, herkunft.race && herkunft.race.label,
		monument && monument.label];
	for (var sSetId in skillsData.oSets || { }) {
		var oSet = skillsData.oSets[sSetId];
		if (oSet && oSet.name && oSet.items && oSet.items.length)
			namen.push(oSet.name);
	}
	return namen.filter(Boolean).map(function (name) {
		return skillsData.translateSpecialSymbols(name).trim();
	});
}

//Run fn with the data of this visit, and again after every new build. Right away
//if there is none to wait for.
function skillsWhenReady(fn) {
	if (!skillsDone && !skillsWillRun()) {
		fn();
		return;
	}
	skillsFolgen.push(fn);
	if (skillsDone)
		skillsFolge(fn);
}

function skillsFolge(fn) {
	try {
		fn();
	} catch (e) {
		mmReportError('Fertigkeitenseite', e);
	}
}

function skillsFinish() {
	skillsDone = true;
	skillsFolgen.forEach(skillsFolge);
}

function skillsInit() {
	//Only from the details view, the way the page was always rebuilt. Without it the
	//module keeps out of the way; the game's own switch is right there.
	if (!skillsWillRun())
		return;

	skillsVisit().catch(function (e) {
		mmReportError('Fertigkeitenseite', e);
		if (!skillsDone)
			skillsFinish();
	});
}

function skillsGrund(fehler) {
	return String(fehler && fehler.message ? fehler.message : fehler);
}

/*
 * One visit. The nine requests go out first, the answers kept from the last visit
 * are unpacked meanwhile and, where there are any, built at once. Then the fresh
 * answers: built where nothing was there yet, built anew where they differ from
 * the kept ones, and kept for the next visit.
 */
async function skillsVisit() {
	var holen = skillsHolen();
	//Its failure is read further down; this only keeps it from being reported as
	//unhandled while the kept answers are unpacked.
	holen.catch(function () { });

	var alt = await skillsCacheRead();
	if (alt && !skillsZeigen(alt.antworten, true))
		alt = null;
	if (alt)
		skillsStand('Gespeicherter Stand, neue Daten werden geholt ...');
	else
		skillsHint('Die Daten der Fertigkeitenseite werden geholt ...');

	var text, antworten;
	try {
		var held = await holen;
		//Taken before the build, which hangs its own things into the answers.
		text = JSON.stringify(held);
		antworten = skillsAntworten(held);
	} catch (fehler) {
		var grund = skillsGrund(fehler);
		mmNote('Fertigkeitenseite: ' + grund);
		if (alt) {
			skillsStand('Stand vom ' + skillsZeitText(alt.zeit) + ', neue Daten nicht abrufbar: '
				+ grund, true);
		} else {
			skillsHint('Die Fertigkeitenseite konnte nicht aufbereitet werden: ' + grund);
			skillsFinish();
		}
		return;
	}

	if (!alt) {
		skillsHintClear();
		skillsZeigen(antworten);
	} else if (alt.text === text) {
		skillsStand('');
		skillsCacheConfirm(alt);
		//What the build of the kept answers left out.
		try {
			skillsFeedItemCompare(antworten.held.items.items);
		} catch (e) {
			mmReportError('Fertigkeitenseite', e);
		}
		return;
	} else {
		skillsNeuBauen(antworten);
		skillsStand('Neue Daten eingearbeitet.', false, 4000);
	}
	await skillsCacheWrite(text);
}

/*
 * The page built from one set of answers, and what uses them run. False where the
 * build broke; then nothing of it is left on the page. Kept answers that break are
 * no error of their own: the fresh ones are on their way.
 */
function skillsZeigen(antworten, gespeichert) {
	try {
		skillsBuild(antworten);
	} catch (e) {
		skillsAbbauen();
		if (gespeichert)
			return false;
		mmReportError('Fertigkeitenseite', e);
		skillsFinish();
		return false;
	}
	skillsFinish();
	return true;
}

/*
 * The page built again from newer answers. The tab stays the one that was open,
 * and every item picked in a row stays picked where the row still offers it.
 */
function skillsNeuBauen(antworten) {
	var tab = skillsTable ? skillsTable.activeTab() : 'all';
	var gewaehlt = skillsTable ? skillsTable.pickedItems() : { };

	skillsAbbauen();
	try {
		skillsBuild(antworten);
		skillsTable.restore(tab, gewaehlt);
	} catch (e) {
		skillsAbbauen();
		mmReportError('Fertigkeitenseite', e);
	}
	skillsFinish();
}

//Everything the build put onto the page taken off it again. The game's own rows
//and cells stay where they are, with whatever the player has changed in them.
function skillsAbbauen() {
	if (skillsTable)
		skillsTable.remove();
	if (skillsLayout)
		skillsLayout.remove();
	skillsHintClear();
}

//A word beside the tabs on where the data of the page stands. Where the export
//has put its own word there since, that one stays.
function skillsStand(text, schlimm, dauer) {
	var note = document.getElementById('mm_skills_export_note');
	if (!note)
		return;
	var alt = note.querySelector('[data-mm-stand]');
	if (!text) {
		if (alt)
			note.removeChild(alt);
		return;
	}
	var zeile = (schlimm || dauer) ? mmFlash(note, text, schlimm, dauer) : null;
	if (!zeile) {
		mmEmpty(note);
		zeile = document.createElement('span');
		zeile.style.opacity = '0.7';
		zeile.textContent = text;
		note.appendChild(zeile);
	}
	zeile.setAttribute('data-mm-stand', '1');
}

function skillsZeitText(zeit) {
	var d = new Date(zeit);
	var zwei = function (n) { return (n < 10 ? '0' : '') + n; };
	return zwei(d.getDate()) + '.' + zwei(d.getMonth() + 1) + '. ' + zwei(d.getHours()) + ':'
		+ zwei(d.getMinutes());
}

//A line above the skills table, for what the reader has to know before anything
//else happens there.
function skillsHint(text) {
	var hinweis = document.getElementById('mm_skills_hint');
	if (!hinweis) {
		var tabelle = skillsGameTable();
		if (!tabelle)
			return null;
		hinweis = document.createElement('p');
		hinweis.id = 'mm_skills_hint';
		hinweis.style.cssText = 'margin:4px 0;font-size:12px;';
		tabelle.parentNode.insertBefore(hinweis, tabelle);
	}
	hinweis.textContent = text;
	return hinweis;
}

function skillsHintClear() {
	var hinweis = document.getElementById('mm_skills_hint');
	if (hinweis && hinweis.parentNode)
		hinweis.parentNode.removeChild(hinweis);
}

/* --- Fetching ----------------------------------------------------------- */

function skillsDataUrl(kind) {
	var held = essentialField('session_hero_id') || id || '';
	return window.location.protocol + '//' + window.location.host
		+ '/wod/spiel/hero/data.php?what=' + encodeURIComponent(kind) + '&type=json'
		+ (held ? '&session_hero_id=' + encodeURIComponent(held) : '')
		+ '&_=' + new Date().getTime();
}

function skillsSleep(ms) {
	return new Promise(function (weiter) { setTimeout(weiter, ms); });
}

/*
 * The cookies go along in one of three ways. "explicit" sends what the page itself
 * sees and switches off the cookies Tampermonkey would add on its own, so the
 * header cannot come out doubled. "trimmed" does the same without single cookies
 * of more than a thousand characters. "browser" leaves it all to Tampermonkey.
 * The server says "Size of a request header field exceeds server limit" when the
 * cookie header is too large; then the next way is tried, once for all requests
 * that ran into it together.
 */
var SKILLS_COOKIE_WAYS = ['explicit', 'trimmed', 'browser'];
var SKILLS_COOKIE_KEEP = ['PHPSESSID', 'wodsession', 'wod_session', 'sessionid'];
var skillsCookieWay = 0;

function skillsCookieHeader(weg) {
	var alle = String(document.cookie || '').split(';');
	var behalten = [];
	for (var i = 0; i < alle.length; i++) {
		var keks = alle[i].trim();
		if (!keks)
			continue;
		if (weg == 'trimmed' && keks.length > 1000
				&& SKILLS_COOKIE_KEEP.indexOf(keks.split('=')[0]) < 0)
			continue;
		behalten.push(keks);
	}
	return behalten.join('; ');
}

function skillsRequest(url, wegNr) {
	var weg = SKILLS_COOKIE_WAYS[wegNr];
	return new Promise(function (gut, schlecht) {
		var optionen = {
			method: 'GET',
			url: url,
			timeout: SKILLS_TIMEOUT_MS,
			headers: { 'Cache-Control': 'no-cache', 'Pragma': 'no-cache' },
			anonymous: weg != 'browser',
			onload: function (antwort) {
				if (antwort.status >= 200 && antwort.status < 300)
					gut(String(antwort.responseText || ''));
				else
					schlecht(new Error('HTTP ' + antwort.status
						+ (/exceeds server limit|request header field/i.test(String(antwort.responseText || ''))
							? ' (Kopfzeile zu gross)' : '')));
			},
			onerror: function () { schlecht(new Error('Netzwerkfehler')); },
			ontimeout: function () { schlecht(new Error('Zeitüberschreitung')); },
			onabort: function () { schlecht(new Error('Abgebrochen')); }
		};
		if (weg != 'browser')
			optionen.headers['Cookie'] = skillsCookieHeader(weg);
		GM_xmlhttpRequest(optionen);
	});
}

//One kind, as an object. A header the server finds too large moves on to the next
//way of sending the cookies; a server that is briefly busy gets a second chance.
async function skillsFetch(kind) {
	var zweiteChance = true;
	for (;;) {
		var wegNr = skillsCookieWay;
		try {
			var text = await skillsRequest(skillsDataUrl(kind), wegNr);
			var daten;
			try {
				daten = JSON.parse(text);
			} catch (e) {
				daten = null;
			}
			if (!daten || typeof daten != 'object')
				throw new Error('keine Daten, vielleicht abgemeldet');
			return daten;
		} catch (e) {
			var grund = String(e && e.message ? e.message : e);
			if (/Kopfzeile zu gross|HTTP 400/.test(grund)) {
				//Another request of the same round may have moved on already.
				if (skillsCookieWay === wegNr && wegNr < SKILLS_COOKIE_WAYS.length - 1)
					skillsCookieWay++;
				if (skillsCookieWay > wegNr)
					continue;
			}
			if (zweiteChance && /HTTP (429|502|503|504)|Zeitüberschreitung/.test(grund)) {
				zweiteChance = false;
				await skillsSleep(600);
				continue;
			}
			throw new Error('"' + kind + '" nicht lesbar (' + grund + ')');
		}
	}
}

//All nine at once, by kind.
async function skillsHolen() {
	var antworten = await Promise.all(SKILLS_KINDS.map(skillsFetch));
	var held = { };
	for (var i = 0; i < SKILLS_KINDS.length; i++)
		held[SKILLS_KINDS[i]] = antworten[i];
	return held;
}

//The answers in the shape the build takes them. types is one object of lists,
//item_classes and skill_classes carry an array under their own name.
function skillsAntworten(held) {
	var listen = {
		types: held.types,
		item_classes: held.item_classes.item_classes,
		skill_classes: held.skill_classes.skill_classes
	};
	if (!listen.item_classes || !listen.skill_classes)
		throw new Error('Listen der Gegenstands- oder Fertigkeitenklassen ohne Inhalt');
	return { listen: listen, held: held };
}

/* --- Keeping the answers ------------------------------------------------- */

/*
 * The nine answers of the last visit, one entry per hero and world. The answers are
 * a quarter of a megabyte of text, and the storage of a userscript is handed to
 * every page it runs on; so they are kept gzipped, about twenty kilobytes a hero.
 * Where the browser cannot pack, nothing is kept and every visit waits for the
 * requests, as it always did.
 *
 * The entry: { v: 1, zeit: when the answers were last confirmed, gz: the answers as
 * JSON, gzipped, in base64 }. An entry that cannot be read counts as none.
 */
var SKILLS_CACHE_VERSION = 1;

function skillsCacheKey() {
	return (world && id) ? world + '_skills_' + id : '';
}

function skillsCacheCan() {
	return typeof CompressionStream === 'function' && typeof DecompressionStream === 'function'
		&& typeof TextEncoder === 'function' && typeof TextDecoder === 'function'
		&& !!skillsCacheKey();
}

//Bytes through one of the browser's gzip streams, and all of what comes out.
async function skillsStrom(bytes, strom) {
	var schreiber = strom.writable.getWriter();
	var leser = strom.readable.getReader();
	var schreiben = schreiber.write(bytes).then(function () { return schreiber.close(); });
	schreiben.catch(function () { });

	var teile = [], laenge = 0;
	for (;;) {
		var stueck = await leser.read();
		if (stueck.done)
			break;
		teile.push(stueck.value);
		laenge += stueck.value.length;
	}
	await schreiben;

	var aus = new Uint8Array(laenge), pos = 0;
	for (var i = 0; i < teile.length; i++) {
		aus.set(teile[i], pos);
		pos += teile[i].length;
	}
	return aus;
}

async function skillsPacken(text) {
	var bytes = await skillsStrom(new TextEncoder().encode(text), new CompressionStream('gzip'));
	var binaer = '';
	for (var i = 0; i < bytes.length; i += 0x8000)
		binaer += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
	return btoa(binaer);
}

async function skillsEntpacken(gz) {
	var binaer = atob(gz);
	var bytes = new Uint8Array(binaer.length);
	for (var i = 0; i < binaer.length; i++)
		bytes[i] = binaer.charCodeAt(i);
	return new TextDecoder().decode(await skillsStrom(bytes, new DecompressionStream('gzip')));
}

//The kept answers of this hero: when, as text, and in the shape the build takes.
//None where there are none or they cannot be read.
async function skillsCacheRead() {
	if (!skillsCacheCan())
		return null;
	try {
		var eintrag = JSON.parse(GM_getValue(skillsCacheKey(), '') || 'null');
		if (!eintrag || eintrag.v !== SKILLS_CACHE_VERSION || !eintrag.gz)
			return null;
		var text = await skillsEntpacken(eintrag.gz);
		var antworten = skillsAntworten(JSON.parse(text));
		antworten.gespeichert = true;
		return { zeit: eintrag.zeit, gz: eintrag.gz, text: text, antworten: antworten };
	} catch (e) {
		return null;
	}
}

async function skillsCacheWrite(text) {
	if (!skillsCacheCan())
		return;
	try {
		GM_setValue(skillsCacheKey(), JSON.stringify({ v: SKILLS_CACHE_VERSION, zeit: Date.now(),
			gz: await skillsPacken(text) }));
	} catch (e) {
		mmNote('Fertigkeitenseite: Daten nicht gespeichert (' + skillsGrund(e) + ')');
	}
}

//The kept answers said the same as the fresh ones: they are as of now.
function skillsCacheConfirm(alt) {
	try {
		GM_setValue(skillsCacheKey(), JSON.stringify({ v: SKILLS_CACHE_VERSION, zeit: Date.now(),
			gz: alt.gz }));
	} catch (e) {
		mmNote('Fertigkeitenseite: Daten nicht gespeichert (' + skillsGrund(e) + ')');
	}
}

/* --- Building ------------------------------------------------------------ */

/*
 * The answers are all in, so everything from here on runs in one go: the data
 * model first, then the bonus overviews, then the page. The order inside the data
 * model matters - skills, items and sets have to be known before the bonuses are
 * summed up, and the set bonuses are taken off the items afterwards.
 */
function skillsBuild(antworten) {
	var listen = antworten.listen;
	var held = antworten.held;

	skillsHero = {
		sName: essentialField('heldenname') || '',
		iLevel: parseInt(essentialField('stufe'), 10) || 0
	};
	skillsData = new SkillsData();
	skillsLayout = new SkillsLayout();
	skillsTable = new SkillsTable();

	skillsData.oTypes = listen.types;
	skillsData.oItemClasses = skillsData.reassignObjectArrayToObject(listen.item_classes);
	skillsData.oSkillClasses = skillsData.reassignObjectArrayToObject(listen.skill_classes);

	skillsTable.oDataPowerUps.attributes = held.attributes.attributes || { };
	if (!skillsHero.iLevel && held.attributes.attributes && held.attributes.attributes.level)
		skillsHero.iLevel = parseInt(held.attributes.attributes.level.effective_value, 10) || 0;

	skillsData.oItems = held.items;
	skillsData.oMonument = held.monument;
	skillsData.oClass = held.class_plain;
	skillsData.oSets = skillsData.orderSets(held.sets.sets || []);
	skillsData.aSkills = held.all_skills.skills || [];

	var monument = held.monument && held.monument.monument;
	if (monument && monument.label)
		for (var aMonument of Object.values(monument.powerups || { }))
			skillsData.assignPowerUps(aMonument, monument.label, { });

	//The rank colours know the monument from the clan page. The data knows it too,
	//and knows when there is none.
	if (world && id)
		GM_setValue(world + '_monument_' + id,
			monument && monument.label ? skillsData.translateSpecialSymbols(monument.label) : 'none');

	for (var oSkill of skillsData.aSkills) {
		skillsData.orderSkill(oSkill);
		for (var aSkillPowerUp of Object.values(oSkill.owner_powerups || { }))
			skillsData.assignPowerUps(aSkillPowerUp, oSkill.template.label,
				{ iSkillLevel: oSkill.effective_value });
	}

	var herkunft = held.class_plain || { };
	for (var teil of ['class', 'race']) {
		if (!herkunft[teil])
			continue;
		var sHerkunft = herkunft[teil].label || essentialField(teil == 'class' ? 'klasse_name' : 'rasse_name')
			|| (teil == 'class' ? 'Klasse' : 'Volk');
		for (var aHerkunft of Object.values(herkunft[teil].powerups || { }))
			skillsData.assignPowerUps(aHerkunft, sHerkunft, { });
	}

	for (var oItem of (held.items.items || [])) {
		var oItemObject = new SkillsItem(oItem);
		var sSetId = String(oItem.template.set_id || '0');

		if (sSetId !== '0' && skillsData.oSets[sSetId])
			skillsData.oSets[sSetId].items.push(oItem);

		for (var sItemClassId of Object.keys(oItem.template.gegenstand_klassen || { })) {
			var oKlasse = skillsData.oItemClasses[sItemClassId];
			if (!oKlasse)
				continue;
			if (typeof oKlasse.items === 'undefined')
				oKlasse.items = [];
			oKlasse.items.push(oItemObject);
		}

		skillsData.oItemsByInstanceId[oItem.instance_id] = oItemObject;
		for (var aItemPowerUp of Object.values(oItem.instance.owner_powerups || { }))
			skillsData.assignPowerUps(aItemPowerUp, oItem.template.name, { });
	}

	skillsData.getSetPowerUps();

	var boni = skillsData.bonusTables();

	skillsTable.initRender();
	skillsLayout.initRender();
	skillsLayout.addAttributeData(skillsTable.oDataPowerUps.attributes);

	skillsTable.oDataPowerUps.skillEffects = boni.skillEffects;
	skillsTable.oDataPowerUps.attacks = boni.attacks;
	skillsTable.oDataPowerUps.parades = boni.parades;
	skillsTable.oDataPowerUps.damages = boni.damages;
	skillsTable.oDataPowerUps.damagesZ = boni.damagesZ;
	skillsTable.oDataPowerUps.initiative = boni.attributes.at_v_initiative;

	skillsTable.fillTable();

	skillsLayout.fillSingleBonus(boni.attacks, 'Attacks');
	skillsLayout.fillSingleBonus(boni.attributes, 'Attributes');
	skillsLayout.fillSingleBonus(boni.drops, 'Drop');
	skillsLayout.fillSingleBonus(boni.parades, 'Parades');
	skillsLayout.fillTripleBonus(boni.armor, 'Armor');
	skillsLayout.fillTripleBonus(boni.damages, 'Damage');
	skillsLayout.fillTripleBonus(boni.damagesZ, 'DamageZ');
	skillsLayout.fillTripleBonus(boni.damageFactors, 'DamageFactor');
	skillsLayout.fillBonusSkillEffects(boni.skillEffects);

	skillsLayout.appendLayout();

	//The equipment only from fresh answers. Kept ones may be older than what the
	//equipment page has taught the compare since.
	if (!antworten.gespeichert)
		skillsFeedItemCompare(held.items.items);
}

/////////////////////////////////////////////////////////////////////////////
///////////////////// Module: the skills page, the data /////////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * The data model: what the data interface says about the hero, sorted into
 * powerups by kind (attack, parry, attribute, damage and so on) and summed up per
 * source into the bonus overviews.
 *
 * Bonuses arrive in two forms. Typed ones carry a kind (bo_wert, bo_prozent,
 * bo_stufen_faktor, bo_wirk_faktor) and a bare number; the others carry the text
 * the game prints, "+2 +10% der Heldenstufe", which is taken apart here. Damage,
 * armour and Anfälligkeit carry three values, for hit, good hit and critical hit.
 *
 * Only what works at all times goes into the overviews. What works on use stays
 * with the skill or item it belongs to and counts for its own throws only.
 *
 * Items carry the bonuses of their set once per worn piece. The set bonuses are
 * taken off them again and counted once for the set.
 */

class SkillsData {
	aHitTypes = ["et_erfolg", "et_gut", "et_kritisch"];
	oPowerUpBoTypes = {
		base: "bo_wert",
		percentage: "bo_prozent",
		level: "bo_stufen_faktor",
		skill: "bo_wirk_faktor",
	};
	oPowerUpEffectType = {
		sActive: "wirkt_bei_anwendung",
		sPassive: "wirkt_immer",
		sClass: ""
	};
	oPowerUpDamageEffectType = {
		sTrigger: "sw_hinzufuegen",
		sDamageZ: "sw_erhoehen"
	};
	oPowerUpSOLabel = {
		sFrom: "wod_SO_powerup_von",
		sSkillRank: "wod_SO_powerup_skill_rang",
	};
	oPowerUpApiKeys = {
		sAttacks: "pt_angriff",
		sAttributes: "pt_attribut",
		sDrops: "pt_drop",
		sParades: "pt_parade",
		sArmors: "pt_ruestung",
		sDamages: "pt_schaden",
		sDamagesZ: "pt_schaden_z",
		sDamageFactors: "pt_schadens_faktor",
		sSkillRanks: "pt_talent",
		sSkillsEffect: "pt_wirkung",
	};
	/**
	 * @type {powerups}
	 */
	oPowerUps = {
		pt_angriff: [],
		pt_attribut: [],
		pt_drop: [],
		pt_parade: [],
		pt_ruestung: [],
		pt_schaden: [],
		pt_schaden_z: [],
		pt_schadens_faktor: [],
		pt_talent: [],
		pt_wirkung: [],
	};
	oMessages = {
		sSetCacheError: "Set-Probleme entdeckt! Bitte einmal Geschlecht ändern oder Held wechseln."
	};
	/**
	 * @type {types}
	 */
	oTypes = {};
	/**
	 * @type {Object<fetch_item_class>}
	 */
	oItemClasses = {};
	/**
	 * @property {{id: string, label: string, powerups: powerups}} class
	 * @property {{id: string, label: string, powerups: powerups}} race
	 */
	oClass = {};
	/**
	 * @type {Object}
	 * @property {items[]} items
	 */
	oItems = {};
	/**
	 * instance_id = individual id of item, template_id = shared id of all items of the same name
	 * @type {Object<SkillsItem>}
	 */
	oItemsByInstanceId = {};
	/**
	 * @type {Array<skills>}
	 */
	aSkills = [];
	/**
	 * @type {Object<skills>}
	 */
	oSkillsByName = {};
	/**
	 * @type {Object<skills[]>}
	 */
	oSkillsById = {};
	/**
	 * @type {Object}
	 */
	oSkillClasses = {};
	/**
	 * @type {Object}
	 * @property {Object} monument
	 * @property {string} monument.id
	 * @property {string} monument.label
	 * @property {powerups[]} monument.powerups
	 */
	oMonument = {};
	/**
	 * @type {Object}
	 */
	oSets = {};
	oSetValues = {};
	sAllAttackTypKey = "alle";

	constructor() {
	}

	/**
	 * @param {Array<Object>} aArray
	 */
	reassignObjectArrayToObject(aArray) {
		let oReturnObject = {};
		/**
		 * @property {string} oObject.id
		 * @property {string} oObject.name
		 * @property {string} [oObject.max_items]
		 * @property {Object} [oObject.powerups]
		 */
		for (let oObject of aArray) {
			oReturnObject[oObject.id] = {
				"id": oObject.id,
				"name": oObject.name
			};

			if (typeof oObject.max_items !== "undefined") {
				oReturnObject[oObject.id]["maxItems"] = oObject.max_items;
			}
		}

		return oReturnObject;
	}

	orderSkill(oSkill) {
		this.oSkillsByName[oSkill.template.label] = oSkill;
		this.oSkillsById[oSkill.template_id] = oSkill;
	}

	orderSets(aSets) {
		let oReturnOrderSets = {};

		for (let oSet of aSets) {
			oReturnOrderSets[oSet.id] = oSet;
			oReturnOrderSets[oSet.id].items = [];
		}

		return oReturnOrderSets;
	};

	getSetPowerUps() {
		let oActiveSets = this.getActiveSets();

		try {
			for (let [sSetId, oSetPowerUps] of Object.entries(oActiveSets)) {
				const sSetName = this.oSets[sSetId].name;

				this.oSetValues[sSetId] = this.getActiveSetsBonus(oSetPowerUps, sSetName);
			}
		} catch (sError) {
			skillsLayout.addMessage(this.oMessages.sSetCacheError);
		}

	};

	getActiveSets() {
		let oSets = {};

		for (let [sSetId, oSet] of Object.entries(this.oSets)) {
			if (oSet.items.length <= 0) {
				continue;
			}

			for (let aPtOb of Object.values(oSet.owner_powerups)) {
				for (let oAttribute of aPtOb) {
					let iFrom = parseInt(oAttribute.from_count);
					let iTo = parseInt(oAttribute.to_count);

					if (oSet.items.length >= iFrom && oSet.items.length <= iTo) {
						const {sSubKey, sLabel} = this.getBonusKeyAndLabel(oAttribute);
						let sPowerUpType = this.assignCorrectPtKey(oAttribute);

						if (!oSets[sSetId]) {
							oSets[sSetId] = {};
						}

						if (!oSets[sSetId][sPowerUpType]) {
							oSets[sSetId][sPowerUpType] = {};
						}

						oAttribute.wod_SO_powerup_von = oSet.name;
						oAttribute.wod_SO_name = this.translateSpecialSymbols(sLabel);

						if (!oSets[sSetId][sPowerUpType][sSubKey]) {
							oSets[sSetId][sPowerUpType][sSubKey] = [];
						}

						oSets[sSetId][sPowerUpType][sSubKey].push(oAttribute);
					}
				}
			}
		}

		return oSets;
	}

	getActiveSetsBonus(oSetPowerUps, sSetName) {
		let oRawSetBonus = {};

		for (let [sPtType, oPtType] of Object.entries(oSetPowerUps)) {
			let blTripleValueBonus = this.isTripleValueBonus(sPtType);

			if (!oRawSetBonus[sPtType]) {
				oRawSetBonus[sPtType] = {};
			}

			for (let [sSubType, aSubTypes] of Object.entries(oPtType)) {
				let aAttackTypes = [];
				let oNormalHits = {};
				let oGoodHits = {};
				let oCriticalHits = {};

				if (!blTripleValueBonus) {
					if (!oRawSetBonus[sPtType][sSubType]) {
						oRawSetBonus[sPtType][sSubType] = this.bonusAndDetailTemplate({
							blIsTripleValue: blTripleValueBonus,
							sPtType: sPtType,
							mSkillClass: aSubTypes[0].talent_klasse,
							sLabel: aSubTypes[0].wod_SO_name
						});
					}

					oRawSetBonus[sPtType][sSubType] = this.setSetDetails(oRawSetBonus[sPtType][sSubType], aSubTypes, {
						blIsTripleValue: blTripleValueBonus
					});
				} else {
					//sSubType: the damage type, e.g. st_feuer_schaden
					//aSubTypes: the powerups of that damage type
					if (!oRawSetBonus[sPtType][sSubType]) {
						oRawSetBonus[sPtType][sSubType] = {};
					}

					for (let oDamageTypeObject of aSubTypes) {
						let sAttackType = oDamageTypeObject.angriffs_typ || this.sAllAttackTypKey;

						if (!aAttackTypes.includes(sAttackType)) {
							aAttackTypes.push(sAttackType);

							oNormalHits[sAttackType] = [];
							oGoodHits[sAttackType] = [];
							oCriticalHits[sAttackType] = [];

							oRawSetBonus[sPtType][sSubType][sAttackType] = this.bonusAndDetailTemplate({blBonus: false});

							for (let oHitType of this.aHitTypes) {
								if (!oRawSetBonus[sPtType][sSubType][sAttackType][oHitType]) {
									oRawSetBonus[sPtType][sSubType][sAttackType][oHitType] = this.bonusAndDetailTemplate({
										sPtType: sPtType,
										mSkillClass: aSubTypes[0].talent_klasse,
										sLabel: aSubTypes[0].wod_SO_name,
										blDetails: false
									});
								}
							}
						}

						switch (oDamageTypeObject.erfolgs_typ) {
							case "et_erfolg":
								oNormalHits[sAttackType].push(oDamageTypeObject);
								break;
							case "et_gut":
								oGoodHits[sAttackType].push(oDamageTypeObject);
								break;
							case "et_kritisch":
								oCriticalHits[sAttackType].push(oDamageTypeObject);
								break;
						}
					}

					for (let sAttackType of aAttackTypes) {
						oRawSetBonus[sPtType][sSubType][sAttackType][this.aHitTypes[0]] = this.setSetDetails(oRawSetBonus[sPtType][sSubType][sAttackType][this.aHitTypes[0]], oNormalHits[sAttackType], {
							blIsTripleValue: blTripleValueBonus
						});

						oRawSetBonus[sPtType][sSubType][sAttackType][this.aHitTypes[1]] = this.setSetDetails(oRawSetBonus[sPtType][sSubType][sAttackType][this.aHitTypes[1]], oGoodHits[sAttackType], {
							blIsTripleValue: blTripleValueBonus
						});

						oRawSetBonus[sPtType][sSubType][sAttackType][this.aHitTypes[2]] = this.setSetDetails(oRawSetBonus[sPtType][sSubType][sAttackType][this.aHitTypes[2]], oCriticalHits[sAttackType], {
							blIsTripleValue: blTripleValueBonus
						});

						let sDetailString = `${sSetName}: `;
						let oNormalBonus = oRawSetBonus[sPtType][sSubType][sAttackType][this.aHitTypes[0]].bonus;
						let oGoodBonus = oRawSetBonus[sPtType][sSubType][sAttackType][this.aHitTypes[1]].bonus;
						let oCriticalBonus = oRawSetBonus[sPtType][sSubType][sAttackType][this.aHitTypes[2]].bonus;
						let oNewBonus = this.updateSetTripleBonus(sPtType, oNormalBonus, oGoodBonus, oCriticalBonus);

						oRawSetBonus[sPtType][sSubType][sAttackType][this.aHitTypes[0]].bonus = oNewBonus[this.aHitTypes[0]].bonus;
						oRawSetBonus[sPtType][sSubType][sAttackType][this.aHitTypes[1]].bonus = oNewBonus[this.aHitTypes[1]].bonus;
						oRawSetBonus[sPtType][sSubType][sAttackType][this.aHitTypes[2]].bonus = oNewBonus[this.aHitTypes[2]].bonus;

						sDetailString += this.createTripleSetDetailString(sPtType, oNewBonus, aSubTypes);
						oRawSetBonus[sPtType][sSubType][sAttackType].details.push(sDetailString);
					}
				}
			}
		}

		return oRawSetBonus;
	}

	setSetDetails(oRawSetBonus, aSubTypes, oOption) {
		for (let oSubType of aSubTypes) {
			oRawSetBonus = this.extractBonusValueFromBonus(oRawSetBonus, oSubType, oOption);
		}

		return oRawSetBonus;
	}

	updateSetTripleBonus(sPtType, oNormalBonus, oGoodBonus, oCriticalBonus) {
		const oReturn = {};

		for (let sHitType of this.aHitTypes) {
			oReturn[sHitType] = this.bonusAndDetailTemplate();
		}
		switch (sPtType) {
			case this.oPowerUpApiKeys.sArmors:
			case this.oPowerUpApiKeys.sDamageFactors:
				oReturn[this.aHitTypes[0]].bonus.flBase = oCriticalBonus.flBase + oGoodBonus.flBase + oNormalBonus.flBase;
				oReturn[this.aHitTypes[0]].bonus.flHero = oCriticalBonus.flHero + oGoodBonus.flHero + oNormalBonus.flHero;
				oReturn[this.aHitTypes[0]].bonus.flSkill = oCriticalBonus.flSkill + oGoodBonus.flSkill + oNormalBonus.flSkill;

				oReturn[this.aHitTypes[1]].bonus.flBase = oCriticalBonus.flBase + oGoodBonus.flBase;
				oReturn[this.aHitTypes[1]].bonus.flHero = oCriticalBonus.flHero + oGoodBonus.flHero;
				oReturn[this.aHitTypes[1]].bonus.flSkill = oCriticalBonus.flSkill + oGoodBonus.flSkill;

				oReturn[this.aHitTypes[2]].bonus.flBase = oCriticalBonus.flBase;
				oReturn[this.aHitTypes[2]].bonus.flHero = oCriticalBonus.flHero;
				oReturn[this.aHitTypes[2]].bonus.flSkill = oCriticalBonus.flSkill;

				oReturn[this.aHitTypes[0]].bonus.flTotal = oReturn[this.aHitTypes[0]].bonus.flBase + oReturn[this.aHitTypes[0]].bonus.flHero + oReturn[this.aHitTypes[0]].bonus.flSkill;
				oReturn[this.aHitTypes[1]].bonus.flTotal = oReturn[this.aHitTypes[1]].bonus.flBase + oReturn[this.aHitTypes[1]].bonus.flHero + oReturn[this.aHitTypes[1]].bonus.flSkill;
				oReturn[this.aHitTypes[2]].bonus.flTotal = oReturn[this.aHitTypes[2]].bonus.flBase + oReturn[this.aHitTypes[2]].bonus.flHero + oReturn[this.aHitTypes[2]].bonus.flSkill;

				oReturn[this.aHitTypes[0]].bonus.percentage.flEffective = oCriticalBonus.percentage.flEffective * oGoodBonus.percentage.flEffective * oNormalBonus.percentage.flEffective;
				oReturn[this.aHitTypes[1]].bonus.percentage.flEffective = oCriticalBonus.percentage.flEffective * oGoodBonus.percentage.flEffective;
				oReturn[this.aHitTypes[2]].bonus.percentage.flEffective = oCriticalBonus.percentage.flEffective;
				break;
			case this.oPowerUpApiKeys.sDamages:
			case this.oPowerUpApiKeys.sDamagesZ:
				oReturn[this.aHitTypes[0]].bonus.flBase = oNormalBonus.flBase;
				oReturn[this.aHitTypes[0]].bonus.flHero = oNormalBonus.flHero;
				oReturn[this.aHitTypes[0]].bonus.flSkill = oNormalBonus.flSkill;

				oReturn[this.aHitTypes[1]].bonus.flBase = oNormalBonus.flBase + oGoodBonus.flBase;
				oReturn[this.aHitTypes[1]].bonus.flHero = oNormalBonus.flHero + oGoodBonus.flHero;
				oReturn[this.aHitTypes[1]].bonus.flSkill = oNormalBonus.flSkill + oGoodBonus.flSkill;

				oReturn[this.aHitTypes[2]].bonus.flBase = oNormalBonus.flBase + oGoodBonus.flBase + oCriticalBonus.flBase;
				oReturn[this.aHitTypes[2]].bonus.flHero = oNormalBonus.flHero + oGoodBonus.flHero + oCriticalBonus.flHero;
				oReturn[this.aHitTypes[2]].bonus.flSkill = oNormalBonus.flSkill + oGoodBonus.flSkill + oCriticalBonus.flSkill;

				oReturn[this.aHitTypes[0]].bonus.flTotal = oReturn[this.aHitTypes[0]].bonus.flBase + oReturn[this.aHitTypes[0]].bonus.flHero + oReturn[this.aHitTypes[0]].bonus.flSkill;
				oReturn[this.aHitTypes[1]].bonus.flTotal = oReturn[this.aHitTypes[1]].bonus.flBase + oReturn[this.aHitTypes[1]].bonus.flHero + oReturn[this.aHitTypes[1]].bonus.flSkill;
				oReturn[this.aHitTypes[2]].bonus.flTotal = oReturn[this.aHitTypes[2]].bonus.flBase + oReturn[this.aHitTypes[2]].bonus.flHero + oReturn[this.aHitTypes[2]].bonus.flSkill;

				oReturn[this.aHitTypes[0]].bonus.percentage.flEffective = oNormalBonus.percentage.flEffective;
				oReturn[this.aHitTypes[1]].bonus.percentage.flEffective = oNormalBonus.percentage.flEffective * oGoodBonus.percentage.flEffective;
				oReturn[this.aHitTypes[2]].bonus.percentage.flEffective = oNormalBonus.percentage.flEffective * oGoodBonus.percentage.flEffective * oCriticalBonus.percentage.flEffective;
				break;
		}

		oReturn[this.aHitTypes[0]].bonus.percentage.iLabel = this.setILabel(oReturn[this.aHitTypes[0]].bonus.percentage.flEffective);
		oReturn[this.aHitTypes[1]].bonus.percentage.iLabel = this.setILabel(oReturn[this.aHitTypes[1]].bonus.percentage.flEffective);
		oReturn[this.aHitTypes[2]].bonus.percentage.iLabel = this.setILabel(oReturn[this.aHitTypes[2]].bonus.percentage.flEffective);

		return oReturn;
	}

	/**
	 * @param sPtType
	 * @param oNewBonus
	 * @param {Array<pt_powerup>} aSetBonusObjects
	 * @return {string}
	 */
	createTripleSetDetailString(sPtType, oNewBonus, aSetBonusObjects) {
		let sReturnString = "";
		let sNormalString, sGoodString, sCriticalString
		let oNormalHitValues = objectStructure();
		let oGoodHitValues = objectStructure();
		let oCriticalHitValues = objectStructure();
		let oNormalCombinedValues = objectStructure();
		let oGoodCombinedValues = objectStructure();
		let oCriticalCombinedValues = objectStructure();

		for (let oSetBonusObject of aSetBonusObjects) {
			switch (oSetBonusObject.erfolgs_typ) {
				case this.aHitTypes[0]:
					oNormalHitValues = addToValues(oNormalHitValues, oSetBonusObject.bonus_typ, oSetBonusObject.bonus_wert);
					break;
				case this.aHitTypes[1]:
					oGoodHitValues = addToValues(oGoodHitValues, oSetBonusObject.bonus_typ, oSetBonusObject.bonus_wert);
					break;
				case this.aHitTypes[2]:
					oCriticalHitValues = addToValues(oCriticalHitValues, oSetBonusObject.bonus_typ, oSetBonusObject.bonus_wert);
					break;
			}
		}

		switch (sPtType) {
			case this.oPowerUpApiKeys.sDamages:
			case this.oPowerUpApiKeys.sDamagesZ:
				oNormalCombinedValues = oNormalHitValues;
				oGoodCombinedValues = {
					level: oNormalHitValues.level + oGoodHitValues.level,
					skill: oNormalHitValues.skill + oGoodHitValues.skill,
				};
				oCriticalCombinedValues = {
					level: oNormalHitValues.level + oGoodHitValues.level + oCriticalHitValues.level,
					skill: oNormalHitValues.skill + oGoodHitValues.skill + oCriticalHitValues.skill,
				};
				break;
			case this.oPowerUpApiKeys.sArmors:
			case this.oPowerUpApiKeys.sDamageFactors:
				oNormalCombinedValues = {
					level: oCriticalHitValues.level + oGoodHitValues.level + oNormalHitValues.level,
					skill: oCriticalHitValues.skill + oGoodHitValues.skill + oNormalHitValues.skill,
				};
				oGoodCombinedValues = {
					level: oCriticalHitValues.level + oGoodHitValues.level,
					skill: oCriticalHitValues.skill + oGoodHitValues.skill,
				};
				oCriticalCombinedValues = oCriticalHitValues;
				break;
		}

		sNormalString = detailStringPart(oNewBonus[this.aHitTypes[0]].bonus, oNormalCombinedValues);
		sGoodString = detailStringPart(oNewBonus[this.aHitTypes[1]].bonus, oGoodCombinedValues);
		sCriticalString = detailStringPart(oNewBonus[this.aHitTypes[2]].bonus, oCriticalCombinedValues);

		if (sNormalString === "") {
			sNormalString = "0";
		}

		if (sGoodString === "") {
			sGoodString = "0";
		}

		if (sCriticalString === "") {
			sCriticalString = "0";
		}

		sReturnString += `${sNormalString} / ${sGoodString} / ${sCriticalString}`;

		function objectStructure() {
			return {
				level: 0,
				skill: 0
			};
		}

		function addToValues(oHitValues, sSetBonusType, sSetBonusValue) {
			switch (sSetBonusType) {
				case skillsData.oPowerUpBoTypes.level:
					oHitValues.level += parseInt(sSetBonusValue);
					break;
				case skillsData.oPowerUpBoTypes.skill:
					oHitValues.skill += parseInt(sSetBonusValue);
					break;
			}

			return oHitValues;
		}

		function detailStringPart(oNewBonus, oCombinedLevelSkill) {
			let sReturnString = "";

			if (oNewBonus.flBase !== 0) {
				sReturnString += `${skillsData.prefacePlus(oNewBonus.flBase)}`;
			}

			if (oNewBonus.percentage.iLabel !== 0) {
				sReturnString += `${skillsData.prefacePlus(oNewBonus.percentage.iLabel)}%`;
			}

			if (oCombinedLevelSkill.level !== 0) {
				sReturnString += `${skillsData.prefacePlus(oCombinedLevelSkill.level)}% HS`;
			}

			if (oCombinedLevelSkill.skill !== 0) {
				sReturnString += `${skillsData.prefacePlus(oCombinedLevelSkill.skill)}% FR`;
			}

			return sReturnString;
		}

		return sReturnString;
	}

	/**
	 * @param {pt_powerup[]} aPowerUps
	 * @param {string} sPowerUpFrom - name of skill, item, monument, class or race
	 * @param {Object} [oOptions] - iSkillLevel for skills
	 * @param {Number} [oOptions.iSkillLevel]
	 */
	assignPowerUps(aPowerUps, sPowerUpFrom = "", oOptions) {
		if (typeof oOptions.iSkillLevel !== "undefined" && oOptions.iSkillLevel === 0) {
			return;
		}

		if (sPowerUpFrom !== "" || oOptions.iSkillLevel >= 0) {
			for (let oPowerUp of aPowerUps) {
				let sPtKey = this.assignCorrectPtKey(oPowerUp);

				if (sPtKey === this.oPowerUpApiKeys.sSkillRanks) {
					continue;
				}

				if (oPowerUp.bonus_wert === 0 || oPowerUp.bonus_wert === "0") {
					continue;
				}

				if (sPowerUpFrom !== "") {
					oPowerUp[this.oPowerUpSOLabel.sFrom] = sPowerUpFrom;
				}

				if (oOptions.iSkillLevel >= 0) {
					oPowerUp[this.oPowerUpSOLabel.sSkillRank] = oOptions.iSkillLevel;
				}

				if (!this.oPowerUps[sPtKey]) {
					this.oPowerUps[sPtKey] = [];
				}

				this.oPowerUps[sPtKey].push(oPowerUp);
			}
		}
	}

	/**
	 * @param {string} sPtType - pt_type of the calling bonus table
	 * @param {Object} oBonusTableValues - values of a bonus table, ie Attack, Attribute or Armor table
	 * @return {*}
	 */
	applySetBoniToPowerUps(sPtType, oBonusTableValues) {
		let blIsTripleValueBonus = this.isTripleValueBonus(sPtType);

		for (let [sSetId, oSetPowerUps] of Object.entries(this.oSetValues)) {
			//A set without bonuses of this kind.
			if (!oSetPowerUps[sPtType]) {
				continue;
			}

			for (let [sSubKey, oSetSubObject] of Object.entries(oSetPowerUps[sPtType])) {
				try {
					if (blIsTripleValueBonus) {
						for (let [sAttackType, oSetAttackTypeDamageType] of Object.entries(oSetSubObject)) {
							for (let sHitType of this.aHitTypes) {
								oBonusTableValues[sSubKey][sAttackType][sHitType].bonus = this.removeSetBonusOnItem(oBonusTableValues[sSubKey][sAttackType][sHitType].bonus, oSetAttackTypeDamageType[sHitType], sSetId);
							}

							oBonusTableValues[sSubKey][sAttackType].details = this.removeSetTripleBonusOnItemDetailString(oBonusTableValues[sSubKey][sAttackType].details, oSetAttackTypeDamageType.details[0], sSetId);
							oBonusTableValues[sSubKey][sAttackType].details.push(oSetAttackTypeDamageType.details[0]);
						}
					} else {
						oBonusTableValues[sSubKey].bonus = this.removeSetBonusOnItem(oBonusTableValues[sSubKey].bonus, oSetSubObject, sSetId);
						oBonusTableValues[sSubKey].details = this.removeSetBonusOnItemDetailString(oBonusTableValues[sSubKey].details, oSetSubObject.details[0], sSetId);
						//The set itself goes into the list of sources.
						oBonusTableValues[sSubKey].details.push(oSetSubObject.details[0]);
					}
				} catch (sError) {
					skillsLayout.addMessage(this.oMessages.sSetCacheError);
				}
			}
		}

		return oBonusTableValues;
	}

	removeSetBonusOnItem(oItemBonus, oSetSubObject, sSetId) {
		let oSetBonusObject = oSetSubObject.bonus;

		for (let sBonusKey of Object.keys(oItemBonus)) {
			if (sBonusKey === "percentage") {
				if (oSetBonusObject[sBonusKey].flEffective !== 1) {
					oItemBonus[sBonusKey].flEffective /= Math.pow(oSetBonusObject[sBonusKey].flEffective, this.oSets[sSetId].items.length - 1);
					oItemBonus[sBonusKey].flEffective = Math.trunc(oItemBonus[sBonusKey].flEffective * 100) / 100;
					oItemBonus[sBonusKey].iLabel = this.setILabel(oItemBonus[sBonusKey].flEffective);
				}
			} else {
				if (oSetBonusObject[sBonusKey] !== 0) {
					oItemBonus[sBonusKey] -= oSetBonusObject[sBonusKey] * (this.oSets[sSetId].items.length - 1);
				}
			}
		}

		oItemBonus.flTotal = this.setBonusTotal(oItemBonus);

		return oItemBonus;
	}

	removeSetBonusOnItemDetailString(aBonusDetails, sSetBonusDetail, sSetId) {
		let oRegEx = new RegExp(/^(?<item>.*): (?<base>[+-][0-9]{1,3})?\s?(?<perc>[-+][0-9]{1,3}%)?\s?(?<level>[+-][0-9]{0,3}(% )?HS)?\s?(?<skill>[+-][0-9]{0,3}(% )?FR)?$/, "gm");
		let aSetPowerUps = [...sSetBonusDetail.matchAll(oRegEx)];

		for (let oSetItem of this.oSets[sSetId].items) {
			let iIndex = aBonusDetails.findIndex(sDetail => {
				return sDetail.includes(`${oSetItem.template.name}`);
			});

			try {
				let aItemPowerUp = [...aBonusDetails[iIndex].matchAll(oRegEx)];
				let sNewDetailString = `${oSetItem.template.name}: `;
				sNewDetailString += this.updateDetailString(aSetPowerUps[0].groups.base, aItemPowerUp[0].groups.base, "base");
				sNewDetailString += this.updateDetailString(aSetPowerUps[0].groups.perc, aItemPowerUp[0].groups.perc, "perc");
				sNewDetailString += this.updateDetailString(aSetPowerUps[0].groups.level, aItemPowerUp[0].groups.level, "level");
				sNewDetailString += this.updateDetailString(aSetPowerUps[0].groups.skill, aItemPowerUp[0].groups.skill, "skill");

				if (sNewDetailString !== `${oSetItem.template.name}: `) {
					aBonusDetails[iIndex] = sNewDetailString;
				} else {
					aBonusDetails.splice(iIndex, 1);
				}
			} catch (sError) {
				skillsLayout.addMessage(this.oMessages.sSetCacheError);
			}
		}

		return aBonusDetails;
	}

	removeSetTripleBonusOnItemDetailString(aPowerUpDetailStrings, sSetBonusDetail, sSetId) {
		let oRegExWithoutName = new RegExp(/^(?<base>[+-]?[0-9]{1,3})?\s?(?<perc>[-+][0-9]{1,3}%)?\s?(?<level>[+-][0-9]{0,3}(% )?HS)?\s?(?<skill>[+-][0-9]{0,3}(% )?FR)?$/, "gm");
		let sSetDetailWithoutName = sSetBonusDetail.replace(/.*:\s/gm, "");
		let aSplitSetValues = sSetDetailWithoutName.split("/");
		let aSetValues = [];

		for (let iSetIndex in aSplitSetValues) {
			aSetValues[iSetIndex] = [...aSplitSetValues[iSetIndex].trim().matchAll(oRegExWithoutName)][0];
		}

		for (let oSetItem of this.oSets[sSetId].items) {
			let iIndex = aPowerUpDetailStrings.findIndex(sDetail => {
				return sDetail.includes(`${oSetItem.template.name}`);
			});

			try {
				let sDetailStringWithoutItemName = aPowerUpDetailStrings[iIndex].replace(`${oSetItem.template.name}: `, "");
				let aItemSplit = sDetailStringWithoutItemName.split("/");
				let sNewDetailString = `${oSetItem.template.name}: `;

				for (let iItemValueIndex in aItemSplit) {
					let aItemPowerUp = [...aItemSplit[iItemValueIndex].trim().matchAll(oRegExWithoutName)];
					let sNewPartialDetailString = "";

					sNewPartialDetailString += this.updateDetailString(aSetValues[iItemValueIndex].groups.base, aItemPowerUp[0].groups.base, "base");
					sNewPartialDetailString += this.updateDetailString(aSetValues[iItemValueIndex].groups.perc, aItemPowerUp[0].groups.perc, "perc");
					sNewPartialDetailString += this.updateDetailString(aSetValues[iItemValueIndex].groups.level, aItemPowerUp[0].groups.level, "level");
					sNewPartialDetailString += this.updateDetailString(aSetValues[iItemValueIndex].groups.skill, aItemPowerUp[0].groups.skill, "skill");

					if (sNewPartialDetailString === "") {
						sNewPartialDetailString += "0";
					}

					if (iItemValueIndex < 2) {
						sNewPartialDetailString += " / ";
					}

					sNewDetailString += sNewPartialDetailString;
				}

				if (sNewDetailString.includes("0 / 0 / 0")) {
					aPowerUpDetailStrings.splice(iIndex, 1);
				} else {
					aPowerUpDetailStrings[iIndex] = sNewDetailString;
				}
			} catch (sError) {
				skillsLayout.addMessage(this.oMessages.sSetCacheError);
			}
		}

		return aPowerUpDetailStrings;
	}

	updateDetailString(sSetPowerUp, sItemPowerUps, sType) {
		let sNewDetailString = "";
		let flItemPowerUp = parseFloat(sItemPowerUps);
		let flSetPowerUp = parseFloat(sSetPowerUp);
		let flNewValue = flItemPowerUp - flSetPowerUp;

		if (!flSetPowerUp && !sItemPowerUps) {
			return "";

		}
		if (flNewValue === 0) {
			return "";
		}

		if (flItemPowerUp && flSetPowerUp) {
			sNewDetailString += `${this.prefacePlus(flNewValue)}`;
		} else if (flItemPowerUp && !flSetPowerUp) {
			sNewDetailString += this.prefacePlus(flItemPowerUp);
		}

		if (sType !== "base") {
			sNewDetailString += "%";
		}

		switch (sType) {
			case "level":
				sNewDetailString += " HS";
				break;
			case "skill":
				sNewDetailString += " FR";
				break;
		}

		return sNewDetailString;
	}

	getBonusTableAttackValues() {
		let aAttackValues = this.oPowerUps[this.oPowerUpApiKeys.sAttacks].filter(/** @param {pt_powerup} oAttack**/oAttack => {
			return oAttack.wirkungs_art !== this.oPowerUpEffectType.sActive
		});

		return this.getBonusFromPowerUp(aAttackValues);
	}

	getBonusTableAttributeValues() {
		let aAttributeValues = this.oPowerUps[this.oPowerUpApiKeys.sAttributes].filter(/** @param {pt_powerup} oAttribute**/oAttribute => {
			return oAttribute.wirkungs_art !== this.oPowerUpEffectType.sActive
		});

		return this.getBonusFromPowerUp(aAttributeValues);
	}

	getBonusTableDropValues() {
		let oDropValues = this.oPowerUps[this.oPowerUpApiKeys.sDrops].filter(/** @param {pt_powerup} oDrops **/oDrops => {
			return oDrops.wirkungs_art !== this.oPowerUpEffectType.sActive;
		});

		return this.getBonusFromPowerUp(oDropValues);
	}

	getBonusTableParadeValues() {
		let oParadesValues = this.oPowerUps[this.oPowerUpApiKeys.sParades].filter(/** @param {pt_powerup} oParades **/oParades => {
			return oParades.wirkungs_art !== this.oPowerUpEffectType.sActive;
		});

		return this.getBonusFromPowerUp(oParadesValues);
	}

	getBonusTableArmorValues() {
		let oArmorValues = this.oPowerUps[this.oPowerUpApiKeys.sArmors].filter(/** @param {pt_powerup} oArmor **/oArmor => {
			return oArmor.wirkungs_art !== this.oPowerUpEffectType.sActive;
		});

		return this.getBonusFromPowerUp(oArmorValues);
	}

	getBonusTableDamageValues() {
		let oDamageValues = this.oPowerUps[this.oPowerUpApiKeys.sDamages].filter(/** @param {pt_powerup} oDamage **/oDamage => {
			return oDamage.wirkungs_art !== this.oPowerUpEffectType.sActive;
		});

		return this.getBonusFromPowerUp(oDamageValues);
	}

	getBonusTableDamageZValues() {
		let oDamageZValues = this.oPowerUps[this.oPowerUpApiKeys.sDamagesZ].filter(/** @param {pt_powerup} oDamageZ **/oDamageZ => {
			return oDamageZ.wirkungs_art !== this.oPowerUpEffectType.sActive;
		});

		return this.getBonusFromPowerUp(oDamageZValues);
	}

	getBonusTableDamageFactorValues() {
		let oDamageFactorValues = this.oPowerUps[this.oPowerUpApiKeys.sDamageFactors].filter(/** @param {pt_powerup} oDamageFactor **/oDamageFactor => {
			return oDamageFactor.wirkungs_art !== this.oPowerUpEffectType.sActive;
		});

		return this.getBonusFromPowerUp(oDamageFactorValues);
	}

	getBonusTableSkillEffectValues() {
		let oSkillEffectValues = this.oPowerUps[this.oPowerUpApiKeys.sSkillsEffect].filter(/** @param {pt_powerup} oSkillEffect **/oSkillEffect => {
			return oSkillEffect.wirkungs_art !== this.oPowerUpEffectType.sActive;
		});

		return this.getBonusFromPowerUp(oSkillEffectValues);
	}

	/*
	 * All nine bonus overviews at once, each with the set bonuses taken off the items
	 * that carry them and put back once for the set.
	 */
	bonusTables() {
		const k = this.oPowerUpApiKeys;
		return {
			attacks: this.applySetBoniToPowerUps(k.sAttacks, this.getBonusTableAttackValues()),
			attributes: this.applySetBoniToPowerUps(k.sAttributes, this.getBonusTableAttributeValues()),
			drops: this.applySetBoniToPowerUps(k.sDrops, this.getBonusTableDropValues()),
			parades: this.applySetBoniToPowerUps(k.sParades, this.getBonusTableParadeValues()),
			armor: this.applySetBoniToPowerUps(k.sArmors, this.getBonusTableArmorValues()),
			damages: this.applySetBoniToPowerUps(k.sDamages, this.getBonusTableDamageValues()),
			damagesZ: this.applySetBoniToPowerUps(k.sDamagesZ, this.getBonusTableDamageZValues()),
			damageFactors: this.applySetBoniToPowerUps(k.sDamageFactors, this.getBonusTableDamageFactorValues()),
			skillEffects: this.applySetBoniToPowerUps(k.sSkillsEffect, this.getBonusTableSkillEffectValues())
		};
	}

	/**
	 * @param {Array<pt_powerup>} aPtPowerUp
	 * @return {bonus_type_details|Array}
	 */
	getBonusFromPowerUp(aPtPowerUp) {
		if (aPtPowerUp.length === 0) {
			return aPtPowerUp;
		}

		/**
		 * @type {bonus_type_details}
		 */
		let oReturnBonus = {};

		for (let oPowerUp of aPtPowerUp) {
			const sPtType = this.assignCorrectPtKey(aPtPowerUp[0]);
			const blIsTripleValue = this.isTripleValueBonus(sPtType);
			const sTripleAttackType = oPowerUp.angriffs_typ || this.sAllAttackTypKey;
			let {sSubKey, sLabel} = this.getBonusKeyAndLabel(oPowerUp);
			sLabel = this.translateSpecialSymbols(sLabel);

			if (!blIsTripleValue && !oReturnBonus[sSubKey]) {
				//sSubKey: an_*, at_*, a drop, a hidden attribute
				oReturnBonus[sSubKey] = this.bonusAndDetailTemplate({
					sPtType: sPtType,
					mSkillClass: oPowerUp.talent_klasse,
					sLabel: sLabel
				})
			}

			if (blIsTripleValue) {
				if (!oReturnBonus[sSubKey]) {
					//sSubKey: the damage type of armour, damage or damage factor
					oReturnBonus[sSubKey] = this.bonusAndDetailTemplate({
						blIsTripleValue: blIsTripleValue,
						blBonus: false,
						blDetails: false
					})
				}

				if (!oReturnBonus[sSubKey][sTripleAttackType]) {
					let oAttackType = oPowerUp.label_angriffs_typ || this.oTypes.angriffs_typ[oPowerUp.angriffs_typ];
					oReturnBonus[sSubKey][sTripleAttackType] = this.bonusAndDetailTemplate({
						blIsTripleValue: blIsTripleValue,
						sLabel: `${sLabel} (${oAttackType || this.sAllAttackTypKey})`,
						blBonus: false,
						blDetails: true
					});

					for (let sHitType of this.aHitTypes) {
						oReturnBonus[sSubKey][sTripleAttackType][sHitType] = this.bonusAndDetailTemplate({
							sLabel: this.oTypes.erfolgs_typ[sHitType],
							blDetails: false
						});
					}
				}
			}

			if (oPowerUp.bonus_typ) {
				//Typed values: monument, class_plain, sets.

				if (oReturnBonus[sSubKey].blIsTripleValue) {
					let sDetailString = `${oPowerUp.wod_SO_powerup_von}: `;

					for (let sHitType of this.aHitTypes) {
						let flTotal = 0;
						let iLabel = 0;

						oReturnBonus[sSubKey][sTripleAttackType][sHitType] = this.extractBonusValueFromBonus(oReturnBonus[sSubKey][sTripleAttackType][sHitType], oPowerUp, {
							blIsTripleValue: blIsTripleValue
						});

						flTotal = this.setBonusTotal(oReturnBonus[sSubKey][sTripleAttackType][sHitType].bonus);
						iLabel = oReturnBonus[sSubKey][sTripleAttackType][sHitType].bonus.percentage.iLabel;

						oReturnBonus[sSubKey][sTripleAttackType][sHitType].bonus.flTotal = flTotal;

						if (flTotal !== 0) {
							sDetailString += this.prefacePlus(flTotal);
						}

						if (iLabel !== 0) {
							if (flTotal !== 0) {
								let sOperator = "";

								if (iLabel < 0) {
									sOperator = "-";
								} else {
									sOperator = "+";
								}

								if (flTotal !== 0) {
									sOperator = ` ${sOperator} `;
								}

								sDetailString += `${sOperator}${Math.abs(iLabel)}`;
							} else {
								sDetailString += this.prefacePlus(iLabel);
							}
						}

						if (sHitType !== this.aHitTypes[2]) {
							sDetailString += " / ";
						}
					}

					oReturnBonus[sSubKey][sTripleAttackType].details.push(this.shortenDetailString(sDetailString));
				} else {
					oReturnBonus[sSubKey] = this.extractBonusValueFromBonus(oReturnBonus[sSubKey], oPowerUp, {
						blIsTripleValue: blIsTripleValue
					});

					oReturnBonus[sSubKey].bonus.flTotal = this.setBonusTotal(oReturnBonus[sSubKey].bonus);
				}
			} else if (blIsTripleValue) {
				//Three values in the text of bonus_wert: armour, damage, damage factor.

				let oSplits = oPowerUp.bonus_wert.split(/\/[^span]/gm);
				let sDetailString = `${oPowerUp.wod_SO_powerup_von}: `;

				for (let iSplitIndex in oSplits) {
					let oPowerUpObject = {
						wod_SO_powerup_von: oPowerUp.wod_SO_powerup_von,
						wod_SO_powerup_skill_rang: oPowerUp.wod_SO_powerup_skill_rang,
						bonus_wert: oSplits[iSplitIndex]
					};
					oReturnBonus[sSubKey][sTripleAttackType][this.aHitTypes[iSplitIndex]] = this.extractBonusValueFromItemString(oReturnBonus[sSubKey][sTripleAttackType][this.aHitTypes[iSplitIndex]], oPowerUpObject, {
						blIsTripleValue: blIsTripleValue
					});

					oReturnBonus[sSubKey][sTripleAttackType][this.aHitTypes[iSplitIndex]].bonus.flTotal = this.setBonusTotal(oReturnBonus[sSubKey][sTripleAttackType][this.aHitTypes[iSplitIndex]].bonus);
				}

				sDetailString += oPowerUp.bonus_wert.replace(/<span class="gem_(malus|bonus)(_(only|also)_by_gem)?">/gm, "").replace(/<\/span>/gm, "");
				oReturnBonus[sSubKey][sTripleAttackType].details.push(this.shortenDetailString(sDetailString));
			} else {
				//One value in the text of bonus_wert: attacks, parades, drops, attributes.

				oReturnBonus[sSubKey] = this.extractBonusValueFromItemString(oReturnBonus[sSubKey], oPowerUp, {});
				oReturnBonus[sSubKey].bonus.flTotal = this.setBonusTotal(oReturnBonus[sSubKey].bonus);
			}
		}

		return oReturnBonus;
	}

	/**
	 * @param oReturnBonusWithBonusKey
	 * @param oPowerUp
	 * @param oOptions
	 * @param sSource
	 * @return {bonus}
	 */
	extractBonusValueFromBonus(oReturnBonusWithBonusKey, oPowerUp, oOptions, sSource = "powerup") {
		const oTypeKey = {
			"powerup": "bonus_typ",
			"probe": "proben_bonus_typ",
			"effect": "wirk_bonus_typ",
		};
		const oValueKey = {
			"powerup": "bonus_wert",
			"probe": "proben_bonus_wert",
			"effect": "wirk_bonus_wert",
		};
		let sBonusDetails = "";
		let iDetailIndex = oOptions.blIsTripleValue ? -1 : oReturnBonusWithBonusKey.details.findIndex(sDetail => {
			return sDetail.includes(oPowerUp.wod_SO_powerup_von);
		});

		switch (oPowerUp[oTypeKey[sSource]]) {
			case this.oPowerUpBoTypes.base:
				oReturnBonusWithBonusKey.bonus.flBase += parseFloat(oPowerUp[oValueKey[sSource]]);
				sBonusDetails = this.prefacePlus(oPowerUp[oValueKey[sSource]]);
				break;
			case this.oPowerUpBoTypes.level:
				//A share of the hero level.
				oReturnBonusWithBonusKey.bonus.flHero += (parseFloat(oPowerUp[oValueKey[sSource]]) / 100) * skillsHero.iLevel;
				sBonusDetails = this.prefacePlus(oPowerUp[oValueKey[sSource]]) + "% HS";
				break;
			case this.oPowerUpBoTypes.skill:
				//A share of the skill rank.
				oReturnBonusWithBonusKey.bonus.flSkill += (parseFloat(oPowerUp[oValueKey[sSource]]) / 100) * oPowerUp.wod_SO_powerup_skill_rang;
				sBonusDetails = this.prefacePlus(oPowerUp[oValueKey[sSource]]) + "% FR";
				break;
			case this.oPowerUpBoTypes.percentage:
				//0 stands for "not set" in the data interface, not for "nothing left".
				if (parseFloat(oPowerUp[oValueKey[sSource]]) === 0)
					break;
				oReturnBonusWithBonusKey.bonus.percentage.flEffective *= parseFloat(oPowerUp[oValueKey[sSource]]) / 100;
				oReturnBonusWithBonusKey.bonus.percentage.iLabel = this.setILabel(oReturnBonusWithBonusKey.bonus.percentage.flEffective);
				sBonusDetails = this.prefacePlus(parseFloat(oPowerUp[oValueKey[sSource]]) - 100) + "%";
				break;
			case "bo_wurf":
				//Only monsters carry it.
				break;
			default:
		}

		if (!oOptions.blIsTripleValue) {
			if (iDetailIndex >= 0) {
				//The fixed part need not come first. Seen with the social parries of the Rashani.
				if (!sBonusDetails.includes("%")) {
					let aStringParts = oReturnBonusWithBonusKey.details[iDetailIndex].split(":");

					if (aStringParts[1]) {
						if (aStringParts[1].includes("%")) {
							sBonusDetails = `${this.prefacePlus(parseFloat(sBonusDetails))}${aStringParts[1].trim()}`;
						} else {
							sBonusDetails = this.prefacePlus(parseFloat(sBonusDetails) + parseFloat(aStringParts[1].trim()));
						}

					} else {
					}

					oReturnBonusWithBonusKey.details[iDetailIndex] = `${aStringParts[0]}: ${sBonusDetails}`;
				} else {

					if (oReturnBonusWithBonusKey.details[iDetailIndex].includes("% HS") && sBonusDetails.includes("% HS")) {
						let flOldValue = parseInt(oReturnBonusWithBonusKey.details[iDetailIndex].match(/[0-9]*?% HS/gm)[0]);
						let flNewValue = parseInt(sBonusDetails.match(/[0-9]*?% HS/gm)[0]);
						oReturnBonusWithBonusKey.details[iDetailIndex] = oReturnBonusWithBonusKey.details[iDetailIndex].replace(/[0-9]*?% HS/gm, `${Math.trunc(flOldValue + flNewValue)}% FR`);
					} else if (oReturnBonusWithBonusKey.details[iDetailIndex].includes("% FR") && sBonusDetails.includes("% FR")) {
						let flOldValue = parseInt(oReturnBonusWithBonusKey.details[iDetailIndex].match(/[0-9]*?% FR/gm)[0]);
						let flNewValue = parseInt(sBonusDetails.match(/[0-9]*?% FR/gm)[0]);
						oReturnBonusWithBonusKey.details[iDetailIndex] = oReturnBonusWithBonusKey.details[iDetailIndex].replace(/[0-9]*?% FR/gm, `${Math.trunc(flOldValue + flNewValue)}% FR`);
					} else {
						oReturnBonusWithBonusKey.details[iDetailIndex] += sBonusDetails;
					}
				}
			} else {
				oReturnBonusWithBonusKey.details.push(`${oPowerUp.wod_SO_powerup_von}: ${sBonusDetails}`);
			}
		}

		return oReturnBonusWithBonusKey;
	}

	extractBonusValueFromItemString(oReturnBonusWithBonusKey, oPowerUp, oOptions) {
		let sBonusDetails = `${oPowerUp.wod_SO_powerup_von}: `;
		let aValues = [...oPowerUp.bonus_wert.matchAll(/<span class="gem_(malus|bonus)(_(only|also)_by_gem)?">(?<detail_string>(?<value>[+-][0-9]{0,5})\s?(?<percentage>[%x]?)\s?(de[sr]\s)?((?<per_type>Heldenstufe|Fertigkeitenrang)s?)?)<\/span>/gm)];

		for (let oMatch of aValues) {
			/**
			 * @type {Object}
			 * @property {string} detail_string
			 * @property {string} value
			 * @property {string} percentage
			 * @property {string} per_type
			 */
			const oValues = oMatch.groups

			if (!oOptions.blIsTripleValue) {
				sBonusDetails += `${oValues.detail_string}`;
				sBonusDetails = this.shortenDetailString(sBonusDetails);
			}

			//A plain number, e.g. -3 or +5.
			if (oValues.percentage === "" && oValues.per_type === undefined) {

				oReturnBonusWithBonusKey.bonus.flBase += parseFloat(oValues.value);
			}
			//Bonuses that depend on the skill rank.
			else if (oValues.per_type === "Fertigkeitenrang") {
				if (oValues.percentage === "") {
					//+ or - the rank
					if (oValues.value === "-" || oValues.value === "+") {

						oReturnBonusWithBonusKey.bonus.flSkill += parseFloat(`${oValues.value}${oPowerUp.wod_SO_powerup_skill_rang}`);
					}
					//+ or - x
					else {

						oReturnBonusWithBonusKey.bonus.flSkill += parseFloat(oValues.value);
					}
				}
				//+ or - x% of the rank
				else {
					//+ y times the rank, e.g. Robust
					if (oValues.percentage === "x") {

						oReturnBonusWithBonusKey.bonus.flSkill += parseFloat(oValues.value) * oPowerUp.wod_SO_powerup_skill_rang;
					}
					//+ x% of the rank
					else {

						oReturnBonusWithBonusKey.bonus.flSkill += Number(oValues.value / 100) * oPowerUp.wod_SO_powerup_skill_rang;
					}
				}
			}
			//Bonuses that depend on the hero level.
			else if (oValues.per_type === "Heldenstufe") {
				if (oValues.percentage === "") {
					//+ or - the level
					if (oValues.value === "-" || oValues.value === "+") {

						oReturnBonusWithBonusKey.bonus.flHero += parseFloat(`${oValues.value}${skillsHero.iLevel}`);
					}
					//+ or - x
					else {

						oReturnBonusWithBonusKey.bonus.flHero += parseFloat(oValues.value);
					}
				}
				//+ or - x% of the level
				else {

					oReturnBonusWithBonusKey.bonus.flHero += ((parseFloat(oValues.value) / 100) * skillsHero.iLevel);
				}
			}
			//A plain percentage.
			else if (oValues.percentage === "%" && oValues.per_type === undefined) {
				let flOldEffective = oReturnBonusWithBonusKey.bonus.percentage.flEffective;
				let flEffectiveValue = (100 + parseFloat(oValues.value)) / 100;
				let iNewShowValue = this.setILabel(flOldEffective * flEffectiveValue);

				oReturnBonusWithBonusKey.bonus.percentage.flEffective *= flEffectiveValue;
				oReturnBonusWithBonusKey.bonus.percentage.iLabel = iNewShowValue;
			}
		}

		if (!oOptions.blIsTripleValue) {
			oReturnBonusWithBonusKey.details.push(sBonusDetails);
		}

		return oReturnBonusWithBonusKey;
	}

	setBonusTotal(oBonus) {
		return oBonus.flBase + oBonus.flHero + oBonus.flSkill;
	}

	setILabel(flEffectiveValue) {
		return Math.trunc(flEffectiveValue * 100 - 100);
	}

	shortenDetailString(sBonusDetails) {
		sBonusDetails = sBonusDetails.replace(/(des )?Fertigkeitenrangs?/gm, "FR");
		sBonusDetails = sBonusDetails.replace(/(der )?Heldenstufe/gm, "HS");

		let oldFormatBonus = sBonusDetails.match(/[+-](?<number>[0-9]{1,3}) x (?:FR|HS)/);
		if (oldFormatBonus?.groups) {
			let sNewFormatValue = (oldFormatBonus.groups.number * 100).toString();
			sBonusDetails = sBonusDetails.replace(/[0-9]{1,3}/, sNewFormatValue);
			sBonusDetails = sBonusDetails.replace(" x", "%");
		}

		return sBonusDetails;
	}

	/**
	 * @param sPtType
	 * @return {Boolean}
	 */
	isTripleValueBonus(sPtType) {
		return sPtType === this.oPowerUpApiKeys.sArmors || sPtType === this.oPowerUpApiKeys.sDamages || sPtType === this.oPowerUpApiKeys.sDamagesZ || sPtType === this.oPowerUpApiKeys.sDamageFactors;
	}

	/**
	 * @param {pt_powerup} oBonus
	 * @return {{sLabel: string, sKey}}
	 */
	getBonusKeyAndLabel(oBonus) {
		let sBonusKey, sLabel;

		switch (oBonus.typ) {
			case this.oPowerUpApiKeys.sAttacks:
			case this.oPowerUpApiKeys.sParades:
				sBonusKey = oBonus.angriffs_typ;
				sLabel = this.oTypes.angriffs_typ[oBonus.angriffs_typ];
				break;
			case this.oPowerUpApiKeys.sDrops:
				sBonusKey = oBonus.extra_drop;

				if (this.oTypes.attribute_versteckt[oBonus.extra_drop]) {
					sLabel = this.oTypes.attribute_versteckt[oBonus.extra_drop];
				} else {
					sLabel = oBonus.extra_drop.at(0).toUpperCase() + oBonus.extra_drop.slice(1);
				}
				break;
			case this.oPowerUpApiKeys.sAttributes:
				sBonusKey = oBonus.attribut;
				sLabel = oBonus.label_attribut || this.oTypes.attribute[oBonus.attribut] || this.oTypes.attribute_versteckt[oBonus.attribut];
				break;
			case this.oPowerUpApiKeys.sSkillsEffect:
			case this.oPowerUpApiKeys.sSkillRanks:
				if (oBonus.talent && oBonus.talent !== "0") {
					try {
						sBonusKey = this.oSkillsById[oBonus.talent].template.label;
					} catch (sError) {
						if (!oBonus.label_talent) {
							//Known neither by id nor by link.
							return {
								sBonusKey: oBonus.talent,
								sLabel: oBonus.talent
							}
						} else {
							sBonusKey = /<a .*?>(?<skill>.*?)<\/a>/.exec(oBonus.label_talent).groups.skill;
						}
					}
				} else if (oBonus.talent_klasse && oBonus.talent_klasse !== "0") {
					try {
						sBonusKey = this.oSkillClasses[oBonus.talent_klasse].name;
					} catch (sError) {
						sBonusKey = oBonus.talent_klasse;
					}
				} else {
					sBonusKey = oBonus.typ;
				}

				sLabel = sBonusKey;
				break;
			case this.oPowerUpApiKeys.sArmors:
			case this.oPowerUpApiKeys.sDamages:
			case this.oPowerUpApiKeys.sDamageFactors:
				sLabel = `${oBonus.label_schadens_typ || this.oTypes.schadens_typ[oBonus.schadens_typ]}`;
				sBonusKey = `${oBonus.schadens_typ}`;
				break;
			default:
				sBonusKey = oBonus.typ;
		}

		return {
			sSubKey: sBonusKey,
			sLabel: sLabel
		};
	}

	/**
	 * @param [oOptions]
	 * @param {Boolean} [oOptions.blIsTripleValue] - blIsTripleValue boolean
	 * @param {Boolean} [oOptions.blBonus] - bonus object, default true
	 * @param {Boolean} [oOptions.blDetails] - details array, default true
	 * @param {string} [oOptions.sPtType] - istTalentKlasseWirkung boolean
	 * @param {string|Number} [oOptions.mSkillClass] - istTalentKlasseWirkung boolean
	 * @param {string} [oOptions.sLabel] - wod_SO_mame string
	 */
	bonusAndDetailTemplate(oOptions) {
		let oReturnObject = {};

		if (!oOptions) {
			oOptions = {};
		}

		if (typeof oOptions.blBonus === "undefined") {
			oOptions.blBonus = true;
		}

		if (typeof oOptions.blDetails === "undefined") {
			oOptions.blDetails = true;
		}

		if (typeof oOptions.blIsTripleValue !== "undefined") {
			oReturnObject.blIsTripleValue = oOptions.blIsTripleValue;
		}

		if (oOptions.blBonus) {
			oReturnObject.bonus = {
				flBase: 0,
				flHero: 0,
				flSkill: 0,
				percentage: {
					iLabel: 0,
					flEffective: 1
				},
				flTotal: 0
			};
		}

		if (oOptions.blDetails) {
			oReturnObject.details = [];
		}

		if (oOptions.sPtType && oOptions.mSkillClass && parseInt(oOptions.mSkillClass) !== 0) {
			oReturnObject.istTalentKlasseWirkung = this.ifTalentKlasseWirkung(oOptions.sPtType, oOptions.mSkillClass);
		}

		if (oOptions.sLabel && oOptions.sLabel !== "") {
			oReturnObject.wod_SO_name = this.translateSpecialSymbols(oOptions.sLabel);
		}

		return oReturnObject;
	}

	assignCorrectPtKey(oPowerUp) {
		let sPtKey = oPowerUp.typ;

		if (sPtKey === this.oPowerUpApiKeys.sDamages && oPowerUp.schadens_wirkungs_art === this.oPowerUpDamageEffectType.sDamageZ) {
			sPtKey = this.oPowerUpApiKeys.sDamagesZ;
		}

		return sPtKey;
	}

	/**
	 * @param sPtType
	 * @param mTalentKlasse
	 * @return {boolean}
	 */
	ifTalentKlasseWirkung(sPtType, mTalentKlasse) {
		return sPtType === "pt_wirkung" && parseInt(mTalentKlasse) !== 0;
	}

	prefacePlus(mNumber) {
		let sReturnString = "";

		if (parseFloat(mNumber) > 0) {
			sReturnString += "+";
		}

		return sReturnString + mNumber;
	}

	translateSpecialSymbols(sString) {
		return String(sString == null ? "" : sString)
			.replace(/&auml;/gm, "ä").replace(/&ouml;/gm, "ö").replace(/&uuml;/gm, "ü")
			.replace(/&Auml;/gm, "Ä").replace(/&Ouml;/gm, "Ö").replace(/&Uuml;/gm, "Ü")
			.replace(/&szlig;/gm, "ß").replace(/&amp;/gm, "&");
	}
}

/////////////////////////////////////////////////////////////////////////////
///////////////// Module: the skills page, skills and items /////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * One skill or one item, with the powerups that only count when it is used: the
 * attribute, throw, damage and rank bonuses on use, and for a skill its template
 * with attributes, attack type, targets, mana cost and the rest.
 *
 * The standard parries and the standard initiative are skills without a template
 * of their own; they get only what a throw needs.
 */

class SkillsPowerUp {
	oPowerUps = {};

	constructor() {
	}

	applyPowerUps(oSkillPowerUps, iRankEffective = 0) {
		for (let [sPtKey, aPowerUp] of Object.entries(oSkillPowerUps)) {
			const aPowerUpsOnApplication = [];
			const aDamageZ = [];

			aPowerUp.forEach(/** @param {pt_powerup} oPowerUp **/oPowerUp => {
				if (oPowerUp.wirkungs_art === skillsData.oPowerUpEffectType.sActive) {
					oPowerUp[skillsData.oPowerUpSOLabel.sSkillRank] = iRankEffective;

					if (sPtKey === skillsData.oPowerUpApiKeys.sDamages && oPowerUp.schadens_wirkungs_art === skillsData.oPowerUpDamageEffectType.sDamageZ) {
						aDamageZ.push(oPowerUp);
					} else {
						aPowerUpsOnApplication.push(oPowerUp);
					}
				}
			});

			this.oPowerUps[sPtKey] = skillsData.getBonusFromPowerUp(aPowerUpsOnApplication);

			if (aDamageZ.length > 0) {
				this.oPowerUps[skillsData.oPowerUpApiKeys.sDamagesZ] = skillsData.getBonusFromPowerUp(aDamageZ);
			}
		}
	}

	getPowerUpAttribute(sAttributeKey) {
		let flFixed = 0;
		let flPercent = 1;

		if (this.oPowerUps.pt_attribut) {
			/**
			 * @type {bonus}
			 */
			const oAttributePowerUp = this.oPowerUps.pt_attribut[sAttributeKey];

			if (oAttributePowerUp) {
				flFixed += oAttributePowerUp.bonus.flTotal;
				flPercent *= oAttributePowerUp.bonus.percentage.flEffective;
			}
		}

		return {
			fixed: flFixed,
			percent: flPercent
		};
	}

	/*
	 * The Probe or Wirkung bonus of a skill template or an item class. One in shares
	 * of the skill rank ("+50% des Fertigkeitenrangs") is reckoned with the rank
	 * given; the data interface itself carries none there.
	 */
	getProbeEffectExtract(sType, oPowerUps, iRang = 0) {
		const oMitRang = Object.assign({}, oPowerUps);
		oMitRang[skillsData.oPowerUpSOLabel.sSkillRank] = Number(iRang) || 0;
		const oBonus = skillsData.extractBonusValueFromBonus(skillsData.bonusAndDetailTemplate(), oMitRang, {blIsTripleValue: true}, sType);

		return {
			percent: oBonus.bonus.percentage.flEffective,
			fixed: skillsData.setBonusTotal(oBonus.bonus) || 0
		}
	}

	getPowerUpDamage(sDamageType, sAttackType, blIsTrigger = true) {
		const oReturn = {};
		oReturn[skillsData.aHitTypes[0]] = skillsData.bonusAndDetailTemplate({blDetails: false, blIsTripleValue: true});
		oReturn[skillsData.aHitTypes[1]] = skillsData.bonusAndDetailTemplate({blDetails: false, blIsTripleValue: true});
		oReturn[skillsData.aHitTypes[2]] = skillsData.bonusAndDetailTemplate({blDetails: false, blIsTripleValue: true});
		oReturn[SKILLS_DAMAGE_TYPE_KEY] = sDamageType;

		let sPowerUpKey = skillsData.oPowerUpApiKeys.sDamagesZ;

		if (blIsTrigger) {
			sPowerUpKey = skillsData.oPowerUpApiKeys.sDamages;
		}

		if (!this.oPowerUps[sPowerUpKey]) {
			return oReturn;
		}

		if (!this.oPowerUps[sPowerUpKey][sDamageType]) {
			return oReturn;
		}

		if (this.oPowerUps[sPowerUpKey][sDamageType][sAttackType]) {
			for (let sHitType of skillsData.aHitTypes) {
				oReturn[sHitType].bonus.flTotal += this.oPowerUps[sPowerUpKey][sDamageType][sAttackType][sHitType].bonus.flTotal;
				oReturn[sHitType].bonus.percentage.flEffective *= this.oPowerUps[sPowerUpKey][sDamageType][sAttackType][sHitType].bonus.percentage.flEffective;
				oReturn[sHitType].bonus.percentage.iLabel = skillsData.setILabel(oReturn[sHitType].bonus.percentage.flEffective);
			}
		}

		if (this.oPowerUps[sPowerUpKey][sDamageType][skillsData.sAllAttackTypKey]) {
			for (let sHitType of skillsData.aHitTypes) {
				oReturn[sHitType].bonus.flTotal += this.oPowerUps[sPowerUpKey][sDamageType][skillsData.sAllAttackTypKey][sHitType].bonus.flTotal;
				oReturn[sHitType].bonus.percentage.flEffective *= this.oPowerUps[sPowerUpKey][sDamageType][skillsData.sAllAttackTypKey][sHitType].bonus.percentage.flEffective;
				oReturn[sHitType].bonus.percentage.iLabel = skillsData.setILabel(oReturn[sHitType].bonus.percentage.flEffective);
			}
		}

		return oReturn;
	}

	getPowerUpProbeThrow(sAttackType, sRealType) {
		const oPowerUpType = {};
		oPowerUpType[SkillsSkill.oRealTypes.attack] = skillsData.oPowerUpApiKeys.sAttacks;
		oPowerUpType[SkillsSkill.oRealTypes.parade] = skillsData.oPowerUpApiKeys.sParades;

		let flFixed = 0;
		let flPercent = 1;

		if (this.oPowerUps[oPowerUpType[sRealType]]) {
			/**
			 * @type {bonus}
			 */
			const oThrowPowerUp = this.oPowerUps[oPowerUpType[sRealType]][sAttackType];

			if (oThrowPowerUp) {
				flFixed += oThrowPowerUp.bonus.flTotal;
				flPercent *= oThrowPowerUp.bonus.percentage.flEffective;
			}
		}

		return {
			fixed: flFixed,
			percent: flPercent
		};
	}

	getPowerUpSkill(sSkillName, sType = "effect") {
		const oPowerUpType = {};
		oPowerUpType["rank"] = skillsData.oPowerUpApiKeys.sSkillRanks;
		oPowerUpType["effect"] = skillsData.oPowerUpApiKeys.sSkillsEffect;
		let flFixed = 0;
		let flPercent = 1;

		if (this.oPowerUps[oPowerUpType[sType]]) {
			/**
			 * @type {bonus}
			 */
			const oSkillClassPowerUp = this.oPowerUps[oPowerUpType[sType]][sSkillName];

			//Fractions and all: the only cut is that of the finished mean and of the
			//result (see skillsRoll).
			if (oSkillClassPowerUp) {
				flFixed += oSkillClassPowerUp.bonus.flSkill + oSkillClassPowerUp.bonus.flHero + oSkillClassPowerUp.bonus.flBase;
				flPercent *= oSkillClassPowerUp.bonus.percentage.flEffective;
			}
		}

		return {
			fixed: flFixed,
			percent: flPercent
		};
	}
}

class SkillsSkill extends SkillsPowerUp {
	static oRealTypes = {
		attack: "rt_attack",
		parade: "rt_parade",
		healing: "rt_healing",
		powerUp: "rt_powerup",
		powerDown: "rt_powerdown",
		ini: "rt_initiativ",
		summon: "rt_create_monster",
		rebirth: "rt_rebirth",
	};
	static oTargetTypes = {
		hero: "tz_selbst",
		oneAlly: "tz_team_figur",
		allyPosition: "tz_team_position",
		allyGroup: "tz_team_alle",
		oneEnemy: "tz_gegner_figur",
		enemyPosition: "tz_gegner_position",
		enemyGroup: "tz_gegner_alle",
	};
	static oTypes = {
		heal: "tt_heil",
		powerUp: "tt_powerup",
		ini: "tt_initiativ",
		summon: "tt_create_monster",
		rebirth: "tt_rebirth",
	};
	static sFakeParade = "fakeParade";
	static sFakeIni = "fakeInitiative";

	/**
	 * @type {powerups}
	 */
	oPowerUps = {}

	/**
	 * @type {Number}
	 */
	#iRankBase;
	/**
	 * @type {Number}
	 */
	#iRankEffective;
	#oEffect = {
		percent: 1,
		fixed: 0,
	};
	#oProbe = {
		percent: 1,
		fixed: 0
	};
	/**
	 * @type {skill_template}
	 */
	#oTemplate;
	/**
	 * @type {String}
	 */
	#sDamageType;
	/**
	 * @type {Number}
	 */
	#iId;

	constructor(sSkillName) {
		super();

		if (sSkillName === SkillsSkill.sFakeIni || sSkillName === SkillsSkill.sFakeParade) {
			this.#iRankBase = 0;
			this.#iRankEffective = 0;
			this.#oTemplate = {};
			this.#oTemplate.konfigurierbar_parade = "1";

			if (sSkillName === SkillsSkill.sFakeIni) {
				this.#oTemplate.real_type = SkillsSkill.oRealTypes.ini;
			} else {
				this.#oTemplate.real_type = SkillsSkill.oRealTypes.parade;
			}
		} else {
			/**
			 * @type {skills}
			 */
			const oSkillObject = skillsData.oSkillsByName[sSkillName];

			this.#iRankEffective = oSkillObject.effective_value;
			this.#iRankBase = parseInt(oSkillObject.base_value);
			this.#oTemplate = oSkillObject.template;
			this.#sDamageType = oSkillObject.template.schadens_typ;
			this.#iId = parseInt(oSkillObject.template_id);

			this.applyPowerUps(oSkillObject.owner_powerups, this.#iRankEffective);
			this.#oEffect = this.getProbeEffectExtract("effect", this.#oTemplate, this.#iRankEffective);
			this.#oProbe = this.getProbeEffectExtract("probe", this.#oTemplate, this.#iRankEffective);
		}
	}

	get attributePrimary() {
		return this.#oTemplate.attr_primaer;
	}

	get attributePrimaryEffect() {
		return this.#oTemplate.attr_wirk_primaer;
	}

	get attributeSecondary() {
		return this.#oTemplate.attr_sekundaer;
	}

	get attributeSecondaryEffect() {
		return this.#oTemplate.attr_wirk_sekundaer;
	}

	get attackType() {
		return this.#oTemplate.angriffs_typ;
	}

	get damageType() {
		return this.#sDamageType;
	}

	get effect() {
		return this.#oEffect;
	}

	get finalEffectBonus() {
		return parseFloat(this.#oTemplate.final_bonus_wert) / 100;
	}

	get gainMpBasic() {
		return parseInt(this.#oTemplate.gain_mp_basis);
	}

	get gainMpPercent() {
		return parseInt(this.#oTemplate.gain_mp_proc);
	}

	get gainMpType() {
		return this.#oTemplate.gain_mp_typ;
	}

	get gainMpValue() {
		return parseInt(this.#oTemplate.gain_mp_wert);
	}

	get hasDamageType() {
		return this.#oTemplate.mit_schadens_typ
	}

	get isChainAttack() {
		return parseInt(this.#oTemplate.is_stop_when_fail) === 1;
	}

	get isConfigurable() {
		return parseInt(this.#oTemplate.konfigurierbar) === 1;
	}

	get isConfigurableParade() {
		return parseInt(this.#oTemplate.konfigurierbar_parade) === 1;
	}

	get isItemOptional() {
		return parseInt(this.#oTemplate.gegenstand_optional) === 1;
	}

	get itemClassId() {
		return parseInt(this.#oTemplate.gegenstand_klasse_id);
	}

	get itemEffectCountForSkillRang() {
		return parseInt(this.#oTemplate.gegenstand_wirkungsbonus_gilt_fuer_powerups) === 1;
	}

	get manaCost() {
		return parseInt(this.#oTemplate.mana_kosten);
	}

	get name() {
		return this.#oTemplate.label;
	}

	get probe() {
		return this.#oProbe;
	}

	get rankBase() {
		return this.#iRankBase;
	}

	get rankEffective() {
		return this.#iRankEffective;
	}

	/*
	 * What works on the own rank only on use: its percentages as one factor, and its
	 * fixed part. The percentages multiply, and they act on the trained rank.
	 */
	get rankOnUse() {
		let flFaktor = 1, flFest = 0;
		const oRanks = this.oPowerUps[skillsData.oPowerUpApiKeys.sSkillRanks];

		if (oRanks) {
			for (const sKey of [this.#oTemplate.label, this.skillClassName]) {
				if (sKey && oRanks[sKey]) {
					flFest += oRanks[sKey].bonus.flTotal;
					flFaktor *= oRanks[sKey].bonus.percentage.flEffective;
				}
			}
		}
		return { faktor: flFaktor, fest: flFest };
	}

	get realType() {
		return this.#oTemplate.real_type;
	}

	get skillClassId() {
		return parseInt(this.#oTemplate.talent_klasse_id);
	}

	get skillClassName() {
		if (parseInt(this.#oTemplate.talent_klasse_id) === 0 || !this.#oTemplate.talent_klasse_id) {
			return "";
		} else {
			const oKlasse = skillsData.oSkillClasses[this.#oTemplate.talent_klasse_id];
			return oKlasse ? oKlasse.name : "";
		}
	}

	get targetNumberBasic() {
		return parseInt(this.#oTemplate.affected_basis);
	}

	get targetNumberType() {
		return this.#oTemplate.affected_typ;
	}

	get targetNumberValue() {
		return parseInt(this.#oTemplate.affected_wert);
	}

	get targetType() {
		return this.#oTemplate.ziel;
	}

	get type() {
		return this.#oTemplate.typ;
	}

	set attackType(sAttackType) {
		this.#oTemplate.angriffs_typ = sAttackType;
	}

	set attributeProbePrimary(sAttributeKey) {
		this.#oTemplate.attr_primaer = sAttributeKey;
	}

	set attributeProbeSecondary(sAttributeKey) {
		this.#oTemplate.attr_sekundaer = sAttributeKey;
	}

	set damageType(sDamageType) {
		this.#sDamageType = sDamageType;
	}

	set name(sName) {
		this.#oTemplate.label = sName;
	}
}

class SkillsItem extends SkillsPowerUp {
	/**
	 * @type {powerups}
	 */
	oPowerUps = Object.create(null);

	#oAmmo = Object.create(null);
	/**
	 * @type {item_template}
	 */
	#oTemplate;
	#sDamageType;
	/**
	 * @type {Number}
	 */
	#iInstanceId;
	/**
	 * @type {Number}
	 */
	#iItemClassId;
	/**
	 * @type {Number}
	 */
	#iTemplateId;
	//The powerups as the data interface has them, and the rank they are reckoned
	//with (see fuerRang).
	#oRoh;
	#iRang = 0;

	/**
	 * @param {items} oItem
	 */
	constructor(oItem) {
		super();

		this.#sDamageType = oItem.template.schadens_typ;
		this.#iInstanceId = oItem.instance_id;
		this.#iTemplateId = oItem.template_id;
		this.#oTemplate = oItem.template;
		this.#oRoh = oItem.instance.owner_powerups || {};

		this.applyPowerUps(this.#oRoh);
	}

	/*
	 * The item in the hands of a skill of this rank. A bonus of the item in shares of
	 * the skill rank, "+50% des Fertigkeitenrangs", only has its number then: on
	 * the item itself as on its item class. Set before every throw reckoned with
	 * the item; the same item serves many skills.
	 */
	fuerRang(iRang) {
		iRang = Number(iRang) || 0;
		if (iRang === this.#iRang) {
			return this;
		}
		this.#iRang = iRang;
		this.oPowerUps = Object.create(null);
		this.applyPowerUps(this.#oRoh, iRang);
		return this;
	}

	get ammo() {
		return this.#oAmmo;
	}

	get ammoEquipped() {
		const oReturnArray = [];

		for (let oAmmoObject of Object.values(this.#oAmmo)) {
			oReturnArray.push(oAmmoObject);
		}

		return oReturnArray;
	}

	get ammoList() {
		return this.#oTemplate.munition_list;
	}

	get applicationsPerFight() {
		return this.#oTemplate.anw_kampf ? parseInt(this.#oTemplate.anw_kampf) : null;
	}

	get applicationsPerDungeon() {
		return this.#oTemplate.anw_dungeon ? parseInt(this.#oTemplate.anw_dungeon) : null;
	}

	get applicationsTotal() {
		return this.#oTemplate.anw_gesamt ? parseInt(this.#oTemplate.anw_gesamt) : null;
	}

	get damageType() {
		return this.#sDamageType;
	}

	/**
	 * @return {{fixed: number, percent: number}|null}
	 */
	get effect() {
		if (this.#oTemplate.gegenstand_klassen[this.#iItemClassId]) {
			return this.getProbeEffectExtract("effect", this.#oTemplate.gegenstand_klassen[this.#iItemClassId], this.#iRang);
		} else {
			return {
				percent: 1,
				fixed: 0
			};
		}
	}

	get equipmentSlot() {
		return this.#oTemplate.trage_typ;
	}

	get hasAmmo() {
		return this.#oTemplate.munition_list.length > 0;
	}

	get instanceId() {
		return this.#iInstanceId;
	}

	get name() {
		return this.#oTemplate.name;
	}

	/**
	 * @return {{fixed: number, percent: number}|null}
	 */
	get probe() {
		if (this.#oTemplate.gegenstand_klassen[this.#iItemClassId]) {
			return this.getProbeEffectExtract("probe", this.#oTemplate.gegenstand_klassen[this.#iItemClassId], this.#iRang);
		} else {
			return {
				fixed: 0,
				percent: 1
			};
		}
	}

	/**
	 * @param {string} sItemClassId
	 * @param {SkillsItem} oAmmoItem
	 */
	//No ammunition, and the damage type of the item itself again.
	clearAmmo() {
		this.#oAmmo = Object.create(null);
		this.damageType = "";
	}

	setAmmo(sItemClassId, oAmmoItem) {
		this.#oAmmo[sItemClassId] = oAmmoItem;

		if (oAmmoItem.damageType) {
			this.damageType = oAmmoItem.damageType;
		}
	}

	set damageType(sDamageType) {
		if (sDamageType && sDamageType !== "") {
			this.#sDamageType = sDamageType;
		} else {
			this.#sDamageType = this.#oTemplate.schadens_typ;
		}
	}

	/**
	 * @param {number} iItemClassId
	 */
	set itemClassId(iItemClassId) {
		this.#iItemClassId = iItemClassId;
	}
}

/////////////////////////////////////////////////////////////////////////////
///////////////// Module: the skills page, above the table //////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * Above the skills table: the hero's general values and his attributes, and below
 * them the bonus overviews that are switched on in the options window. An overview
 * only shows where the hero has anything of its kind.
 *
 * Everything is built into a fragment first and goes into the page in one move,
 * in appendLayout.
 */

//Which switch in SKILLS_CFG shows which overview.
var SKILLS_BONUS_SWITCHES = {
	sTableAttacks: 'boniAngriffe',
	sTableParades: 'boniParaden',
	sTableAttributes: 'boniEigenschaften',
	sTableSkillEffects: 'boniWirkung',
	sTableDamage: 'boniSchaden',
	sTableDamageZ: 'boniSchadenZ',
	sTableArmor: 'boniRuestung',
	sTableDamageFactor: 'boniAnfaelligkeiten',
	sTableDrop: 'boniBelohnungen'
};

class SkillsLayout {
	oElements = {
		oLayout: document.createDocumentFragment(),
		oTable: document.createElement("table"),
		oTh: document.createElement("th"),
		oSpan: document.createElement("span")
	};
	oIds = {
		sTopTable: "mm_skills_top",
		oTableGeneral: {
			sTable: "mm_skills_general",
			sHeroLvl: "mm_skills_general_level",
			sHitPoints: "mm_skills_general_hp",
			sHpReg: "mm_skills_general_hpreg",
			sManaPoints: "mm_skills_general_mp",
			sMpReg: "mm_skills_general_mpreg",
			sAction: "mm_skills_general_actions",
			sIni: "mm_skills_general_ini"
		},
		oTableAttributes: {
			sTable: "mm_skills_attributes",
			sStBase: "mm_skills_st_base",
			sStEffective: "mm_skills_st_eff",
			sKoBase: "mm_skills_ko_base",
			sKoEffective: "mm_skills_ko_eff",
			sInBase: "mm_skills_in_base",
			sInEffective: "mm_skills_in_eff",
			sGeBase: "mm_skills_ge_base",
			sGeEffective: "mm_skills_ge_eff",
			sChBase: "mm_skills_ch_base",
			sChEffective: "mm_skills_ch_eff",
			sSnBase: "mm_skills_sn_base",
			sSnEffective: "mm_skills_sn_eff",
			sWaBase: "mm_skills_wa_base",
			sWaEffective: "mm_skills_wa_eff",
			sWiBase: "mm_skills_wi_base",
			sWiEffective: "mm_skills_wi_eff"
		},
		oTableBonus: {
			sHiddenBonusTable: "mm_skills_boni",
			sTableAttacks: "mm_skills_boni_angriffe",
			sTableParades: "mm_skills_boni_paraden",
			sTableAttributes: "mm_skills_boni_eigenschaften",
			sTableSkillEffects: "mm_skills_boni_wirkung",
			sTableDamage: "mm_skills_boni_schaden",
			sTableDamageZ: "mm_skills_boni_schaden_z",
			sTableArmor: "mm_skills_boni_ruestung",
			sTableDamageFactor: "mm_skills_boni_anfaelligkeiten",
			sTableDrop: "mm_skills_boni_belohnungen"
		}
	};
	oOrder = {
		aAttributes: ["at_st", "at_ko", "at_in", "at_ge", "at_ch", "at_sn", "at_wa", "at_wi"],
		oBonus: {
			aAttackTypes: ["an_nahkampf", "an_fernkampf", "an_zauber", "an_sozial", "an_natur", "an_falle_a", "an_falle_p", "an_detonate", "an_misc_1", "an_misc_2", "an_misc_4"],
			aDamageTypes: ["st_hieb_schaden", "st_schneid_schaden", "st_stich_schaden", "st_feuer_schaden", "st_eis_schaden", "st_blitz_schaden", "st_gift_schaden", "st_saeure_schaden", "st_psycho_schaden", "st_nn_1", "st_mana_schaden", "st_hl_schaden", "st_wucht_schaden"],
			aAttributes: ["at_st", "at_ko", "at_in", "at_ge", "at_ch", "at_sn", "at_wa", "at_wi", "at_v_max_hitpoints", "at_v_heil_hitpoints", "at_v_max_manapoints", "at_v_heil_manapoints", "at_v_anz_aktionen", "at_v_initiative", "maxitems_ring", "maxitems_tasche", "maxitems_orden", "fame", "clan_fame"],
			aDrops: ["gold", "fame"]
		}
	};

	initRender() {
		this.createTopTable();
		this.createHiddenTopBonusTables();
		this.hidePagination();
	}

	/* --- The two tables at the top ------------------------------------------ */

	createTopTable() {
		let oTopTable = this.oElements.oTable.cloneNode();
		let oHeaderRow = oTopTable.insertRow();
		let oGeneralTh = this.oElements.oTh.cloneNode();
		let oAttributesTh = this.oElements.oTh.cloneNode();
		let oClassDataRow = oTopTable.insertRow();
		let oGeneralCell = oClassDataRow.insertCell();
		let oAttributeCell = oClassDataRow.insertCell();

		oTopTable.id = this.oIds.sTopTable;
		oGeneralTh.textContent = "Allgemeines";
		oAttributesTh.textContent = "Eigenschaften";
		oHeaderRow.appendChild(oGeneralTh);
		oHeaderRow.appendChild(oAttributesTh);

		this.createTopGeneralTable(oGeneralCell);
		this.createTopAttributesTable(oAttributeCell);

		this.oElements.oLayout.appendChild(oTopTable);
	}

	createTopGeneralTable(oGeneralCell) {
		const aGeneralOrder = ["sHeroLvl", "sHitPoints", "sHpReg", "sManaPoints", "sMpReg", "sAction", "sIni"];
		const oGeneralTranslation = {
			sHeroLvl: {sToolTip: "Heldenstufe", sLabel: "Stufe"},
			sHitPoints: {sToolTip: "Hitpoints", sLabel: "HP"},
			sHpReg: {sToolTip: "HP-Regeneration pro Runde", sLabel: "HP-Reg"},
			sManaPoints: {sToolTip: "Manapoints", sLabel: "MP"},
			sMpReg: {sToolTip: "MP-Regeneration pro Runde", sLabel: "MP-Reg"},
			sAction: {sToolTip: "Aktionen pro Runde", sLabel: "Akt"},
			sIni: {sToolTip: "Initiativebonus", sLabel: "Ini-Bonus"}
		};
		let oGeneralTable = this.oElements.oTable.cloneNode();
		let oGeneralHeaderRow = oGeneralTable.insertRow();
		let oGeneralDataRow = oGeneralTable.insertRow();

		oGeneralTable.id = this.oIds.oTableGeneral.sTable;
		oGeneralTable.className = "content_table";
		oGeneralHeaderRow.className = "header";
		oGeneralDataRow.className = "row0";
		oGeneralCell.appendChild(oGeneralTable);

		for (let sGeneralAttribute of aGeneralOrder) {
			let oHeaderCell = oGeneralHeaderRow.insertCell();
			let oHeaderSpan = this.createMouseOver(oGeneralTranslation[sGeneralAttribute].sToolTip, oGeneralTranslation[sGeneralAttribute].sLabel);
			let oClassDataCell = oGeneralDataRow.insertCell();

			oHeaderCell.style.minWidth = "20px";
			oHeaderCell.style.textAlign = "center";
			oHeaderCell.appendChild(oHeaderSpan);

			oClassDataCell.style.textAlign = "center";
			oClassDataCell.id = this.oIds.oTableGeneral[sGeneralAttribute];
		}
	}

	createTopAttributesTable(oAttributeCell) {
		const oAttributesTranslation = {
			at_st: {sToolTip: "Stärke", sLabel: "St"},
			at_ko: {sToolTip: "Konstitution", sLabel: "Ko"},
			at_in: {sToolTip: "Intelligenz", sLabel: "In"},
			at_ge: {sToolTip: "Geschicklichkeit", sLabel: "Ge"},
			at_ch: {sToolTip: "Charisma", sLabel: "Ch"},
			at_sn: {sToolTip: "Schnelligkeit", sLabel: "Sn"},
			at_wa: {sToolTip: "Wahrnehmung", sLabel: "Wa"},
			at_wi: {sToolTip: "Willenskraft", sLabel: "Wi"}
		};
		let oAttributesTable = this.oElements.oTable.cloneNode();
		let oAttributesHeaderRow = oAttributesTable.insertRow();
		let oAttributesDataRow = oAttributesTable.insertRow();

		oAttributesTable.id = this.oIds.oTableAttributes.sTable;
		oAttributesTable.className = "content_table";
		oAttributesHeaderRow.className = "header";
		oAttributesDataRow.className = "row0";
		oAttributeCell.appendChild(oAttributesTable);

		for (let sAttributesAttribute of this.oOrder.aAttributes) {
			let oHeaderCell = oAttributesHeaderRow.insertCell();
			let oHeaderSpan = this.createMouseOver(oAttributesTranslation[sAttributesAttribute].sToolTip, oAttributesTranslation[sAttributesAttribute].sLabel);
			let oClassDataCell = oAttributesDataRow.insertCell();
			let oClassDataSpanBase = this.oElements.oSpan.cloneNode();
			let oClassDataSpanEffective = this.oElements.oSpan.cloneNode();
			const sBaseId = `s${oAttributesTranslation[sAttributesAttribute].sLabel}Base`;
			const sEffectiveId = `s${oAttributesTranslation[sAttributesAttribute].sLabel}Effective`;

			oHeaderCell.style.minWidth = "20px";
			oHeaderCell.style.textAlign = "center";
			oHeaderCell.appendChild(oHeaderSpan);

			oClassDataCell.style.textAlign = "center";
			oClassDataCell.style.whiteSpace = "nowrap";
			oClassDataSpanBase.id = this.oIds.oTableAttributes[sBaseId];
			oClassDataSpanEffective.style.color = "gold";
			oClassDataSpanEffective.id = this.oIds.oTableAttributes[sEffectiveId];
			oClassDataCell.appendChild(oClassDataSpanBase);
			oClassDataCell.appendChild(document.createTextNode(" "));
			oClassDataCell.appendChild(oClassDataSpanEffective);
		}
	}

	/**
	 * @param {attributes} oAttributes
	 */
	addAttributeData(oAttributes) {
		const oIdsTableGeneral = this.oIds.oTableGeneral;
		const oIdsTableAttributes = this.oIds.oTableAttributes;
		const aHiddenAttributes = ["level", "max_hp", "heil_hp", "max_mp", "heil_mp", "anz_aktionen", "ini_bonus"];
		const oIdToAttribute = {
			"level": "sHeroLvl",
			"max_hp": "sHitPoints",
			"heil_hp": "sHpReg",
			"max_mp": "sManaPoints",
			"heil_mp": "sMpReg",
			"anz_aktionen": "sAction",
			"ini_bonus": "sIni",
			"at_st": "sSt",
			"at_ko": "sKo",
			"at_in": "sIn",
			"at_ge": "sGe",
			"at_ch": "sCh",
			"at_sn": "sSn",
			"at_wa": "sWa",
			"at_wi": "sWi"
		};

		for (let sAttribute of aHiddenAttributes) {
			if (oAttributes[sAttribute])
				this.addGeneralAttribute(oIdsTableGeneral[oIdToAttribute[sAttribute]], oAttributes[sAttribute]);
		}

		for (let sAttribute of this.oOrder.aAttributes) {
			if (!oAttributes[sAttribute])
				continue;
			this.addBaseAttribute(oIdsTableAttributes[`${oIdToAttribute[sAttribute]}Base`], oAttributes[sAttribute]);
			this.addEffectiveAttribute(oIdsTableAttributes[`${oIdToAttribute[sAttribute]}Effective`], oAttributes[sAttribute]);
		}
	}

	addGeneralAttribute(sAttributeId, oAttribute) {
		this.oElements.oLayout.getElementById(sAttributeId).textContent = `${oAttribute.effective_value}`;
	}

	addBaseAttribute(sAttributeId, oAttribute) {
		this.oElements.oLayout.getElementById(sAttributeId).textContent = oAttribute.base_value;
	}

	addEffectiveAttribute(sAttributeId, oAttribute) {
		if (parseInt(oAttribute.base_value) !== oAttribute.effective_value) {
			this.oElements.oLayout.getElementById(sAttributeId).textContent = `[${oAttribute.effective_value}]`;
		}
	}

	/* --- The bonus overviews ------------------------------------------------ */

	createHiddenTopBonusTables() {
		let oTopBonusTable = this.oElements.oTable.cloneNode();
		let oHeaderRow = oTopBonusTable.insertRow();
		let oClassDataRow = oTopBonusTable.insertRow();
		const aCells = ["sTableAttacks", "sTableParades", "sTableAttributes", "sTableSkillEffects", "sTableDamage", "sTableDamageZ", "sTableArmor", "sTableDamageFactor", "sTableDrop"];
		const oCellsLabel = {
			sTableAttacks: "Boni auf Angriffe",
			sTableParades: "Boni auf Paraden",
			sTableAttributes: "Boni auf Eigenschaften",
			sTableSkillEffects: "Boni auf Wirkung von Fertigkeiten",
			sTableDamage: "Boni auf Schaden",
			sTableDamageZ: "Boni auf Schaden (z)",
			sTableArmor: "Boni auf Rüstung",
			sTableDamageFactor: "Boni auf Anfälligkeiten",
			sTableDrop: "Gold-Belohnungs Boni in Dungeons"
		};

		oTopBonusTable.id = this.oIds.oTableBonus.sHiddenBonusTable;

		for (let sTableId of aCells) {
			let oTh = this.oElements.oTh.cloneNode();
			let oCell = oClassDataRow.insertCell();
			let oTable = this.oElements.oTable.cloneNode();

			oTh.setAttribute("data-mm-boni", this.oIds.oTableBonus[sTableId]);
			oTh.style.textAlign = "center";
			oTh.style.display = "none";
			oTh.textContent = oCellsLabel[sTableId];
			oHeaderRow.appendChild(oTh);

			oCell.style.verticalAlign = "top";
			oCell.style.textAlign = "center";
			oCell.style.display = "none";
			oTable.id = this.oIds.oTableBonus[sTableId];
			oTable.className = "content_table";
			oTable.createTBody();
			oCell.appendChild(oTable);
		}

		this.oElements.oLayout.appendChild(oTopBonusTable);
	}

	getOrder(sOrderKey) {
		return this.oOrder.oBonus[sOrderKey];
	}

	//An overview with rows shows when its switch is on.
	showBonusTable(sTableKey) {
		const sBonusTableId = this.oIds.oTableBonus[sTableKey];
		const oTable = this.oElements.oLayout.getElementById(sBonusTableId);

		if (SKILLS_CFG[SKILLS_BONUS_SWITCHES[sTableKey]] !== true || !oTable || oTable.rows.length === 0)
			return;

		this.oElements.oLayout.querySelector(`[data-mm-boni="${sBonusTableId}"]`).style.display = "table-cell";
		oTable.parentElement.style.display = "table-cell";
	}

	/**
	 * @param {Object<bonus_type_details>} oValues
	 * @param {string} sType
	 */
	fillSingleBonus(oValues, sType) {
		if (oValues.length === 0) {
			return;
		}

		const sTableKey = `sTable${sType}`;
		let sOrderKey = "";

		switch (sType) {
			case "Attributes":
				sOrderKey = "aAttributes";
				break;
			case "Attacks":
			case "Parades":
				sOrderKey = "aAttackTypes";
				break;
			case "Drop":
				sOrderKey = "aDrops";
				break;
		}

		const oHiddenBonusTableTBody = this.oElements.oLayout.getElementById(this.oIds.oTableBonus[sTableKey]).tBodies[0];
		const aTypeOrder = this.getOrder(sOrderKey);

		for (let sTypeKey of aTypeOrder) {
			if (oValues[sTypeKey]) {
				this.createBonusRow(oHiddenBonusTableTBody, oValues[sTypeKey]);
			}
		}

		this.showBonusTable(sTableKey);
	}

	/**
	 * @param {Object<bonus_type_details>} oValues
	 * @param {string} sType
	 */
	fillTripleBonus(oValues, sType) {
		if (oValues.length === 0) {
			return;
		}

		const sTableKey = `sTable${sType}`;
		const oHiddenBonusTableTBody = this.oElements.oLayout.getElementById(this.oIds.oTableBonus[sTableKey]).tBodies[0];
		const aDamageTypeOrder = this.getOrder("aDamageTypes");
		const aAttackTypeOrder = this.getOrder("aAttackTypes");

		for (let sDamageTypeKey of aDamageTypeOrder) {
			if (!oValues[sDamageTypeKey]) {
				continue;
			}

			if (oValues[sDamageTypeKey][skillsData.sAllAttackTypKey]) {
				this.createBonusRow(oHiddenBonusTableTBody, oValues[sDamageTypeKey][skillsData.sAllAttackTypKey]);
			}

			for (let sAttackTypeKey of aAttackTypeOrder) {
				if (oValues[sDamageTypeKey][sAttackTypeKey] === "blIsTripleValue" || sAttackTypeKey === skillsData.sAllAttackTypKey) {
					continue;
				}

				if (oValues[sDamageTypeKey][sAttackTypeKey]) {
					this.createBonusRow(oHiddenBonusTableTBody, oValues[sDamageTypeKey][sAttackTypeKey]);
				}
			}
		}

		this.showBonusTable(sTableKey);
	}

	/**
	 * @param {Object<bonus_type_details>} oSkillEffects
	 */
	fillBonusSkillEffects(oSkillEffects) {
		const oBonusSkillEffectsTBody = this.oElements.oLayout.getElementById(this.oIds.oTableBonus.sTableSkillEffects).tBodies[0];

		if (Object.keys(oSkillEffects).length === 0) {
			return;
		}

		for (let oSkillEffect of Object.values(oSkillEffects)) {
			this.createBonusRow(oBonusSkillEffectsTBody, oSkillEffect);
		}

		this.showBonusTable("sTableSkillEffects");
	}

	/**
	 * @param {HTMLTableSectionElement} oTbody
	 * @param {bonus_type_details} oBonusObject
	 */
	createBonusRow(oTbody, oBonusObject) {
		if (!oBonusObject.blIsTripleValue && oBonusObject.bonus.flTotal === 0 && oBonusObject.bonus.percentage.flEffective === 1) {
			return;
		}

		let oBonusRow = oTbody.insertRow();
		let oLabelCell = oBonusRow.insertCell();
		let oValueCell = oBonusRow.insertCell();
		let sValueInnerText = "";
		let sOnMouseOver = "";
		let sLabel = oBonusObject.wod_SO_name;

		oBonusRow.className = oBonusRow.rowIndex % 2 === 0 ? "row0" : "row1";

		if (oBonusObject.istTalentKlasseWirkung) {
			sLabel = `alle Fertigkeiten der Klasse `;
		}

		oLabelCell.textContent = sLabel;
		oLabelCell.style.textAlign = "left";

		if (oBonusObject.istTalentKlasseWirkung) {
			let oTextNode = this.oElements.oSpan.cloneNode();
			oTextNode.style.fontStyle = "italic";
			oTextNode.textContent = oBonusObject.wod_SO_name;
			oLabelCell.appendChild(oTextNode);
		}

		if (oBonusObject.blIsTripleValue) {
			sValueInnerText += this.formValueString(oBonusObject.et_erfolg.bonus);
			sValueInnerText += ` / ${this.formValueString(oBonusObject.et_gut.bonus)}`;
			sValueInnerText += ` / ${this.formValueString(oBonusObject.et_kritisch.bonus)}`;
		} else {
			sValueInnerText = this.formValueString(oBonusObject.bonus);
		}

		for (let sDetail of oBonusObject.details) {
			sOnMouseOver += `${sDetail}<br />`;
		}

		oValueCell.appendChild(this.createMouseOver(sOnMouseOver, sValueInnerText));
	}

	formValueString(oTripleValueBonusObject) {
		let sReturnString = "";
		let sOperator = "";

		if (oTripleValueBonusObject.flTotal !== 0) {
			sReturnString = this.formatTotal(oTripleValueBonusObject.flTotal);
		}

		if (oTripleValueBonusObject.percentage.flEffective !== 1) {
			if (oTripleValueBonusObject.percentage.flEffective >= 1) {
				sOperator += "+";
			} else {
				sOperator += "-";
			}

			if (oTripleValueBonusObject.flTotal !== 0) {
				sOperator = ` ${sOperator} `;
			}

			sReturnString += `${sOperator}${Math.abs(oTripleValueBonusObject.percentage.iLabel)}%`;
		}

		if (sReturnString === "") {
			sReturnString = "0";
		}

		return sReturnString;
	}

	formatTotal(flTotal) {
		return new Intl.NumberFormat("default", {
			style: "decimal",
			minimumFractionDigits: 0,
			maximumFractionDigits: 2
		}).format(flTotal);
	}

	/* --- Helpers ------------------------------------------------------------ */

	/**
	 * A span with the game's tooltip on it. The text is put in as the game writes
	 * its own: as an attribute with "return", quotes and backslashes escaped.
	 *
	 * @param {string} sMouseOverText
	 * @param {string|number|Node} mInnerText
	 * @param {Object|false} oStyleOptions
	 * @return {Node}
	 */
	createMouseOver(sMouseOverText, mInnerText, oStyleOptions = false) {
		const oMouseOverSpan = this.oElements.oSpan.cloneNode();
		let oStyleElement = oMouseOverSpan;

		if (typeof mInnerText === "object") {
			oStyleElement = mInnerText;
			oMouseOverSpan.appendChild(mInnerText);
		} else {
			oMouseOverSpan.appendChild(document.createTextNode(mInnerText));
		}

		oMouseOverSpan.style.verticalAlign = "middle";
		oStyleElement.style.borderBottom = "1px dotted white";
		skillsTipOn(oStyleElement, sMouseOverText);

		if (oStyleOptions !== false) {
			for (let [sStyleKey, sStyleValue] of Object.entries(oStyleOptions)) {
				oMouseOverSpan.style[sStyleKey] = sStyleValue;
			}
		}

		return oMouseOverSpan;
	}

	//The game's page switch for the skills table has nothing to do once the table is
	//rebuilt from the data interface.
	hidePagination() {
		document.querySelectorAll(".paginator_selected, .paginator_selected + .texttoken").forEach(oElement => {
			oElement.style.display = "none";
		});
	}

	//Everything above goes in front of the tabs, in one move. What went is noted, so
	//that a new build can take it off again.
	appendLayout() {
		const oTabs = document.getElementById("mm_skills_tabs");

		this.aOnPage = Array.from(this.oElements.oLayout.childNodes);
		if (oTabs && oTabs.parentNode)
			oTabs.parentNode.insertBefore(this.oElements.oLayout, oTabs);
	}

	remove() {
		for (const oNode of this.aOnPage || []) {
			if (oNode.parentNode) {
				oNode.parentNode.removeChild(oNode);
			}
		}
	}
}

//The game's tooltip on an element, written the way the game writes its own.
function skillsTipOn(element, html) {
	var text = String(html == null ? '' : html).replace(/\\/g, '\\\\').replace(/'/g, "\\'")
		.replace(/\r?\n/g, ' ');
	element.setAttribute('onmouseover', "return wodToolTip(this,'" + text + "');");
}

/////////////////////////////////////////////////////////////////////////////
//////////////////// Module: the skills page, the table /////////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * The game's skills table, extended by seven columns: class, item, throws, attack
 * type, mana cost, item class and targets. The rows keep the game's own cells, so
 * the rank with its tooltip and the buttons to raise it stay as they are.
 *
 * Tabs above the table sort the rows by kind. The parries and the initiative tab
 * also show the standard parries and the standard initiative, the throws a hero
 * rolls without a skill for it. The export tab is no view: it puts the build into
 * the clipboard and leaves the page on the tab it was on.
 */

class SkillsTable {
	oCellTypeNames = {
		skillClass: "skillClass",
		itemDropDown: "itemsDropDown",
		effectThrows: "throws",
		attackType: "attackType",
		manaCost: "manaCost",
		item: "item",
		numberOfTargets: "targets"
	};
	oCellTypeLabel = {
		skillClass: "Klasse",
		itemsDropDown: "Item(a)",
		effectThrows: "Würfe",
		attackType: "Angriffsart",
		manaCost: "Manakosten",
		item: "Gegenstand",
		numberOfTargets: "Betroffene"
	};
	oDataPowerUps = {
		attributes: {},
		attacks: {},
		parades: {},
		damages: {},
		damagesZ: {},
		initiative: {},
		skillEffects: {},
	};
	oDataSets = {
		tabs: {
			js: "tab",
			css: "data-tab"
		},
		tabRow: {
			js: "tabRow",
			css: "data-tab-row"
		},
		tabRowParade: {
			js: "tabRowParade",
			css: "data-tab-row-parade"
		},
		tabSkill: {
			js: "tabSkillName",
			css: "data-tab-skill-name"
		},
		cellType: {
			js: "cellType",
			css: "data-cell-type"
		},
		cellRowType: {
			js: "cellRowType",
			css: "data-cell-row-type"
		},
		selectSkillName: {
			js: "selectSkillName",
			css: "data-select-skill-name"
		},
		itemClassId: {
			js: "itemClassId",
			css: "data-item-class-id"
		},
	};
	//The attributes of the standard parries and the standard initiative.
	oDefaultParades = {
		an_nahkampf: {
			primary: "at_sn",
			secondary: "at_ge"
		},
		an_fernkampf: {
			primary: "at_sn",
			secondary: "at_wa"
		},
		an_zauber: {
			primary: "at_wi",
			secondary: "at_in",
		},
		an_sozial: {
			primary: "at_wi",
			secondary: "at_ch"
		},
		an_detonate: {
			primary: "at_sn",
			secondary: "at_wa"
		},
		an_falle_p: {
			primary: "at_wa",
			secondary: "at_sn"
		},
		//Hinterhalt
		an_misc_1: {
			primary: "at_wa",
			secondary: "at_in"
		},
		//Krankheit
		an_misc_2: {
			primary: "at_ko",
			secondary: "at_ch"
		},
		an_natur: {
			primary: "at_wi",
			secondary: "at_sn"
		},
		initiative: {
			primary: "at_sn",
			secondary: "at_wa"
		}
	};
	oElements = {
		oTh: document.createElement("th"),
		oDiv: document.createElement("div"),
		oUl: document.createElement("ul"),
		oLi: document.createElement("li"),
		oSpan: document.createElement("span"),
		oA: document.createElement("a"),
		oSmall: document.createElement("small"),
		oTbody: document.createElement("tbody"),
		oSelect: document.createElement("select"),
		oOption: document.createElement("option"),
	};
	oItemClassItemsSorted = {};
	/**
	 * @type {HTMLTableElement}
	 */
	oSkillTable;
	oTableBodySkills = {};
	/**
	 * @type {HTMLTableSectionElement}
	 */
	oTableBodyParades = {};
	/**
	 * @type {HTMLTableSectionElement}
	 */
	oTableBodyInitiative = {};
	/**
	 * @type {Object<SkillsSkill>}
	 */
	oSkillObjectByName = {};
	aNewCells = ["skillClass", "itemsDropDown", "effectThrows", "attackType", "manaCost", "item", "numberOfTargets"];
	aOldCells = ["index", "label", "rank", "cost1", "cost2"];
	aOrderSlots = ["tr_kopf", "tr_ohren", "tr_brille", "tr_hals", "tr_orden", "tr_schaerpe", "tr_torso", "tr_umhang", "tr_arme", "tr_hand", "tr_ring", "tr_beide_haende", "tr_waffen_hand", "tr_schild_hand", "tr_einhaendig", "tr_beine", "tr_fuss", "tr_tasche", "tr_rucksack"];
	aTabSkillGroups = ["rt_attack", "rt_parade", "rt_initiativ", "rt_healing", "rt_powerup", "rt_create_monster"];
	iDefaultTableHeaderCells = 0;
	/**
	 * @type {HTMLDivElement}
	 */
	oTabs = null;

	initRender() {
		this.oSkillTable = skillsGameTable();
		skillsDetailsToPlain(this.oSkillTable);
		this.oTableBodySkills = this.oSkillTable.tBodies[0];

		this.createTabs();
		this.extendTableStructure();
		this.createTableFooter();
		this.eventListener();
	}

	/* --- Filling the table -------------------------------------------------- */

	fillTable() {
		const oFragment = document.createDocumentFragment();

		oFragment.appendChild(this.oTableBodySkills);

		for (let oRow of this.oTableBodySkills.rows) {
			const sSkillName = skillsRowName(oRow);
			const oCells = oRow.cells;

			//A row the data interface does not know stays as the game wrote it and only
			//shows among all.
			if (!skillsData.oSkillsByName[sSkillName]) {
				oRow.dataset[this.oDataSets.tabRow.js] = "unknown";
				continue;
			}

			const oSkillObject = this.oSkillObjectByName[sSkillName] = new SkillsSkill(sSkillName);

			this.applySkillClassDataAttribute(oRow, oSkillObject);
			this.insertSkillClass(oCells[this.iDefaultTableHeaderCells + this.aNewCells.indexOf("skillClass") + 1], oSkillObject);
			const oFirstItemInList = this.insertItemDropDown(oCells[this.iDefaultTableHeaderCells + this.aNewCells.indexOf("itemsDropDown") + 1], oSkillObject);
			this.insertThrows(oCells[this.iDefaultTableHeaderCells + this.aNewCells.indexOf("effectThrows") + 1], oSkillObject, oFirstItemInList);
			this.insertAttackType(oCells[this.iDefaultTableHeaderCells + this.aNewCells.indexOf("attackType") + 1], oSkillObject);
			this.insertManaCosts(oCells[this.iDefaultTableHeaderCells + this.aNewCells.indexOf("manaCost") + 1], oSkillObject);
			this.insertItemClass(oCells[this.iDefaultTableHeaderCells + this.aNewCells.indexOf("item") + 1], oSkillObject);
			this.insertNumberOfTargets(oCells[this.iDefaultTableHeaderCells + this.aNewCells.indexOf("numberOfTargets") + 1], oSkillObject);
		}

		this.oSkillTable.appendChild(oFragment);

		this.addDefaultParades();
		this.addDefaultInitiative();
	}

	/**
	 * @param {HTMLTableRowElement} oRow
	 * @param {SkillsSkill} oSkillObject
	 */
	applySkillClassDataAttribute(oRow, oSkillObject) {
		oRow.dataset[this.oDataSets.tabSkill.js] = oSkillObject.name;

		if (!oSkillObject.isConfigurable) {
			oRow.dataset[this.oDataSets.tabRow.js] = "passive";
		} else if (oSkillObject.realType === SkillsSkill.oRealTypes.powerDown) {
			oRow.dataset[this.oDataSets.tabRow.js] = "rt_attack";
		} else {
			oRow.dataset[this.oDataSets.tabRow.js] = oSkillObject.realType;
		}

		if (oSkillObject.realType !== SkillsSkill.oRealTypes.parade && oSkillObject.isConfigurableParade) {
			oRow.dataset[this.oDataSets.tabRowParade.js] = true;
		}
	}

	/**
	 * @param {HTMLTableCellElement} oCell
	 * @param {SkillsSkill} oSkillObject
	 */
	insertSkillClass(oCell, oSkillObject) {
		oCell.dataset[this.oDataSets.cellType.js] = this.oCellTypeNames.skillClass;

		if (oSkillObject.skillClassId) {
			oCell.textContent = oSkillObject.skillClassName;
		}
	}

	/**
	 * @param {HTMLTableCellElement} oCell
	 * @param {SkillsSkill} oSkillObject
	 * @return {SkillsItem|null} oItem
	 */
	insertItemDropDown(oCell, oSkillObject) {
		const iItemClassId = oSkillObject.itemClassId;
		/**
		 * @type {SkillsItem|null}
		 */
		let oFirstItem = null;

		oCell.dataset[this.oDataSets.cellType.js] = this.oCellTypeNames.itemDropDown;

		if (oSkillObject.type !== SkillsSkill.oTypes.heal && oSkillObject.realType !== SkillsSkill.oRealTypes.ini && oSkillObject.realType !== SkillsSkill.oRealTypes.powerDown) {
			return oFirstItem;
		}

		if (iItemClassId === 0) {
			return oFirstItem;
		}

		const oItemClass = skillsData.oItemClasses[iItemClassId];

		if (!oItemClass || !oItemClass.items || oItemClass.items.length === 0) {
			return oFirstItem;
		}

		let oPrimarySelect = this.createItemDropDown(iItemClassId, oSkillObject.isItemOptional);
		oPrimarySelect.dataset[this.oDataSets.selectSkillName.js] = oSkillObject.name;

		if (!oPrimarySelect.selectedOptions[0]) {
			return oFirstItem;
		}

		if (oPrimarySelect.selectedOptions[0].value !== "") {
			oFirstItem = skillsData.oItemsByInstanceId[oPrimarySelect.selectedOptions[0].value];
		}

		oCell.appendChild(oPrimarySelect);
		this.ammoDropDowns(oCell, oFirstItem);

		return oFirstItem;
	}

	/*
	 * The dropdowns for the ammunition of the item picked: one for every class the
	 * item takes, arrows for a bow, the instrument for a Liedtext. Each starts on its
	 * first piece. They are built anew whenever another item is picked, and go when
	 * none is; a class the hero has no piece of gets none.
	 */
	ammoDropDowns(oCell, oItem) {
		oCell.querySelectorAll(`select:not([${this.oDataSets.selectSkillName.css}])`).forEach(oAlt => oAlt.remove());
		if (!oItem) {
			return;
		}
		oItem.clearAmmo();
		if (!oItem.hasAmmo) {
			return;
		}

		oItem.ammoList.forEach(oAmmoList => {
			const sKlasse = oAmmoList.gegenstand_klasse_id;
			const oAmmoSelect = this.createItemDropDown(sKlasse, false);
			const oAmmoObject = oAmmoSelect.selectedOptions[0] ? skillsData.oItemsByInstanceId[oAmmoSelect.selectedOptions[0].value] : null;

			if (!oAmmoObject) {
				return;
			}
			oCell.appendChild(oAmmoSelect);
			oAmmoObject.itemClassId = sKlasse;
			oItem.setAmmo(sKlasse, oAmmoObject);
		});
	}

	/**
	 * @param {HTMLTableCellElement} oCell
	 * @param {SkillsSkill} oSkillObject
	 */
	insertAttackType(oCell, oSkillObject) {
		oCell.dataset[this.oDataSets.cellType.js] = this.oCellTypeNames.attackType;

		if (oSkillObject.attackType) {
			oCell.textContent = skillsData.translateSpecialSymbols(skillsData.oTypes.angriffs_typ[oSkillObject.attackType]);
		}
	}

	/**
	 * @param {HTMLTableCellElement} oCell
	 * @param {SkillsSkill} oSkillObject
	 */
	insertManaCosts(oCell, oSkillObject) {
		const oFragment = document.createDocumentFragment()
		const iNextCostRows = 12;

		oCell.dataset[this.oDataSets.cellType.js] = this.oCellTypeNames.manaCost;

		if (oSkillObject.manaCost === 0 && oSkillObject.gainMpBasic === 0 && oSkillObject.gainMpPercent === 0) {
			return;
		}

		const flNotVariable = oSkillObject.manaCost * 0.8;
		const iTotalCost = Math.trunc(flNotVariable + (oSkillObject.rankEffective / 10) * oSkillObject.manaCost);
		let sMouseOverText = `Basismanakosten: ${oSkillObject.manaCost}<hr />Nächste Erhöhung der Manakosten:<br />`;
		let sGainMinusMouseOverText = "<hr />Die Fertigkeit wird grundsätzlich in voller Wirkung ausgeführt, solange der Held Basis-Manakosten bestreiten kann."
			+ "<br />Die zusätzlichen Manakosten werden nach der Ausführung der Fertigkeit von deinem Manavorrat abgezogen, dieser kann dabei nicht unter 0 sinken.";
		let sGainPlusMouseOverText = "<hr />";
		let iLastTotal = iTotalCost;
		let sCellText = "";

		oCell.style.textAlign = "center";

		for (let iIndex = 1; iIndex <= iNextCostRows; iIndex++) {
			const iNewSkillRank = oSkillObject.rankEffective + iIndex;
			let iNewTotal = Math.trunc(flNotVariable + (iNewSkillRank / 10) * oSkillObject.manaCost);

			if (iLastTotal === iNewTotal) {
				continue;
			}

			sMouseOverText += `Rang ${iNewSkillRank}: ${iNewTotal}<br />`;

			iLastTotal = iNewTotal;
		}

		oFragment.appendChild(skillsLayout.createMouseOver(`<p>${sMouseOverText}</p>`, iTotalCost));

		if (oSkillObject.gainMpBasic) {
			let sOperator = " - ";
			let sGainBasisMouseOverText;

			if (oSkillObject.gainMpBasic < 0) {
				sOperator = " + ";
				sGainBasisMouseOverText = "Verlust an MP" + sGainMinusMouseOverText;
			} else {
				sGainBasisMouseOverText = "Gewinn an MP" + sGainPlusMouseOverText;
			}

			sCellText = Math.abs(oSkillObject.gainMpBasic);
			oFragment.appendChild(document.createTextNode(sOperator));
			oFragment.appendChild(skillsLayout.createMouseOver(sGainBasisMouseOverText, sCellText));
		}

		if (oSkillObject.gainMpValue) {
		}

		if (oSkillObject.gainMpType !== "bo_wert" && oSkillObject.gainMpPercent !== 0 && oSkillObject.gainMpBasic !== 0 && oSkillObject.gainMpValue !== 0) {
		}

		if (oSkillObject.gainMpPercent) {
			let sOperator = " - ";
			let sGainProcMouseOverText;

			if (oSkillObject.gainMpPercent < 0) {
				sOperator = " + ";
				sGainProcMouseOverText = `Verlust an MP: ${oSkillObject.gainMpPercent}% des Schadenswurfes` + sGainMinusMouseOverText;
			} else {
				sGainProcMouseOverText = `Gewinn an MP: ${oSkillObject.gainMpPercent}% des Schadenswurfes` + sGainPlusMouseOverText;
			}

			sCellText = `${Math.abs(oSkillObject.gainMpPercent)}%`;
			oFragment.appendChild(document.createTextNode(sOperator));
			oFragment.appendChild(skillsLayout.createMouseOver(sGainProcMouseOverText, sCellText));
		}

		oCell.appendChild(oFragment);
	}

	/**
	 * @param {HTMLTableCellElement} oCell
	 * @param {SkillsSkill} oSkillObject
	 */
	insertItemClass(oCell, oSkillObject) {
		oCell.dataset[this.oDataSets.cellType.js] = this.oCellTypeNames.item;

		if (!oSkillObject.itemClassId || !skillsData.oItemClasses[oSkillObject.itemClassId]) {
			return;
		}

		const sItemClassName = skillsData.oItemClasses[oSkillObject.itemClassId].name;

		if (oSkillObject.isItemOptional) {
			oCell.appendChild(skillsLayout.createMouseOver("optional", sItemClassName));
		} else {
			oCell.textContent = sItemClassName;
		}
	}

	/**
	 * @param {HTMLTableCellElement} oCell
	 * @param {SkillsSkill} oSkillObject
	 */
	insertNumberOfTargets(oCell, oSkillObject) {
		const oHeroMaxLevel = 40;
		const sChainAttackPopUp = "Der zweite Gegner erhält nur dann Schaden,<br />wenn der erste bewusstlos geworden ist.<br /><br />Der dritte erhält nur dann Schaden,<br />wenn der zweite bewusstlos geworden ist.<br /><br />Usw.";

		oCell.dataset[this.oDataSets.cellType.js] = this.oCellTypeNames.numberOfTargets;

		if (oSkillObject.realType === SkillsSkill.oRealTypes.parade || oSkillObject.realType === SkillsSkill.oRealTypes.ini) {
			return;
		}

		if (!oSkillObject.isConfigurable) {
			return;
		}

		let blOnlyOnePosition = false;

		oCell.style.textAlign = "center";

		switch (oSkillObject.targetType) {
			case SkillsSkill.oTargetTypes.hero:
				oCell.textContent = "nur auf Selbst";
				break;
			case SkillsSkill.oTargetTypes.oneAlly:
			case SkillsSkill.oTargetTypes.oneEnemy:
				oCell.textContent = "1";
				break;
			case SkillsSkill.oTargetTypes.allyPosition:
			case SkillsSkill.oTargetTypes.enemyPosition:
				blOnlyOnePosition = true;
			case SkillsSkill.oTargetTypes.allyGroup:
			case SkillsSkill.oTargetTypes.enemyGroup:
				const blAffectedIsNumber = !Number.isNaN(oSkillObject.targetNumberValue);
				let sMouseOverText = "Anzahl Betroffene: ";
				let sFactorLabel = "der Heldenstufe";
				let sNextTargetFactor = "Stufe";
				let iMoreTargetLevel = 0;
				let iFactor = skillsHero.iLevel;

				/**
				 * @type {number|string}
				 */
				let mNumberOfTargets = 0;

				if (oSkillObject.targetNumberBasic) {
					sMouseOverText += oSkillObject.targetNumberBasic;
					mNumberOfTargets += oSkillObject.targetNumberBasic;
				}

				if (blAffectedIsNumber && oSkillObject.targetNumberValue !== 0) {
					switch (oSkillObject.targetNumberType) {
						case "bo_wert":
							mNumberOfTargets += oSkillObject.targetNumberValue;

							break;
						case "bo_prozent":
							if (oSkillObject.targetNumberValue === 100) {
								mNumberOfTargets = "Alle";
							} else {
								mNumberOfTargets += `${oSkillObject.targetNumberValue}%`;
							}

							break;
						case "bo_wirk_faktor":
							iFactor = oSkillObject.rankEffective;
							sFactorLabel = "des Fertigkeitenrangs";
							sNextTargetFactor = "Rang";
						case "bo_stufen_faktor":
							iMoreTargetLevel = (Math.trunc(oSkillObject.targetNumberValue * iFactor / 100) + 1) / (oSkillObject.targetNumberValue / 100);
							sMouseOverText += `${skillsData.prefacePlus(oSkillObject.targetNumberValue)}% ${sFactorLabel}`;
							mNumberOfTargets += Math.trunc(iFactor * (oSkillObject.targetNumberValue / 100));

							if (iMoreTargetLevel <= oHeroMaxLevel) {
								sMouseOverText += `<hr />Ein Betroffener mehr auf ${sNextTargetFactor} ${Math.ceil(iMoreTargetLevel)}`;
							}

							break;
						default:
					}
				}

				if (oSkillObject.targetNumberType === "bo_wert" || !blAffectedIsNumber || mNumberOfTargets === "Alle" || (iMoreTargetLevel === 0 || iMoreTargetLevel > oHeroMaxLevel)) {
					oCell.textContent = mNumberOfTargets;
				} else {
					oCell.appendChild(skillsLayout.createMouseOver(sMouseOverText, mNumberOfTargets));
				}

				if (oSkillObject.isChainAttack) {
					oCell.appendChild(skillsLayout.createMouseOver(sChainAttackPopUp, "🔗", {
						fontSize: "10px",
						marginLeft: "2px"
					}));
				}

				if (blOnlyOnePosition) {
					oCell.appendChild(document.createTextNode(" auf einer Position"));
				}

				break;
			default:
		}
	}

	/**
	 * @param {HTMLTableCellElement} oCell
	 * @param {SkillsSkill} oSkillObject
	 * @param {SkillsItem} oItemObject
	 */
	insertThrows(oCell, oSkillObject, oItemObject = null) {
		oCell.dataset[this.oDataSets.cellType.js] = this.oCellTypeNames.effectThrows;

		if (oSkillObject.type !== SkillsSkill.oTypes.heal && oSkillObject.type !== SkillsSkill.oTypes.ini && oSkillObject.realType !== SkillsSkill.oRealTypes.powerDown) {
			return;
		}

		if (oItemObject) {
			oItemObject.itemClassId = oSkillObject.itemClassId;

			if (oItemObject.damageType) {
				oSkillObject.damageType = oItemObject.damageType;
			}
		}

		switch (oSkillObject.realType) {
			case "rt_healing":
				this.createThrowRows(oSkillObject, oItemObject, oCell, "healing");
				break;
			case "rt_parade":
				this.createThrowRows(oSkillObject, oItemObject, oCell, "parades");
				break;
			case "rt_initiativ":
				this.createThrowRows(oSkillObject, oItemObject, oCell, "initiative");
				break;
			case "rt_powerdown":
				this.createThrowRows(oSkillObject, oItemObject, oCell, "attacks");
				break;
			case "rt_attack":
				this.createThrowRows(oSkillObject, oItemObject, oCell, "attacks");

				if (oSkillObject.isConfigurableParade) {
					this.createThrowRows(oSkillObject, oItemObject, oCell, "parades");
				}

				if (oSkillObject.hasDamageType) {
					this.createThrowRows(oSkillObject, oItemObject, oCell, "damage");
				}

				break;
		}
	}

	/* --- One throw ---------------------------------------------------------- */

	/**
	 * One throw of a skill, with its Rechenweg in the tooltip. Damage comes with a
	 * row for every other damage type a trigger adds on top.
	 *
	 * @param {SkillsSkill} oSkillObject
	 * @param {SkillsItem} oItemObject
	 * @param {HTMLTableCellElement} oCell
	 * @param {string} sDataType - attacks, parades, initiative, healing or damage
	 */
	createThrowRows(oSkillObject, oItemObject = null, oCell, sDataType) {
		const oWurf = this.throwCalc(oSkillObject, oItemObject, sDataType);
		let oCellRow = document.createDocumentFragment();

		oCellRow.appendChild(this.createCellRow(oSkillObject.damageType, sDataType, skillsRechenweg(oWurf),
			oWurf.min, oWurf.avg, oWurf.max, oWurf.blIsDamage, {
				hit: oWurf.avg,
				good: oWurf.good,
				critical: oWurf.critical
			}));

		if (oWurf.blIsDamage) {
			for (let sDamageType of skillsLayout.getOrder("aDamageTypes")) {
				if (sDamageType === oSkillObject.damageType) {
					continue;
				}

				const oTriggerFixedBonus = this.getDamageBonusse(oSkillObject, oItemObject, sDamageType, true);

				if (oTriggerFixedBonus.normal === 0 && oTriggerFixedBonus.good === 0 && oTriggerFixedBonus.critical === 0) {
					continue;
				}

				const oDamageZFixedBonus = this.getDamageBonusse(oSkillObject, oItemObject, sDamageType);
				const aTrigger = [oTriggerFixedBonus.normal, oTriggerFixedBonus.good, oTriggerFixedBonus.critical];
				const aZ = [oDamageZFixedBonus.normal, oDamageZFixedBonus.good, oDamageZFixedBonus.critical];

				//Raising damage counts only where a trigger brings damage to raise.
				const aWerte = aTrigger.map((w, i) => w !== 0 ? w + aZ[i] : 0);

				if (aWerte[0] === 0 && aWerte[1] === 0 && aWerte[2] === 0) {
					continue;
				}

				const flFinal = skillsFinalFactor(oSkillObject);
				const oTrigger = {
					sDamageType: sDamageType,
					aQuellen: this.damageList(oSkillObject, oItemObject, sDamageType, true, false)
						.concat(this.damageList(oSkillObject, oItemObject, sDamageType, false, false)
							.map(q => ({ name: q.name, werte: q.werte.map((w, i) => aTrigger[i] !== 0 ? w : 0) }))),
					aSumme: aWerte,
					flFinal: flFinal,
					aErgebnis: aWerte.map(w => Math.max(0, w * flFinal))
				};

				oCellRow.appendChild(this.createCellRow(sDamageType, sDataType, skillsRechenwegTrigger(oTrigger), 0, 0, 0, true, {
					hit: oTrigger.aErgebnis[0],
					good: oTrigger.aErgebnis[1],
					critical: oTrigger.aErgebnis[2],
					blDamageTrigger: true
				}));
			}
		}

		oCell.appendChild(oCellRow);
	}

	/**
	 * The numbers of one throw, and every step on the way to them, the way the
	 * engine rolls it (R1 to R6 above skillsRoll): attributes and rank give the
	 * mean, it is cut to a whole number and rolled, every percentage scales the
	 * roll, the fixed bonuses come on top, the final effect bonus multiplies it
	 * all, and the result is cut once. What the table shows is the mean of all the
	 * values that can come up, each as often as it does.
	 *
	 * Damage has three columns, hit, good and critical hit, each with its own
	 * percentages and fixed bonuses on the same dice. The range runs from the
	 * lowest a hit can do to the highest a critical hit can do.
	 *
	 * @param {SkillsSkill} oSkillObject
	 * @param {SkillsItem} oItemObject
	 * @param {string} sDataType
	 */
	throwCalc(oSkillObject, oItemObject, sDataType) {
		const blIsEffect = (sDataType === "healing" || sDataType === "damage");
		const blIsDamage = sDataType === "damage";
		const sPrimaryAttributeKey = blIsEffect ? oSkillObject.attributePrimaryEffect : oSkillObject.attributePrimary;
		const sSecondaryAttributeKey = blIsEffect ? oSkillObject.attributeSecondaryEffect : oSkillObject.attributeSecondary;
		const oKein = { effective_value: 0, base_value: "0" };
		const oPrimaryAttribute = this.oDataPowerUps.attributes[sPrimaryAttributeKey] || oKein;
		const oSecondaryAttribute = this.oDataPowerUps.attributes[sSecondaryAttributeKey] || oKein;
		const aStuecke = [];
		const oWurf = {
			sDataType: sDataType,
			blIsEffect: blIsEffect,
			blIsDamage: blIsDamage,
			blIsIni: oSkillObject.realType === SkillsSkill.oRealTypes.ini,
			oPrimary: { sKey: sPrimaryAttributeKey, flStart: Number(oPrimaryAttribute.effective_value) || 0, aQuellen: [] },
			oSecondary: { sKey: sSecondaryAttributeKey, flStart: Number(oSecondaryAttribute.effective_value) || 0, aQuellen: [] },
			oRank: { flStart: oSkillObject.rankEffective || 0, aQuellen: [] }
		};

		if (oItemObject) {
			aStuecke.push(oItemObject);
			if (oItemObject.hasAmmo) {
				oItemObject.ammoEquipped.forEach(oAmmo => aStuecke.push(oAmmo));
			}
		}
		//What an item gives in shares of the skill rank, with the rank of this skill.
		aStuecke.forEach(oStueck => oStueck.fuerRang(oSkillObject.rankEffective));

		/*
		 * The rank on use: every percentage on it, the skill's own and those of the
		 * item and its ammunition, multiplies, and all of them act on the trained
		 * rank. What the effective rank has beyond it, and the fixed parts, come on
		 * top.
		 */
		const aRangTeile = [Object.assign({ name: "Anwendung" }, oSkillObject.rankOnUse)]
			.concat(aStuecke.map(oStueck => Object.assign({ name: oStueck.name }, this.getItemRankParts(oStueck, oSkillObject))));
		const flGeskillt = oWurf.oRank.flGeskillt = oSkillObject.rankBase || 0;
		oWurf.oRank.aFaktoren = aRangTeile.filter(t => t.faktor !== 1 && !Number.isNaN(t.faktor))
			.map(t => ({ name: t.name, wert: t.faktor }));
		oWurf.oRank.flFaktorTeil = (oWurf.oRank.aFaktoren.reduce((f, t) => f * t.wert, 1) - 1) * flGeskillt;
		aRangTeile.forEach(t => oWurf.oRank.aQuellen.push({ name: t.name, wert: t.fest }));

		/*
		 * Item bonuses on the rank are at most as high as the trained rank, those on
		 * use as well. What the item and its ammunition add on use goes to the item
		 * bonuses the skill has already; past the trained rank it is lost. A malus
		 * can bring an item bonus back under it. The skill's own bonuses on use are
		 * no item bonuses and stay as they are.
		 */
		const aItemTeile = aRangTeile.slice(1).filter(t => !Number.isNaN(t.faktor) && !Number.isNaN(t.fest));
		const flItemsDazu = flGeskillt * aRangTeile[0].faktor * (aItemTeile.reduce((f, t) => f * t.faktor, 1) - 1)
			+ aItemTeile.reduce((flSumme, t) => flSumme + t.fest, 0);
		const oItemBoni = flItemsDazu ? skillsItemBoni(oSkillObject.name) : null;
		if (oItemBoni) {
			const flDeckel = Math.min(flGeskillt, oItemBoni.itemFloored + flItemsDazu) - oItemBoni.itemApplied - flItemsDazu;
			if (Math.abs(flDeckel) > 1e-9) {
				oWurf.oRank.aQuellen.push({ name: "Obergrenze Itemboni", wert: flDeckel });
				oWurf.oRank.oDeckel = { vorher: oItemBoni.itemFloored, dazu: flItemsDazu, grenze: flGeskillt };
			}
		}

		for (const oStueck of aStuecke) {
			oWurf.oPrimary.aQuellen.push({ name: oStueck.name, wert: this.getItemAttributeBonus(oStueck, sPrimaryAttributeKey, oPrimaryAttribute.base_value) });
			oWurf.oSecondary.aQuellen.push({ name: oStueck.name, wert: this.getItemAttributeBonus(oStueck, sSecondaryAttributeKey, oSecondaryAttribute.base_value) });
		}

		for (const [oTeil, oAttribut] of [[oWurf.oPrimary, oPrimaryAttribute], [oWurf.oSecondary, oSecondaryAttribute]]) {
			const oAnwendung = oSkillObject.getPowerUpAttribute(oTeil.sKey);
			oTeil.aQuellen.push({ name: "Anwendung", wert: (oAnwendung.percent - 1) * (parseInt(oAttribut.base_value) || 0) + oAnwendung.fixed });
		}

		//Each part with what the item and the use add, fractions and all. The only
		//cut before the end is that of the whole mean (R2, in skillsRoll).
		for (const oTeil of [oWurf.oPrimary, oWurf.oSecondary, oWurf.oRank]) {
			oTeil.aQuellen = oTeil.aQuellen.filter(q => q.wert !== 0 && !Number.isNaN(q.wert));
			oTeil.flWert = Math.max(0, oTeil.aQuellen.reduce((flSumme, q) => flSumme + q.wert,
				oTeil.flStart + (oTeil.flFaktorTeil || 0)));
		}

		//The mean as the game shows it (R1).
		const flP = oWurf.oPrimary.flWert, flS = oWurf.oSecondary.flWert, flR = oWurf.oRank.flWert;
		oWurf.aTeile = blIsEffect ? [flP / 2, flS / 3, flR / 2] : [flP * 2, flS, flR * 2];
		oWurf.flBase = oWurf.aTeile[0] + oWurf.aTeile[1] + oWurf.aTeile[2];

		//Every percentage on the throw, and for damage those of each column. They
		//scale the roll, not the mean the dice are chosen for (R4).
		oWurf.aProzente = this.bonusList(blIsEffect, sDataType, oSkillObject, oItemObject, true);
		oWurf.flFaktor = oWurf.aProzente.reduce((flFaktor, q) => flFaktor * q.wert, 1);
		oWurf.aProzente = oWurf.aProzente.filter(q => q.wert !== 1);

		let aFaktor = [oWurf.flFaktor];
		oWurf.aStufen = [];
		if (blIsDamage) {
			const aTrigger = this.damageList(oSkillObject, oItemObject, oSkillObject.damageType, true, true);
			const aZ = this.damageList(oSkillObject, oItemObject, oSkillObject.damageType, false, true);
			aFaktor = [oWurf.flFaktor, oWurf.flFaktor, oWurf.flFaktor];
			for (const q of aTrigger.concat(aZ)) {
				aFaktor = aFaktor.map((w, i) => w * q.werte[i]);
				if (q.werte.some(w => w !== 1)) {
					oWurf.aStufen.push(q);
				}
			}
		}
		oWurf.aFaktor = aFaktor;

		//The whole mean and its roll (R2, R3).
		oWurf.oRoll = skillsRoll(oWurf.flBase);

		//The fixed bonuses, the same for every column, and for damage those of each
		//column (R5).
		oWurf.aFeste = this.bonusList(blIsEffect, sDataType, oSkillObject, oItemObject, false)
			.filter(q => q.wert !== 0 && !Number.isNaN(q.wert))
			.map(q => ({ name: q.name, werte: aFaktor.map(() => q.wert) }));
		if (blIsDamage) {
			for (const q of this.damageList(oSkillObject, oItemObject, oSkillObject.damageType, true, false)
					.concat(this.damageList(oSkillObject, oItemObject, oSkillObject.damageType, false, false))) {
				if (q.werte.some(w => w !== 0)) {
					oWurf.aFeste.push(q);
				}
			}
		}
		oWurf.aFest = aFaktor.map((w, i) => oWurf.aFeste.reduce((flSumme, q) => flSumme + q.werte[i], 0));

		oWurf.flFinal = blIsEffect ? skillsFinalFactor(oSkillObject) : 1;

		//What a column rolls on average and where it can land, before the final
		//effect bonus and the cut.
		const oRoll = oWurf.oRoll;
		const iLetzte = aFaktor.length - 1;
		oWurf.aGewuerfelt = aFaktor.map(f => oRoll.schnitt * f);
		oWurf.aSumme = oWurf.aGewuerfelt.map((w, i) => w + oWurf.aFest[i]);
		oWurf.flVon = oRoll.min * aFaktor[0] + oWurf.aFest[0];
		oWurf.flBis = oRoll.max * aFaktor[iLetzte] + oWurf.aFest[iLetzte];

		//Every value that can come up, and how often (R6).
		oWurf.aVerteilung = aFaktor.map((f, i) => skillsVerteilung(oRoll, f, oWurf.aFest[i], oWurf.flFinal));
		oWurf.aMittel = oWurf.aVerteilung.map(v => v.mittel);

		oWurf.avg = Math.round(oWurf.aMittel[0]);
		oWurf.good = blIsDamage ? Math.round(oWurf.aMittel[1]) : undefined;
		oWurf.critical = blIsDamage ? Math.round(oWurf.aMittel[2]) : undefined;
		oWurf.min = oWurf.aVerteilung[0].min;
		oWurf.max = oWurf.aVerteilung[iLetzte].max;

		if (oWurf.blIsIni) {
			oWurf.sAktionen = this.addActionsToolTip(oWurf.aMittel[0]);
		}

		return oWurf;
	}

	/**
	 * @param {HTMLSelectElement} oSelect
	 */
	updateThrowCell(oSelect) {
		const oThrowCell = oSelect.closest("tr").cells[this.iDefaultTableHeaderCells + this.aNewCells.indexOf("effectThrows") + 1];
		let sSkillName = oSelect.dataset[this.oDataSets.selectSkillName.js];
		let sItemInstanceId = oSelect.selectedOptions[0].value;
		let oSkill, oItem;

		oThrowCell.innerHTML = "";

		if (!sSkillName) {
			const oSkillSelect = oSelect.parentElement.querySelector(`select[${this.oDataSets.selectSkillName.css}]`);

			sSkillName = oSkillSelect.dataset[this.oDataSets.selectSkillName.js];
			sItemInstanceId = oSkillSelect.selectedOptions[0].value;
		}

		oSkill = this.oSkillObjectByName[sSkillName];
		oItem = skillsData.oItemsByInstanceId[sItemInstanceId];

		if (oSelect.dataset[this.oDataSets.selectSkillName.js]) {
			//Another item: its own ammunition.
			this.ammoDropDowns(oSelect.parentElement, oItem);
		} else if (oItem) {
			const sItemClassId = oSelect.dataset[this.oDataSets.itemClassId.js];
			const oAmmoItem = skillsData.oItemsByInstanceId[oSelect.selectedOptions[0].value];
			if (oAmmoItem) {
				oAmmoItem.itemClassId = sItemClassId;
				oItem.setAmmo(sItemClassId, oAmmoItem);
				oItem.damageType = oAmmoItem.damageType;
			}
		}

		this.insertThrows(oThrowCell, oSkill, oItem);
	}

	/* --- Where the bonuses come from ---------------------------------------- */

	/**
	 * Every bonus on a throw, by where it comes from: the item the skill is used
	 * with, its ammunition, the skill itself, and what the hero carries at all times.
	 * Percentages as factors (1.1 for +10%), fixed bonuses as numbers.
	 *
	 * @return {Array<{name: string, wert: number}>}
	 */
	bonusList(blIsEffect, sDataType, oSkillObject, oItemObject, blIsPercent) {
		const sSkillValueType = blIsPercent ? "percent" : "fixed";
		const sAngriff = skillsData.translateSpecialSymbols(skillsData.oTypes.angriffs_typ && skillsData.oTypes.angriffs_typ[oSkillObject.attackType] || "");
		const aListe = [];
		const fnGlobal = (sName, oBonus) => {
			if (oBonus && oBonus.bonus) {
				aListe.push({ name: sName, wert: this.getDataValue(blIsPercent, oBonus.bonus) });
			}
		};

		if (oItemObject) {
			this.itemSkillBonusList(aListe, blIsEffect, sDataType, sSkillValueType, oItemObject, oSkillObject, oItemObject.name, sAngriff);

			if (oItemObject.hasAmmo) {
				oItemObject.ammoEquipped.forEach(oAmmo => {
					this.itemSkillBonusList(aListe, blIsEffect, sDataType, sSkillValueType, oAmmo, oSkillObject, oAmmo.name, sAngriff);
				});
			}
		}

		this.itemSkillBonusList(aListe, blIsEffect, sDataType, sSkillValueType, oSkillObject, oSkillObject, "", sAngriff);

		if (blIsEffect) {
			fnGlobal("Bonus Wirkung", this.oDataPowerUps.skillEffects[oSkillObject.name]);
			if (oSkillObject.skillClassName) {
				fnGlobal(`Bonus Wirkung ${oSkillObject.skillClassName}`, this.oDataPowerUps.skillEffects[oSkillObject.skillClassName]);
			}
		} else if (sDataType === "attacks" && (oSkillObject.realType === SkillsSkill.oRealTypes.attack || oSkillObject.realType === SkillsSkill.oRealTypes.powerDown)) {
			fnGlobal(`Bonus Angriffe ${sAngriff}`, this.oDataPowerUps.attacks[oSkillObject.attackType]);
		} else if (sDataType === "parades" && oSkillObject.isConfigurableParade) {
			fnGlobal(`Bonus Paraden ${sAngriff}`, this.oDataPowerUps.parades[oSkillObject.attackType]);
		} else if (sDataType === "initiative" && oSkillObject.realType === SkillsSkill.oRealTypes.ini) {
			fnGlobal("Bonus Initiative", this.oDataPowerUps.initiative);
		}

		return aListe;
	}

	/**
	 * What an item, a piece of ammunition or the skill itself adds to a throw. An
	 * empty source name stands for the skill.
	 *
	 * @param {Array} aListe
	 * @param {SkillsItem|SkillsSkill} oClassObject
	 * @param {SkillsSkill} oSkillObject
	 */
	itemSkillBonusList(aListe, blIsEffect, sDataType, sSkillValueType, oClassObject, oSkillObject, sQuelle, sAngriff) {
		const sWer = sQuelle || "Anwendung";

		if (blIsEffect) {
			aListe.push({ name: sQuelle ? `${sQuelle} (Wirkung)` : "Fertigkeit (Wirkung)", wert: oClassObject.effect[sSkillValueType] });
			aListe.push({ name: `${sWer} auf die Fertigkeit`, wert: oClassObject.getPowerUpSkill(oSkillObject.name)[sSkillValueType] });
			if (oSkillObject.skillClassName) {
				aListe.push({ name: `${sWer} auf ${oSkillObject.skillClassName}`, wert: oClassObject.getPowerUpSkill(oSkillObject.skillClassName)[sSkillValueType] });
			}
			return;
		}

		let blProbe = false;

		if (sDataType === "attacks" && (oSkillObject.realType === SkillsSkill.oRealTypes.attack || oSkillObject.realType === SkillsSkill.oRealTypes.powerDown)) {
			aListe.push({ name: `${sWer} auf Angriffe ${sAngriff}`, wert: oClassObject.getPowerUpProbeThrow(oSkillObject.attackType, SkillsSkill.oRealTypes.attack)[sSkillValueType] });
			blProbe = true;
		} else if (sDataType === "parades" && oSkillObject.isConfigurableParade) {
			aListe.push({ name: `${sWer} auf Paraden ${sAngriff}`, wert: oClassObject.getPowerUpProbeThrow(oSkillObject.attackType, SkillsSkill.oRealTypes.parade)[sSkillValueType] });
			blProbe = true;
		} else if (sDataType === "initiative" && oSkillObject.realType === SkillsSkill.oRealTypes.ini) {
			aListe.push({ name: `${sWer} auf Initiative`, wert: oClassObject.getPowerUpAttribute("at_v_initiative")[sSkillValueType] });
			blProbe = true;
		}

		if (blProbe) {
			aListe.push({ name: sQuelle ? `${sQuelle} (Probe)` : "Fertigkeit (Probe)", wert: oClassObject.probe[sSkillValueType] });
		}
	}

	/**
	 * Every damage bonus of one damage type, per column: what the hero carries, the
	 * skill on use, the item and its ammunition. A trigger adds damage of its type,
	 * the other kind (z) raises damage the throw already does.
	 *
	 * @return {Array<{name: string, werte: number[]}>}
	 */
	damageList(oSkillObject, oItemObject, sDamageType, blIsTrigger, blIsPercent) {
		const sArt = blIsTrigger ? "Schaden" : "Schaden (z)";
		const sDataPowerUpType = blIsTrigger ? "damages" : "damagesZ";
		const aHit = skillsData.aHitTypes;
		const aListe = [];
		const fnWerte = oBonus => aHit.map(sHit => this.getDataValue(blIsPercent, oBonus[sHit].bonus));
		const oTyp = this.oDataPowerUps[sDataPowerUpType][sDamageType];

		if (typeof oTyp !== "undefined") {
			if (typeof oTyp[oSkillObject.attackType] !== "undefined") {
				aListe.push({ name: `Bonus ${sArt}`, werte: fnWerte(oTyp[oSkillObject.attackType]) });
			}

			if (typeof oTyp[skillsData.sAllAttackTypKey] !== "undefined") {
				aListe.push({ name: `Bonus ${sArt}, alle Angriffsarten`, werte: fnWerte(oTyp[skillsData.sAllAttackTypKey]) });
			}
		}

		const oSkillDamage = oSkillObject.getPowerUpDamage(sDamageType, oSkillObject.attackType, blIsTrigger);
		if (oSkillDamage) {
			aListe.push({ name: `Anwendung, ${sArt}`, werte: fnWerte(oSkillDamage) });
		}

		if (oItemObject) {
			aListe.push({ name: `${oItemObject.name}, ${sArt}`, werte: fnWerte(oItemObject.getPowerUpDamage(sDamageType, oSkillObject.attackType, blIsTrigger)) });

			if (oItemObject.hasAmmo) {
				oItemObject.ammoEquipped.forEach(oAmmo => {
					aListe.push({ name: `${oAmmo.name}, ${sArt}`, werte: fnWerte(oAmmo.getPowerUpDamage(sDamageType, oSkillObject.attackType, blIsTrigger)) });
				});
			}
		}

		return aListe;
	}

	/**
	 * All damage bonuses of one damage type together, per column.
	 *
	 * @return {{normal: number, good: number, critical: number}}
	 */
	getDamageBonusse(oSkillObject, oItemObject, sDamageType, blIsTrigger = false, blIsPercent = false) {
		const aSumme = blIsPercent ? [1, 1, 1] : [0, 0, 0];

		for (const q of this.damageList(oSkillObject, oItemObject, sDamageType, blIsTrigger, blIsPercent)) {
			for (let i = 0; i < 3; i++) {
				aSumme[i] = blIsPercent ? aSumme[i] * q.werte[i] : aSumme[i] + q.werte[i];
			}
		}

		return { normal: aSumme[0], good: aSumme[1], critical: aSumme[2] };
	}

	getItemAttributeBonus(oItemObject, sAttributeKey, sAttributeBaseValue) {
		const oItemPowerUpAttribute = oItemObject.getPowerUpAttribute(sAttributeKey);
		let flReturnBonus = 0;

		flReturnBonus += (oItemPowerUpAttribute.percent - 1) * parseInt(sAttributeBaseValue) + oItemPowerUpAttribute.fixed;

		return flReturnBonus;
	}

	//What an item or its ammunition does to the rank of the skill it is used with:
	//its percentages as one factor, and its fixed part.
	getItemRankParts(oItemObject, oSkillObject) {
		let flFaktor = 1, flFest = 0;
		const fnDazu = oTeil => {
			flFaktor *= oTeil.percent;
			flFest += oTeil.fixed;
		};

		if (oSkillObject.itemEffectCountForSkillRang) {
			fnDazu(oItemObject.effect);
		}
		fnDazu(oItemObject.getPowerUpSkill(oSkillObject.name, "rank"));
		if (oSkillObject.skillClassId) {
			fnDazu(oItemObject.getPowerUpSkill(oSkillObject.skillClassName, "rank"));
		}

		return { faktor: flFaktor, fest: flFest };
	}

	getDataValue(blIsPercent, oBonusObject) {
		if (blIsPercent) {
			return oBonusObject.percentage.flEffective;
		} else {
			return oBonusObject.flTotal;
		}
	}

	addActionsToolTip(flEffectBase) {
		const iActions = this.oDataPowerUps.attributes.anz_aktionen.effective_value;
		let sReturnActionToolTip = "";

		if (iActions > 1) {
			let flSecondValue = flEffectBase;

			sReturnActionToolTip += `<hr />`;

			for (let iActionIndex = 1; iActionIndex <= iActions; iActionIndex++) {
				let flFirstValue = (flEffectBase / iActions) * (1 + iActions - iActionIndex);

				sReturnActionToolTip += `${iActionIndex}. Aktion bei Initiative ${Math.floor((flFirstValue + flSecondValue) / 2)}<br />`;
				flSecondValue /= 2;
			}
		}

		return sReturnActionToolTip;
	}

	/**
	 * @param sDamageType
	 * @param sDataType
	 * @param sToolTip
	 * @param flEffectMin
	 * @param flEffectBase
	 * @param flEffectMax
	 * @param blIsDamage
	 * @param oDamageBonus
	 * @return {Node}
	 */
	createCellRow(sDamageType, sDataType, sToolTip, flEffectMin, flEffectBase, flEffectMax, blIsDamage, oDamageBonus) {
		const oLabel = {
			"healing": "Heilung",
			"attacks": "Angriff",
			"parades": "Parade",
			"initiative": "Initiative",
			"damage": skillsData.translateSpecialSymbols(skillsData.oTypes.schadens_typ[sDamageType] || "")
		};
		const oDamageColor = {
			"st_blitz_schaden": "yellow",
			"st_eis_schaden": "cyan",
			"st_feuer_schaden": "red",
			"st_gift_schaden": "greenyellow",
			"st_hl_schaden": "silver",
			"st_mana_schaden": "dodgerblue",
			"st_nn_1": "purple",
			"st_psycho_schaden": "fuchsia",
			"st_saeure_schaden": "green",
			"st_wucht_schaden": "inherit",
			"st_hieb_schaden": "inherit",
			"st_schneid_schaden": "inherit",
			"st_stich_schaden": "inherit",
		};
		const oCellRow = this.oElements.oDiv.cloneNode();
		const oCellLabelElement = this.oElements.oSpan.cloneNode();
		const oCellValueElement = this.oElements.oSpan.cloneNode();
		const oCellValueRangeElement = this.oElements.oSmall.cloneNode();

		oCellRow.dataset[this.oDataSets.cellRowType.js] = sDataType;

		oCellLabelElement.style.fontWeight = "bold";
		oCellLabelElement.style.display = "table-cell";
		oCellLabelElement.style.paddingRight = "4px";
		oCellLabelElement.textContent = oLabel[sDataType];

		if (sDataType === "damage") {
			oCellLabelElement.style.color = oDamageColor[sDamageType];
		}

		if (!oDamageBonus.blDamageTrigger) {
			oCellValueRangeElement.textContent = `(${Math.trunc(flEffectMin > 0 ? flEffectMin : 0)} - ${Math.trunc(flEffectMax > 0 ? flEffectMax : 0)})`;
			oCellValueRangeElement.style.marginLeft = "2px";
		} else if (sToolTip === "") {
			oCellValueElement.style.display = "table-cell";
		}

		oCellValueElement.style.textAlign = "right";

		if (blIsDamage) {
			oCellValueElement.textContent = `${Math.trunc(oDamageBonus.hit < 0 ? 0 : oDamageBonus.hit)} / ${Math.trunc(oDamageBonus.good > 0 ? oDamageBonus.good : 0)} / ${Math.trunc(oDamageBonus.critical < 0 ? 0 : oDamageBonus.critical)}`;
		} else {
			oCellValueElement.textContent = Math.trunc(flEffectBase < 0 ? 0 : flEffectBase);
		}

		//What the export reads back: the number as the table shows it, and its range.
		oCellValueElement.setAttribute("data-mm-wert", oCellValueElement.textContent);
		oCellValueRangeElement.setAttribute("data-mm-spanne", "");
		oCellValueElement.appendChild(oCellValueRangeElement);

		oCellRow.style.display = "table";
		oCellRow.style.width = "100%";
		oCellRow.appendChild(oCellLabelElement);

		if (sToolTip !== "") {
			oCellRow.appendChild(skillsLayout.createMouseOver(sToolTip, oCellValueElement, {
				display: "table-cell",
				whiteSpace: "nowrap",
				textAlign: "right",
			}));
		} else {
			oCellRow.appendChild(oCellValueElement);
		}

		return oCellRow;
	}

	createItemDropDown(iItemClassId, blIsItemOptional) {
		/**
		 * @param {Array} aArrayToPushTo
		 * @param {SkillsItem} oItem
		 */
		const fnAddToArray = function (aArrayToPushTo, oItem) {
			if (!aArrayToPushTo.find(/** @param {SkillsItem} oSavedItem **/oSavedItem => oSavedItem.name === oItem.name)) {
				aArrayToPushTo.push(oItem);
			}
		}
		/**
		 * @type {HTMLSelectElement}
		 */
		const oSelect = this.oElements.oSelect.cloneNode();
		const aDoubleEndless = [];
		const aEndlessPerDungeon = [];
		const aEndlessPerFight = [];
		const aNeverEndless = [];
		const aExpandable = [];
		let aSortingArrays = [aDoubleEndless, aEndlessPerDungeon, aEndlessPerFight, aNeverEndless, aExpandable];

		oSelect.dataset[this.oDataSets.itemClassId.js] = iItemClassId;
		oSelect.style.display = "block";
		oSelect.style.marginBottom = "2px";

		if (blIsItemOptional) {
			const oOption = this.oElements.oOption.cloneNode();
			oOption.value = "";
			oOption.textContent = "Bitte auswählen";

			oSelect.appendChild(oOption);
		}

		if (this.oItemClassItemsSorted[iItemClassId]) {
			aSortingArrays = this.oItemClassItemsSorted[iItemClassId];
		} else {
			if (!skillsData.oItemClasses[iItemClassId] || typeof skillsData.oItemClasses[iItemClassId].items === "undefined") {
				return oSelect;
			}

			for (let oItem of skillsData.oItemClasses[iItemClassId].items) {
				if (oItem.applicationsTotal === null) {
					if (oItem.applicationsPerDungeon === null && oItem.applicationsPerFight === null) {
						fnAddToArray(aDoubleEndless, oItem);
					} else if (oItem.applicationsPerDungeon === null) {
						fnAddToArray(aEndlessPerDungeon, oItem);
					} else if (oItem.applicationsPerFight === null) {
						fnAddToArray(aEndlessPerFight, oItem);
					} else {
						fnAddToArray(aNeverEndless, oItem);
					}
				} else {
					fnAddToArray(aExpandable, oItem);
				}
			}

			this.oItemClassItemsSorted[iItemClassId] = aSortingArrays;
		}

		for (let aSortingArray of aSortingArrays) {
			for (/** @type {SkillsItem} oItem **/let oItem of aSortingArray) {
				for (let sSlot of this.aOrderSlots) {
					if (oItem.equipmentSlot === sSlot) {
						const oOption = this.oElements.oOption.cloneNode();
						oOption.value = oItem.instanceId;
						oOption.textContent = oItem.name;

						oSelect.appendChild(oOption);
						break;
					}
				}
			}
		}

		return oSelect;
	}

	/**
	 * @param {string} sTabKey
	 */
	updateRows(sTabKey) {
		const oFragment = document.createDocumentFragment();
		const oThead = this.oSkillTable.tHead.rows[0];
		const oTFoot = this.oSkillTable.tFoot.rows[0];
		let iRowCounter = 0;

		oFragment.appendChild(this.oTableBodySkills);

		this.unHideCells(oThead, true);
		this.unHideCells(oTFoot, true);
		this.updateCells(oThead, sTabKey)
		this.updateCells(oTFoot, sTabKey)

		for (let oRow of this.oTableBodySkills.rows) {
			this.unHideCells(oRow);

			if (sTabKey === "all" || oRow.dataset[this.oDataSets.tabRow.js] === sTabKey || (sTabKey === SkillsSkill.oRealTypes.parade && oRow.dataset[this.oDataSets.tabRowParade.js] === "true")) {
				oRow.style.display = "table-row";

				this.setRowClassAndIndexLabel(oRow, iRowCounter++);
				this.updateCells(oRow, sTabKey);
				this.updateCellRows(oRow, sTabKey);
			} else {
				oRow.style.display = "none";
			}
		}

		this.oSkillTable.appendChild(oFragment);
	}

	/**
	 * @param {HTMLTableRowElement} oRow
	 * @param {number} iRowCounter
	 */
	setRowClassAndIndexLabel(oRow, iRowCounter) {
		oRow.className = `row${iRowCounter % 2}`;
		oRow.cells[0].textContent = (iRowCounter + 1).toString();
	}

	/**
	 * @param {HTMLTableRowElement} oRow
	 * @param {boolean} blIsHeader
	 */
	unHideCells(oRow, blIsHeader = false) {
		oRow.querySelectorAll(`${blIsHeader ? "th" : "td"}[style]`).forEach(oCell => {
			oCell.style.display = "table-cell";
		});
	}

	/**
	 * @param {HTMLTableRowElement} oRow
	 * @param {string} sTabKey
	 */
	updateCells(oRow, sTabKey) {
		switch (sTabKey) {
			case SkillsSkill.oRealTypes.parade:
				this.hideCell("numberOfTargets", oRow);
				break;
			case SkillsSkill.oRealTypes.ini:
				this.hideCell("attackType", oRow)
				this.hideCell("numberOfTargets", oRow);
				break;
			case SkillsSkill.oRealTypes.healing:
				this.hideCell("attackType", oRow);
				break;
			case SkillsSkill.oRealTypes.powerUp:
				this.hideCell("attackType", oRow);
				this.hideCell("effectThrows", oRow);
				break;
			case SkillsSkill.oRealTypes.summon:
				this.hideCell("attackType", oRow);
				this.hideCell("effectThrows", oRow);
				this.hideCell("numberOfTargets", oRow);
				break;
			case "passive":
				this.hideCell("attackType", oRow);
				this.hideCell("effectThrows", oRow);
				this.hideCell("numberOfTargets", oRow);
				this.hideCell("item", oRow);
				this.hideCell("manaCost", oRow);
				break;
			case "all":
				//Every cell stays.
				break;
		}
	}

	/**
	 * @param {HTMLTableRowElement} oRow
	 * @param {string} sTabKey
	 */
	updateCellRows(oRow, sTabKey) {
		if (sTabKey === SkillsSkill.oRealTypes.parade) {
			oRow.querySelectorAll(`[${this.oDataSets.cellRowType.css}]:not([${this.oDataSets.cellRowType.css}="parades"])`).forEach(oCellRow => {
				oCellRow.style.display = "none";
			});
		} else {
			oRow.querySelectorAll(`[${this.oDataSets.cellRowType.css}]:not([${this.oDataSets.cellRowType.css}="parades"])`).forEach(oCellRow => {
				oCellRow.style.display = "table";
			});
		}

		if (sTabKey === SkillsSkill.oRealTypes.attack) {
			oRow.querySelectorAll(`[${this.oDataSets.cellRowType.css}="parades"]`).forEach(oCellRow => {
				oCellRow.style.display = "none";
			});
		} else {
			oRow.querySelectorAll(`[${this.oDataSets.cellRowType.css}="parades"]`).forEach(oCellRow => {
				oCellRow.style.display = "table";
			});
		}
	}

	/**
	 * @param {string} sCellType
	 * @param {HTMLTableRowElement} oRow
	 */
	hideCell(sCellType, oRow) {
		oRow.querySelector(`[${this.oDataSets.cellType.css}="${this.oCellTypeNames[sCellType]}"]`).style.display = "none";
	}

	/**
	 * @param {string} sTabKey
	 * @param {string} sType
	 * @param {boolean} blIsAppended
	 * @param {HTMLTableSectionElement} oTBody
	 * @return {boolean}
	 */
	updateExtraTBody(sTabKey, sType, blIsAppended, oTBody) {
		if (sTabKey === sType) {
			this.oSkillTable.appendChild(oTBody);
			this.updateSecondTBody(oTBody);

			blIsAppended = true;
		} else if (blIsAppended) {
			blIsAppended = false;
			this.oSkillTable.removeChild(oTBody);
		}

		return blIsAppended;
	}

	/**
	 * @param {HTMLTableSectionElement} oTableBody
	 */
	updateSecondTBody(oTableBody) {
		const iInitial = 0;

		let iRowCounter = Array.from(this.oTableBodySkills.rows).reduce((accumulator, oRow) => {
			return accumulator + (oRow.style.display === "none" ? 0 : 1);
		}, iInitial);

		for (let oRow of oTableBody.rows) {
			this.setRowClassAndIndexLabel(oRow, iRowCounter++);
		}
	}

	extendTableStructure() {
		const oFragment = document.createDocumentFragment();
		const oSkillTHead = this.oSkillTable.createTHead();
		const oHeaderRow = this.oTableBodySkills.rows[0];
		let iRowIndex = 0;

		this.iDefaultTableHeaderCells = oHeaderRow.cells.length;

		oFragment.appendChild(this.oTableBodySkills);

		for (let oRow of this.oTableBodySkills.rows) {
			oRow.cells[1].style.verticalAlign = "middle";

			for (let sCellType of this.aNewCells) {
				if (iRowIndex === 0) {
					//The heading row.
					const oNewHeaderCell = this.oElements.oTh.cloneNode();
					oNewHeaderCell.textContent = this.oCellTypeLabel[sCellType];
					oNewHeaderCell.dataset[this.oDataSets.cellType.js] = this.oCellTypeNames[sCellType];
					oRow.appendChild(oNewHeaderCell);
				} else {
					oRow.insertCell();
				}
			}

			iRowIndex++;
		}

		oSkillTHead.appendChild(oHeaderRow);
		this.oSkillTable.appendChild(oFragment);
	}

	addDefaultParades() {
		const oTableParades = this.oElements.oTbody.cloneNode();
		const aAttackTypes = skillsLayout.getOrder("aAttackTypes");

		this.oTableBodyParades = oTableParades;

		for (const sAttackType of aAttackTypes) {
			if (sAttackType === "an_falle_a" || !this.oDefaultParades[sAttackType]) {
				continue;
			}

			this.createExtraTBodyRow(SkillsSkill.sFakeParade, oTableParades, this.oDefaultParades[sAttackType].primary, this.oDefaultParades[sAttackType].secondary, sAttackType);
		}
	}

	addDefaultInitiative() {
		const oTableInitiative = this.oElements.oTbody.cloneNode();

		this.oTableBodyInitiative = oTableInitiative;

		this.createExtraTBodyRow(SkillsSkill.sFakeIni, oTableInitiative, this.oDefaultParades.initiative.primary, this.oDefaultParades.initiative.secondary);
	}

	createExtraTBodyRow(sFakeType, oTable, sPrimaerAttr, sSecondaryAttr, sAttackType = "") {
		const oInnerText = {
			rt_parade: `Standardparade (${sAttackType !== "" ? skillsData.translateSpecialSymbols(skillsData.oTypes.angriffs_typ[sAttackType]) : ""})`,
			rt_initiativ: "Standardinitiative"
		};
		const oDataType = {
			rt_parade: "parades",
			rt_initiativ: "initiative"
		};

		const oRow = oTable.insertRow();
		const oFakeSkill = new SkillsSkill(sFakeType);
		oRow.setAttribute("data-mm-angriffsart", sAttackType);
		oFakeSkill.attackType = sAttackType;
		oFakeSkill.attributeProbePrimary = sPrimaerAttr;
		oFakeSkill.attributeProbeSecondary = sSecondaryAttr;
		oFakeSkill.name = oInnerText[oFakeSkill.realType];

		for (const sOldCellType of this.aOldCells) {
			const oCell = oRow.insertCell();

			if (sOldCellType === "index") {
				oCell.style.textAlign = "right";
			} else if (sOldCellType === "label") {
				oCell.textContent = oInnerText[oFakeSkill.realType];
			}
		}

		for (const sCellType of this.aNewCells) {
			if (sCellType === "numberOfTargets") {
				continue;
			}

			if (oFakeSkill.realType === SkillsSkill.oRealTypes.ini && sCellType === "attackType") {
				continue;
			}

			const oCell = oRow.insertCell();
			oCell.dataset[this.oDataSets.cellType.js] = this.oCellTypeNames[sCellType] || sCellType;

			if (sCellType === "effectThrows") {
				this.createThrowRows(oFakeSkill, null, oCell, oDataType[oFakeSkill.realType]);
			} else if (oFakeSkill.realType === SkillsSkill.oRealTypes.parade && sCellType === "attackType") {
				oCell.textContent = skillsData.translateSpecialSymbols(skillsData.oTypes.angriffs_typ[sAttackType]);
			}
		}
	}

	createTableFooter() {
		const oTableFooter = this.oSkillTable.createTFoot();
		const oFooterRow = oTableFooter.insertRow();
		const oHeaderCells = this.oSkillTable.tHead.firstElementChild.cells;
		const oIndexCell = this.oElements.oTh.cloneNode();
		const oLabelCell = this.oElements.oTh.cloneNode();
		const oRankCell = this.oElements.oTh.cloneNode();
		const oCostCell = this.oElements.oTh.cloneNode();

		oFooterRow.className = "header";
		oIndexCell.textContent = "";
		oLabelCell.innerHTML = oHeaderCells[1].innerHTML;
		oRankCell.innerHTML = oHeaderCells[2].innerHTML;
		oCostCell.colSpan = 2;
		oCostCell.textContent = oHeaderCells[3].textContent;

		oFooterRow.appendChild(oIndexCell);
		oFooterRow.appendChild(oLabelCell);
		oFooterRow.appendChild(oRankCell);
		oFooterRow.appendChild(oCostCell);

		for (const sNewCellType of this.aNewCells) {
			const oNewCell = this.oElements.oTh.cloneNode();
			oNewCell.textContent = this.oCellTypeLabel[sNewCellType];
			oNewCell.dataset[this.oDataSets.cellType.js] = this.oCellTypeNames[sNewCellType];
			oFooterRow.appendChild(oNewCell);
		}
	}

	/* --- Tabs ----------------------------------------------------------------- */

	createTabs() {
		const oTabs = this.oElements.oDiv.cloneNode();
		const oList = this.oElements.oUl.cloneNode();
		const oClear = this.oElements.oSpan.cloneNode();
		const oNote = this.oElements.oSpan.cloneNode();
		const oTabLabel = {
			"all": "Alle",
			"passive": "Passiv",
			"export": "Export"
		};
		const oTalentTypen = skillsData.oTypes.talent_typ || {};

		oTabs.className = "tab";
		oTabs.id = "mm_skills_tabs";
		oTabs.style.backgroundImage = "none";

		oList.appendChild(this.createTabElement("all", oTabLabel.all));

		for (let sTab of this.aTabSkillGroups) {
			oList.appendChild(this.createTabElement(sTab, skillsData.translateSpecialSymbols(oTalentTypen[sTab] || sTab)));
		}

		oList.appendChild(this.createTabElement("passive", oTabLabel.passive));

		const oExport = this.createTabElement("export", oTabLabel.export);
		oExport.firstChild.title = "Legt die ganze Skillung als BBCode in die Zwischenablage";
		oList.appendChild(oExport);

		//What became of the export, said right beside the tabs. On a line of its own
		//it would push the whole table down as it came and up again as it went.
		oNote.id = "mm_skills_export_note";
		oNote.style.cssText = "display:inline-block;vertical-align:middle;margin-left:10px;font-size:11px;";

		oClear.style.display = "block";
		oClear.style.clear = "both";

		oTabs.appendChild(oList);
		oTabs.appendChild(oNote);
		oTabs.appendChild(oClear);

		this.oTabs = oTabs;
		this.oSkillTable.parentElement.insertBefore(oTabs, this.oSkillTable);
	}

	/**
	 * @param {string} sKey
	 * @param {string} sLabel
	 * @return {Node}
	 */
	createTabElement(sKey, sLabel) {
		let oTabElement = this.oElements.oLi.cloneNode();
		let oLinkElement = this.oElements.oA.cloneNode();

		oTabElement.className = sKey !== "all" ? "not_selected" : "selected";

		oLinkElement.href = "#";
		oLinkElement.dataset[this.oDataSets.tabs.js] = sKey;
		oLinkElement.textContent = sLabel;

		oTabElement.appendChild(oLinkElement);

		return oTabElement;
	}

	/**
	 * @param {string} sTabKey
	 */
	selectTab(sTabKey) {
		this.oTabs.querySelector(`[${this.oDataSets.tabs.css}="${sTabKey}"]`).parentElement.className = "selected";
	}

	unselectActiveTab() {
		const oSelected = this.oTabs.querySelector(".selected");
		if (oSelected) {
			oSelected.className = "not_selected";
		}
	}

	/* --- Events --------------------------------------------------------------- */

	eventListener() {
		let blIsParadesAppended = false;
		let blIsInitiativeAppended = false;

		this.oTabs.addEventListener("click", e => {
			const sTabKey = e.target.dataset ? e.target.dataset[this.oDataSets.tabs.js] : null;

			if (!sTabKey) {
				return;
			}

			e.preventDefault();

			try {
				if (sTabKey === "export") {
					skillsExportToClipboard();
					return;
				}

				this.updateRows(sTabKey);
				this.unselectActiveTab();
				this.selectTab(sTabKey);

				blIsParadesAppended = this.updateExtraTBody(sTabKey, "rt_parade", blIsParadesAppended, this.oTableBodyParades);
				blIsInitiativeAppended = this.updateExtraTBody(sTabKey, "rt_initiativ", blIsInitiativeAppended, this.oTableBodyInitiative);
			} catch (oFehler) {
				mmReportError("Fertigkeitenseite", oFehler);
			}
		});

		//Kept, so that a new build can take it off the game's table again.
		this.fnChange = e => {
			if (e.target && e.target.tagName === "SELECT") {
				try {
					this.updateThrowCell(e.target);
				} catch (oFehler) {
					mmReportError("Fertigkeitenseite", oFehler);
				}
			}
		};
		this.oSkillTable.addEventListener("change", this.fnChange);
	}

	/* --- A new build ---------------------------------------------------------- */

	activeTab() {
		const oLink = this.oTabs ? this.oTabs.querySelector(`.selected [${this.oDataSets.tabs.css}]`) : null;
		return oLink ? oLink.dataset[this.oDataSets.tabs.js] : "all";
	}

	//The items picked in the rows, by skill, in the order of their dropdowns.
	pickedItems() {
		const oGewaehlt = {};

		for (const oRow of Array.from(this.oTableBodySkills.rows || [])) {
			const sName = oRow.dataset[this.oDataSets.tabSkill.js];
			const aSelects = oRow.querySelectorAll("select");
			if (sName && aSelects.length) {
				oGewaehlt[sName] = Array.from(aSelects).map(oSelect => oSelect.value);
			}
		}
		return oGewaehlt;
	}

	//The tab and the picked items of the build before, where they are still there.
	restore(sTab, oGewaehlt) {
		for (const oRow of Array.from(this.oTableBodySkills.rows)) {
			const aWerte = oGewaehlt[oRow.dataset[this.oDataSets.tabSkill.js]];
			if (!aWerte) {
				continue;
			}
			//One at a time and looked up afresh: picking the item builds the dropdowns
			//for its ammunition anew.
			for (let i = 0; i < aWerte.length; i++) {
				const oSelect = oRow.querySelectorAll("select")[i];
				if (!oSelect) {
					break;
				}
				const blDa = Array.from(oSelect.options).some(oOption => oOption.value === aWerte[i]);
				if (blDa && oSelect.value !== aWerte[i]) {
					oSelect.value = aWerte[i];
					this.updateThrowCell(oSelect);
				}
			}
		}

		const oLink = sTab && sTab !== "all" && sTab !== "export"
			? this.oTabs.querySelector(`[${this.oDataSets.tabs.css}="${sTab}"]`) : null;
		if (oLink) {
			oLink.click();
		}
	}

	/*
	 * The table back to the game's rows and cells, for a build with other data. The
	 * rows are the game's own: whatever the player changed in them stays. The cells
	 * this build added go with the next build's first step, skillsDetailsToPlain.
	 */
	remove() {
		const oTable = this.oSkillTable;

		if (this.oTabs && this.oTabs.parentNode) {
			this.oTabs.parentNode.removeChild(this.oTabs);
		}
		if (!oTable) {
			return;
		}
		if (this.fnChange) {
			oTable.removeEventListener("change", this.fnChange);
		}

		const oBody = this.oTableBodySkills;
		for (const oExtra of Array.from(oTable.tBodies)) {
			if (oExtra !== oBody) {
				oExtra.parentNode.removeChild(oExtra);
			}
		}
		oTable.deleteTFoot();
		if (oTable.tHead) {
			if (oTable.tHead.rows.length) {
				oBody.insertBefore(oTable.tHead.rows[0], oBody.firstChild);
			}
			oTable.deleteTHead();
		}

		for (const oRow of Array.from(oBody.rows)) {
			for (const sKey of ["tabRow", "tabRowParade", "tabSkill"]) {
				delete oRow.dataset[this.oDataSets[sKey].js];
			}
			oRow.style.display = "";
		}
	}

}

/*
 * The details view, brought into the shape of the plain one. Its last column, a
 * small table of type and use for every skill, goes: the new columns say the same
 * and more. The description below each name moves into a tooltip on the row
 * number, so the rows stay one line high and the text is one hover away.
 */
function skillsDetailsToPlain(tabelle) {
	var body = tabelle && tabelle.tBodies[0];
	if (!body || !body.rows.length)
		return;

	//#, Fertigkeit, Rang and Kosten over two columns; anything behind that is the
	//description column of the details view.
	var kopf = body.rows[0];
	while (kopf.cells.length > 4)
		kopf.removeChild(kopf.cells[kopf.cells.length - 1]);

	for (var i = 1; i < body.rows.length; i++) {
		var zeile = body.rows[i];
		while (zeile.cells.length > 5)
			zeile.removeChild(zeile.cells[zeile.cells.length - 1]);

		var name = zeile.cells[1];
		var trenner = name ? name.querySelector('hr') : null;
		if (!trenner)
			continue;

		var box = document.createElement('div');
		while (trenner.nextSibling)
			box.appendChild(trenner.nextSibling);
		trenner.parentNode.removeChild(trenner);

		var text = box.innerHTML.replace(/\s+/g, ' ').trim();
		if (text) {
			skillsTipOn(zeile.cells[0], text);
			zeile.cells[0].style.cursor = 'help';
		}
	}
}

//The name of the skill a row of the game's table stands for: the text of its link,
//without the little info picture inside it.
function skillsRowName(oRow) {
	var zelle = oRow && oRow.cells ? oRow.cells[1] : null;
	if (!zelle)
		return '';
	var link = zelle.querySelector('a');
	return String((link || zelle).textContent || '').trim();
}

/////////////////////////////////////////////////////////////////////////////
/////////////// Module: the skills page, rolls and Rechenweg ////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * How the engine rolls a throw. A developer transpiled the combat script's own
 * roll function, probe(); it reproduces every one of some 14,000 logged rolls of
 * attack, parry, initiative and damage.
 *
 *   R1  The mean as the game shows it. Attack, parry and initiative:
 *       P x 2 + S + Rang x 2. Damage and healing: P / 2 + S / 3 + Rang / 2.
 *       P, S and Rang are the effective values of the data interface, plus what
 *       works on use of the skill, its item and the item's ammunition, fractions
 *       and all. Percentages on the rank on use multiply, and all of them act on
 *       the trained rank. Item bonuses on the rank, those on use included, are at
 *       most as high as the trained rank (see skillsItemBoni).
 *   R2  The mean is cut to a whole number, toward zero: the only rounding before
 *       the end.
 *   R3  The roll for that whole mean ("mittel"):
 *         0       no roll, 0
 *         1       no roll, 1
 *         2       a W5 whose 0 counts as 1: 1, 1, 2, 3, 4
 *         3 up    m = mittel - 1; n = floor(m / 7), at least 1 and at most 8;
 *                 n dice of W(2 x floor(m / n) + 1), and one W(2r + 1) for the
 *                 rest r of m / n where there is one. The roll is 1 plus their
 *                 sum: 1 to 2m + 1, on average mittel.
 *   R4  Every percentage on the throw multiplies the roll.
 *   R5  The fixed bonuses come on top, unscaled.
 *   R6  Cut toward zero once, at the very end. Below 0 counts as 0.
 *
 * Assumed, not in probe(): the final effect bonus multiplies roll and fixed part
 * alike, before the cut. probe() mirrors a negative mean; here none comes up, no
 * part is ever below 0.
 *
 * What follows from it, and what the tooltip says: one die rolls flat, every value
 * as often as the next; two or more pile up in the middle and make the lowest
 * rolls rare; a percentage leaves values out that can never come up.
 */

//A number freed of the dust floating point leaves on it, so that 2.9999999999
//is cut to 3 and not to 2.
function skillsGenau(x) {
	return Math.round(x * 1e6) / 1e6;
}

//The dice for m = mittel - 1 (R3). A W(2k+1) shows 0 to 2k.
function skillsDice(m) {
	if (!(m >= 1))
		return [];
	var anzahl = Math.max(1, Math.min(8, Math.floor(m / 7)));
	var gross = Math.floor(m / anzahl);
	var rest = m - anzahl * gross;
	var out = [{ anzahl: anzahl, seiten: 2 * gross + 1 }];
	if (rest > 0)
		out.push({ anzahl: 1, seiten: 2 * rest + 1 });
	return out;
}

//The dice as the game names them, "2W17 + W3".
function skillsDiceName(wuerfel) {
	return wuerfel.map(function (w) {
		return (w.anzahl > 1 ? w.anzahl : '') + 'W' + w.seiten;
	}).join(' + ');
}

//How often each sum of the dice comes up: the share of sum s at index s.
function skillsSummen(wuerfel) {
	var anteile = [1];
	wuerfel.forEach(function (w) {
		for (var n = 0; n < w.anzahl; n++) {
			var neu = [];
			for (var i = 0; i < anteile.length + w.seiten - 1; i++)
				neu.push(0);
			for (var d = 0; d < anteile.length; d++)
				for (var k = 0; k < w.seiten; k++)
					neu[d + k] += anteile[d] / w.seiten;
			anteile = neu;
		}
	});
	return anteile;
}

/*
 * The roll for a mean, as probe() makes it (R2, R3): the whole mean, the dice,
 * and the share of every roll, at the index of its value. Also its lowest, its
 * highest and its average.
 *
 * @return {{mittel: number, blWurf: boolean, wuerfel: Array, anteile: Array<number>,
 *     min: number, max: number, schnitt: number}}
 */
function skillsRoll(flMean) {
	var mittel = Math.max(0, Math.trunc(skillsGenau(flMean)));
	var wuerfel = [];
	var anteile;

	if (mittel === 0)
		anteile = [1];
	else if (mittel === 1)
		anteile = [0, 1];
	else if (mittel === 2) {
		//max(1, W5): the 0 counts as 1.
		wuerfel = [{ anzahl: 1, seiten: 5 }];
		anteile = [0, 0.4, 0.2, 0.2, 0.2];
	} else {
		wuerfel = skillsDice(mittel - 1);
		anteile = [0].concat(skillsSummen(wuerfel));
	}

	var schnitt = 0;
	anteile.forEach(function (a, wert) { schnitt += a * wert; });
	return { mittel: mittel, blWurf: mittel >= 2, wuerfel: wuerfel, anteile: anteile,
		min: mittel ? 1 : 0, max: anteile.length - 1, schnitt: schnitt };
}

/*
 * Every value a column of a throw can show and how often, the percentages f and
 * the fixed part fest of that column taken in, and the final effect bonus: the
 * values from min to max, the share of each (0 for one that never comes up), their
 * mean and the values that never come up.
 */
function skillsVerteilung(r, f, fest, flFinal) {
	var anteil = { };
	r.anteile.forEach(function (w, wurf) {
		if (!w)
			return;
		var wert = Math.max(0, Math.trunc(skillsGenau((wurf * f + fest) * flFinal)));
		anteil[wert] = (anteil[wert] || 0) + w;
	});

	var werte = Object.keys(anteil).map(Number);
	var min = Math.min.apply(null, werte), max = Math.max.apply(null, werte);
	var out = { min: min, max: max, anteile: [], mittel: 0, nie: [] };
	for (var v = min; v <= max; v++) {
		var a = anteil[v] || 0;
		out.anteile.push(a);
		out.mittel += v * a;
		if (!a)
			out.nie.push(v);
	}
	return out;
}

//What is rolled for the whole mean: "Würfel für 18: 2W17 + W3, + 1".
function skillsDiceText(r) {
	if (r.mittel === 0)
		return 'Kein Wurf: unter 1 ist der Wurf 0.';
	if (r.mittel === 1)
		return 'Würfel für 1: keiner, immer 1';
	if (r.mittel === 2)
		return 'Würfel für 2: W5, die 0 zählt als 1';
	return 'Würfel für ' + r.mittel + ': ' + skillsDiceName(r.wuerfel) + ', + 1';
}

//The final effect bonus as a factor. A skill without one has 1.
function skillsFinalFactor(oSkillObject) {
	var f = oSkillObject.finalEffectBonus;
	return (typeof f == 'number' && isFinite(f)) ? f : 1;
}

/*
 * The item bonuses a skill has on its rank already, as the game counts them (see
 * skillCapBuckets): reckoned from its current bonuses in the data interface, and
 * checked against the effective rank the data gives. Where that check fails, none:
 * then no ceiling is applied on use rather than a wrong one.
 */
function skillsItemBoni(sName) {
	if (!skillsData || !skillsHero)
		return null;
	var roh = skillsData.oSkillsByName[sName];
	if (!roh)
		return null;

	if (!skillsData.oItemBoniVorrat) {
		var index = Object.create(null);
		(skillsData.aSkills || []).forEach(function (s) {
			index[skillsData.translateSpecialSymbols(s.template.label)] = {
				rank: parseInt(s.base_value, 10) || 0,
				eff: Number(s.effective_value) || 0
			};
		});
		skillsData.oItemBoniVorrat = { index: index, herkunft: skillCapOriginSources(), fertig: Object.create(null) };
	}
	var vorrat = skillsData.oItemBoniVorrat;
	if (!(sName in vorrat.fertig)) {
		var rang = parseInt(roh.base_value, 10) || 0;
		var zeilen = (roh.current_bonusse || []).map(function (z) {
			return skillsData.translateSpecialSymbols(String(z)).trim();
		});
		var res = skillCapBuckets(skillCapParse(zeilen), rang, vorrat.index, skillsHero.iLevel, vorrat.herkunft,
			skillsData.translateSpecialSymbols(String(roh.template && roh.template.label || sName)));
		vorrat.fertig[sName] = (res.notes.length || res.predictedEff !== Number(roh.effective_value)) ? null
			: { itemFloored: res.itemFloored, itemApplied: res.itemApplied };
	}
	return vorrat.fertig[sName];
}

/* --- Writing numbers ----------------------------------------------------- */

//Two decimals at most, none where there are none, with a comma. 1,275 is 1,28:
//the hundredfold is freed of floating point dust before it is rounded.
function skillsZahl(x) {
	return String(Math.round(Number((x * 100).toPrecision(12))) / 100).replace('.', ',');
}

//A factor, "1,2" for +20%.
function skillsFaktor(f) {
	return String(Math.round(f * 10000) / 10000).replace('.', ',');
}

//"+20%" for 1.2.
function skillsProzent(f) {
	var p = Math.round(f * 100 - 100);
	return (p > 0 ? '+' : '') + p + '%';
}

//"+3" or "-1" for a fixed bonus standing alone.
function skillsVorzeichen(x) {
	return (x > 0 ? '+' : '') + skillsZahl(x);
}

//"+ 3" or "- 1", written after another number.
function skillsPlus(x) {
	return (x < 0 ? '- ' : '+ ') + skillsZahl(Math.abs(x));
}

//Several columns as one: "a / b / c", or just "a" where all of them say the same.
function skillsSpalten(texte) {
	for (var k = 1; k < texte.length; k++)
		if (texte[k] !== texte[0])
			return texte.join(' / ');
	return String(texte[0]);
}

//The short name of an attribute, "Sn".
function skillsKurz(sKey) {
	var liste = skillsData && skillsData.oTypes ? skillsData.oTypes.attribute_kurz : null;
	var name = liste && liste[sKey];
	return name ? skillsData.translateSpecialSymbols(name) : '?';
}

//The names of the three columns of a damage row.
var SKILLS_TREFFER = ['Treffer', 'guter Treffer', 'kritischer Treffer'];

/*
 * What is rolled and what is fixed, side by side: one row per source, its name
 * and its number in the column it belongs to.
 */
function skillsWegTabelle(reihen) {
	var zelle = function (inhalt, zahl) {
		return '<td' + (zahl ? ' align=\'right\'' : '') + ' style=\'padding:0 0 0 '
			+ (zahl ? '12px;white-space:nowrap;' : '0;') + '\'>' + inhalt + '</td>';
	};
	var html = '<table cellpadding=\'0\' cellspacing=\'0\' style=\'border:0;margin:0;'
		+ 'background:none;font-size:inherit;color:inherit;border-collapse:collapse;\'>'
		+ '<tr>' + zelle('') + zelle('<u>Variabel</u>', true) + zelle('<u>Fest</u>', true) + '</tr>';
	for (var r = 0; r < reihen.length; r++)
		html += '<tr>' + zelle(reihen[r][0]) + zelle(reihen[r][1], true) + zelle(reihen[r][2], true) + '</tr>';
	return html + '</table>';
}

/*
 * The Rechenweg of one throw, for its tooltip, in the order the engine reckons:
 *
 *   1. the formula with the hero's numbers,
 *   2. the dice, and every percentage as a factor on the roll,
 *   3. what is rolled on average and what is fixed, side by side, and the range,
 *   4. the final effect bonus, the distribution, and the result as the table
 *      shows it,
 *   5. the distribution as a list with bars, where the settings want it.
 *
 * Damage has three columns, hit, good hit and critical hit. Where all three say
 * the same, one is written.
 */
function skillsRechenweg(w) {
	var X = skillsSpalten;
	var Z = skillsZahl;
	var r = w.oRoll;
	var abschnitte = [];
	var zeilen = [];
	var k;

	//1. The formula, what the item and the use add to its parts, its sum, and the
	//whole number that is rolled.
	var p = skillsKurz(w.oPrimary.sKey), s = skillsKurz(w.oSecondary.sKey);
	zeilen.push(w.blIsEffect
		? p + ' / 2 + ' + s + ' / 3 + Rang / 2'
		: p + ' x 2 + ' + s + ' + Rang x 2');

	var teile = [[p, w.oPrimary], [s, w.oSecondary], ['Rang', w.oRank]];
	var rang = w.oRank;
	if (rang.aFaktoren && rang.aFaktoren.length) {
		//The percentages act on the trained rank; what the effective rank has beyond
		//it comes on top.
		zeilen.push('Rang: ' + Z(rang.flGeskillt) + rang.aFaktoren.map(function (f) {
			return ' x ' + skillsFaktor(f.wert) + ' (' + f.name + ')';
		}).join('') + (rang.flStart !== rang.flGeskillt
			? ' ' + skillsPlus(rang.flStart - rang.flGeskillt) + ' (Effektivrang)' : '')
			+ rang.aQuellen.map(function (q) {
				return ' ' + skillsPlus(q.wert) + ' (' + q.name + ')';
			}).join('') + ' = ' + Z(rang.flWert));
		teile.pop();
	}
	var deckelZeile = rang.oDeckel ? 'Itemboni bei Anwendung: ' + Z(rang.oDeckel.vorher) + ' ' + skillsPlus(rang.oDeckel.dazu)
		+ ' = ' + Z(rang.oDeckel.vorher + rang.oDeckel.dazu) + ', höchstens ' + Z(rang.oDeckel.grenze)
		+ ' (geskillter Rang)' : '';
	if (deckelZeile && !teile[2])
		zeilen.push(deckelZeile);
	for (k = 0; k < teile.length; k++) {
		var teil = teile[k][1];
		if (!teil.aQuellen.length)
			continue;
		zeilen.push(teile[k][0] + ': ' + Z(teil.flStart) + teil.aQuellen.map(function (q) {
			return ' ' + skillsPlus(q.wert) + ' (' + q.name + ')';
		}).join('') + ' = ' + Z(teil.flWert));
		if (k === 2 && deckelZeile)
			zeilen.push(deckelZeile);
	}

	var P = Z(w.oPrimary.flWert), S = Z(w.oSecondary.flWert), R = Z(w.oRank.flWert);
	zeilen.push('= ' + (w.blIsEffect
		? P + ' / 2 + ' + S + ' / 3 + ' + R + ' / 2 = ' + w.aTeile.map(Z).join(' + ')
		: P + ' x 2 + ' + S + ' + ' + R + ' x 2') + ' = ' + Z(w.flBase));
	if (skillsGenau(w.flBase) !== r.mittel)
		zeilen.push('abgeschnitten auf ' + r.mittel);
	abschnitte.push(zeilen.join('<br />'));

	//2. The dice, and the percentages on what they roll.
	zeilen = [skillsDiceText(r)];
	if (r.mittel > 0) {
		for (k = 0; k < w.aProzente.length; k++)
			zeilen.push(w.aProzente[k].name + ' ' + skillsProzent(w.aProzente[k].wert)
				+ ': Wurf x ' + skillsFaktor(w.aProzente[k].wert));
		if (w.blIsDamage && w.aStufen.length) {
			zeilen.push(SKILLS_TREFFER.join(' / '));
			for (k = 0; k < w.aStufen.length; k++)
				zeilen.push(w.aStufen[k].name + ' ' + X(w.aStufen[k].werte.map(skillsProzent))
					+ ': Wurf x ' + X(w.aStufen[k].werte.map(skillsFaktor)));
		}
		if (w.aProzente.length + w.aStufen.length > 1)
			zeilen.push('Zusammen: Wurf x ' + X(w.aFaktor.map(skillsFaktor)));
	}
	abschnitte.push(zeilen.join('<br />'));

	//3. What is rolled on average and the fixed bonuses beside it, then the range.
	var reihen = [['Wurf, im Mittel', X(w.aGewuerfelt.map(Z)), '']];
	for (k = 0; k < w.aFeste.length; k++)
		reihen.push([w.aFeste[k].name, '', X(w.aFeste[k].werte.map(skillsVorzeichen))]);
	//A table ends its own line, so what follows needs no break of its own.
	var html = skillsWegTabelle(reihen) + (w.aFeste.length
		? 'Zusammen: ' + X(w.aGewuerfelt.map(function (x, i) {
			return Z(x) + ' ' + skillsPlus(w.aFest[i]) + ' = ' + Z(w.aSumme[i]);
		})) : '');
	if (r.blWurf) {
		var letzte = w.aFaktor.length - 1;
		var ende = function (wert, f, fest) {
			return Z(wert) + (f !== 1 ? ' x ' + skillsFaktor(f) : '') + (fest ? ' ' + skillsPlus(fest) : '');
		};
		var spanne = 'Spanne: ' + ende(r.min, w.aFaktor[0], w.aFest[0]) + ' bis '
			+ ende(r.max, w.aFaktor[letzte], w.aFest[letzte]);
		if (w.aFaktor[0] !== 1 || w.aFaktor[letzte] !== 1 || w.aFest[0] || w.aFest[letzte])
			spanne += ' = ' + Z(w.flVon) + ' bis ' + Z(w.flBis);
		if (w.flFinal === 1)
			spanne += ' → ' + w.min + ' bis ' + w.max;
		html += (w.aFeste.length ? '<br />' : '') + spanne + (w.flVon < 0 ? ', unter 0 gilt 0' : '');
	}
	abschnitte.push(html);

	//4. The final effect bonus, the distribution, and the result as the table shows it.
	zeilen = [];
	var f = w.flFinal;
	if (f !== 1) {
		zeilen.push('Finaler Wirkbonus ' + skillsProzent(f));
		zeilen.push('Im Mittel: ' + X(w.aSumme.map(Z)) + ' x ' + skillsFaktor(f) + ' = '
			+ X(w.aSumme.map(function (x) { return Z(x * f); })));
		zeilen.push('Spanne: ' + Z(w.flVon) + ' bis ' + Z(w.flBis) + ' x ' + skillsFaktor(f)
			+ ' = ' + Z(w.flVon * f) + ' bis ' + Z(w.flBis * f) + ' → ' + w.min + ' bis ' + w.max);
	}
	zeilen.push('Verteilung: ' + skillsVerteilungText(w));
	var ergebnis = w.blIsDamage ? [w.avg, w.good, w.critical] : [w.avg];
	zeilen.push('Ergebnis: ' + ergebnis.join(' / ') + ' (' + w.min + '-' + w.max + ')');
	abschnitte.push(zeilen.join('<br />'));

	if (w.sAktionen)
		abschnitte.push(w.sAktionen.replace(/^<hr \/>/, ''));

	//5. Every value, how often, and a bar.
	if (SKILLS_CFG.histogramm && r.blWurf)
		abschnitte.push(skillsBalken(w));

	return abschnitte.join('<hr />');
}

var SKILLS_ZAHLWORT = ['kein', 'ein', 'zwei', 'drei', 'vier', 'fünf', 'sechs', 'sieben', 'acht', 'neun'];

/*
 * The distribution in words: how many dice and the shape they give, the values
 * that never come up, and the mean. "zwei Würfel, Dreieck, 24 kommt nie vor,
 * Ø 22,42".
 */
function skillsVerteilungText(w) {
	var r = w.oRoll;
	var spalten = w.aVerteilung;
	var anzahl = r.wuerfel.reduce(function (n, x) { return n + x.anzahl; }, 0);
	var teile = [];

	if (!anzahl) {
		teile.push('fest');
	} else {
		teile.push(SKILLS_ZAHLWORT[anzahl] + ' Würfel, ' + (anzahl == 1 ? 'flach' : anzahl == 2 ? 'Dreieck' : 'Glocke'));
		//One die rolls every face alike; a value that still comes up more often got
		//two faces, from the W5 of a mean of 2 or from a percentage.
		if (anzahl == 1) {
			var a = spalten[0].anteile;
			var einzeln = Math.min.apply(null, a.filter(Boolean));
			var oefter = [];
			a.forEach(function (x, i) {
				if (x > einzeln * 1.5)
					oefter.push(spalten[0].min + i);
			});
			if (oefter.length)
				teile.push(skillsListe(oefter) + ' öfter');
		}
	}

	var nie = spalten.map(function (v) { return v.nie.join(','); });
	if (nie.every(function (n) { return n === nie[0]; })) {
		if (spalten[0].nie.length)
			teile.push(skillsListe(spalten[0].nie) + (spalten[0].nie.length == 1 ? ' kommt' : ' kommen') + ' nie vor');
	} else {
		teile.push('nie: ' + skillsSpalten(spalten.map(function (v) {
			return v.nie.length ? skillsListe(v.nie) : 'keine';
		})));
	}

	teile.push('Ø ' + skillsSpalten(w.aMittel.map(skillsZahl)));
	return teile.join(', ');
}

//"24", "24 und 31", "24, 31 und 38"; past six values the rest only counted.
function skillsListe(werte) {
	if (werte.length > 6)
		return werte.slice(0, 5).join(', ') + ' und ' + (werte.length - 5) + ' weitere';
	if (werte.length == 1)
		return String(werte[0]);
	return werte.slice(0, -1).join(', ') + ' und ' + werte[werte.length - 1];
}

/*
 * The distribution as a list, one row per value from the lowest to the highest:
 * the value, how often it comes up in percent, and a bar that long beside it, four
 * pixels to the percent. A value that never comes up keeps its row, with 0 %.
 * Past SKILLS_BALKEN_ZEILEN values, neighbours share a row, so the tooltip stays on
 * the screen. Damage shows its three columns side by side where they differ.
 */
var SKILLS_BALKEN_ZEILEN = 20;

function skillsBalken(w) {
	var spalten = w.aVerteilung;
	var gleich = spalten.every(function (v) {
		return v.min === spalten[0].min && v.anteile.join() === spalten[0].anteile.join();
	});
	var zeigen = gleich ? [spalten[0]] : spalten;
	var drei = zeigen.length > 1;

	var von = Math.min.apply(null, zeigen.map(function (v) { return v.min; }));
	var bis = Math.max.apply(null, zeigen.map(function (v) { return v.max; }));
	var buendel = Math.max(1, Math.ceil((bis - von + 1) / SKILLS_BALKEN_ZEILEN));

	//Three columns side by side get half the room each.
	var proProzent = drei ? 2 : 4, hoechstens = drei ? 70 : 160;
	var neutral = 'border:0;margin:0;background:none;';
	var zelle = function (inhalt, stil) {
		return '<td style=\'' + neutral + 'padding:0 6px 0 0;white-space:nowrap;' + (stil || '') + '\'>'
			+ inhalt + '</td>';
	};

	var html = '<table cellpadding=\'0\' cellspacing=\'0\' style=\'' + neutral
		+ 'border-collapse:collapse;color:inherit;font-size:11px;line-height:12px;\'>';
	if (drei)
		html += '<tr>' + zelle('') + ['Treffer', 'gut', 'kritisch'].map(function (t) {
			return zelle(t, 'text-align:left;') + zelle('');
		}).join('') + '</tr>';

	for (var start = von; start <= bis; start += buendel) {
		var ende = Math.min(bis, start + buendel - 1);
		html += '<tr>' + zelle(start === ende ? String(start) : start + '-' + ende, 'text-align:right;');
		for (var k = 0; k < zeigen.length; k++) {
			var v = zeigen[k], anteil = 0;
			for (var wert = Math.max(start, v.min); wert <= Math.min(ende, v.max); wert++)
				anteil += v.anteile[wert - v.min];
			var prozent = anteil * 100;
			var breite = anteil ? Math.max(1, Math.min(hoechstens, Math.round(prozent * proProzent))) : 0;
			html += zelle(skillsProzentWert(prozent), 'text-align:right;')
				+ zelle('<div style=\'display:inline-block;width:' + breite + 'px;height:8px;'
					+ 'background:currentColor;opacity:0.8;\'></div>');
		}
		html += '</tr>';
	}
	return html + '</table>';
}

//A share in percent, one decimal, "3,7 %". What is there but rounds away still
//shows as there.
function skillsProzentWert(prozent) {
	if (!prozent)
		return '0 %';
	if (prozent < 0.05)
		return '&lt;0,1 %';
	return String(Math.round(prozent * 10) / 10).replace('.', ',') + ' %';
}

/*
 * The Rechenweg of a damage row a trigger adds: nothing is rolled there, only the
 * fixed damage of each source, and the final effect bonus on it.
 */
function skillsRechenwegTrigger(t) {
	var X = skillsSpalten;
	var reihen = [];
	for (var k = 0; k < t.aQuellen.length; k++)
		if (t.aQuellen[k].werte.some(function (v) { return v !== 0; }))
			reihen.push([t.aQuellen[k].name, '', X(t.aQuellen[k].werte.map(skillsVorzeichen))]);

	var abschnitte = [SKILLS_TREFFER.join(' / ') + '<br />' + skillsWegTabelle(reihen)
		+ 'Zusammen: ' + X(t.aSumme.map(skillsZahl))];
	var zeilen = [];
	if (t.flFinal !== 1) {
		zeilen.push('Finaler Wirkbonus ' + skillsProzent(t.flFinal));
		zeilen.push(X(t.aSumme.map(skillsZahl)) + ' x ' + skillsFaktor(t.flFinal) + ' = '
			+ X(t.aSumme.map(function (x) { return skillsZahl(x * t.flFinal); })));
	}
	zeilen.push('Ergebnis: ' + t.aErgebnis.map(Math.trunc).join(' / '));
	abschnitte.push(zeilen.join('<br />'));
	return abschnitte.join('<hr />');
}

/////////////////////////////////////////////////////////////////////////////
//////////////////// Module: the skills page, the export ////////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * The whole build as BBCode, in one click, straight into the clipboard: a line
 * with level, class and race, then in a spoiler the attributes, the bonus
 * overviews and one table per kind of skill, and behind it the equipment in a
 * spoiler of its own.
 *
 * Only skills with a trained rank of 1 or more go along; an untrained skill says
 * nothing about a build. The standard parries and the standard initiative go along
 * while no trained skill has taken their place: of the four parries every hero has
 * (close combat, ranged, magic, social) one drops out as soon as a trained parry
 * of that attack type is there, and the standard initiative drops out with the
 * first trained initiative skill. The other standard parries always stay.
 */

//Skills below this trained rank are left out of the export.
var SKILLS_EXPORT_MIN_RANK = 1;

//The four standard parries a trained skill replaces.
var SKILLS_EXPORT_BASE_PARRIES = ['an_nahkampf', 'an_fernkampf', 'an_zauber', 'an_sozial'];

//One table per kind of skill: its heading, the tab it is read from, the throw rows
//it keeps and its columns after name and rank.
var SKILLS_EXPORT_SECTIONS = [
	{ titel: 'Angriff', tab: 'rt_attack', ohne: 'parades', spalten: ['Würfe', 'Angriffsart', 'MP', 'Betroffene'] },
	{ titel: 'Parade', tab: 'rt_parade', nur: 'parades', spalten: ['Würfe', 'Angriffsart', 'MP'] },
	{ titel: 'Initiative', tab: 'rt_initiativ', spalten: ['Würfe', 'MP'] },
	{ titel: 'Heilung', tab: 'rt_healing', spalten: ['Würfe', 'MP', 'Betroffene'] },
	{ titel: 'Verbesserung', tab: 'rt_powerup', spalten: ['MP', 'Betroffene'] },
	{ titel: 'Herbeirufung', tab: 'rt_create_monster', spalten: ['MP'] },
	{ titel: 'Passive', tab: 'passive', spalten: [] }
];

function skillsExportToClipboard() {
	var note = document.getElementById('mm_skills_export_note');
	var text = skillsExportText();

	if (!text) {
		if (note)
			mmFlash(note, 'Es gab nichts zu exportieren.', true);
		return '';
	}

	mmCopy(text, function (wort, schlimm) {
		if (note)
			mmFlash(note, wort, schlimm);
	}, 'Skillung liegt in der Zwischenablage.');
	return text;
}

function skillsExportText() {
	if (!skillsTable || !skillsData)
		return '';

	var out = [];
	out.push(skillsExportHeader());
	out.push('Skillung[br][spoiler]');
	out.push(skillsExportAttributes());
	out.push(skillsExportBoni('mm_skills_boni_wirkung', 'Wirkung', 'Fertigkeit / Fertigkeitenklasse', 'Wirkung'));
	out.push(skillsExportBoni('mm_skills_boni_schaden', 'Schaden', 'Schadensart (Angriffsart)', 'Schaden (normal/gut/kritisch)'));
	out.push(skillsExportBoni('mm_skills_boni_schaden_z', 'Schaden (z)', 'Schadensart (Angriffsart)', 'Schaden (normal/gut/kritisch)'));
	out.push(skillsExportBoni('mm_skills_boni_ruestung', 'Rüstung', 'Schadensart (Angriffsart)', 'Rüstung (normal/gut/kritisch)'));
	out.push(skillsExportBoni('mm_skills_boni_anfaelligkeiten', 'Anfälligkeiten', 'Schadensart (Angriffsart)', 'Anfälligkeit (normal/gut/kritisch)'));
	for (var i = 0; i < SKILLS_EXPORT_SECTIONS.length; i++)
		out.push(skillsExportSection(SKILLS_EXPORT_SECTIONS[i]));
	out.push('[/spoiler]');

	if (SKILLS_CFG.exportGear) {
		var gear = skillsExportGear(skillsData.oItems && skillsData.oItems.items);
		if (gear)
			out.push('[br]Ausrüstung:[br][spoiler]' + gear + '[/spoiler]');
	}
	return out.join('');
}

/*
 * Level, class and race. The forum turns class and race into links with one and
 * the same tag, [class:...], and only knows the male form of either. Where one of
 * them is missing, only its column falls away.
 */
function skillsExportHeader() {
	var herkunft = (skillsData.oClass) || { };
	var spalten = [];
	var stufe = essentialField('stufe') || (skillsHero && skillsHero.iLevel ? String(skillsHero.iLevel) : '');
	if (stufe)
		spalten.push(['Stufe', stufe]);

	var klasse = essentialField('klasse_name') || (herkunft['class'] && herkunft['class'].label) || '';
	if (klasse)
		spalten.push(['Klasse', '[class:' + heroMaleForm(klasse) + ']']);

	var volk = essentialField('rasse_name') || (herkunft.race && herkunft.race.label) || '';
	if (volk)
		spalten.push(['Volk', '[class:' + heroMaleForm(volk) + ']']);

	if (!spalten.length)
		return '';

	var kopf = '', werte = '';
	for (var i = 0; i < spalten.length; i++) {
		kopf += '[td align=center][b]' + spalten[i][0] + '[/b][/td]';
		werte += '[td align=center]' + spalten[i][1] + '[/td]';
	}
	return '[table border=1][tr]' + kopf + '[/tr][tr]' + werte + '[/tr][/table][br]';
}

//The general values without the level, which already stands in the header, and
//the eight attributes with their effective value in gold where it differs.
function skillsExportAttributes() {
	var werte = skillsTable.oDataPowerUps.attributes || { };
	var allgemein = [['HP', 'max_hp'], ['HP-Reg', 'heil_hp'], ['MP', 'max_mp'], ['MP-Reg', 'heil_mp'],
		['Akt', 'anz_aktionen'], ['Ini-Bonus', 'ini_bonus']];
	var eigenschaften = [['St', 'at_st'], ['Ko', 'at_ko'], ['In', 'at_in'], ['Ge', 'at_ge'],
		['Ch', 'at_ch'], ['Sn', 'at_sn'], ['Wa', 'at_wa'], ['Wi', 'at_wi']];
	var zelle = function (text) { return '[td align=center]' + text + '[/td]'; };

	var out = '[h1]Eigenschaften[/h1][table border=1][tr]';
	out += allgemein.map(function (a) { return zelle(a[0]); }).join('') + '[/tr][tr]';
	out += allgemein.map(function (a) {
		return zelle(werte[a[1]] ? werte[a[1]].effective_value : '');
	}).join('') + '[/tr][/table]';

	out += '[table border=1][tr]' + eigenschaften.map(function (a) { return zelle(a[0]); }).join('') + '[/tr][tr]';
	out += eigenschaften.map(function (a) {
		var w = werte[a[1]];
		if (!w)
			return zelle('');
		var basis = String(w.base_value == null ? '' : w.base_value);
		return zelle(basis + (parseInt(basis, 10) !== w.effective_value
			? ' [color=gold][' + w.effective_value + '][/color]' : ''));
	}).join('') + '[/tr][/table]';
	return out;
}

//One of the bonus overviews above the table, as it stands there.
function skillsExportBoni(tabellenId, titel, kopfLinks, kopfRechts) {
	var tabelle = document.getElementById(tabellenId);
	if (!tabelle || !tabelle.rows.length)
		return '';

	var out = '[h1]' + titel + '[/h1][table border=1][tr][td align=center][b]' + kopfLinks
		+ '[/b][/td][td align=center][b]' + kopfRechts + '[/b][/td][/tr]';
	for (var i = 0; i < tabelle.rows.length; i++) {
		var zellen = tabelle.rows[i].cells;
		if (zellen.length < 2)
			continue;
		var klasse = zellen[0].querySelector('span');
		var links = klasse
			? String(zellen[0].firstChild ? zellen[0].firstChild.textContent : '') + '[i]' + klasse.textContent + '[/i]'
			: zellen[0].textContent;
		out += '[tr][td]' + links.trim() + '[/td][td align=center]' + zellen[1].textContent.trim() + '[/td][/tr]';
	}
	return out + '[/table]';
}

/* --- One kind of skill --------------------------------------------------- */

function skillsExportSection(abschnitt) {
	var zeilen = [];
	var tab = abschnitt.tab;
	var rows = skillsTable.oTableBodySkills.rows || [];

	for (var i = 0; i < rows.length; i++) {
		var row = rows[i];
		var gehoert = row.dataset.tabRow === tab
			|| (tab === 'rt_parade' && row.dataset.tabRowParade === 'true');
		if (!gehoert)
			continue;
		var skill = skillsTable.oSkillObjectByName[row.dataset.tabSkillName];
		if (!skill || !(skill.rankBase >= SKILLS_EXPORT_MIN_RANK))
			continue;
		zeilen.push(skillsExportRow(row, skill, abschnitt, false));
	}

	if (tab === 'rt_parade')
		zeilen = zeilen.concat(skillsExportStandard(skillsTable.oTableBodyParades, abschnitt, skillsTrainedParries()));
	if (tab === 'rt_initiativ' && !skillsTrainedInitiative())
		zeilen = zeilen.concat(skillsExportStandard(skillsTable.oTableBodyInitiative, abschnitt, { }));

	if (!zeilen.length)
		return '';

	var kopf = '[tr][td] [/td][td]Fertigkeit[/td][td]Rang[/td]' + abschnitt.spalten.map(function (s) {
		return s == 'Betroffene' ? '[td colspan=2]Betroffene[/td]' : '[td]' + s + '[/td]';
	}).join('') + '[/tr]';
	return '[h1]' + abschnitt.titel + '[/h1][table border="1"]' + kopf + zeilen.join('') + '[/table]';
}

//The standard rows of one extra table body, less those a trained skill replaces.
function skillsExportStandard(tbody, abschnitt, ersetzt) {
	var out = [];
	var rows = tbody && tbody.rows ? tbody.rows : [];
	for (var i = 0; i < rows.length; i++) {
		var art = rows[i].getAttribute('data-mm-angriffsart') || '';
		if (SKILLS_EXPORT_BASE_PARRIES.indexOf(art) > -1 && ersetzt[art])
			continue;
		out.push(skillsExportRow(rows[i], null, abschnitt, true));
	}
	return out;
}

//The attack types a trained skill parries.
function skillsTrainedParries() {
	var out = { };
	for (var name in skillsTable.oSkillObjectByName) {
		var skill = skillsTable.oSkillObjectByName[name];
		if (!(skill.rankBase >= SKILLS_EXPORT_MIN_RANK))
			continue;
		if (skill.realType === SkillsSkill.oRealTypes.parade || skill.isConfigurableParade)
			out[skill.attackType] = true;
	}
	return out;
}

function skillsTrainedInitiative() {
	for (var name in skillsTable.oSkillObjectByName) {
		var skill = skillsTable.oSkillObjectByName[name];
		if (skill.realType === SkillsSkill.oRealTypes.ini && skill.rankBase >= SKILLS_EXPORT_MIN_RANK)
			return true;
	}
	return false;
}

function skillsExportRow(row, skill, abschnitt, standard) {
	var zelle = function (text) { return '[td align=center]' + text + '[/td]'; };
	var name = standard ? skillsRowName(row) || row.cells[1].textContent.trim() : skillsRowName(row);
	var out = '[tr][td][/td][td]' + (standard ? name : '[skill=' + name + ']') + '[/td]';

	out += zelle(standard ? '0' : skillsExportRank(row));

	for (var i = 0; i < abschnitt.spalten.length; i++) {
		switch (abschnitt.spalten[i]) {
			case 'Würfe':
				out += zelle(skillsExportThrows(row, abschnitt));
				break;
			case 'Angriffsart':
				out += zelle(skillsExportCell(row, 'attackType'));
				break;
			case 'MP':
				out += zelle(skillsExportCell(row, 'manaCost'));
				break;
			case 'Betroffene':
				var ziel = skillsExportTargets(row, skill);
				out += zelle(ziel[0]) + zelle(ziel[1]);
				break;
		}
	}
	return out + '[/tr]';
}

//The trained rank, and the effective one in gold where the page shows one.
function skillsExportRank(row) {
	var rang = row.querySelector('[id^="skill_rang_"]');
	var effektiv = row.querySelector('.effective_value');
	var text = rang ? rang.textContent.replace(/\s+/g, ' ').trim() : row.cells[2].textContent.trim();
	var eff = effektiv ? effektiv.textContent.trim() : '';
	return text + (eff ? ' [color=gold]' + eff + '[/color]' : '');
}

function skillsExportCell(row, typ) {
	var zelle = row.querySelector('[data-cell-type="' + skillsTable.oCellTypeNames[typ] + '"]');
	return zelle ? zelle.textContent.replace(/\s+/g, ' ').trim() : '';
}

//The throws of a row as a small table: name, value and the range below or beside.
function skillsExportThrows(row, abschnitt) {
	var zeilen = row.querySelectorAll('[data-cell-row-type]');
	var out = '';
	for (var i = 0; i < zeilen.length; i++) {
		var typ = zeilen[i].getAttribute('data-cell-row-type');
		if ((abschnitt.nur && typ !== abschnitt.nur) || (abschnitt.ohne && typ === abschnitt.ohne))
			continue;
		var label = zeilen[i].firstChild ? zeilen[i].firstChild.textContent.trim() : '';
		var wert = zeilen[i].querySelector('[data-mm-wert]');
		var spanne = zeilen[i].querySelector('[data-mm-spanne]');
		var zahl = wert ? wert.getAttribute('data-mm-wert') : '';
		var bereich = spanne ? spanne.textContent.replace(/\s+/g, '') : '';
		if (bereich)
			zahl += (zahl.indexOf('/') > -1 ? '[br]' : ' ') + '[size=10]' + bereich + '[/size]';
		out += '[tr align=center][th]' + label + '[/th][td align=center]' + zahl + '[/td][/tr]';
	}
	return out ? '[table]' + out + '[/table]' : '';
}

//How many a skill reaches, and where: "Selbst", "Position" or "Alle".
function skillsExportTargets(row, skill) {
	var typ = skill ? skill.targetType : '';
	var anzahl = skillsExportCell(row, 'numberOfTargets').replace(/\s*auf einer Position$/, '');
	if (typ === SkillsSkill.oTargetTypes.hero)
		return ['', 'Selbst'];
	if (typ === SkillsSkill.oTargetTypes.allyPosition || typ === SkillsSkill.oTargetTypes.enemyPosition)
		return [anzahl, 'Position'];
	if (typ === SkillsSkill.oTargetTypes.allyGroup || typ === SkillsSkill.oTargetTypes.enemyGroup)
		return [anzahl, 'Alle'];
	return [anzahl, ''];
}

/* --- The equipment --------------------------------------------------------- */

/*
 * The worn items from the data interface, in the shape of the button on the
 * equipment page: head to toe, then bag, rings and medals, each piece with its
 * gems. The medals fold away behind a spoiler of their own if the switch says so.
 */
function skillsExportGear(items) {
	if (!items || !items.length)
		return '';

	var reihenfolge = [];
	var namen = { };
	for (var label in ITEM_SLOT_NAMES) {
		var platz = ITEM_SLOT_NAMES[label];
		if (reihenfolge.indexOf(platz) < 0)
			reihenfolge.push(platz);
		if (!namen[platz])
			namen[platz] = label;
	}

	var liste = items.filter(function (it) {
		return it && it.instance && reihenfolge.indexOf(it.instance.place) > -1;
	});
	liste.sort(function (a, b) {
		return reihenfolge.indexOf(a.instance.place) - reihenfolge.indexOf(b.instance.place);
	});

	var gruppen = { };
	for (var i = 0; i < liste.length; i++) {
		var ort = liste[i].instance.place;
		var name = String(liste[i].template.name || '').trim();
		if (!name)
			continue;
		var bezeichnung = (ort == 'go_waffen_hand' && liste[i].template.trage_typ == 'tr_beide_haende')
			? 'Beide Hände' : namen[ort];
		var steine = (liste[i].instance.gem_icon_list || []).map(function (g) {
			var alt = /alt=['"]([^'"]*)['"]/.exec(String(g && g.icon || ''));
			return alt ? (GEAR_GEM_CODES[alt[1]] || '') : '';
		}).join('');
		var schluessel = GEAR_EXPORT_GROUPS.some(function (g) { return g.key === ort; }) ? ort : '';
		(gruppen[schluessel] || (gruppen[schluessel] = []))
			.push('[tr][td]' + bezeichnung + '[/td][td][item:' + name + '] ' + steine + '[/td][/tr]');
	}

	var out = [];
	for (var b = 0; b < GEAR_EXPORT_GROUPS.length; b++) {
		var block = GEAR_EXPORT_GROUPS[b];
		var zeilen = gruppen[block.key];
		if (!zeilen || !zeilen.length)
			continue;
		var tabelle = '[table border=1]' + zeilen.join('') + '[/table]';
		out.push((block.spoiler && FEATURES.gearOrdenSpoiler === true)
			? '[spoiler title="' + block.spoiler + '"]' + tabelle + '[/spoiler]'
			: tabelle);
	}
	return out.join('[br]');
}

/////////////////////////////////////////////////////////////////////////////
/////////////// Module: the skills page, for the item compare ///////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * What the data interface says about the worn pieces, handed to the item compare:
 * which piece sits where, as the equipment page would say it, and what each one
 * grants its owner, in the shape the item page is read into. So the compare knows
 * the worn pieces without a visit to the equipment page or to a single item page.
 *
 * An item page stays the better source: a name already known from its page keeps
 * what the page said. Only names no page has taught yet are filled in from here,
 * and those are marked so that the first visit of their page replaces them quietly.
 *
 * The data is told piece by piece, and it marks what a gem has added. So a worn
 * piece with gems is kept under its own number with all it grants, and under the
 * name goes only what every piece of that name has (see "The cache").
 */

//Which kind of bonus goes into which section of the item page.
var SKILLS_ITEM_SECTIONS = {
	pt_angriff: 'Angriffe',
	pt_parade: 'Paraden',
	pt_attribut: 'Eigenschaften',
	pt_schaden: 'Schaden',
	pt_schadens_faktor: 'Anfälligkeit',
	pt_ruestung: 'Rüstung',
	pt_talent: 'Fertigkeitsrang',
	pt_wirkung: 'Wirkung'
};
var SKILLS_ITEM_TRIPLES = ['pt_schaden', 'pt_ruestung', 'pt_schadens_faktor'];
var SKILLS_ITEM_LEVELS = { et_erfolg: 0, et_gut: 1, et_kritisch: 2 };

//Text with markup, as plain text.
function skillsPlain(html) {
	if (html === null || html === undefined)
		return '';
	var box = document.createElement('div');
	box.innerHTML = String(html);
	return box.textContent.trim();
}

//A code from the game's name lists, as the name the page prints.
function skillsTypeName(liste, code) {
	var tabelle = skillsData && skillsData.oTypes ? skillsData.oTypes[liste] : null;
	return tabelle && code ? skillsPlain(tabelle[code] || '') : '';
}

//What a bonus works on, by the name the item page gives it.
function skillsItemBonusOn(pu) {
	var angriff = skillsPlain(pu.label_angriffs_typ) || skillsTypeName('angriffs_typ', pu.angriffs_typ);
	switch (pu.typ) {
		case 'pt_angriff':
		case 'pt_parade':
			return angriff;
		case 'pt_attribut':
			return skillsPlain(pu.label_attribut) || skillsTypeName('attribute', pu.attribut)
				|| skillsTypeName('attribute_versteckt', pu.attribut);
		case 'pt_schaden':
		case 'pt_ruestung':
		case 'pt_schadens_faktor':
			var schaden = skillsPlain(pu.label_schadens_typ) || skillsTypeName('schadens_typ', pu.schadens_typ);
			return schaden && angriff ? schaden + ' (' + angriff + ')' : schaden;
		case 'pt_talent':
		case 'pt_wirkung':
			var talent = skillsPlain(pu.label_talent);
			if (!talent && pu.talent && String(pu.talent) !== '0') {
				var oSkill = skillsData && skillsData.oSkillsById[pu.talent];
				talent = oSkill ? oSkill.template.label : '';
			}
			if (talent)
				return talent;
			var klasse = skillsPlain(pu.label_talent_klasse);
			if (!klasse && pu.talent_klasse && String(pu.talent_klasse) !== '0') {
				var oKlasse = skillsData && skillsData.oSkillClasses[pu.talent_klasse];
				klasse = oKlasse ? oKlasse.name : '';
			}
			//The item page writes a whole class in italics in the effect table only.
			return klasse ? (pu.typ === 'pt_wirkung' ? '<i>' + klasse + '</i>' : klasse) : '';
	}
	return '';
}

/*
 * The data interface prints a value the way the item page does, colour and all:
 * <span class="gem_bonus_only_by_gem">+2</span> is a bonus the piece has through a
 * gem alone. ohneVeredelung puts a nought in its place.
 */
var SKILLS_GEM_ONLY = /<span class=["'][^"']*_only_by_gem[^"']*["']>[\s\S]*?<\/span>/g;

function skillsBonusText(pu, ohneVeredelung) {
	var roh = String(pu.bonus_wert == null ? '' : pu.bonus_wert);
	return skillsPlain(ohneVeredelung ? roh.replace(SKILLS_GEM_ONLY, '0') : roh);
}

//What the gems have done to the bonuses of a piece, in the words of
//itemPageGemMarks: 'keine', 'nur' or 'auch'.
function skillsItemGemMarks(powerups) {
	var text = JSON.stringify(powerups || { });
	if (text.indexOf('_also_by_gem') > -1)
		return 'auch';
	return text.indexOf('_only_by_gem') > -1 ? 'nur' : 'keine';
}

//The value of one bonus: a typed number, or the text the page prints.
function skillsItemBonusValue(pu, ohneVeredelung) {
	if (pu.bonus_typ && wertIstZahl(pu.bonus_wert))
		return wertAusTyp(pu.bonus_typ, pu.bonus_wert);
	return wertAusText(skillsBonusText(pu, ohneVeredelung));
}

/*
 * Damage, armour and Anfälligkeit carry three values, "a / b / c". A single value
 * with a success level counts from that level on: damage upwards, armour and
 * Anfälligkeit downwards. Without a level it counts on all three.
 */
function skillsItemTriple(pu, ohneVeredelung) {
	if (!(pu.bonus_typ && wertIstZahl(pu.bonus_wert))) {
		var drei = wertDreiAusText(skillsBonusText(pu, ohneVeredelung));
		if (drei)
			return drei;
	}
	var wert = skillsItemBonusValue(pu, ohneVeredelung);
	var stufe = SKILLS_ITEM_LEVELS[pu.erfolgs_typ];
	return [0, 1, 2].map(function (k) {
		if (stufe === undefined)
			return wert;
		return (pu.typ === 'pt_schaden' ? k >= stufe : k <= stufe) ? wert : { };
	});
}

//What a piece grants its owner at all times, section by section. What counts only
//on use or for some rounds is left out, as the item page reading leaves it out.
//ohneVeredelung: without what only a gem has given it.
function skillsItemBonuses(powerups, ohneVeredelung) {
	var besitzer = { };
	var anwendung = { };
	var gruppen = Object.values(powerups || { });
	for (var g = 0; g < gruppen.length; g++) {
		var liste = Array.isArray(gruppen[g]) ? gruppen[g] : [gruppen[g]];
		for (var i = 0; i < liste.length; i++) {
			var pu = liste[i];
			var abschnitt = pu && SKILLS_ITEM_SECTIONS[pu.typ];
			if (!abschnitt)
				continue;
			if (String(pu.runden_anzahl || '') !== '' || String(pu.runden_verz || '') !== '')
				continue;
			//What works only on use is the item page's (a), and kept apart the same way.
			var ziel = (pu.wirkungs_art === 'wirkt_bei_anwendung') ? anwendung : besitzer;
			var worauf = skillsItemBonusOn(pu);
			var wert = SKILLS_ITEM_TRIPLES.indexOf(pu.typ) > -1
				? skillsItemTriple(pu, ohneVeredelung) : skillsItemBonusValue(pu, ohneVeredelung);
			if (!worauf || wertLeer(wert))
				continue;
			//"erhöht bestehenden": the item page marks that (z).
			if (pu.schadens_wirkungs_art === 'sw_erhoehen')
				worauf += ' (z)';
			if (!ziel[abschnitt])
				ziel[abschnitt] = { };
			ziel[abschnitt][worauf] = ziel[abschnitt][worauf]
				? wertPlus(ziel[abschnitt][worauf], wert) : wert;
		}
	}
	return { Besitzer: besitzer, Anwendung: anwendung };
}

//Where a piece can go, from the game's wearing place: tr_kopf goes into go_kopf.
//The hands go by the names this world's equipment page taught.
function skillsItemPlaces(trageTyp, labels) {
	var waffe = labels['Waffenhand'] || 'go_waffen_hand';
	var schild = labels['Schildhand'] || 'go_schild_hand';
	switch (trageTyp) {
		case 'tr_none':
		case '':
		case undefined:
		case null:
			return [];
		case 'tr_einhaendig':
			return [waffe, schild];
		case 'tr_waffen_hand':
			return [waffe];
		case 'tr_schild_hand':
			return [schild];
		case 'tr_beide_haende':
			return [labels['Beide Hände'] || 'go_beide_haende'];
	}
	return [String(trageTyp).replace(/^tr_/, 'go_')];
}

/*
 * The worn pieces into the equipment store, in the form the equipment page leaves
 * there, and their bonuses into the compare's store where no item page is known.
 * A piece with a limited number of uses is kept by its name, as the equipment page
 * keeps it; anything else by its instance.
 */
function skillsFeedItemCompare(items) {
	if (!FEATURES.itemCompare || !world || !id || !items)
		return;

	var labels = loadWorldSlotLabels();
	var orte = { go_beide_haende: true };
	for (var label in ITEM_SLOT_NAMES)
		orte[ITEM_SLOT_NAMES[label]] = true;

	var slots = { }, names = { }, fits = { };
	for (var i = 0; i < items.length; i++) {
		var it = items[i];
		var ort = it && it.instance ? it.instance.place : '';
		var name = it && it.template ? itemNamePlain(it.template.name) : '';
		if (!orte[ort] || !name)
			continue;

		var begrenzt = it.template.anw_gesamt !== null && it.template.anw_gesamt !== undefined
			&& it.template.anw_gesamt !== '';
		var key = begrenzt ? name : String(it.instance_id);
		(slots[ort] || (slots[ort] = [])).push(key);
		names[key] = name;
		var passt = skillsItemPlaces(it.template.trage_typ, labels);
		if (passt.length)
			fits[key] = passt;

		//The piece itself, where a gem makes it more than its name.
		var veredelt = skillsItemGemMarks(it.instance.owner_powerups);
		if (!begrenzt && veredelt !== 'keine')
			itemPeekInstancePut(it.instance_id, { name: name, slots: passt,
				bonusData: skillsItemBonuses(it.instance.owner_powerups, false),
				veredelt: veredelt, src: 'daten' });
		else if (!begrenzt)
			itemPeekInstanceDrop(it.instance_id);

		//The name: what the piece grants without its gems.
		var ohne = skillsItemBonuses(it.instance.owner_powerups, true);
		var bekannt = itemPeekCacheGet(name);
		if (!bekannt || (bekannt.src === 'daten' && !(veredelt === 'auch' && !bekannt.unsicher))) {
			var eintrag = { name: name, slots: passt, bonusData: ohne, src: 'daten' };
			if (veredelt === 'auch')
				eintrag.unsicher = 1;
			itemPeekCachePut(name, eintrag);
		} else if (veredelt === 'nur' && bekannt.src !== 'daten' && bekannt.lese !== ITEM_PAGE_READER
				&& bekannt.bonusData) {
			//An entry read from a page before gems were told apart may hold this very
			//piece with its gems. The data knows it without them.
			bekannt.bonusData.Besitzer = ohne.Besitzer;
			bekannt.bonusData.Anwendung = ohne.Anwendung;
			bekannt.lese = ITEM_PAGE_READER;
			itemPeekCachePut(name, bekannt);
		}
	}

	saveEquipmentSlotsIntoStorage(slots, { }, fits, names);
}

/////////////////////////////////////////////////////////////////////////////
///////////////////// Module: comparing items on hover //////////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * The game shows an item's bonuses only on the item's own page. Standing in
 * front of a find in the storage, on the market or in the dungeon, you have to
 * open it first and then remember by hand what the piece worn in the same place
 * can do. This module takes that off your hands: let the mouse rest briefly on
 * an item link and the bonuses remembered from its page are put next to the
 * pieces worn in the same slot.
 *
 * What it does NOT do: recalculate. What gets compared are the raw bonuses as
 * they stand on the item page. The ceiling on item bonuses, set bonuses and the
 * effect on individual throws are left out. A "+3" here therefore means "+3
 * according to the item page", not "+3 effective rank".
 *
 * Where the knowledge comes from:
 *  - The compare itself never asks the server. The rules of this game allow a
 *    script to do as it likes with a page that is already open, and forbid it to
 *    ask the server for one by itself. So this module only reads what the player
 *    has opened.
 *  - Every item page the player calls up is read once and remembered, per world.
 *    From then on, hovering that item anywhere shows the comparison at no cost.
 *  - An item nobody has opened yet shows nothing. That is the price of asking
 *    nothing, and it is the right way round.
 *  - The store belongs to the world, not to the hero: what one hero looked at is
 *    there for the next one.
 *  - Where the skills page is rebuilt, the data it fetches for itself also names
 *    the worn pieces and what they grant (see "Module: the skills page, for the
 *    item compare").
 */

/* --- State -------------------------------------------------------------- */

var itemPeekCurrentId = '';
var itemPeekPanel = null;

/* --- The cache ---------------------------------------------------------- */

/*
 * The store is kept by NAME and by nothing else, and it belongs to no world.
 *
 * An instance number names one single piece out of a thousand of the same kind,
 * and since nothing is ever fetched, every one of those thousand would have to be
 * opened by hand before it said anything. Under the name, opening one "Fackel"
 * teaches the script what every Fackel does, in every world.
 *
 * Two pieces of the same name can differ after a world reset, and then the
 * comparison shows what was stored last. That is accepted deliberately, and the
 * tab says so.
 *
 * A gem is another matter: it makes one piece differ from its thousand namesakes
 * for good, and some pieces grant nothing at all without one. So the name holds
 * what a piece grants WITHOUT its gems, and a piece with gems is kept a second
 * time under its own instance number, with everything it grants. That store
 * belongs to the world, because the number does. It is filled from the two
 * places that show a single piece: its own item page, and the data of the skills
 * page for what the hero carries. Whoever asks for a piece looks under its number
 * first and under its name second.
 *
 * Where a gem has changed a bonus the piece had anyway, the page shows the
 * changed value alone. The entry under the name is then marked unsicher: it gives
 * way to any reading of a piece without that, and never replaces one.
 */
function itemPeekKey(name) {
	return 'mm_peek_' + String(name == null ? '' : name).trim();
}

function itemPeekCacheGet(name) {
	try {
		var raw = GM_getValue(itemPeekKey(name), false);
		if (!raw)
			return false;
		var cached = JSON.parse(raw);
		if (cached && cached.v === ITEM_PEEK_CACHE_VERSION)
			return cached;
		if (cached && cached.v === 2)
			return itemPeekFromVersion2(cached);
		//Anything older may carry place keys that were never the game's own. Those
		//entries are thrown away rather than puzzled over.
	} catch (e) {
		//unreadable - then it counts as unknown and is written again on the next visit
	}
	return false;
}

/*
 * Version 2 kept every value as a short text, "+4 +10%HS" or "+1/+1/0", and a
 * whole class of skills under the page's own words. Those entries were learned by
 * hand, one opened page at a time, so they are carried over and not dropped. The
 * result has the shape reading the page now gives, so opening it again normally
 * counts as nothing new.
 */
function itemPeekFromVersion2(alt) {
	var besitzer = { };
	var quelle = (alt.bonusData && alt.bonusData['Besitzer']) || { };

	for (var abschnitt in quelle) {
		var dreifach = ITEM_PAGE_TRIPLES.indexOf(abschnitt) > -1;
		for (var worauf in quelle[abschnitt]) {
			var wert = itemPeekWertAusKurz(quelle[abschnitt][worauf], dreifach);
			if (wertLeer(wert))
				continue;
			if (!besitzer[abschnitt])
				besitzer[abschnitt] = { };
			besitzer[abschnitt][itemPageClassName(worauf, abschnitt)] = wert;
		}
	}

	return { name: alt.name, slots: alt.slots || [], bonusData: { Besitzer: besitzer },
		v: ITEM_PEEK_CACHE_VERSION };
}

//"+4 +10%HS" as a value, and "+1/+1/0" as three.
function itemPeekWertAusKurz(text, dreifach) {
	var roh = String(text == null ? '' : text);
	var teile = roh.split('/');

	if (dreifach) {
		var drei = [];
		for (var k = 0; k < DAMAGE_LEVELS.length; k++)
			drei.push(itemPeekWertAusKurz(teile.length === DAMAGE_LEVELS.length ? teile[k] : roh, false));
		return drei;
	}

	var out = { };
	var stuecke = roh.trim().split(/\s+/);
	for (var i = 0; i < stuecke.length; i++) {
		var teil = stuecke[i].match(/^([+-]?\d+(?:\.\d+)?)(%HS|HS|%FR|FR|%)?$/);
		var zahl = teil ? parseFloat(teil[1]) : 0;
		if (!zahl)
			continue;
		var stueck = { };
		if (/HS/.test(teil[2] || ''))
			stueck.hs = zahl;
		else if (/FR/.test(teil[2] || ''))
			stueck.fr = zahl;
		else if (teil[2] === '%')
			stueck.p = wertRund(1 + zahl / 100);
		else
			stueck.f = zahl;
		out = wertPlus(out, stueck);
	}
	return out;
}

/*
 * Put an entry away and say what happened: nothing, a new name, or a name that
 * now means something else. Only the bonuses and the places are weighed for that;
 * the name is the key and cannot differ.
 */
function itemPeekCachePut(name, entry) {
	entry.v = ITEM_PEEK_CACHE_VERSION;

	var vorher = itemPeekCacheGet(name);
	var neu = JSON.stringify(entry);
	var art = 'gleich';

	if (!vorher)
		art = 'neu';
	else if (JSON.stringify(vorher) !== neu)
		art = 'geaendert';

	//An entry of the older version is written anew even where nothing changed.
	if (GM_getValue(itemPeekKey(name), '') !== neu)
		GM_setValue(itemPeekKey(name), neu);
	return art;
}

function itemPeekInstanceKey(nr) {
	return world + '_peek_i_' + String(nr == null ? '' : nr).trim();
}

//A piece with gems, by its number. None where the number is none, or where the
//piece is known by its name alone.
function itemPeekInstanceGet(nr) {
	if (!world || !/^\d+$/.test(String(nr == null ? '' : nr)))
		return false;
	var cached = mmParseStored(GM_getValue(itemPeekInstanceKey(nr), ''), null);
	return (cached && cached.v === ITEM_PEEK_CACHE_VERSION && cached.bonusData) ? cached : false;
}

function itemPeekInstancePut(nr, entry) {
	if (!world || !/^\d+$/.test(String(nr == null ? '' : nr)))
		return false;
	entry.v = ITEM_PEEK_CACHE_VERSION;
	var neu = JSON.stringify(entry);
	if (GM_getValue(itemPeekInstanceKey(nr), '') !== neu)
		GM_setValue(itemPeekInstanceKey(nr), neu);
	return true;
}

//A piece that has no gems, or no longer has them, is its name and nothing more.
function itemPeekInstanceDrop(nr) {
	if (!world || !/^\d+$/.test(String(nr == null ? '' : nr)))
		return false;
	if (GM_getValue(itemPeekInstanceKey(nr), '') === '')
		return false;
	GM_deleteValue(itemPeekInstanceKey(nr));
	return true;
}

/* --- Reading the item page ----------------------------------------------- */

//Which slots come into question for this item? First the select list "Sende diesen
//Gegenstand an", which names the slot machine-readably
//(<option value="go_ohren">Ausruesten (Ohren)</option>). Otherwise the row "Wo
//getragen?", whose text is matched against the labels learned on the equipment
//page.
/* --- The hands ------------------------------------------------------------
 * Every other slot is unambiguous: a ring goes on a ring finger, a helmet on the
 * head. The hands are not. A piece can be marked Waffenhand, Schildhand,
 * Einhändig - fits either hand - or Beide Hände. What is WORN, on the other hand,
 * always sits in a concrete slot. So the possible slots of the hovered piece are
 * widened to everything it would actually displace:
 *
 *   Waffenhand   -> Waffenhand and whatever occupies both hands
 *   Schildhand   -> Schildhand and whatever occupies both hands
 *   Einhändig    -> both hands (the game offers both in its select) and Beide Hände
 *   Beide Hände  -> both hands and Beide Hände, because it displaces all of them
 * ------------------------------------------------------------------------- */
//The four words the item page prints under "Wo getragen?" for the hands. Only the
//WORDS are named here - never a slot key. Which key belongs to "Waffenhand" is
//learned from the equipment page, because the game spells it go_waffen_hand while
//the item page's own select says go_waffenhand, and inventing either spelling
//would leave the comparison silently finding nothing at all.
var ITEM_HAND_LABELS = ['Waffenhand', 'Schildhand', 'Beide Hände'];

//"Einhändig" is no place of its own: it means whichever hand is free.
var ITEM_HAND_ALIASES = {
	'einhändig':    ['Waffenhand', 'Schildhand'],
	'einhaendig':   ['Waffenhand', 'Schildhand'],
	'zweihändig':   ['Beide Hände'],
	'zweihaendig':  ['Beide Hände'],
	'beide hände':  ['Beide Hände'],
	'beide haende': ['Beide Hände']
};

//The slot keys of the hands, as this world's equipment page calls them.
function itemPeekHandSlots(labels) {
	var out = [];
	for (var i = 0; i < ITEM_HAND_LABELS.length; i++) {
		var key = labels[ITEM_HAND_LABELS[i]];
		if (key && out.indexOf(key) < 0)
			out.push(key);
	}
	return out;
}

//The item page and the equipment page do not always spell a place the same way -
//go_waffenhand here, go_waffen_hand there. Where the equipment page has taught us
//the canonical key, the other spelling is folded onto it. Matched on the game's
//own wording, never on a key made up here.
function itemPeekNormalizeSlot(key, labels) {
	for (var label in labels)
		if (labels[label] === key)
			return key;

	var flat = String(key).toLowerCase().replace(/[^a-zäöü]/g, '');
	if (flat.indexOf('waffenhand') >= 0) return labels['Waffenhand'] || key;
	if (flat.indexOf('schildhand') >= 0) return labels['Schildhand'] || key;
	if (flat.indexOf('beidehaende') >= 0 || flat.indexOf('beidehände') >= 0)
		return labels['Beide Hände'] || key;
	return key;
}

/* --- What would have to give way? -----------------------------------------
 * Outside the hands this is trivial: a ring competes with the rings. The hands
 * are the exception, because a place and a piece are not the same thing:
 *
 *   Waffenhand   the piece fits the weapon hand only
 *   Schildhand   the shield hand only
 *   Einhändig    either hand - so it can be shuffled from one to the other
 *   Beide Hände  takes both, and therefore displaces everything
 *
 * Which hands a WORN piece accepts is not guessed: gearReadSlotFits() read it off
 * the game's own select lists. So the rule is simply: the find competes with a
 * worn piece if that piece could vacate a hand the find is able to take.
 *
 * That is what makes the awkward case come out right - two one-handers worn and a
 * weapon-hand-only find: the piece in the SHIELD hand is one-handed too, so it can
 * move over, and both are therefore up for replacement.
 * ------------------------------------------------------------------------- */
function itemPeekWornToCompare(itemSlots, equipment) {
	var hands = itemPeekHandSlots(equipment.labels);
	var twoHanded = equipment.labels['Beide Hände'];
	var wornIds = [];

	function take(list) {
		for (var i = 0; list && i < list.length; i++)
			if (wornIds.indexOf(list[i]) < 0)
				wornIds.push(list[i]);
	}

	//Which hands could the find itself occupy?
	var takes = [];
	var needsBothHands = false;
	for (var i = 0; i < itemSlots.length; i++) {
		if (hands.indexOf(itemSlots[i]) < 0) {
			//An ordinary place - whatever sits there is the comparison.
			take(equipment.slots[itemSlots[i]]);
			continue;
		}
		if (twoHanded && itemSlots[i] === twoHanded)
			needsBothHands = true;
		else
			takes.push(itemSlots[i]);
	}

	if (!takes.length && !needsBothHands)
		return wornIds;

	for (var h = 0; h < hands.length; h++) {
		var here = equipment.slots[hands[h]] || [];
		for (var w = 0; w < here.length; w++) {
			var instance = here[w];

			//A two-hander blocks both hands, so anything wanting a hand displaces it -
			//and a two-handed find displaces everything in the hands.
			if ((twoHanded && hands[h] === twoHanded) || needsBothHands) {
				take([instance]);
				continue;
			}

			//Otherwise: can this piece move out of a hand the find wants?
			var fits = equipment.fits[instance];
			if (!fits || !fits.length)
				fits = [hands[h]];          //nothing learned yet - the place it sits in
			for (var f = 0; f < fits.length; f++)
				if (takes.indexOf(fits[f]) >= 0) {
					take([instance]);
					break;
				}
		}
	}
	return wornIds;
}

function itemPeekSlots(doc, labels) {
	var found = [];

	var options = doc.querySelectorAll('select[name="send_to"] option[value^="go_"]');
	for (var i = 0; i < options.length; i++) {
		var value = options[i].getAttribute('value');
		var text = (options[i].textContent || '').trim();
		if (text.indexOf('Ausr') === 0 && found.indexOf(value) < 0)
			found.push(value);
	}
	if (found.length > 0) {
		for (var n = 0; n < found.length; n++)
			found[n] = itemPeekNormalizeSlot(found[n], labels);
		return found;
	}

	var cells = doc.querySelectorAll('div#details table.content_table td:first-child');
	for (var j = 0; j < cells.length; j++) {
		var caption = (cells[j].textContent || '').trim();
		if (caption != 'Wo getragen?')
			continue;
		var valueCell = cells[j].parentNode.querySelector('td:nth-child(2)');
		if (!valueCell)
			continue;
		//"Ring / Ring" or "Einhaendig" - each part is looked up separately.
		var parts = (valueCell.textContent || '').split('/');
		for (var k = 0; k < parts.length; k++) {
			var name = parts[k].trim();
			if (labels[name] && found.indexOf(labels[name]) < 0) {
				found.push(labels[name]);
				continue;
			}
			//"Einhändig" is no place on the equipment page, so it was never learned
			//there. It is resolved into the places it stands for, and those ARE
			//learned - no key is guessed at.
			var alias = ITEM_HAND_ALIASES[name.toLowerCase()];
			for (var h = 0; alias && h < alias.length; h++) {
				var key = labels[alias[h]];
				if (key && found.indexOf(key) < 0)
					found.push(key);
			}
		}
	}
	return found;
}

function itemPeekName(doc) {
	var anchor = doc.querySelector('form a[class*="item_"]');
	if (anchor)
		return itemNamePlain(anchor.innerHTML.split('<')[0]);
	var field = doc.querySelector("form input[name='name']");
	return field ? itemNamePlain(field.value) : '';
}

//Which reading of the item page an entry comes from. Raised whenever the page is
//read differently: an entry of an older reading differs from a new one without
//the item having changed, and that is no news worth a note.
var ITEM_PAGE_READER = 4;

//The entry for the name: the piece on the page without what only a gem gave it.
function itemPeekParse(doc, labels) {
	return {
		name: itemPeekName(doc),
		slots: itemPeekSlots(doc, labels),
		bonusData: itemPageReadBonuses(doc, true),
		wer: itemPageWho(doc),
		lese: ITEM_PAGE_READER
	};
}

//The number of the piece the page shows. A page called up by name shows no single
//piece and has none.
function itemPeekPageInstance(doc) {
	var feld = doc.querySelector('form input[name="id"]');
	var nr = feld ? String(feld.value || '').trim() : '';
	if (!/^\d+$/.test(nr)) {
		var adresse = String(window.location.search || '').match(/[?&](?:item_instance_id|id)=(\d+)/);
		nr = adresse ? adresse[1] : '';
	}
	return /^\d+$/.test(nr) ? nr : '';
}

/*
 * Who may wear the piece at all. The details name the classes and the races,
 * "ausschließlich für" a list, "nicht für" a list, or "für alle". Kept by the item
 * and not by the hero who happened to open it: the next hero asks the same
 * question with another class. Levels and attributes are not asked here - what a
 * hero can wear later is exactly what is worth comparing now.
 */
function itemPageWho(doc) {
	var out = { klassen: null, voelker: null };
	var zeilen = doc.querySelectorAll('#details tr');
	for (var i = 0; i < zeilen.length; i++) {
		var zellen = zeilen[i].cells;
		if (!zellen || zellen.length < 2)
			continue;
		var was = taktikClean(zellen[0].textContent);
		if (was === 'Heldenklassen')
			out.klassen = itemPageRestriction(zellen[1]);
		else if (was === 'Völker')
			out.voelker = itemPageRestriction(zellen[1]);
	}
	return out;
}

//{ art: 'nur' | 'nicht', namen: [...] }, or nothing where all may. The names in
//their male form, which is the one the lists use.
function itemPageRestriction(zelle) {
	var eintraege = zelle.querySelectorAll('li');
	var namen = [];
	for (var i = 0; i < eintraege.length; i++) {
		var name = heroMaleForm(taktikClean(eintraege[i].textContent));
		if (name && namen.indexOf(name) < 0)
			namen.push(name);
	}
	if (!namen.length)
		return null;

	var vorweg = zelle.cloneNode(true);
	var listen = vorweg.querySelectorAll('ul, ol');
	for (var k = 0; k < listen.length; k++)
		listen[k].parentNode.removeChild(listen[k]);
	return { art: /nicht/i.test(vorweg.textContent) ? 'nicht' : 'nur', namen: namen };
}

/* --- Turning bonuses into rows -------------------------------------------- */

//{ Besitzer: { Eigenschaften: { Wahrnehmung: {f: 2} } } } becomes one row per
//bonus, with the value written short and, where it is a plain number, as that
//number. What applies while the piece is worn is under Besitzer; what applies only
//while it is used, under Anwendung.
function itemPeekRows(bonusData, teil) {
	var rows = [];
	var section = bonusData ? bonusData[teil || 'Besitzer'] : null;
	if (!section)
		return rows;

	for (var category in section)
		for (var target in section[category])
			rows.push({
				category: category,
				target: String(target).replace(/<[^>]*>/g, ''),
				value: wertKurz(section[category][target]),
				wert: section[category][target],
				zahl: itemPeekNumeric(section[category][target])
			});
	return rows;
}

//Only plain numbers can be set against each other. "+34%FR" depends on the skill
//rank, a percentage on the throw it goes into; both are shown but not judged.
function itemPeekNumeric(wert) {
	if (!wert || Array.isArray(wert) || wert.hs || wert.fr || wertFaktor(wert) !== 1)
		return null;
	return wert.f || 0;
}

/* --- The display -------------------------------------------------------- */

function itemPeekEnsurePanel() {
	if (itemPeekPanel && itemPeekPanel.parentNode)
		return itemPeekPanel;

	itemPeekPanel = document.createElement('div');
	itemPeekPanel.id = 'mm_peek';
	itemPeekPanel.style.cssText =
		'position:fixed;z-index:99999;display:none;max-width:640px;max-height:70vh;'
		+ 'overflow:auto;border:1px solid #a89464;background:#1c1c14;color:#d4c07b;'
		+ 'font-size:11px;padding:5px 7px;box-shadow:0 2px 8px rgba(0,0,0,.6);'
		//Deliberately clickable: a long list of rings scrolls, and with
		//pointer-events:none the pointer would go straight through the panel - the
		//wheel would not scroll it, and moving towards it would count as leaving
		//the link.
		+ 'pointer-events:auto;line-height:1.45';

	//Over the panel it stays; leaving it closes it after the same short grace.
	itemPeekPanel.addEventListener('mouseover', itemPeekKeepOpen, true);
	itemPeekPanel.addEventListener('mouseout', function (event) {
		if (event && event.relatedTarget && itemPeekPanel.contains(event.relatedTarget))
			return;
		itemPeekScheduleHide();
	}, true);

	document.body.appendChild(itemPeekPanel);
	return itemPeekPanel;
}

function itemPeekPlace(mouseX, mouseY) {
	var panel = itemPeekEnsurePanel();
	panel.style.display = 'block';
	//Show first, then measure, otherwise the size is unknown.
	var width = panel.offsetWidth;
	var height = panel.offsetHeight;
	var left = mouseX + 16;
	var top = mouseY + 16;
	if (left + width > window.innerWidth - 8)
		left = Math.max(8, mouseX - width - 16);
	if (top + height > window.innerHeight - 8)
		top = Math.max(8, window.innerHeight - height - 8);
	panel.style.left = left + 'px';
	panel.style.top = top + 'px';
}

//The gap between leaving the link and the panel closing. Long enough to reach the
//panel with the pointer, short enough not to feel stuck.
var ITEM_PEEK_CLOSE_MS = 400;

//How long the pointer has to rest on another link before an open panel gives way
//to it. On the way into the panel it crosses whatever lies between, in the forum
//often a whole list of other items, and none of those is meant.
var ITEM_PEEK_SWITCH_MS = 300;

var itemPeekHideTimer;
var itemPeekSwitchTimer = null;

function itemPeekKeepOpen() {
	if (itemPeekHideTimer) {
		clearTimeout(itemPeekHideTimer);
		itemPeekHideTimer = null;
	}
	itemPeekCancelSwitch();
}

function itemPeekCancelSwitch() {
	if (itemPeekSwitchTimer) {
		clearTimeout(itemPeekSwitchTimer);
		itemPeekSwitchTimer = null;
	}
}

function itemPeekIsOpen() {
	return !!(itemPeekPanel && itemPeekPanel.style.display === 'block');
}

function itemPeekScheduleHide() {
	itemPeekKeepOpen();
	itemPeekHideTimer = setTimeout(function () {
		itemPeekHideTimer = null;
		itemPeekHide();
	}, ITEM_PEEK_CLOSE_MS);
}

function itemPeekHide() {
	if (itemPeekPanel)
		itemPeekPanel.style.display = 'none';
	itemPeekCurrentId = '';
}

function itemPeekShow(html, mouseX, mouseY) {
	//Two boxes at one link would be one too many. This one has the trigger note in
	//it, so the trigger module's own box can go.
	try {
		triggerBoxHide();
	} catch (e) {
		//the trigger module may be switched off
	}

	var panel = itemPeekEnsurePanel();
	panel.innerHTML = html;
	itemPeekPlace(mouseX, mouseY);
}

//Is this one of the pieces that trigger something? Then its note goes at the bottom
//of this panel instead of into a yellow box of its own beside it - one window, not
//two. itemPeekShow takes the trigger module's own box off the screen for the same
//reason.
function itemPeekTriggerBlock(name) {
	var hit = triggerNoteFor(name);
	if (!hit)
		return '';
	return '<div style="margin:6px 0 0;padding:5px 0 0;'
		+ 'border-top:1px solid rgba(168,148,84,0.4);color:' + hit.colour + '">'
		+ '<b>Trigger</b><div style="color:' + SETTINGS_SKIN.ink + ';margin:2px 0 0">'
		+ triggerNoteHtml(hit.html) + '</div></div>';
}

function itemPeekEscape(text) {
	return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

//Shorten long item names so the column headers do not run away.
function itemPeekShort(name, howLong) {
	name = String(name || '?');
	return name.length > howLong ? name.substring(0, howLong - 1) + '.' : name;
}

var ITEM_PEEK_CELL = 'padding:1px 6px;border:1px solid #52492c;white-space:nowrap';
var ITEM_PEEK_HEAD = ITEM_PEEK_CELL + ';font-weight:bold';

//What a mark means, where no page read so far has said it.
var ITEM_PEEK_MARKEN = {
	z: 'zählt nur zusätzlich, wenn schon Schaden dieser Art gemacht wird',
	r: 'wird bei normalen / guten / kritischen Treffern zur Wirkung der benutzten Waffe addiert'
};
var ITEM_PEEK_MARK_FARBE = '#e0a030';

/*
 * The columns: the new piece, every worn piece it would push out, and the
 * difference. A two-hander pushes out everything in the hands at once, so it is set
 * against all of them together, and so is a piece that meets only one worn piece.
 * Where it would take the place of just one of several - a ring, a one-hander
 * beside another - there is a difference for each of them.
 */
function itemPeekBuildTable(entry, wornEntries, alleWeg) {
	var i;
	var alle = [entry].concat(wornEntries);
	var marken = { benutzt: [], teile: itemPeekSectionMarks(alle), texte: itemPeekMarkTexts(alle) };
	var vergleiche = itemPeekComparisons(wornEntries, alleWeg);
	var dauer = itemPeekBlock(entry, wornEntries, 'Besitzer', marken, vergleiche);
	var anwendung = ITEM_CFG.anwendung === true
		? itemPeekBlock(entry, wornEntries, 'Anwendung', marken, vergleiche) : '';

	if (!dauer && !anwendung)
		return '<div style="opacity:.8">Keine dauerhaften Boni.</div>';

	var html = '<table style="border-collapse:collapse;margin-top:3px">'
		+ '<tr><th style="' + ITEM_PEEK_HEAD + '">Bonus</th>'
		+ '<th style="' + ITEM_PEEK_HEAD + ';color:#68b6ff">neu</th>';
	for (i = 0; i < wornEntries.length; i++)
		html += '<th style="' + ITEM_PEEK_HEAD + '">'
			+ itemPeekEscape(itemPeekShort(wornEntries[i].name, 22))
			+ (wornEntries[i].anzahl > 1 ? ' \u00d7' + wornEntries[i].anzahl : '')
			+ (wornEntries[i].veredelt ? '<br><span style="font-weight:normal;opacity:.7">'
				+ 'mit Veredelung</span>' : '') + '</th>';
	for (i = 0; i < vergleiche.length; i++)
		html += '<th style="' + ITEM_PEEK_HEAD + ';border-left:2px solid #a89454">'
			+ itemPeekEscape(vergleiche[i].titel) + '</th>';
	html += '</tr>' + dauer;

	//What works only on use stands apart, under a line of its own, so it cannot be
	//read as something the piece gives while it is merely worn.
	if (anwendung)
		html += '<tr><td colspan="' + (wornEntries.length + vergleiche.length + 2)
			+ '" style="padding:4px 6px 1px;border-top:2px solid #a89454;font-weight:bold;'
			+ 'white-space:nowrap">Nur bei Anwendung (a)</td></tr>' + anwendung;
	return html + '</table>' + itemPeekLegend(marken);
}

function itemPeekComparisons(wornEntries, alleWeg) {
	var i, out = [];
	if (!wornEntries.length)
		return out;
	if (alleWeg || wornEntries.length === 1) {
		var alle = [];
		for (i = 0; i < wornEntries.length; i++)
			alle.push(i);
		return [{ titel: 'Unterschied', gegen: alle }];
	}
	for (i = 0; i < wornEntries.length; i++)
		out.push({ titel: '\u00b1 ' + itemPeekShort(wornEntries[i].name, 16), gegen: [i] });
	return out;
}

/* --- Colours and differences ---------------------------------------------- *
 * A bonus is green, a malus red, in every column. For a vulnerability it is the
 * other way round: more of it is worse. A share of the hero level or the skill rank
 * counts by its sign as well, +20%HS is a bonus at every level. Only a value that
 * is partly up and partly down, "+2 -10%", says neither and stays uncoloured.
 *
 * The difference is the new piece minus what it replaces: +20 against +10 is +10.
 * Percentages are taken apart point by point, so +20% against +10% is +10% as well.
 * -------------------------------------------------------------------------- */

var ITEM_PEEK_GRUEN = '#57d977';
var ITEM_PEEK_ROT = '#ff6b6b';
var ITEM_PEEK_UMGEKEHRT = ['Anfälligkeit'];

//1 all up, -1 all down, 0 neither or both.
function itemPeekSign(wert) {
	var teile = Array.isArray(wert) ? wert : [wert];
	var hoch = false, runter = false;
	for (var i = 0; i < teile.length; i++) {
		var w = teile[i] || { };
		var zahlen = [w.f || 0, w.hs || 0, w.fr || 0, wertFaktor(w) - 1];
		for (var k = 0; k < zahlen.length; k++) {
			if (zahlen[k] > 0)
				hoch = true;
			else if (zahlen[k] < 0)
				runter = true;
		}
	}
	return (hoch && !runter) ? 1 : (runter && !hoch) ? -1 : 0;
}

function itemPeekColour(wert, category) {
	if (!ITEM_CFG.faerben || wert == null)
		return '';
	var zeichen = itemPeekSign(wert);
	if (ITEM_PEEK_UMGEKEHRT.indexOf(category) > -1)
		zeichen = -zeichen;
	return zeichen > 0 ? ';color:' + ITEM_PEEK_GRUEN : zeichen < 0 ? ';color:' + ITEM_PEEK_ROT : '';
}

//a + b, or with minus -1 a - b. Percentages go point by point.
function itemPeekCombine(a, b, vorzeichen) {
	if (Array.isArray(a) || Array.isArray(b)) {
		var liste = [];
		for (var k = 0; k < DAMAGE_LEVELS.length; k++)
			liste.push(itemPeekCombine(Array.isArray(a) ? a[k] : a, Array.isArray(b) ? b[k] : b, vorzeichen));
		return liste;
	}
	var out = { };
	for (var i = 0; i < WERT_TEILE.length; i++) {
		var zahl = wertRund(((a && a[WERT_TEILE[i]]) || 0)
			+ vorzeichen * ((b && b[WERT_TEILE[i]]) || 0));
		if (zahl)
			out[WERT_TEILE[i]] = zahl;
	}
	var faktor = wertRund(1 + (wertFaktor(a) - 1) + vorzeichen * (wertFaktor(b) - 1));
	if (faktor !== 1)
		out.p = faktor;
	return out;
}

//The marks in the heads of the tables, per part, over every piece in the panel.
function itemPeekSectionMarks(eintraege) {
	var out = { };
	for (var i = 0; i < eintraege.length; i++) {
		var marken = (eintraege[i].bonusData && eintraege[i].bonusData.Marken) || { };
		for (var teil in marken)
			for (var k = 0; k < marken[teil].length; k++) {
				if (!out[teil])
					out[teil] = [];
				if (out[teil].indexOf(marken[teil][k]) < 0)
					out[teil].push(marken[teil][k]);
			}
	}
	return out;
}

//What each mark means: the page's own words where a page has said it.
function itemPeekMarkTexts(eintraege) {
	var out = { };
	for (var key in ITEM_PEEK_MARKEN)
		out[key] = ITEM_PEEK_MARKEN[key];
	for (var i = eintraege.length - 1; i >= 0; i--) {
		var noten = (eintraege[i].bonusData && eintraege[i].bonusData.Fussnoten) || { };
		for (var b in noten)
			out[b] = noten[b];
	}
	return out;
}

//"Giftschaden (Fernkampf) (z)" -> the name and the marks behind it.
function itemPeekSplitMarks(target) {
	var marken = [];
	var name = String(target);
	var treffer;
	while ((treffer = / \(([a-z])\)$/.exec(name)) !== null) {
		marken.unshift(treffer[1]);
		name = name.slice(0, treffer.index);
	}
	return { name: name, marken: marken };
}

function itemPeekMarkBadge(buchstabe, marken) {
	if (marken.benutzt.indexOf(buchstabe) < 0)
		marken.benutzt.push(buchstabe);
	return ' <b style="color:' + ITEM_PEEK_MARK_FARBE + '" title="'
		+ itemPeekEscape(marken.texte[buchstabe] || '').replace(/"/g, '&quot;') + '">('
		+ buchstabe + ')</b>';
}

//Under the table, what the marks in it mean.
function itemPeekLegend(marken) {
	var html = '';
	marken.benutzt.sort();
	for (var i = 0; i < marken.benutzt.length; i++) {
		var b = marken.benutzt[i];
		html += '<div style="margin:2px 0 0;white-space:normal"><b style="color:'
			+ ITEM_PEEK_MARK_FARBE + '">(' + b + ')</b> '
			+ itemPeekEscape(marken.texte[b] || 'eine Marke der Gegenstandsseite') + '</div>';
	}
	return html ? '<div style="margin:4px 0 0;opacity:.85;max-width:560px">' + html + '</div>' : '';
}

//The rows of one part, the new piece against every worn one, and the differences.
//Nothing to show: an empty text. A row's marks, and those of its table's head,
//stand behind its name in a colour of their own.
function itemPeekBlock(entry, wornEntries, teil, marken, vergleiche) {
	var cell = ITEM_PEEK_CELL;
	var newRows = itemPeekRows(entry.bonusData, teil);
	var wornRows = [];
	var i, j;
	for (i = 0; i < wornEntries.length; i++)
		wornRows.push(itemPeekRows(wornEntries[i].bonusData, teil));

	//Collect every bonus that occurs, so each row appears in every column.
	var order = [];
	var seen = { };
	var collect = function (rows) {
		for (var k = 0; k < rows.length; k++) {
			var key = rows[k].category + ' ' + rows[k].target;
			if (!seen[key]) {
				seen[key] = true;
				order.push({ key: key, category: rows[k].category, target: rows[k].target });
			}
		}
	};
	collect(newRows);
	for (i = 0; i < wornRows.length; i++)
		collect(wornRows[i]);

	var rowOf = function (rows, key) {
		for (var k = 0; k < rows.length; k++)
			if (rows[k].category + ' ' + rows[k].target === key)
				return rows[k];
		return null;
	};

	var html = '';
	for (i = 0; i < order.length; i++) {
		var art = order[i].category;
		var mine = rowOf(newRows, order[i].key);

		var geteilt = itemPeekSplitMarks(order[i].target);
		var zeichen = geteilt.marken.slice();
		var kopf = (marken && marken.teile[art]) || [];
		for (var m = 0; m < kopf.length; m++)
			if (zeichen.indexOf(kopf[m]) < 0)
				zeichen.push(kopf[m]);
		var abzeichen = '';
		for (m = 0; m < zeichen.length && marken; m++)
			abzeichen += itemPeekMarkBadge(zeichen[m], marken);

		html += '<tr><td style="' + cell + '">'
			+ '<span style="opacity:.6">' + itemPeekEscape(art) + '</span> '
			+ itemPeekEscape(geteilt.name) + abzeichen + '</td>'
			+ '<td align="center" style="' + cell + itemPeekColour(mine && mine.wert, art) + '">'
			+ itemPeekEscape(mine ? mine.value : '-') + '</td>';

		var getragen = [];
		for (j = 0; j < wornRows.length; j++) {
			var other = rowOf(wornRows[j], order[i].key);
			getragen.push(other ? other.wert : null);
			html += '<td align="center" style="' + cell + itemPeekColour(other && other.wert, art) + '">'
				+ itemPeekEscape(other ? other.value : '-') + '</td>';
		}

		for (j = 0; vergleiche && j < vergleiche.length; j++) {
			var weg = null;
			for (var g = 0; g < vergleiche[j].gegen.length; g++)
				weg = itemPeekCombine(weg, getragen[vergleiche[j].gegen[g]], 1);
			var unterschied = itemPeekCombine(mine ? mine.wert : null, weg, -1);
			html += '<td align="center" style="' + cell + ';border-left:2px solid #a89454'
				+ itemPeekColour(unterschied, art) + '">'
				+ itemPeekEscape(wertLeer(unterschied) ? '0' : wertKurz(unterschied)) + '</td>';
		}
		html += '</tr>';
	}
	return html;
}

//What the panel says about the gems of the piece under the pointer.
var ITEM_PEEK_GEM_TEXT = {
	veredelt:  'Mit den Boni seiner Veredelung.',
	unbekannt: 'Veredeltes Item. Gezeigt wird es ohne die Boni der Veredelung, bis du '
		+ 'seine Seite einmal geöffnet hast.'
};

//extra: what the game's own tooltip on the link said beyond the name and the
//other worlds. It comes along underneath, so nothing of it is lost.
//stand: 'veredelt' where entry is the piece itself with its gems, 'unbekannt'
//where the piece has gems the store knows nothing of.
function itemPeekRender(entry, mouseX, mouseY, extra, stand) {
	var dazu = extra ? '<div style="margin:6px 0 0;padding:5px 0 0;'
		+ 'border-top:1px solid rgba(168,148,84,0.4)">' + extra + '</div>' : '';
	try {
		var equipment = loadEquipmentSlotsFromStorage();
		var slotKey = '';
		var i;
		for (i = 0; i < entry.slots.length; i++)
			if (ITEM_CFG.ignoredSlots.indexOf(entry.slots[i]) < 0) {
				slotKey = entry.slots[i];
				break;
			}

		//Pure bag goods have nothing to compare against. This window has already
		//taken the link over, so vanishing here would take the trigger note along
		//with it. So: is there anything worth saying about the piece besides the
		//comparison? Then say that. Otherwise stay out of the way.
		if (!slotKey && entry.slots.length > 0) {
			var only = itemPeekTriggerBlock(entry.name);
			if (!only) {
				itemPeekHide();
				return;
			}
			var alone = '<b>' + itemPeekEscape(entry.name || 'Gegenstand') + '</b>';
			var otherWorlds = worldLinksHtml(entry.name);
			if (otherWorlds)
				alone += '<div style="opacity:.75;margin:2px 0 0">' + otherWorlds + '</div>';
			itemPeekShow(alone + only + dazu, mouseX, mouseY);
			return;
		}

		//Everything the find would displace - in the hands that is more than just the
		//place it would land in.
		var wornIds = itemPeekWornToCompare(entry.slots, equipment);

		//The worn pieces out of the same store as the find: a piece with gems by its
		//own number, every other by its name.
		//The same piece twice - two rings of one kind - is one column: the store
		//knows it by its name, so both columns would say the same. Two of a name
		//with different gems are two columns.
		var wornEntries = [];
		var schonDa = { };
		for (i = 0; i < wornIds.length; i++) {
			var wornName = (equipment.names && equipment.names[wornIds[i]]) || wornIds[i];
			var eigen = itemPeekInstanceGet(wornIds[i]);
			var spalte = eigen ? wornName + '\n' + JSON.stringify(eigen.bonusData) : wornName;
			if (schonDa[spalte]) {
				schonDa[spalte].anzahl++;
				continue;
			}
			var gemerkt = eigen || itemPeekCacheGet(wornName);
			if (gemerkt && gemerkt.bonusData) {
				schonDa[spalte] = { name: wornName, bonusData: gemerkt.bonusData, anzahl: 1,
					veredelt: !!eigen };
				wornEntries.push(schonDa[spalte]);
			}
		}

		var title = '<b>' + itemPeekEscape(entry.name || 'Gegenstand') + '</b>';
		if (entry.slots.length > 0) {
			var slotNames = [];
			for (i = 0; i < entry.slots.length; i++) {
				var pretty = entry.slots[i];
				for (var label in equipment.labels)
					if (equipment.labels[label] === entry.slots[i])
						pretty = label;
				slotNames.push(pretty);
			}
			title += ' <span style="opacity:.7">- ' + itemPeekEscape(slotNames.join(' / ')) + '</span>';
		}

		//The other worlds. The game's own tooltip carries these in the forum, and this
		//panel takes that tooltip's place on every page where the compare runs - so they
		//have to be here, or they are lost.
		var worlds = worldLinksHtml(entry.name);
		if (worlds)
			title += '<div style="opacity:.75;margin:2px 0 0">' + worlds + '</div>';

		var note = '';
		if (entry.slots.length === 0)
			note = '<div style="opacity:.7">Platz unbekannt, nur die eigenen Boni.</div>';
		else if (wornEntries.length === 0)
			note = '<div style="opacity:.7">Nichts Vergleichbares getragen.</div>';
		if (stand && ITEM_PEEK_GEM_TEXT[stand])
			note += '<div data-mm-peek-gem="' + stand + '" style="opacity:.7">'
				+ itemPeekEscape(ITEM_PEEK_GEM_TEXT[stand]) + '</div>';

		//A two-hander pushes out everything in the hands at once.
		var beideHaende = equipment.labels ? equipment.labels['Beide Hände'] : null;
		var alleWeg = !!beideHaende && entry.slots.indexOf(beideHaende) > -1;

		itemPeekShow(title + note + itemPeekBuildTable(entry, wornEntries, alleWeg)
			+ itemPeekTriggerBlock(entry.name) + dazu, mouseX, mouseY);
	} catch (e) {
		mmReportError('itemPeekRender', e);
	}
}

/* --- Reading the page the player opened --------------------------------- */

/*
 * The item page of the game, read where it stands. No request is made for it: the
 * player called it up himself, the script merely takes note of what is on it.
 *
 * Whoever opens a piece teaches the script what that name is worth, and from then
 * on it is worth that everywhere. A piece with gems teaches two things: under the
 * name what it grants without them, and under its own number what it grants as it
 * is.
 */
function itemPeekHarvest() {
	if (!itemPeekIsItemPage())
		return false;

	var entry = itemPeekParse(document, loadEquipmentSlotsFromStorage().labels);
	if (!entry || !entry.name)
		return false;

	//A piece does not change where it is worn. A page that does not say it - an
	//item this hero cannot put on - keeps the places an earlier visit found.
	var vorher = itemPeekCacheGet(entry.name);
	if (!entry.slots.length && vorher && vorher.slots && vorher.slots.length)
		entry.slots = vorher.slots;

	var veredelt = itemPageGemMarks(document);
	var nr = itemPeekPageInstance(document);
	if (nr && veredelt !== 'keine')
		itemPeekInstancePut(nr, { name: entry.name, slots: entry.slots,
			bonusData: itemPageReadBonuses(document, false), wer: entry.wer,
			lese: ITEM_PAGE_READER, veredelt: veredelt });
	else if (nr)
		itemPeekInstanceDrop(nr);

	//A gem changed a bonus the piece has anyway: what it was without the gem is
	//not on this page. A reading that is sure stays; otherwise this one is kept
	//until a better one comes.
	if (veredelt === 'auch') {
		if (vorher && !vorher.unsicher && vorher.src !== 'daten' && vorher.lese === ITEM_PAGE_READER)
			return true;
		entry.unsicher = 1;
	}

	//What the data of the skills page filled in gives way to the page without a word:
	//nothing was learned wrong, the page simply says it better. The same holds for
	//an entry that was not sure of itself.
	var art = itemPeekCachePut(entry.name, entry);
	if (art === 'geaendert' && vorher && vorher.lese !== ITEM_PAGE_READER)
		art = 'gleich';
	if (art === 'geaendert' && ITEM_CFG.meldeAenderung && !entry.unsicher
			&& !(vorher && (vorher.src === 'daten' || vorher.unsicher)))
		itemPeekChangeNote(entry.name);
	return true;
}

function itemPeekIsItemPage() {
	return /\/wod\/spiel\/hero\/item\.php/.test(String(location.pathname || ''));
}

//A quiet line at the top of the page. It is the one moment where the store can be
//put right, so it should not pass unmentioned - and it should not be a dialogue
//either, because nothing needs answering.
function itemPeekChangeNote(name) {
	if (document.getElementById('mm_peek_note'))
		return;

	var note = document.createElement('div');
	note.id = 'mm_peek_note';
	note.setAttribute('data-mm-peek-note', name);
	note.style.cssText = 'margin:4px 0;padding:4px 8px;font-size:11px;line-height:1.45;'
		+ 'border:1px solid #a89464;border-left-width:3px;border-radius:2px;'
		+ 'background:rgba(168,148,84,0.12);color:' + SETTINGS_SKIN.ink + ';';
	note.textContent = 'Der Gegenstandsvergleich kannte "' + name
		+ '" schon, mit anderen Werten. Gespeichert ist jetzt, was hier steht.';

	var form = document.querySelector('form') || document.body;
	if (form.firstChild)
		form.insertBefore(note, form.firstChild);
	else
		form.appendChild(note);
}

/* --- The mouse pointer -------------------------------------------------- */

//The one place that forgets which item the pointer was on. There is no request
//and no timer to call off.
/* --- The game's own tooltip on the same link ------------------------------ *
 * In the forum an item link carries a tooltip of the game's: the name, and the
 * item in the other worlds. The panel says the same at its head, and two boxes at
 * one link lie on top of each other. So where the panel comes up, the game's call
 * is taken off the link. This happens in the capture phase, before the event
 * reaches the link, so the game does not hear of that mouse at all. Should its box
 * already be open from before, the game's own function for closing it is called.
 *
 * Whatever the game's tooltip says beyond the name and the worlds is not thrown
 * away: it goes into the panel, underneath. The trigger note the trigger module
 * hung into it is left out there, because the panel has that one already.
 * -------------------------------------------------------------------------- */

var ITEM_PEEK_WELTEN_RE = /<p>\s*<b>[^<]*<\/b>\s*<br\s*\/?>\s*(?:<a\b[^>]*>[^<]*<\/a>\s*(?:<br\s*\/?>)?\s*)+<hr\s*\/?>\s*<span class=["']footnote["']>[\s\S]*?<\/span>\s*<\/p>/i;
var ITEM_PEEK_TRIGGER_RE = /<hr\s*\/?>\s*<b>Trigger:<\/b>[\s\S]*$/i;

function itemPeekGameTipRest(anchor) {
	var html = anchor ? mobilTooltipHtml(anchor) : '';
	if (!html)
		return '';
	var rest = html.replace(ITEM_PEEK_TRIGGER_RE, '').replace(ITEM_PEEK_WELTEN_RE, '')
		.replace(/^\s*(<hr\s*\/?>\s*)+/i, '').trim();
	var probe = document.createElement('div');
	probe.innerHTML = rest;
	return taktikClean(probe.textContent) ? rest : '';
}

//Only a link whose whole handler is the game's tooltip call is touched.
var ITEM_PEEK_GAME_CALL = /^\s*(return\s+)?wodToolTip\(\s*this\s*,\s*'[\s\S]*'\s*\)\s*;?\s*$/;

//The game's call off the link, kept in an attribute of ours.
function itemPeekHoldGameTip(anchor) {
	var roh = anchor.getAttribute('onmouseover') || '';
	if (!ITEM_PEEK_GAME_CALL.test(roh))
		return false;
	anchor.setAttribute('data-mm-peek-tip', roh);
	anchor.removeAttribute('onmouseover');
	return true;
}

//And back on again, where the panel has nothing to say about the link after all.
//With a position, the pointer is resting on the link right now: the game hears of
//it at once instead of on the next pass.
function itemPeekGiveGameTipBack(anchor, x, y) {
	var roh = anchor.getAttribute('data-mm-peek-tip');
	if (!roh || anchor.hasAttribute('onmouseover'))
		return false;
	anchor.setAttribute('onmouseover', roh);
	anchor.removeAttribute('data-mm-peek-tip');
	if (typeof x == 'number') {
		try {
			anchor.dispatchEvent(new MouseEvent('mouseover',
				{ bubbles: true, cancelable: true, clientX: x, clientY: y }));
		} catch (e) {
			//an old browser without MouseEvent: then on the next pass
		}
	}
	return true;
}

function itemPeekTakeGameTip(anchor) {
	itemPeekHoldGameTip(anchor);

	var seite = (typeof unsafeWindow != 'undefined' && unsafeWindow) ? unsafeWindow : window;
	try {
		if (typeof seite.wodToolTipClose == 'function')
			seite.wodToolTipClose();
	} catch (e) {
		//a box of the game's that stays open is a blemish, not a failure
	}
}

//Consumables carry a use count in their text - "Spruchrolle (10/12)". Those live in
//the bag and are not compared, and the text alone is enough to recognise them.
function itemPeekLooksLikeConsumable(anchor) {
	var after = anchor.nextSibling;
	var text = after && after.nodeType === 3 ? after.nodeValue : '';
	return /^\s*\(\d+\/\d+\)/.test(text || '');
}

//Can the hero playing wear this piece, by class and race? What the item page has
//not said - an entry from before this was read, a piece known only from the data
//of the skills page, which the hero wears anyway - counts as yes.
function itemPeekWearable(entry) {
	var wer = entry && entry.wer;
	if (!wer)
		return true;
	return itemPeekAllowed(wer.klassen, heroMaleForm(essentialField('klasse_name') || ''))
		&& itemPeekAllowed(wer.voelker, heroMaleForm(essentialField('rasse_name') || ''));
}

function itemPeekAllowed(regel, name) {
	if (!regel || !regel.namen || !name)
		return true;
	var drin = regel.namen.indexOf(name) > -1;
	return regel.art === 'nicht' ? !drin : drin;
}

function itemPeekCandidate(target) {
	if (!target || !target.closest)
		return null;
	var anchor = target.closest('a[href*="item.php"]');
	if (!anchor)
		return null;

	var classes = anchor.getAttribute('class') || '';
	//What this hero can never wear is not compared - there is nothing to weigh it
	//against. It is still remembered when its page is opened, because the store
	//belongs to the world and the next hero may well be able to wear it.
	//item_later_usable is deliberately not filtered: those are the pieces the hero
	//is working towards, and they are the interesting ones to compare.
	if (classes.indexOf('item_unusable') >= 0)
		return null;
	if (itemPeekLooksLikeConsumable(anchor))
		return null;

	//The name, because that is what the store is keyed by. The same reading the
	//trigger module uses, so both agree on what a link is called even after one of
	//them has painted a span around the text.
	var name = itemNamePlain(itemNameFromLink(anchor));
	if (!name)
		return null;
	var nummer = String(anchor.getAttribute('href') || '').match(/[?&]item_instance_id=(\d+)/);
	return { anchor: anchor, name: name, instanz: nummer ? nummer[1] : '',
		veredelt: itemPeekHasGems(anchor) };
}

//The game puts a small picture behind an item link for every place a gem can sit
//in, an empty one for an empty place. Whether one of them is filled.
function itemPeekHasGems(anchor) {
	for (var knoten = anchor.nextSibling; knoten; knoten = knoten.nextSibling) {
		if (knoten.nodeType === 3 && !knoten.nodeValue.trim())
			continue;
		if (knoten.nodeType !== 1 || knoten.tagName !== 'IMG')
			return false;
		var bild = String(knoten.getAttribute('src') || '');
		if (bild.indexOf('/gems/gem_') < 0)
			return false;
		if (!/\/gems\/gem_0\./.test(bild))
			return true;
	}
	return false;
}

//What the pointer is on, as one word: the name, and for a piece with gems its
//number as well, so that two of a name in one list are told apart.
function itemPeekIdentity(found) {
	if (found.kennung === undefined)
		found.kennung = found.name + ((found.veredelt || itemPeekInstanceGet(found.instanz))
			? '#' + (found.instanz || 'veredelt') : '');
	return found.kennung;
}

function itemPeekInit() {
	if (!FEATURES.itemCompare || !world || !id)
		return;

	//Where the pieces sit, and what they are called, comes from the equipment page.
	if (gearIsEquipmentPage())
		gearReadSlots();

	//Whoever is standing on an item page is looking at exactly the page this module
	//lives on. It gets read and put away, and that is the only way anything ever
	//enters the store.
	itemPeekHarvest();

	//A single listener for the whole page. With a thousand items anything else would
	//be waste, and rows loaded later are covered along with it.
	document.addEventListener('mouseover', function (event) {
		//The links inside the panel are the panel's; they open nothing.
		if (itemPeekPanel && itemPeekPanel.contains(event.target))
			return;
		var found = itemPeekCandidate(event.target);
		if (!found || itemPeekIdentity(found) === itemPeekCurrentId)
			return;

		var x = event.clientX, y = event.clientY;
		if (!itemPeekIsOpen()) {
			itemPeekOpen(found, x, y);
			return;
		}

		//An open panel only gives way once the pointer stays on the new link. The
		//game's tooltip on that link is kept away meanwhile, or it would come up in
		//the panel's place.
		itemPeekHoldGameTip(found.anchor);
		itemPeekCancelSwitch();
		itemPeekSwitchTimer = setTimeout(function () {
			itemPeekSwitchTimer = null;
			itemPeekOpen(found, x, y);
		}, ITEM_PEEK_SWITCH_MS);
	}, true);

	document.addEventListener('mouseout', function (event) {
		if (itemPeekPanel && itemPeekPanel.contains(event.target))
			return;
		if (!itemPeekCandidate(event.target))
			return;
		//Straight into the panel is not leaving.
		if (event.relatedTarget && itemPeekPanel && itemPeekPanel.contains(event.relatedTarget))
			return;
		//A link only passed on the way is not meant.
		itemPeekCancelSwitch();
		itemPeekScheduleHide();
	}, true);
}

function itemPeekOpen(found, x, y) {
	itemPeekKeepOpen();
	itemPeekCurrentId = itemPeekIdentity(found);

	//Only what is already known. An item nobody has opened stays silent rather
	//than asking the server about it, and the game's own tooltip stays as it is.
	//A piece with gems is looked up by its number first; under its name stands
	//what it grants without them.
	var eigen = itemPeekInstanceGet(found.instanz);
	var bekannt = eigen || itemPeekCacheGet(found.name);
	if (!bekannt || !itemPeekWearable(bekannt)) {
		itemPeekHide();
		itemPeekCurrentId = itemPeekIdentity(found);
		itemPeekGiveGameTipBack(found.anchor, x, y);
		return;
	}
	itemPeekRender(bekannt, x, y, itemPeekGameTipRest(found.anchor),
		eigen ? 'veredelt' : (found.veredelt ? 'unbekannt' : ''));
	if (itemPeekIsOpen())
		itemPeekTakeGameTip(found.anchor);
	else {
		itemPeekCurrentId = itemPeekIdentity(found);
		itemPeekGiveGameTipBack(found.anchor, x, y);
	}
}

/////////////////////////////////////////////////////////////////////////////
//////////////////////// Groundwork: general helpers ////////////////////////
/////////////////////////////////////////////////////////////////////////////

/* --- Six small builders every module reaches for ------------------------- *
 * One copy for all of them: the options window, the finds, the configuration
 * tweaks, the BBCode bar, the mobile mode, the gem list and the battle
 * statistics all build with these.
 * ------------------------------------------------------------------------- */

//An element with an inline style and a text, any of the three may be left out.
function mmEl(tag, css, text) {
	var el = document.createElement(tag);
	if (css)
		el.style.cssText = css;
	if (text != null)
		el.appendChild(document.createTextNode(text));
	return el;
}

//A bubbling event of the given kind, sent from the element.
function mmFire(el, art) {
	var ereignis;

	try {
		ereignis = new Event(art, { bubbles: true });
	} catch (e) {
		ereignis = document.createEvent('HTMLEvents');
		ereignis.initEvent(art, true, false);
	}
	el.dispatchEvent(ereignis);
}

//A click that does what fn says and nothing of what the page would do. In a net
//of its own, because a click is an entry point; the report names the button by
//its title or its text.
function mmOnClick(knopf, fn) {
	knopf.addEventListener('click', function (event) {
		if (event && event.preventDefault)
			event.preventDefault();
		try {
			fn();
		} catch (e) {
			mmReportError(mmButtonName(knopf), e);
		}
	}, false);
}

function mmButtonName(knopf) {
	var name = knopf.title || knopf.value || knopf.textContent || '';
	name = String(name).replace(/\s+/g, ' ').trim();
	return name ? 'Knopf "' + name + '"' : 'Knopf';
}

//Runs fn once the page has stopped changing under the node for a moment - the
//game rebuilds some of its lists in several steps, and the decoration is to be
//done once, at the end. In a net of its own: this is an entry point.
function mmWatch(node, wo, fn) {
	var offen = null;
	new MutationObserver(function () {
		window.clearTimeout(offen);
		offen = window.setTimeout(function () {
			try {
				fn();
			} catch (e) {
				mmReportError(wo, e);
			}
		}, 150);
	}).observe(node, { childList: true, subtree: true });
}

//Everything out of an element; the element itself is handed back.
function mmEmpty(el) {
	while (el.firstChild)
		el.removeChild(el.firstChild);
	return el;
}

//A stylesheet under the given id, once: a second call with the same id does nothing.
function mmInjectCss(id, css) {
	if (document.getElementById(id))
		return null;

	var stil = document.createElement('style');
	stil.id = id;
	stil.type = 'text/css';
	stil.appendChild(document.createTextNode(css));
	(document.head || document.documentElement).appendChild(stil);
	return stil;
}


//The worlds an item can be looked up in, as the game's own tooltip in the forum
//offers them. Each name is also the host name of that world.
var WORLD_LINKS = ['algarion', 'cartegon', 'darakesh'];

function worldLinksHtml(name) {
	var clean = String(name == null ? '' : name).trim();
	if (!clean)
		return '';

	var parts = [];
	for (var i = 0; i < WORLD_LINKS.length; i++) {
		if (WORLD_LINKS[i] === world_written)
			continue;
		parts.push('<a href="https://' + WORLD_LINKS[i] + '.world-of-dungeons.de'
			+ '/wod/spiel/hero/item.php?name=' + encodeURIComponent(clean)
			+ '" target="_blank">'
			+ WORLD_LINKS[i].charAt(0).toUpperCase() + WORLD_LINKS[i].slice(1)
			+ '</a>');
	}
	return parts.join(' &middot; ');
}


/////////////////////////////////////////////////////////////////////////////
//////////////////////// Module: the options window /////////////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * A gear button in the game's gadget bar opens a small window with four tabs.
 * Everything adjustable is described once in SETTINGS_TABS at the top of the
 * file; this module only turns that description into fields and reads them back.
 *
 * Placement: the button stands at the right end of the bar, behind the game's own
 * icons and behind anything another script has put there. The left end belongs to
 * what is pressed often - the way to the next hero, the dungeon planner - and the
 * settings are pressed once a month.
 */

function settingsInit() {
	if (document.getElementById('mm_settings_btn'))
		return;

	var wrap = document.createElement('div');
	wrap.className = 'gadget_icon';

	var button = document.createElement('a');
	button.id = 'mm_settings_btn';
	button.href = '#';
	button.title = 'Einstellungen für Enhance Fertigkeiten';
	button.textContent = '⚙';
	button.style.cssText = 'display:inline-flex;align-items:center;cursor:pointer;'
		+ 'text-decoration:none;color:' + SETTINGS_SKIN.ink + ';font-weight:bold;'
		+ 'font-family:sans-serif;font-size:11px;background:' + SETTINGS_SKIN.back + ';'
		+ 'border:1px solid ' + SETTINGS_SKIN.border + ';padding:2px 7px 3px;'
		+ 'border-radius:2px;user-select:none;white-space:nowrap;vertical-align:middle;';
	wrap.appendChild(button);

	if (settingsParkRight(wrap)) {
		settingsWatchGadgetBar(wrap);
	} else {
		//No gadget bar on this page - park it in the corner rather than lose it.
		wrap.className = '';
		wrap.style.cssText = 'position:fixed;top:6px;right:6px;z-index:99999;display:block;';
		document.body.appendChild(wrap);
	}

	button.addEventListener('click', function (event) {
		if (event && event.preventDefault)
			event.preventDefault();
		settingsOpen();
	}, true);
}

/*
 * The right end of the bar. The end is the last icon box that is not our own, and
 * the button is only moved when something really stands behind it - otherwise the
 * observer below would answer its own change. A box marked data-mm-hinten stands
 * behind the button on purpose and does not count.
 */
function settingsParkRight(wrap) {
	var gadgets = document.querySelectorAll('.gadget_icon');
	var last = null;

	for (var i = 0; i < gadgets.length; i++)
		if (gadgets[i] !== wrap && !gadgets[i].hasAttribute('data-mm-hinten'))
			last = gadgets[i];

	//No bar of the game's own: whoever already stands somewhere stays there, and
	//whoever does not gets the corner from the caller.
	if (!last || !last.parentElement)
		return wrap.parentElement != null;
	if (last.nextSibling === wrap)
		return true;

	last.parentElement.insertBefore(wrap, last.nextSibling);
	return true;
}

/* --- Room in the gadget bar ----------------------------------------------
 * The game gives the icon bar a fixed width - 220px in the current skin, written
 * onto three nested elements at once - and hides whatever does not fit behind a
 * scrollbar. Two added buttons are enough to push the game's own icons out of
 * sight. So the bar is grown to what it now actually needs.
 *
 * Nothing is measured by hand: the row of icons reports its own scrollWidth. The
 * observer is there because the other script may insert its button after this one
 * - then the bar has to grow a second time.
 * ------------------------------------------------------------------------- */

function settingsWidenGadgetBar(el) {
	//In mobile mode that one settles the width - two calculations for the same
	//measurement only get in each other's way.
	if (MOBIL_CFG.enabled === true)
		return;

	var body = el.closest ? el.closest('.gadget_body') : null;
	if (!body)
		return;

	//Without a layout - hidden bar, or a test rig - there is nothing to measure.
	var needed = body.scrollWidth;
	if (!needed)
		return;

	//Two ceilings, the lower one wins: the fixed one above, and what the window can
	//spare beside the rest of the header. On a telephone the second is the smaller,
	//and the row simply stays as the game left it.
	var ceiling = Math.min(SETTINGS_BAR_MAX_PX,
		Math.max(220, (window.innerWidth || 1024) - 320));
	needed = Math.min(needed + 8, ceiling);

	var levels = ['.gadget_scroll', '.gadget_inner', '.gadget_table_cell'];
	for (var i = 0; i < levels.length; i++) {
		var box = el.closest(levels[i]);
		if (!box)
			continue;
		var current = parseInt(box.style.width, 10);
		if (isNaN(current) || current < needed)
			box.style.width = needed + 'px';
	}
}

//Measure the row once more, from the outside. The observer below does the same
//thing, but on its own schedule; this is called when the last module has had its
//turn, so that a module which adds a button of its own does not have to know that
//the row has to grow with it.
function settingsFitGadgetBar() {
	var button = document.getElementById('mm_settings_btn');
	var wrap = button && button.closest ? button.closest('.gadget_icon') : null;
	if (!wrap)
		return;

	//A module that has added a button of its own has added it at the front; that the
	//gear still stands at the end is made sure of here rather than in each of them.
	settingsParkRight(wrap);
	settingsWidenGadgetBar(wrap);
}

function settingsWatchGadgetBar(el) {
	settingsWidenGadgetBar(el);

	//Widening happens on the ancestors, never inside the observed row. The one change
	//inside it is the move to the right end, and that one settles after a single
	//round: what stands last is not moved again.
	try {
		var body = el.closest('.gadget_body');
		if (!body || typeof MutationObserver == 'undefined')
			return;
		new MutationObserver(function () {
			settingsParkRight(el);
			settingsWidenGadgetBar(el);
		}).observe(body, { childList: true, subtree: true });
	} catch (e) {
		//An observer is a comfort, not a requirement.
	}
}

/* --- Small builders ------------------------------------------------------ */

//<input type="color"> only accepts #rrggbb in lower case; anything else it silently
//turns black, which looks exactly like a lost setting. Returns null for what is not
//a colour, so a stored oddity can be told apart from a deliberate black.
function settingsColourValue(value) {
	var text = String(value == null ? '' : value).trim().toLowerCase();
	if (/^#[0-9a-f]{3}$/.test(text))
		text = '#' + text[1] + text[1] + text[2] + text[2] + text[3] + text[3];
	return /^#[0-9a-f]{6}$/.test(text) ? text : null;
}

function settingsButton(label, primary) {
	var b = mmEl('input');
	b.type = 'button';
	b.value = label;
	b.style.cssText = 'font-family:inherit;font-size:12px;cursor:pointer;padding:4px 12px;'
		+ 'border-radius:2px;margin-left:6px;'
		+ 'border:1px solid ' + SETTINGS_SKIN.border + ';'
		+ 'background:' + (primary ? '#3a3524' : SETTINGS_SKIN.back) + ';'
		+ 'color:' + SETTINGS_SKIN.ink + ';';
	return b;
}

/* --- The window ---------------------------------------------------------- */

//What stands at the head of the window: the name, and the version where
//Tampermonkey names one.
function settingsTitle() {
	var version = mmScriptVersion();
	return 'WoD Enhancer ' + (version ? '(Version ' + version + ') ' : '') + 'Einstellungen';
}

//The script's own thread in the game's forum, by the number of its post. In a
//post the forum makes a link of "[post:16707322|...]"; this window is not a post,
//so the link is built here.
var SETTINGS_FORUM_POST = '16707322';

//The address of a post in the general forum, the way the game itself links one:
//pid names the post, board=kein the general forum, and the anchor is the bare
//number again. The hero goes along where one is known, as on every link of the
//game.
function mmPostUrl(pid) {
	return '/wod/spiel/forum/viewtopic.php?pid=' + pid + '&board=kein'
		+ (id ? '&session_hero_id=' + encodeURIComponent(id) : '') + '#' + pid;
}

//Opens in a tab of its own, so that the window and what was changed in it stay.
function settingsPostLink() {
	var link = mmEl('a', 'margin-left:12px;font-weight:normal;font-size:12px;'
		+ 'text-decoration:underline;color:' + SETTINGS_SKIN.ink + ';', 'Link zum Beitrag');
	link.id = 'mm_settings_post';
	link.href = mmPostUrl(SETTINGS_FORUM_POST);
	link.target = '_blank';
	link.rel = 'noopener';
	return link;
}

//Values being edited. Kept apart from the live blocks so "Abbrechen" really does
//nothing - nothing is written until Speichern.
var settingsDraft = null;
var settingsEscHandler = null;

function settingsOpen() {
	if (document.getElementById('mm_settings_overlay'))
		return;

	settingsDraft = settingsSnapshot();

	var overlay = mmEl('div', 'position:fixed;left:0;top:0;right:0;bottom:0;'
		+ 'background:rgba(0,0,0,0.55);z-index:99998;');
	overlay.id = 'mm_settings_overlay';

	//As roomy as the planner's window: the script has a lot to set, and a tab with
	//twenty ticks in it should not be read through a letterbox.
	var win = mmEl('div', 'position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);'
		+ 'width:min(1100px,96vw);height:min(900px,94vh);max-height:94vh;'
		+ 'display:flex;flex-direction:column;'
		+ 'background:' + SETTINGS_SKIN.back + ';color:' + SETTINGS_SKIN.ink + ';'
		+ 'border:1px solid ' + SETTINGS_SKIN.border + ';border-radius:3px;'
		+ 'box-shadow:0 6px 24px ' + SETTINGS_SKIN.shadow + ';'
		+ 'font-family:sans-serif;font-size:12px;z-index:99999;');
	win.id = 'mm_settings_window';

	var head = mmEl('div', 'padding:8px 12px;border-bottom:1px solid ' + SETTINGS_SKIN.border
		+ ';font-weight:bold;font-size:13px;', settingsTitle());
	head.appendChild(settingsPostLink());
	win.appendChild(head);

	var tabBar = mmEl('div', 'display:flex;flex-wrap:wrap;gap:4px;padding:8px 12px 0;');
	win.appendChild(tabBar);

	//Below the row of groups the window is split in two: what the group holds on
	//the left, the page itself on the right.
	var mitte = mmEl('div', 'display:flex;flex:1;min-height:0;'
		+ 'border-top:1px solid ' + SETTINGS_SKIN.border + ';');
	win.appendChild(mitte);

	//Narrow, and narrower still where the window is: on a phone a fixed column of
	//names takes the room the settings themselves need.
	var liste = mmEl('div', 'flex:0 1 auto;width:min(150px,34vw);'
		+ 'min-width:96px;overflow-y:auto;padding:8px 0;'
		+ 'border-right:1px solid ' + SETTINGS_SKIN.border + ';');
	liste.setAttribute('data-mm-liste', 'module');
	mitte.appendChild(liste);

	var body = mmEl('div', 'padding:10px 12px;overflow-y:auto;flex:1;'
		+ 'min-width:0;');
	mitte.appendChild(body);

	var panes = { };
	var labels = { };
	var tabButtons = { };
	var listButtons = { };

	function showTab(id) {
		var gruppe = settingsGroupOf(id);
		var key;

		for (key in panes)
			panes[key].style.display = (key == id) ? 'block' : 'none';
		for (key in tabButtons) {
			var anGruppe = key == gruppe.id;
			tabButtons[key].style.background = anGruppe ? '#3a3524' : SETTINGS_SKIN.back;
			tabButtons[key].style.fontWeight = anGruppe ? 'bold' : 'normal';
		}
		fillList(gruppe, id);
	}

	/*
	 * The list beside the page. It is built anew for every group rather than kept
	 * standing and hidden: a group holds three pages or a dozen, and a list of the
	 * wrong length would only have to be corrected afterwards.
	 */
	function fillList(gruppe, id) {
		mmEmpty(liste);
		listButtons = { };

		//One page alone is no choice. Then the list goes and the page takes the room.
		liste.hidden = gruppe.tabs.length < 2;
		if (liste.hidden)
			return;

		for (var i = 0; i < gruppe.tabs.length; i++)
			liste.appendChild(settingsListEntry(gruppe.tabs[i],
				labels[gruppe.tabs[i]], gruppe.tabs[i] == id, showTab, listButtons));
	}

	function addTab(id, label, pane) {
		labels[id] = label;
		pane.style.display = 'none';
		panes[id] = pane;
		body.appendChild(pane);
	}

	function addGroup(gruppe) {
		var b = mmEl('input');
		b.type = 'button';
		b.value = gruppe.label;
		b.style.cssText = 'font-family:inherit;font-size:12px;cursor:pointer;padding:4px 10px;'
			+ 'border:1px solid ' + SETTINGS_SKIN.border + ';border-bottom:none;'
			+ 'border-radius:3px 3px 0 0;background:' + SETTINGS_SKIN.back + ';'
			+ 'color:' + SETTINGS_SKIN.ink + ';';
		b.setAttribute('data-mm-gruppe', gruppe.id);
		b.addEventListener('click', function () { showTab(gruppe.tabs[0]); }, true);
		tabBar.appendChild(b);
		tabButtons[gruppe.id] = b;
	}

	//Every page is built once and put away; the groups above only decide which of
	//them is showing. The two that are no module at all - the window's own page and
	//the calculator - are built here and stand in the group table like the rest.
	SETTINGS_EXTRA_SAVE = [];
	addTab('data', 'Daten & Meldungen', settingsBuildDataPane());
	addTab('legend', 'Legendenrechner', legendBuildPane());

	for (var i = 0; i < SETTINGS_TABS.length; i++)
		addTab(SETTINGS_TABS[i].id, SETTINGS_TABS[i].label,
			settingsBuildPane(SETTINGS_TABS[i]));

	for (var g = 0; g < SETTINGS_GROUPS.length; g++)
		addGroup(SETTINGS_GROUPS[g]);

	/* --- Footer --- */
	var foot = mmEl('div', 'padding:8px 12px;border-top:1px solid ' + SETTINGS_SKIN.border
		+ ';display:flex;align-items:center;');
	var note = mmEl('span', 'flex:1;opacity:0.7;font-size:11px;',
		'Die meisten Änderungen greifen erst, wenn die Seite neu geladen wird.');
	foot.appendChild(note);

	var cancel = settingsButton('Abbrechen');
	cancel.addEventListener('click', settingsClose, true);
	foot.appendChild(cancel);

	var save = settingsButton('Speichern', true);
	save.addEventListener('click', function () {
		settingsSave(settingsDraft);
		settingsClose();
	}, true);
	foot.appendChild(save);
	win.appendChild(foot);

	overlay.appendChild(win);
	document.body.appendChild(overlay);

	showTab(settingsStartTab());

	overlay.addEventListener('click', function (event) {
		if (event.target === overlay)
			settingsClose();
	}, true);
	settingsEscHandler = function (event) {
		if (event.key == 'Escape' || event.keyCode == 27)
			settingsClose();
	};
	document.addEventListener('keydown', settingsEscHandler, true);
}

/*
 * One name in the list beside the page. It is a button and not a link: the window
 * is one page of the game, and a link in it would want somewhere to go.
 */
function settingsListEntry(id, label, an, waehle, merker) {
	var b = mmEl('input');

	b.type = 'button';
	b.value = label || id;
	b.setAttribute('data-mm-seite', id);
	b.style.cssText = 'display:block;width:100%;text-align:left;box-sizing:border-box;'
		+ 'white-space:normal;line-height:1.3;'
		+ 'font-family:inherit;font-size:12px;cursor:pointer;padding:5px 8px;'
		+ 'border:none;border-left:3px solid ' + (an ? SETTINGS_SKIN.border : 'transparent')
		+ ';background:' + (an ? '#3a3524' : 'transparent') + ';'
		+ 'color:' + SETTINGS_SKIN.ink + ';font-weight:' + (an ? 'bold' : 'normal') + ';';
	b.addEventListener('click', function () { waehle(id); }, true);

	merker[id] = b;
	return b;
}

/*
 * Which tab the window opens on. Not always the core one: whoever reaches for the
 * settings while standing on the marketplace is almost certainly after the
 * marketplace and not after the list of stored data.
 *
 * Taken is the module with the SHORTEST page list among those running here. A
 * short list means the module was written for exactly this page; a module that
 * runs everywhere is only passing through and never wins. "quiet" takes a module
 * out of the choice altogether, for the one case where the narrowest list is not
 * the module that owns the page.
 *
 * The question is which module the page belongs to, not what it found to do there:
 * the marketplace tab also opens on an item page that holds nothing for sale, and
 * that is the honest answer - it is still the page where that module works.
 */
function settingsStartTab() {
	var best = null;

	for (var i = 0; i < MODULES.length; i++) {
		var module = MODULES[i];
		if (!module.toggle || module.quiet || !module.pages)
			continue;
		if (module.pages.indexOf(page) < 0)
			continue;
		if (settingsRead(module.toggle) !== true)
			continue;
		if (best && module.pages.length >= best.pages.length)
			continue;
		best = module;
	}

	var tab = best ? settingsTabOf(best.toggle) : null;
	return tab ? tab.id : 'data';
}

//The tab holding a given switch. With three modules in one tab, switches and tabs
//are not one for one, so it is looked up rather than assumed.
function settingsTabOf(path) {
	for (var i = 0; i < SETTINGS_TABS.length; i++)
		for (var j = 0; j < SETTINGS_TABS[i].fields.length; j++)
			if (SETTINGS_TABS[i].fields[j].path === path)
				return SETTINGS_TABS[i];
	return null;
}

function settingsClose() {
	var overlay = document.getElementById('mm_settings_overlay');
	if (overlay && overlay.parentNode)
		overlay.parentNode.removeChild(overlay);
	if (settingsEscHandler) {
		document.removeEventListener('keydown', settingsEscHandler, true);
		settingsEscHandler = null;
	}
	settingsDraft = null;
}

/* --- One tab of adjustable fields ---------------------------------------- */

function settingsBuildPane(tab) {
	var pane = mmEl('div');

	if (tab.intro)
		pane.appendChild(mmEl('div',
			'opacity:0.75;margin:2px 0 10px;line-height:1.45;', tab.intro));

	//Where a module comes from somebody else's script, it says so here. The work was
	//done by another; that belongs said.
	if (tab.author)
		pane.appendChild(mmEl('div',
			'opacity:0.5;font-size:11px;margin:0 0 12px;', 'Ursprünglich von ' + tab.author + '.'));

	//A limit that no setting can take away belongs above the settings, not into the
	//small print of one of them: it holds whichever way the ticks are set.
	if (tab.warn) {
		var kasten = mmEl('div', 'margin:0 0 14px;padding:7px 9px;line-height:1.45;'
			+ 'font-size:11px;border:1px solid #b06a3a;border-left-width:3px;'
			+ 'border-radius:2px;background:rgba(176,106,58,0.12);', tab.warn);
		kasten.setAttribute('data-mm-warn', tab.id);
		pane.appendChild(kasten);
	}

	/*
	 * Two things can take a row out of a tab.
	 *
	 * The module's own switch: everything below it only means something while the
	 * module runs, so off, the rest is simply not there - a page of settings for
	 * something that is not running only invites the question why they do nothing.
	 * A tab carries such a switch only when exactly ONE of its fields is a module
	 * toggle; the Sonstiges tab holds three modules side by side and none of them
	 * governs the others.
	 *
	 * And a single field may hang on another tick of its own through "needs" - the
	 * second colour for Kaja's workshop has nothing to set while the two halves are
	 * not being told apart.
	 */
	var master = settingsMasterField(tab);
	var rows = [];
	var gruppen = { };

	for (var i = 0; i < tab.fields.length; i++) {
		var row = settingsField(tab.fields[i]);
		rows.push(row);

		//Ticks that belong together and carry nothing but a short name stand side by
		//side: four of them in a column are mostly empty space. They share a "reihe",
		//and the frame around them takes over the dividing line.
		var reihe = tab.fields[i].reihe;
		if (!reihe) {
			/*
			 * A group of sub-options belongs to the tick above it. So that tick draws no
			 * line of its own - the line under the group closes the whole block, and no
			 * rule runs between a heading and what it governs.
			 *
			 * The same holds for a single field hanging off the one above it through
			 * "needs". In a tab where every field belongs to the same module that says
			 * nothing, but where several modules stand side by side it is the only thing
			 * saying which sub-option belongs to which of them.
			 */
			var naechste = tab.fields[i + 1];
			if (naechste && (naechste.reihe
					|| settingsNeedsList(naechste)
						.indexOf(tab.fields[i].path) > -1)) {
				row.style.cssText = 'margin:0 0 6px;padding:0;';
				//Only while what belongs to it is showing. Folded away, the tick stands
				//alone again and needs its line back, or it would run into the next one.
				row.setAttribute('data-mm-kopf', 'ja');
			}
			pane.appendChild(row);
			continue;
		}

		if (!gruppen[reihe]) {
			gruppen[reihe] = { kasten: mmEl('div',
				'display:flex;flex-wrap:wrap;gap:2px 20px;margin:0 0 12px;'
				+ 'padding:0 0 10px;border-bottom:1px solid rgba(168,148,84,0.25);'),
				zeilen: [] };
			gruppen[reihe].kasten.setAttribute('data-mm-reihe', reihe);
			pane.appendChild(gruppen[reihe].kasten);
		}
		row.style.cssText = 'margin:0;padding:0;';
		gruppen[reihe].kasten.appendChild(row);
		gruppen[reihe].zeilen.push(row);
	}

	//Some tabs need more than ticks and numbers - the auto login, for one, keeps a
	//list of worlds with credentials. What such a tab builds itself hangs on the same
	//switch as its other rows and writes along at the same "Speichern": nobody wants
	//two buttons with the same label doing different things.
	var eigenes = tab.build ? tab.build() : null;
	var teil = eigenes ? eigenes.node : null;

	if (teil)
		pane.appendChild(teil);
	if (eigenes && eigenes.save)
		SETTINGS_EXTRA_SAVE.push(eigenes.save);

	settingsFollowSwitches(pane, tab, rows, master, teil, gruppen);
	return pane;
}

//The one field that switches this tab's module. A tab holding more than one
//module says which of them is the master; where it says nothing and more than one
//module is in the tab, none of them governs the others.
function settingsMasterField(tab) {
	var found = null;

	for (var i = 0; i < tab.fields.length; i++) {
		if (tab.master && tab.fields[i].path === tab.master)
			return tab.fields[i];

		for (var j = 0; j < MODULES.length; j++)
			if (MODULES[j].toggle && MODULES[j].toggle === tab.fields[i].path) {
				if (found)
					found = 'mehrere';
				else
					found = tab.fields[i];
			}
	}

	return (found === 'mehrere') ? null : found;
}

function settingsNeedsList(field) {
	if (!field.needs)
		return [];
	return settingsIsList(field.needs) ? field.needs : [field.needs];
}

/*
 * A "needs" entry may start with "!", which means the field wants that tick OFF,
 * and it may name a value with an "=", which means the dropdown it points at has
 * to stand on exactly that.
 */
function settingsNeedsPath(entry) {
	var text = String(entry);

	if (text.charAt(0) === '!')
		text = text.slice(1);
	var gleich = text.indexOf('=');
	return (gleich < 0) ? text : text.slice(0, gleich);
}

function settingsNeedsMet(gate, entry) {
	if (!gate)
		return true;

	var text = String(entry);
	var nein = text.charAt(0) === '!';
	var gleich = text.indexOf('=');
	var erfuellt = (gleich < 0)
		? !!gate.checked : (String(gate.value) === text.slice(gleich + 1));

	return nein ? !erfuellt : erfuellt;
}

//The other half of a pair that cannot both stand on, or nothing where the switch
//is in no such pair.
function settingsExclusivePartner(path) {
	for (var i = 0; i < SETTINGS_EXCLUSIVE.length; i++) {
		if (SETTINGS_EXCLUSIVE[i][0] === path)
			return SETTINGS_EXCLUSIVE[i][1];
		if (SETTINGS_EXCLUSIVE[i][1] === path)
			return SETTINGS_EXCLUSIVE[i][0];
	}
	return '';
}

/*
 * Put the partner out. It usually sits in another tab, so the box is looked for in
 * the whole window and not in the pane at hand.
 *
 * A tick set from code tells nobody: everything hanging off that switch would stay
 * on the screen although the switch below it is gone. So the box is sent an event
 * of its own, and the tab it stands in folds itself up the way it would under a
 * real click.
 */
function settingsExclusiveClear(path) {
	var partner = settingsExclusivePartner(path);
	if (!partner)
		return;

	if (settingsDraft)
		settingsDraft[partner] = false;

	var fenster = document.getElementById('mm_settings_overlay');
	var box = fenster
		? fenster.querySelector('input[type="checkbox"][data-mm-path="' + partner + '"]')
		: null;

	if (!box || !box.checked)
		return;
	box.checked = false;
	mmFire(box, 'change');
}

function settingsFollowSwitches(pane, tab, rows, master, eigenes, gruppen) {
	//The element a "needs" entry points at. Usually a tick; where the entry names a
	//value with an "=", it is the dropdown that holds it.
	function box(path) {
		return pane.querySelector('input[type="checkbox"][data-mm-path="' + path + '"]')
			|| pane.querySelector('select[data-mm-path="' + path + '"]');
	}

	var masterBox = master ? box(master.path) : null;
	var gates = masterBox ? [masterBox] : [];

	function show() {
		for (var i = 0; i < tab.fields.length; i++) {
			var field = tab.fields[i];

			//A field marked "frei" does not hang on the tab's own switch. That is for
			//the second module in a tab: colouring the ranks reads the game's table and
			//goes on working when our own page building is off, so its settings have to
			//stay reachable.
			var hide = masterBox && field !== master && field.frei !== true
				&& !masterBox.checked;

			//"needs" may be one path or several: the source list in the tooltip hangs on
			//the tooltip, and that in turn on the module. Only once everything is ticked
			//does the field stand there.
			var needs = settingsNeedsList(field);
			for (var n = 0; !hide && n < needs.length; n++)
				hide = !settingsNeedsMet(box(settingsNeedsPath(needs[n])), needs[n]);
			rows[i].hidden = !!hide;
		}

		//The line under a tick that governs the row below it: gone while that row is
		//there, back as soon as it is not.
		for (i = 0; i < rows.length; i++) {
			if (rows[i].getAttribute('data-mm-kopf') !== 'ja')
				continue;

			var offen = false;
			for (var k = i + 1; k < rows.length; k++) {
				//Only the run of rows that hangs on this one counts. The first row that
				//does not ends it, whatever comes after.
				if (!tab.fields[k].reihe && settingsNeedsList(tab.fields[k])
						.indexOf(tab.fields[i].path) < 0)
					break;
				if (!rows[k].hidden)
					offen = true;
			}
			rows[i].style.cssText = offen
				? 'margin:0 0 6px;padding:0;'
				: SETTINGS_FIELD_CSS;
		}
		if (eigenes)
			eigenes.hidden = !!(masterBox && !masterBox.checked);

		//A frame whose every tick is gone leaves its dividing line behind and a gap
		//where nothing stands.
		for (var key in (gruppen || { })) {
			var leer = true;
			for (k = 0; k < gruppen[key].zeilen.length; k++)
				if (!gruppen[key].zeilen[k].hidden)
					leer = false;
			gruppen[key].kasten.hidden = leer;
		}
	}

	for (var i = 0; i < tab.fields.length; i++) {
		var needs = settingsNeedsList(tab.fields[i]);
		for (var n = 0; n < needs.length; n++) {
			var gate = box(settingsNeedsPath(needs[n]));
			if (gate && gates.indexOf(gate) < 0)
				gates.push(gate);
		}
	}

	for (var j = 0; j < gates.length; j++)
		gates[j].addEventListener('change', show, false);

	show();
}

//How a row of settings stands when nothing else is said about it: a little air
//below and a hairline under that.
var SETTINGS_FIELD_CSS = 'margin:0 0 12px;padding:0 0 10px;'
	+ 'border-bottom:1px solid rgba(168,148,84,0.25);';

function settingsField(field) {
	var row = mmEl('div', SETTINGS_FIELD_CSS);
	row.setAttribute('data-mm-field', field.path);

	//A field marked "trenner" opens a block of its own: a rule above it sets it
	//apart from the list it follows.
	if (field.trenner)
		row.style.cssText += 'margin-top:16px;padding-top:12px;'
			+ 'border-top:1px solid rgba(168,148,84,0.5);';

	var line = mmEl('label', 'display:flex;align-items:center;gap:8px;cursor:pointer;');
	var input;

	if (field.type == 'bool') {
		input = mmEl('input');
		input.type = 'checkbox';
		input.checked = settingsDraft[field.path] === true;
		input.style.cssText = 'margin:0;';
		input.addEventListener('change', function () {
			settingsDraft[field.path] = input.checked;

			//Some switches shut each other out. Only the one just switched on has to
			//look: switching something off can never make a forbidden pair.
			if (input.checked)
				settingsExclusiveClear(field.path);
		}, true);
		line.appendChild(input);
		line.appendChild(mmEl('span', 'font-weight:bold;', field.label));
	} else if (field.type == 'colour') {
		//Not a <label> here: the row carries a button of its own, and inside a label
		//every click would also open the colour picker.
		line = mmEl('div', 'display:flex;align-items:center;gap:8px;');
		line.appendChild(mmEl('span', 'font-weight:bold;flex:1;', field.label));

		//A sample in the colour itself, so the effect can be judged without closing
		//the window - the picker's own swatch is tiny and says nothing about how
		//bold text looks against the game's dark background.
		var sample = mmEl('span', 'font-weight:bold;padding:1px 6px;border-radius:2px;'
			+ 'background:' + SETTINGS_SKIN.panel + ';color:' + settingsDraft[field.path] + ';',
			'Beispiel');
		line.appendChild(sample);

		input = mmEl('input');
		input.type = 'color';
		input.value = settingsColourValue(settingsDraft[field.path]) || '#000000';
		input.style.cssText = 'width:44px;height:22px;padding:0;cursor:pointer;'
			+ 'background:' + SETTINGS_SKIN.panel + ';'
			+ 'border:1px solid ' + SETTINGS_SKIN.border + ';border-radius:2px;';
		input.addEventListener('input', function () {
			settingsDraft[field.path] = input.value;
			sample.style.color = input.value;
		}, true);
		line.appendChild(input);

		var back = settingsButton('Vorgabe');
		back.style.cssText += 'padding:2px 8px;font-size:11px;';
		back.addEventListener('click', function (event) {
			if (event && event.preventDefault)
				event.preventDefault();
			var def = SETTINGS_DEFAULTS[field.path];
			settingsDraft[field.path] = def;
			input.value = settingsColourValue(def) || '#000000';
			sample.style.color = def;
		}, true);
		line.appendChild(back);
	} else if (field.type == 'choice') {
		line.appendChild(mmEl('span', 'font-weight:bold;flex:1;', field.label));
		input = mmEl('select');
		input.style.cssText = 'font-family:inherit;font-size:12px;padding:2px 4px;'
			+ 'background:' + SETTINGS_SKIN.panel + ';color:' + SETTINGS_SKIN.ink + ';'
			+ 'border:1px solid ' + SETTINGS_SKIN.border + ';border-radius:2px;';

		for (var c = 0; c < field.options.length; c++) {
			var choice = mmEl('option', '', field.options[c].label);
			choice.value = field.options[c].value;
			input.appendChild(choice);
		}
		input.value = settingsDraft[field.path];

		input.setAttribute('data-mm-path', field.path);
		input.addEventListener('change', function () {
			settingsDraft[field.path] = input.value;
		}, true);
		line.appendChild(input);
	} else if (field.type == 'order') {
		//Not a <label>: the rows carry buttons, and inside a label every click would
		//also count as a click on the field.
		line = mmEl('div');
		line.appendChild(mmEl('div', 'font-weight:bold;margin:0 0 6px;', field.label));
		line.appendChild(settingsOrderList(field));
	} else if (field.type == 'list') {
		line = mmEl('div');
		line.appendChild(mmEl('div', 'font-weight:bold;margin:0 0 6px;', field.label));
		line.appendChild(settingsWordList(field));
	} else if (field.type == 'pairs') {
		line = mmEl('div');
		line.appendChild(mmEl('div', 'font-weight:bold;margin:0 0 6px;', field.label));
		line.appendChild(settingsPairList(field));
	} else if (field.type == 'farbpaare') {
		line = mmEl('div');
		line.appendChild(mmEl('div', 'font-weight:bold;margin:0 0 6px;', field.label));
		line.appendChild(settingsColourPairList(field));
	} else if (field.type == 'steps') {
		line = mmEl('div');
		line.appendChild(mmEl('div', 'font-weight:bold;margin:0 0 6px;', field.label));
		line.appendChild(settingsStepList(field));
	} else if (field.type == 'text') {
		line = mmEl('div');
		line.appendChild(mmEl('div', 'font-weight:bold;margin:0 0 6px;', field.label));

		input = mmEl('input');
		input.type = 'text';
		input.value = settingsDraft[field.path] == null ? '' : settingsDraft[field.path];
		if (field.placeholder)
			input.placeholder = field.placeholder;
		input.style.cssText = 'width:100%;box-sizing:border-box;font-family:inherit;'
			+ 'font-size:12px;padding:3px 5px;'
			+ 'background:' + SETTINGS_SKIN.panel + ';color:' + SETTINGS_SKIN.ink + ';'
			+ 'border:1px solid ' + SETTINGS_SKIN.border + ';border-radius:2px;';
		input.addEventListener('input', function () {
			settingsDraft[field.path] = input.value;
		}, true);
		line.appendChild(input);
	} else {
		line.appendChild(mmEl('span', 'font-weight:bold;flex:1;', field.label));
		input = mmEl('input');
		input.type = 'number';
		if (field.min != null) input.min = field.min;
		if (field.max != null) input.max = field.max;
		if (field.step != null) input.step = field.step;
		input.value = settingsDraft[field.path];
		input.style.cssText = 'width:90px;font-family:inherit;font-size:12px;padding:2px 4px;'
			+ 'background:' + SETTINGS_SKIN.panel + ';color:' + SETTINGS_SKIN.ink + ';'
			+ 'border:1px solid ' + SETTINGS_SKIN.border + ';border-radius:2px;';
		input.addEventListener('change', function () {
			var num = parseInt(input.value, 10);
			if (isNaN(num))
				num = SETTINGS_DEFAULTS[field.path];
			if (field.min != null) num = Math.max(field.min, num);
			if (field.max != null) num = Math.min(field.max, num);
			input.value = num;
			settingsDraft[field.path] = num;
		}, true);
		line.appendChild(input);
	}

	if (input)
		input.setAttribute('data-mm-path', field.path);
	row.appendChild(line);

	if (field.hint)
		row.appendChild(mmEl('div',
			'opacity:0.65;font-size:11px;line-height:1.45;margin:4px 0 0;', field.hint));

	var written = settingsDefaultText(field);
	if (written)
		row.appendChild(mmEl('div', 'opacity:0.45;font-size:11px;margin:2px 0 0;',
			'Default: ' + written));

	return row;
}

//What the field started out as, in words. An order has no short form worth
//printing - the list itself already shows where things stand - so it says nothing.
function settingsDefaultText(field) {
	var def = SETTINGS_DEFAULTS[field.path];

	if (field.type == 'order' || field.type == 'list' || field.type == 'steps'
			|| field.type == 'pairs' || field.type == 'farbpaare')
		return '';
	if (field.type == 'text')
		return def ? String(def) : 'leer';
	if (field.type == 'choice') {
		for (var i = 0; i < field.options.length; i++)
			if (field.options[i].value === def)
				return field.options[i].label;
		return String(def);
	}
	if (typeof def == 'boolean')
		return def ? 'ein' : 'aus';

	return String(def);
}

/* --- A list the reader lengthens themselves -------------------------------- *
 * One line per entry, each with its own box and a minus to throw it away, and a
 * plus underneath for one more. The boxes stay while the window is open, so
 * several names can be typed one after another without the list closing itself
 * around them.
 *
 * Typing writes straight into the entry it belongs to and redraws nothing: a
 * redraw on every keystroke would take the cursor out of the box being typed in.
 * Only adding and removing redraw.
 * ------------------------------------------------------------------------- */

function settingsWordList(field) {
	var box = mmEl('div');

	function draw(focusIndex) {
		mmEmpty(box);

		var values = settingsDraft[field.path] || [];
		var boxes = [];
		for (var i = 0; i < values.length; i++) {
			var row = settingsWordRow(field, values, i, draw);
			box.appendChild(row);
			boxes.push(row.querySelector('input'));
		}

		box.appendChild(settingsWordAdd(field, draw));

		//A freshly added line is where the reader wants to be next.
		if (focusIndex != null && boxes[focusIndex] && boxes[focusIndex].focus)
			boxes[focusIndex].focus();
	}

	draw(null);
	return box;
}

function settingsWordRow(field, values, index, draw) {
	var row = mmEl('div', 'display:flex;align-items:center;gap:6px;margin:0 0 4px;');

	var input = mmEl('input');
	input.type = 'text';
	input.value = values[index] == null ? '' : values[index];
	if (field.placeholder)
		input.placeholder = field.placeholder;
	input.style.cssText = 'flex:1;min-width:0;font-family:inherit;font-size:12px;'
		+ 'padding:3px 5px;'
		+ 'background:' + SETTINGS_SKIN.panel + ';color:' + SETTINGS_SKIN.ink + ';'
		+ 'border:1px solid ' + SETTINGS_SKIN.border + ';border-radius:2px;';
	input.addEventListener('input', function () {
		values[index] = input.value;
	}, true);
	row.appendChild(input);

	var drop = settingsSmallButton('−', true, function () {
		values.splice(index, 1);
		draw(null);
	});
	drop.title = 'Diese Zeile entfernen';
	row.appendChild(drop);

	return row;
}

function settingsWordAdd(field, draw) {
	var row = mmEl('div', 'display:flex;align-items:center;gap:6px;');

	var add = settingsSmallButton('+', true, function () {
		var values = settingsDraft[field.path] || [];
		values.push('');
		settingsDraft[field.path] = values;
		draw(values.length - 1);
	});
	add.title = field.addLabel || 'Zeile hinzufügen';
	row.appendChild(add);
	row.appendChild(mmEl('span', 'opacity:0.6;font-size:11px;',
		field.addLabel || 'Zeile hinzufügen'));

	return row;
}

/* --- A list of pairs ------------------------------------------------------- *
 * A name and what belongs to it, one line each - a button and the code it writes.
 * Built like the word list above, with two boxes instead of one, and typing writes
 * straight into the entry rather than redrawing: a redraw between two keystrokes
 * loses the cursor.
 * ------------------------------------------------------------------------- */

function settingsPairList(field) {
	var box = mmEl('div');

	function draw(focusIndex) {
		mmEmpty(box);

		var paare = settingsDraft[field.path] || [];
		var ersten = [];
		for (var i = 0; i < paare.length; i++) {
			var row = settingsPairRow(field, paare, i, draw);
			box.appendChild(row);
			ersten.push(row.querySelector('input'));
		}

		box.appendChild(settingsPairAdd(field, draw));
		if (focusIndex != null && ersten[focusIndex] && ersten[focusIndex].focus)
			ersten[focusIndex].focus();
	}

	draw(null);
	return box;
}

function settingsPairRow(field, paare, index, draw) {
	var row = mmEl('div', 'display:flex;align-items:center;gap:6px;margin:0 0 4px;');

	row.appendChild(settingsPairBox(paare[index], 'name',
		field.linksHalt || field.links || '', '0 0 110px'));
	row.appendChild(settingsPairBox(paare[index], 'code',
		field.rechtsHalt || field.rechts || '', '1'));

	var drop = settingsSmallButton('−', true, function () {
		paare.splice(index, 1);
		draw(null);
	});
	drop.title = 'Diesen Knopf entfernen';
	row.appendChild(drop);

	return row;
}

function settingsPairBox(paar, key, platzhalter, flex) {
	var input = mmEl('input');

	input.type = 'text';
	input.value = (paar && paar[key] != null) ? paar[key] : '';
	if (platzhalter)
		input.placeholder = platzhalter;
	input.style.cssText = 'flex:' + flex + ';min-width:0;font-family:inherit;'
		+ 'font-size:12px;padding:3px 5px;'
		+ 'background:' + SETTINGS_SKIN.panel + ';color:' + SETTINGS_SKIN.ink + ';'
		+ 'border:1px solid ' + SETTINGS_SKIN.border + ';border-radius:2px;';
	input.setAttribute('data-mm-paar', key);
	input.addEventListener('input', function () {
		paar[key] = input.value;
	}, true);
	return input;
}

function settingsPairAdd(field, draw) {
	var row = mmEl('div', 'display:flex;align-items:center;gap:6px;');

	var add = settingsSmallButton('+', true, function () {
		var paare = settingsDraft[field.path] || [];
		paare.push({ name: '', code: '' });
		settingsDraft[field.path] = paare;
		draw(paare.length - 1);
	});
	add.title = field.addLabel || 'Zeile hinzufügen';
	row.appendChild(add);
	row.appendChild(mmEl('span', 'opacity:0.6;font-size:11px;',
		field.addLabel || 'Zeile hinzufügen'));

	return row;
}

/* --- A list of names, each with a colour ---------------------------------- *
 * The same shape as the pair list above, only the right half is not a second box
 * to type into but a colour. Used where a name is to be recognised by its colour
 * and the name alone would say nothing about how it will look.
 * -------------------------------------------------------------------------- */

function settingsColourPairList(field) {
	var box = mmEl('div');

	function draw(focusIndex) {
		mmEmpty(box);

		var paare = settingsDraft[field.path] || [];
		var ersten = [];

		for (var i = 0; i < paare.length; i++) {
			var row = settingsColourPairRow(field, paare, i, draw);
			box.appendChild(row);
			ersten.push(row.querySelector('[data-mm-paar="name"]'));
		}

		box.appendChild(settingsColourPairAdd(field, draw));
		if (focusIndex != null && ersten[focusIndex] && ersten[focusIndex].focus)
			ersten[focusIndex].focus();
	}

	draw(null);
	return box;
}

function settingsColourPairRow(field, paare, index, draw) {
	var row = mmEl('div', 'display:flex;align-items:center;gap:6px;margin:0 0 4px;');
	var paar = paare[index] || { };

	row.appendChild(settingsNameBox(field, paar));

	var farbe = mmEl('input');
	farbe.type = 'color';
	farbe.value = settingsColourValue(paar.code) || '#445544';
	farbe.setAttribute('data-mm-paar', 'code');
	farbe.style.cssText = 'width:44px;height:22px;padding:0;cursor:pointer;flex:0 0 auto;'
		+ 'background:' + SETTINGS_SKIN.panel + ';'
		+ 'border:1px solid ' + SETTINGS_SKIN.border + ';border-radius:2px;';
	farbe.addEventListener('input', function () {
		paar.code = farbe.value;
	}, true);
	row.appendChild(farbe);

	var drop = settingsSmallButton('−', true, function () {
		paare.splice(index, 1);
		draw(null);
	});
	drop.title = 'Diese Zeile entfernen';
	row.appendChild(drop);

	return row;
}

/*
 * The left half of such a row. Where the field can say which names are worth
 * offering, they are offered: typing a hero's name letter by letter and getting
 * it wrong once is enough to wonder for a while why nothing is coloured. Where it
 * cannot, or where it knows none, a box to type into is left.
 *
 * Whatever already stands in the row is always among the choices, even when it is
 * not one the field knows - otherwise opening the window would quietly change a
 * setting.
 */
function settingsNameBox(field, paar) {
	var namen = (typeof field.auswahl == 'function') ? field.auswahl() : null;
	var jetzt = (paar && paar.name != null) ? String(paar.name) : '';

	if (!settingsIsList(namen) || !namen.length)
		return settingsPairBox(paar, 'name', field.links || '', '1');

	var liste = mmEl('select');
	liste.setAttribute('data-mm-paar', 'name');
	liste.style.cssText = 'flex:1;min-width:0;font-family:inherit;font-size:12px;'
		+ 'padding:2px 4px;'
		+ 'background:' + SETTINGS_SKIN.panel + ';color:' + SETTINGS_SKIN.ink + ';'
		+ 'border:1px solid ' + SETTINGS_SKIN.border + ';border-radius:2px;';

	var offen = namen.slice();
	if (jetzt && offen.indexOf(jetzt) < 0)
		offen.unshift(jetzt);

	var leer = mmEl('option', '', field.links || 'bitte wählen');
	leer.value = '';
	liste.appendChild(leer);

	for (var i = 0; i < offen.length; i++) {
		var eintrag = mmEl('option', '', offen[i]);
		eintrag.value = offen[i];
		liste.appendChild(eintrag);
	}

	liste.value = jetzt;
	liste.addEventListener('change', function () {
		paar.name = liste.value;
	}, true);

	return liste;
}

//The first colour of the field's own list that no row has yet; once all are
//taken, the list starts over.
function settingsNextColour(field, paare) {
	var farben = settingsIsList(field.farben) && field.farben.length
		? field.farben : ['#445544'];
	var vergeben = { };

	for (var i = 0; i < paare.length; i++)
		if (paare[i] && paare[i].code)
			vergeben[String(paare[i].code).toLowerCase()] = true;

	for (var j = 0; j < farben.length; j++)
		if (!vergeben[farben[j].toLowerCase()])
			return farben[j];
	return farben[paare.length % farben.length];
}

function settingsColourPairAdd(field, draw) {
	var row = mmEl('div', 'display:flex;align-items:center;gap:6px;');

	var add = settingsSmallButton('+', true, function () {
		var paare = settingsDraft[field.path] || [];
		paare.push({ name: '', code: settingsNextColour(field, paare) });
		settingsDraft[field.path] = paare;
		draw(paare.length - 1);
	});
	add.title = field.addLabel || 'Helden hinzufügen';
	row.appendChild(add);
	row.appendChild(mmEl('span', 'opacity:0.6;font-size:11px;',
		field.addLabel || 'Helden hinzufügen'));

	return row;
}

/* --- A list of rounding steps ---------------------------------------------- *
 * The same idea as the word list above, only each line holds two numbers instead
 * of one: from which amount on, and to what it is then rounded. Typing writes
 * straight into the step it belongs to and redraws nothing, for the same reason.
 * ------------------------------------------------------------------------- */

function settingsStepList(field) {
	var box = mmEl('div');

	function draw(focusIndex) {
		mmEmpty(box);

		var steps = settingsDraft[field.path] || [];
		var first = null;
		for (var i = 0; i < steps.length; i++) {
			var row = settingsStepRow(field, steps, i, draw);
			box.appendChild(row);
			if (i === focusIndex)
				first = row.querySelector('input[type="number"]');
		}

		box.appendChild(settingsStepAdd(field, draw));
		if (first && first.focus)
			first.focus();
	}

	draw(null);
	return box;
}

function settingsStepRow(field, steps, index, draw) {
	var row = mmEl('div', 'display:flex;align-items:center;gap:6px;margin:0 0 4px;');

	row.appendChild(mmEl('span', 'opacity:0.7;', 'ab'));
	row.appendChild(settingsStepNumber(steps[index], 'ab', 0));
	row.appendChild(mmEl('span', 'opacity:0.7;flex:1;', 'Gold auf'));
	row.appendChild(settingsStepNumber(steps[index], 'auf', 1));
	row.appendChild(mmEl('span', 'opacity:0.7;', 'runden'));

	var drop = settingsSmallButton('−', true, function () {
		steps.splice(index, 1);
		draw(null);
	});
	drop.title = 'Diese Stufe entfernen';
	row.appendChild(drop);

	return row;
}

function settingsStepNumber(step, key, least) {
	var input = mmEl('input');
	input.type = 'number';
	input.min = least;
	input.value = step[key];
	input.style.cssText = 'width:70px;font-family:inherit;font-size:12px;padding:2px 4px;'
		+ 'background:' + SETTINGS_SKIN.panel + ';color:' + SETTINGS_SKIN.ink + ';'
		+ 'border:1px solid ' + SETTINGS_SKIN.border + ';border-radius:2px;';
	input.addEventListener('input', function () {
		var number = parseInt(input.value, 10);
		step[key] = isNaN(number) ? least : Math.max(least, number);
	}, true);
	return input;
}

function settingsStepAdd(field, draw) {
	var row = mmEl('div', 'display:flex;align-items:center;gap:6px;');

	var add = settingsSmallButton('+', true, function () {
		var steps = settingsDraft[field.path] || [];
		steps.push({ ab: 0, auf: 10 });
		settingsDraft[field.path] = steps;
		draw(steps.length - 1);
	});
	add.title = field.addLabel || 'Stufe hinzufügen';
	row.appendChild(add);
	row.appendChild(mmEl('span', 'opacity:0.6;font-size:11px;',
		field.addLabel || 'Stufe hinzufügen'));

	return row;
}

/* --- The order of a handful of entries ------------------------------------ *
 * Each entry on its own line with two arrows beside it. Moving one redraws the
 * list, which keeps the buttons and the draft in step without either having to
 * know where anything sits.
 * ------------------------------------------------------------------------- */

function settingsOrderList(field) {
	var box = mmEl('div', 'border:1px solid rgba(168,148,84,0.35);border-radius:2px;');

	function move(from, to) {
		var order = settingsDraft[field.path].slice();
		if (to < 0 || to >= order.length)
			return;
		var moved = order.splice(from, 1)[0];
		order.splice(to, 0, moved);
		settingsDraft[field.path] = order;
		draw();
	}

	function draw() {
		mmEmpty(box);

		var order = settingsDraft[field.path] || [];
		for (var i = 0; i < order.length; i++)
			box.appendChild(settingsOrderRow(field, order[i], i, order.length, move));
	}

	draw();
	return box;
}

function settingsOrderRow(field, value, index, total, move) {
	var row = mmEl('div', 'display:flex;align-items:center;gap:6px;padding:3px 6px;'
		+ (index ? 'border-top:1px solid rgba(168,148,84,0.2);' : ''));

	row.appendChild(mmEl('span', 'opacity:0.5;width:14px;', String(index + 1) + '.'));
	row.appendChild(mmEl('span', 'flex:1;', settingsOrderLabel(field, value)));

	row.appendChild(settingsSmallButton('▲', index > 0, function () {
		move(index, index - 1);
	}));
	row.appendChild(settingsSmallButton('▼', index + 1 < total, function () {
		move(index, index + 1);
	}));

	return row;
}

//The small square buttons of the list editors - a plus, a minus, an arrow.
function settingsSmallButton(sign, usable, act) {
	var button = mmEl('input');
	button.type = 'button';
	button.value = sign;
	button.disabled = !usable;
	button.style.cssText = 'font-family:inherit;font-size:11px;line-height:1;'
		+ 'padding:2px 6px;cursor:' + (usable ? 'pointer' : 'default') + ';'
		+ 'opacity:' + (usable ? '1' : '0.3') + ';'
		+ 'background:' + SETTINGS_SKIN.panel + ';color:' + SETTINGS_SKIN.ink + ';'
		+ 'border:1px solid ' + SETTINGS_SKIN.border + ';border-radius:2px;';
	button.addEventListener('click', function (event) {
		if (event && event.preventDefault)
			event.preventDefault();
		act();
	}, true);
	return button;
}

function settingsOrderLabel(field, value) {
	for (var i = 0; i < field.options.length; i++)
		if (field.options[i].value === value)
			return field.options[i].label;
	return String(value);
}

/* --- The message list ----------------------------------------------------- *
 * At the bottom of the first tab: the newest entry on top, links where there are
 * links, and one button to empty it.
 * ------------------------------------------------------------------------- */

function settingsMessagePane() {
	var box = mmEl('div', 'margin:18px 0 0;');
	box.appendChild(mmEl('div', 'font-weight:bold;margin:0 0 8px;', 'Meldungen'));

	var list = mmMessagesLoad();

	if (!list.length) {
		box.appendChild(mmEl('div', 'opacity:0.65;font-size:11px;',
			'Hier erscheinen etwaige Fehlermeldungen.'));
		return box;
	}

	var scroller = mmEl('div', 'max-height:180px;overflow-y:auto;padding:6px 8px;'
		+ 'border-radius:2px;background:' + SETTINGS_SKIN.panel + ';'
		+ 'border:1px solid rgba(168,148,84,0.4);');

	//Newest first: on a long read-in the interesting line is the last one.
	for (var i = list.length - 1; i >= 0; i--) {
		var entry = list[i];
		var row = mmEl('div', 'margin:0 0 5px;line-height:1.4;');

		var when = new Date(entry.t);
		var stamp = ('0' + when.getHours()).slice(-2) + ':' + ('0' + when.getMinutes()).slice(-2);
		row.appendChild(mmEl('span', 'opacity:0.45;margin-right:6px;', stamp));

		if (entry.l) {
			var link = mmEl('a', 'color:' + SETTINGS_SKIN.ink + ';', entry.m);
			link.href = entry.l;
			link.target = '_blank';
			row.appendChild(link);
		} else {
			row.appendChild(mmEl('span', '', entry.m));
		}
		scroller.appendChild(row);
	}
	box.appendChild(scroller);

	var clear = settingsButton('Meldungen löschen');
	clear.style.marginLeft = '0';
	clear.style.marginTop = '8px';
	clear.addEventListener('click', function () {
		mmMessagesClear();
		settingsClose();
	}, true);
	box.appendChild(clear);

	return box;
}

/* --- Data and maintenance ------------------------------------------------- */

//How much this world occupies. Counted, not guessed: key plus value in characters.
//One block of the list: a heading and a line per kind, with count and size. An
//empty block is left out, so a player with one world sees one block.
function settingsStorageBlock(titel, zeilen, leer) {
	var kasten = mmEl('div', 'margin:0 0 10px;');

	kasten.appendChild(mmEl('div',
		'font-weight:bold;font-size:11px;margin:0 0 4px;opacity:0.85;', titel));

	if (!zeilen.length) {
		kasten.appendChild(mmEl('div',
			'font-size:11px;opacity:0.6;margin:0 0 2px;', leer));
		return kasten;
	}

	for (var i = 0; i < zeilen.length; i++) {
		var zeile = mmEl('div', 'display:flex;justify-content:space-between;'
			+ 'align-items:baseline;gap:12px;font-size:11px;margin:0 0 2px;');
		zeile.setAttribute('data-mm-storage', zeilen[i].name);
		zeile.appendChild(mmEl('span', '',
			zeilen[i].name + (zeilen[i].bleibt ? ' (bleibt stehen)' : '')));

		var rechts = mmEl('span', 'display:flex;align-items:baseline;gap:6px;'
			+ 'white-space:nowrap;');
		rechts.appendChild(mmEl('span', 'opacity:0.7;',
			zeilen[i].zahl + (zeilen[i].zahl === 1 ? ' Eintrag, ' : ' Einträge, ')
			+ zeilen[i].kb + ' KB'));
		if (!zeilen[i].bleibt)
			rechts.appendChild(settingsStorageDelete(zeilen[i]));
		zeile.appendChild(rechts);

		kasten.appendChild(zeile);
	}
	return kasten;
}

//The cross behind one line. It takes that line and nothing else, so a single
//module can be started over without throwing away what all the others collected.
function settingsStorageDelete(zeile) {
	var kreuz = mmEl('span', 'cursor:pointer;opacity:0.55;padding:0 2px;'
		+ 'font-weight:bold;line-height:1;', 'X');
	kreuz.setAttribute('data-mm-storage-del', zeile.name);
	kreuz.setAttribute('title', '"' + zeile.name + '" löschen');

	kreuz.addEventListener('mouseover', function () { kreuz.style.opacity = '1'; }, true);
	kreuz.addEventListener('mouseout', function () { kreuz.style.opacity = '0.55'; }, true);
	kreuz.addEventListener('click', function () {
		if (deleteStorageRow(zeile.block, zeile.name))
			settingsRefreshStorage();
	}, true);

	return kreuz;
}

//The list, drawn again after something was taken out of it.
function settingsRefreshStorage() {
	var alt = document.querySelector('[data-mm-settings="speicher"]');
	if (alt && alt.parentNode)
		alt.parentNode.replaceChild(settingsStorageList(), alt);
}

function settingsStorageList() {
	var kasten = mmEl('div', 'margin:0 0 12px;padding:8px 10px;border-radius:2px;'
		+ 'background:' + SETTINGS_SKIN.panel + ';border:1px solid rgba(168,148,84,0.4);');
	kasten.setAttribute('data-mm-settings', 'speicher');

	var bestand = storageInventory();
	if (!bestand) {
		kasten.appendChild(mmEl('div', '',
			'Der Umfang liess sich nicht ermitteln.'));
		return kasten;
	}

	kasten.appendChild(settingsStorageBlock('Welt ' + worldName(), bestand.welt,
		'Für diese Welt ist noch nichts gespeichert.'));
	if (bestand.andere.length)
		kasten.appendChild(settingsStorageBlock('Andere Welten', bestand.andere, ''));
	kasten.appendChild(settingsStorageBlock('Weltübergreifend', bestand.ueber,
		'Noch nichts gespeichert.'));
	kasten.appendChild(settingsStorageTotal(bestand));
	return kasten;
}

//The sum under the blocks. Three lists of kilobytes say nothing about whether the
//whole thing is large, and that is the one question this list is opened for.
function settingsStorageTotal(bestand) {
	var zahl = 0;
	var zeichen = 0;
	var toepfe = [bestand.welt, bestand.andere, bestand.ueber];

	for (var i = 0; i < toepfe.length; i++)
		for (var j = 0; j < toepfe[i].length; j++) {
			zahl += toepfe[i][j].zahl;
			zeichen += toepfe[i][j].zeichen;
		}

	var zeile = mmEl('div', 'display:flex;justify-content:space-between;'
		+ 'gap:12px;font-size:11px;font-weight:bold;margin:6px 0 0;padding:5px 0 0;'
		+ 'border-top:1px solid rgba(168,148,84,0.4);');
	zeile.setAttribute('data-mm-storage-total', String(zahl));
	zeile.appendChild(mmEl('span', '', 'Gesamt'));
	zeile.appendChild(mmEl('span', 'white-space:nowrap;',
		zahl + (zahl === 1 ? ' Eintrag, ' : ' Einträge, ')
		+ Math.round(zeichen / 1024) + ' KB'));
	return zeile;
}

function settingsBuildDataPane() {
	var pane = mmEl('div');

	pane.appendChild(mmEl('div', 'opacity:0.75;margin:2px 0 10px;line-height:1.45;',
		'Alles, was das Skript gespeichert hat, und was es zu berichten hatte. Die '
		+ 'Einstellungen gelten für alle Welten und bleiben bei jedem Löschen stehen, '
		+ 'ebenso die Zugangsdaten des Auto Logins.'));

	pane.appendChild(mmEl('div', 'font-weight:bold;margin:4px 0 8px;',
		'Gespeicherte Daten'));

	pane.appendChild(settingsStorageList());

	function action(label, hint, handler, enabled) {
		var box = mmEl('div', 'margin:0 0 12px;padding:0 0 10px;'
			+ 'border-bottom:1px solid rgba(168,148,84,0.25);');
		var b = settingsButton(label);
		b.style.marginLeft = '0';
		if (enabled === false) {
			b.disabled = true;
			b.style.opacity = '0.45';
			b.style.cursor = 'default';
		} else {
			b.addEventListener('click', function () {
				try {
					handler();
				} catch (e) {
					mmReportError(label, e);
				}
			}, true);
		}
		box.appendChild(b);
		box.appendChild(mmEl('div',
			'opacity:0.65;font-size:11px;line-height:1.45;margin:6px 0 0;', hint));
		pane.appendChild(box);
		return b;
	}

	action('Daten für diese Welt löschen',
		'Wirft alles weg, was oben unter dieser Welt steht, und dazu das '
		+ 'Weltübergreifende der übrigen Module. Beim nächsten Besuch wird geholt, '
		+ 'was gebraucht wird. Sinnvoll bei einem Weltenreset.',
		function () { settingsClose(); deleteAllDataForWorld(); });

	action('Daten aller Welten löschen',
		'Dasselbe für jede Welt auf einmal.',
		function () { settingsClose(); deleteAllDataEverywhere(); });

	action('Alle Einstellungen zurücksetzen',
		'Setzt alle Reiter auf die Vorgaben aus dem Kopf der Skriptdatei zurück. '
		+ 'Eingelesene Daten bleiben unberührt.',
		function () {
			if (!window.confirm('Alle Einstellungen auf die Vorgaben zurücksetzen?'))
				return;
			settingsReset();
			settingsClose();
		});

	settingsBuildTransferPane(pane, action);
	pane.appendChild(settingsMessagePane());
	return pane;
}

/*
 * Export and import, with room under them for what an import has to say. That can
 * run to several lines - which entries fell away, which fell back to a default -
 * and it belongs where the buttons are, not in a dialog box that has to be clicked
 * away before it can be read twice.
 */
function settingsBuildTransferPane(pane, action) {
	var bericht = mmEl('div', 'margin:-4px 0 12px;font-size:11px;'
		+ 'line-height:1.5;');
	bericht.setAttribute('data-mm-settings', 'transfer-bericht');

	function melden(zeilen, schlimm) {
		mmEmpty(bericht);

		for (var i = 0; i < zeilen.length; i++)
			bericht.appendChild(mmEl('div',
				'margin:0 0 3px;' + (schlimm ? 'color:#e0a030;' : 'opacity:0.8;'),
				zeilen[i]));
	}

	//Two ways out, chosen under the button: the settings alone, or the settings
	//with everything the script has stored.
	var wahl = mmEl('div', 'margin:6px 0 0;display:none;');
	wahl.setAttribute('data-mm-settings', 'export-wahl');

	var nurEinstellungen = settingsButton('Nur Einstellungen');
	var mitDaten = settingsButton('Einstellungen und alle Daten');
	nurEinstellungen.style.marginLeft = '0';
	nurEinstellungen.setAttribute('data-mm-settings', 'export-einstellungen');
	mitDaten.setAttribute('data-mm-settings', 'export-daten');
	wahl.appendChild(nurEinstellungen);
	wahl.appendChild(mitDaten);

	function exportiere(daten) {
		wahl.style.display = 'none';
		settingsExportDownload(melden, daten);
	}
	nurEinstellungen.addEventListener('click', function () { exportiere(false); }, true);
	mitDaten.addEventListener('click', function () { exportiere(true); }, true);

	var exportKnopf = action('Einstellungen exportieren',
		'Schreibt alle Reiter in eine Datei und legt sie in den Download-Ordner. '
		+ 'Damit lassen sie sich sichern oder auf einen anderen Rechner bringen. '
		+ 'Auf Wunsch kommen alle gespeicherten Daten mit, etwa der '
		+ 'Gegenstandsvergleich. Benutzername und Kennwort des Auto Logins stehen '
		+ 'nie darin.',
		function () {
			wahl.style.display = (wahl.style.display === 'none') ? 'block' : 'none';
		});
	exportKnopf.parentNode.insertBefore(wahl, exportKnopf.nextSibling);

	//The file picker of the browser, hidden: its own look cannot be styled and
	//would be the one thing in this window that belongs to another program. The
	//button above opens it.
	var datei = mmEl('input');
	datei.type = 'file';
	datei.accept = '.json,application/json';
	datei.style.display = 'none';
	datei.setAttribute('data-mm-settings', 'import-datei');
	datei.addEventListener('change', function () {
		var gewaehlt = datei.files && datei.files[0];
		if (gewaehlt)
			settingsImportFile(gewaehlt, melden);
		//Emptied, so choosing the same file twice in a row is noticed again.
		datei.value = '';
	}, false);

	action('Einstellungen importieren',
		'Liest so eine Datei wieder ein. Was darin steht, gilt danach. Was diese '
		+ 'Version nicht mehr kennt oder nicht mehr annimmt, fällt auf die Vorgabe '
		+ 'zurück und wird hier genannt. Eine Datei aus einer anderen Version wird '
		+ 'angenommen, aber mit einem Hinweis. Stehen auch Daten darin, wird vorher '
		+ 'gefragt, ob sie übernommen werden sollen.',
		function () { datei.click(); });

	pane.appendChild(datei);
	pane.appendChild(bericht);
	return bericht;
}

/////////////////////////////////////////////////////////////////////////////
/////////////////// Module: triggers and Kaja's workshop ////////////////////
/////////////////////////////////////////////////////////////////////////////
/*
 * Three lists of item names, each with a note saying where the piece is needed.
 * Wherever such a name turns up on the page it is coloured and gets that note.
 *
 * Where the note is shown depends on what the name sits in. There are three cases
 * and each of them ends with exactly ONE window on the screen:
 *
 *   1. A link the item compare already handles. Nothing at all is written onto the
 *      link. The compare panel asks triggerNoteFor() while it is being drawn and
 *      hangs the note underneath its table.
 *   2. A link that already carries the game's own tooltip - the forum does this
 *      with its item links. The note is appended inside that call, behind a rule.
 *      The rule matters: the rank colouring reads bonuses out of such tooltips and
 *      stops at the first <hr>, so everything behind it stays out of its way.
 *   3. Everything else, and names found in running text. Those get the module's
 *      own small box.
 *
 * Case 3 uses a box of the module's own rather than a tooltip function injected
 * into the page: the page's wodToolTip cannot be reached from the sandbox, a
 * script tag is the first thing a content security policy stops, and a handler on
 * document.onmousemove would take that slot away from whoever else wants it.
 */

/* --- The lists ----------------------------------------------------------- *
 * Name of the piece -> where it is needed. [post:12345|Text] becomes a link into
 * the forum, [item: Name] a link to the item page. Both are written out in
 * triggerNoteHtml below.
 * ------------------------------------------------------------------------ */

